ST.xhtml:
{region "§1 Gate et demande"}
ExecuteEdge(CLK := Execute);
RequestPending := RequestPending OR ExecuteEdge.Q;
PreflightBusy := RequestPending AND NOT MachineIsStill;
IF NOT MachineIsStill THEN PreflightDone := FALSE; RETURN; END_IF;
IF NOT RequestPending THEN RETURN; END_IF;
{endregion}

{region "§2 Calcul verdict"}
PreflightErrorId := 0;
(* bit0..2 frein M1/M2/M3 serré; bit3..4 contacteurs M1/M2 retombés;
   bit5..6 thermique M1/M2 OK; bit7 thermique frein OK; bit8 phases OK;
   bit9 câble M2 tendu; bit10 mot M3 cohérent; bit11 contacteur sans chaîne;
   bit12..13 codeur M1/M2 opérationnel; bit14..15 homé et position bornée M1/M2. *)
IF NOT M1BrakeApplied THEN PreflightErrorId := PreflightErrorId OR 16#0001; END_IF;
IF NOT M2BrakeApplied THEN PreflightErrorId := PreflightErrorId OR 16#0002; END_IF;
IF NOT M3BrakeApplied THEN PreflightErrorId := PreflightErrorId OR 16#0004; END_IF;
IF NOT M1ContactorsReleased THEN PreflightErrorId := PreflightErrorId OR 16#0008; END_IF;
IF NOT M2ContactorsReleased THEN PreflightErrorId := PreflightErrorId OR 16#0010; END_IF;
IF NOT M1ThermalOk THEN PreflightErrorId := PreflightErrorId OR 16#0020; END_IF;
IF NOT M2ThermalOk THEN PreflightErrorId := PreflightErrorId OR 16#0040; END_IF;
IF NOT BrakeThermalOk THEN PreflightErrorId := PreflightErrorId OR 16#0080; END_IF;
IF NOT PhaseRotationOk THEN PreflightErrorId := PreflightErrorId OR 16#0100; END_IF;
IF NOT SlackCableTensioned THEN PreflightErrorId := PreflightErrorId OR 16#0200; END_IF;
IF M3SensorWordIncoherent THEN PreflightErrorId := PreflightErrorId OR 16#0400; END_IF;
IF PowerContactorEngaged AND NOT EmergencyChainClosed THEN PreflightErrorId := PreflightErrorId OR 16#0800; END_IF;
IF NOT EncoderM1Operational THEN PreflightErrorId := PreflightErrorId OR 16#1000; END_IF;
IF NOT EncoderM2Operational THEN PreflightErrorId := PreflightErrorId OR 16#2000; END_IF;
IF NOT HomedM1 OR NOT M1PositionInBounds THEN PreflightErrorId := PreflightErrorId OR 16#4000; END_IF;
IF NOT HomedM2 OR NOT M2PositionInBounds THEN PreflightErrorId := PreflightErrorId OR 16#8000; END_IF;
{endregion}

{region "§3 Sortie"}
PreflightOk := (PreflightErrorId = 0); PreflightDone := TRUE; RequestPending := FALSE;
{endregion}

{region "§1 Lissage anti-clignotement"}
// Défaut critique : affichage immédiat, le TON est remis à zéro (aucune latence).
IF ForceInstant THEN
    Text := NewText;
    TonHold(IN := FALSE);
ELSE
    // Warning / état : le texte ne change qu'après maintien min (HoldTime).
    // Un signal qui oscille plus vite que HoldTime → texte stable.
    TonHold(IN := (NewText <> Text), PT := HoldTime);
    IF TonHold.Q THEN
        Text := NewText;
    END_IF;
END_IF;
{endregion}

IF RawIn >= Neutral THEN
    Delta := INT_TO_REAL(10000 - Neutral);
    IF Delta > 0.0 THEN
        OutPct := (INT_TO_REAL(RawIn - Neutral) / Delta) * 100.0;
    ELSE
        OutPct := 0.0;
    END_IF;
ELSE
    Delta := INT_TO_REAL(Neutral);
    IF Delta > 0.0 THEN
        OutPct := (INT_TO_REAL(RawIn - Neutral) / Delta) * 100.0;
    ELSE
        OutPct := 0.0;
    END_IF;
END_IF;

IF ABS(RawIn - Neutral) <= DeadbandRaw THEN
    OutPct := 0.0;
END_IF;

// 🛡️ Limitation de plage : une valeur brute hors plage nominale ne doit jamais
// produire une consigne supérieure à ±100 %. Ce garde-fou protège les
// consommateurs en aval, notamment la translation M3.
OutPct := LIMIT(-100.0, OutPct, 100.0);

// === IMPLEMENTATION ===

{region "§1 Fronts"}
// 🔑 1. FRONTS
ResetEdge(CLK := Reset);
BypassEdge(CLK := BypassContactorCheck);

// Acquittement des drapeaux contacteur
IF ResetEdge.Q OR BypassContactorCheck THEN
    ContactorIncoherentError := FALSE;
    ContactorCheck.StuckClosed := FALSE;
    ContactorCheck.StuckOpen   := FALSE;
END_IF;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE — pas d'Enable = frein collé (sécurité positive), aucune temporisation en cours
IF NOT Enable THEN
    TonMagnetise(IN := FALSE, PT := DelayMagnetise + DelayContactClose);
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    TonFeedback(IN := FALSE, PT := FeedbackTimeout);
    BrakeCmd := FALSE;
    Ready := FALSE;
    ContactorCheck.Command := FALSE;          // 📊 Neutralisation : miroir de BrakeCmd := FALSE
    ContactorCheck.Feedback := ContactorFeedback; // 📊 Neutralisation : miroir entrée physique
    BrakeCommandOpenConfirmed := FALSE;       // 🛡️ Fail-Safe : frein commandé fermé hors Enable

    // Évaluation du socle de défaut sous neutralisation (permet acquittement Reset hors Enable)
    instCauses[0].Active   := FALSE;
    instCauses[0].Latching := TRUE;
    instCauses[0].Texte    := 'Incoherence retour contacteur frein';
    instFault(Enable := FALSE, Reset := Reset, Causes := instCauses);
    Fault := instFault.Fault;
    RETURN;
END_IF;
{endregion}

{region "§3 Séquence temporisée"}
// 🛠️ 3. SÉQUENCE TEMPORISÉE (démarrage vs arrêt)
IF MovementRequested THEN
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    TonMagnetise(IN := TRUE, PT := DelayMagnetise + DelayContactClose);
    IF TonMagnetise.Q THEN
        BrakeCmd := TRUE;              // ✅ Contacteur + magnétisation acquis → relâche
    ELSE
        BrakeCmd := FALSE;             // ⏳ Encore collé pendant la magnétisation
    END_IF;
ELSE
    // Sécurité positive : fermeture immédiate du frein (collé) dès que les contacteurs de sens s'ouvrent
    TonMagnetise(IN := FALSE, PT := DelayMagnetise + DelayContactClose);
    TonDecel(IN := FALSE, PT := DelayMotorDecel);
    BrakeCmd := FALSE;                 // Fermeture immédiate
END_IF;
{endregion}

{region "§4 Double vérification contacteur"}
// 🔍 4. DOUBLE VÉRIFICATION RETOUR CONTACTEUR (ST_ContactorCheck)
ContactorCheck.Command := BrakeCmd;
ContactorCheck.Feedback := ContactorFeedback;

// ContactorFeedback est dans le MÊME sens que BrakeCmd (TRUE = relâché = frein ouvert).
TonFeedback(IN := (BrakeCmd <> ContactorFeedback), PT := FeedbackTimeout);
IF NOT BypassContactorCheck THEN
    IF TonFeedback.Q THEN
        ContactorCheck.StuckClosed := (BrakeCmd AND NOT ContactorFeedback);
        ContactorCheck.StuckOpen   := (NOT BrakeCmd AND ContactorFeedback);
        ContactorIncoherentError   := TRUE;
    END_IF;
END_IF;
{endregion}

{region "§5 Causes & Socle Défaut"}
// 🚨 5. SOCLE DÉFAUT & SORTIE SÛRE
instCauses[0].Active   := NOT BypassContactorCheck AND (ContactorCheck.StuckClosed OR ContactorCheck.StuckOpen OR (TonFeedback.Q AND (BrakeCmd <> ContactorFeedback)));
instCauses[0].Latching := TRUE;
instCauses[0].Texte    := 'Incoherence retour contacteur frein';

instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

Ready := Enable AND NOT Fault.Latched;

// Sortie sûre immédiate
IF Fault.Error OR Fault.Latched THEN
    BrakeCmd := FALSE;
END_IF;
{endregion}

{region "§6 Confirmation ouverture"}
// 📤 6. CONFIRMATION OUVERTURE FREIN
IF BypassContactorCheck THEN
    BrakeCommandOpenConfirmed := BrakeCmd;
ELSE
    BrakeCommandOpenConfirmed := ContactorFeedback AND NOT Fault.Latched;  (* TRUE = frein ouvert = desserrage confirmé *)
END_IF;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. FRONTS & REARMEMENT
ResetEdge(CLK := Reset);

IF ResetEdge.Q OR BypassGlobal THEN
    CfgFaultLatched       := FALSE;
    OffsetMaxFaultLatched := FALSE;
    TimeoutFaultLatched   := FALSE;
    M1SlipFaultLatched    := FALSE;
    HomingFaultLatched    := FALSE;
END_IF;

IF NOT BypassGlobal THEN
    // Cause 0 : Configuration géométrie benne.
    // Ordre ouvert < ferme obligatoire. Offset ouvert legerement negatif tolere
    // (M2 un cheveu sous M1 a l'ouverture pleine, recalibration MES) -> seuil -2 m.
    IF (Config.OffsetOpenM >= Config.OffsetCloseM)
       OR (Config.OffsetOpenM < -2.0) THEN
        CfgFaultLatched := TRUE;
    END_IF;
    instCauses[0].Active   := CfgFaultLatched;
    instCauses[0].Latching := TRUE;
    instCauses[0].Texte    := 'Configuration geometrie benne invalide';

    // Cause 1 : Depassement ecart max (plage physique plausible M2 - M1).
    // Borne haute : offset ferme + 2 m de marge inertie. Borne basse : offset ouvert
    // MOINS la tolerance de coherence (bruit codeur / leger sur-jog a l'ouverture) ->
    // ne latche plus un defaut pour quelques cm de M2 sous M1.
    MaxAllowedOffset := Config.OffsetCloseM + 2.0;
    MinAllowedOffset := Config.OffsetOpenM - Config.CoherenceLimitM;
    OffsetMaxViolNow := (CablePosM2 > (CablePosM1 + MaxAllowedOffset))
                     OR (CablePosM2 < (CablePosM1 + MinAllowedOffset));
    // Anti-pic : ne latche que si l'ecart reste hors plage > 500 ms (bruit codeur / glitch).
    TonOffsetMaxViol(IN := OffsetMaxViolNow, PT := T#500ms);
    IF TonOffsetMaxViol.Q THEN
        OffsetMaxFaultLatched := TRUE;
    END_IF;
    instCauses[1].Active   := OffsetMaxFaultLatched;
    instCauses[1].Latching := TRUE;
    instCauses[1].Texte    := 'Depassement ecart maximum autorise benne';

    // Cause 2 : Timeout
    TonTimeout(IN := Lifecycle.Busy, PT := CfgTimeoutDuration);
    IF TonTimeout.Q THEN
        TimeoutFaultLatched := TRUE;
    END_IF;
    instCauses[2].Active   := TimeoutFaultLatched;
    instCauses[2].Latching := TRUE;
    instCauses[2].Texte    := 'Timeout commande deplacement benne';

    // Cause 3 : Glissement M1
    M1SlipDetected := Lifecycle.Busy AND (ABS(CablePosM1 - M1RefPosM) > M1SlipToleranceM);
    IF M1SlipDetected THEN
        M1SlipFaultLatched := TRUE;
    END_IF;
    instCauses[3].Active   := M1SlipFaultLatched;
    instCauses[3].Latching := TRUE;
    instCauses[3].Texte    := 'Glissement treuil M1 pendant manoeuvre benne';

    // Cause 4 : Non référencé
    IF NOT HomedM1 OR NOT HomedM2 THEN
        HomingFaultLatched := TRUE;
    END_IF;
    instCauses[4].Active   := HomingFaultLatched;
    instCauses[4].Latching := TRUE;
    instCauses[4].Texte    := 'Codeurs treuils non references pour sequence benne';
ELSE
    TonTimeout(IN := FALSE);
    M1SlipDetected := FALSE;
    instCauses[0].Active := FALSE;
    instCauses[1].Active := FALSE;
    instCauses[2].Active := FALSE;
    instCauses[3].Active := FALSE;
    instCauses[4].Active := FALSE;
END_IF;

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate securite"}
// 🛑 2. GATE
IF NOT Enable OR NOT PowerContactorEngaged THEN
    IF Lifecycle.Busy OR CloseReq OR OpenReq THEN
        BucketState.StateIncoherent := TRUE;
    END_IF;
    Ready := FALSE;
    ActiveOffsetValid := FALSE;
    ActiveOffsetSettled := FALSE;
    ActiveOffsetM := 0.0;
    HoldOffsetM := 0.0;          // R8 : ne pas ressortir un HOLD d'avant la coupure a la reprise
    DeltaPosition_M := 0.0;
    RemainingTravelM := 0.0;
    Lifecycle.Busy := FALSE;
    Lifecycle.Done := FALSE;
    M2_RunRequest := FALSE;
    M2_ReqAscent := FALSE;
    M2_ReqDescend := FALSE;
    M2_BucketJogLimit := FALSE;
    CloseReq := FALSE;
    OpenReq := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Premier cycle & recalage boutons IHM"}
IF FirstCycle THEN
    FirstCycle := FALSE;
    BucketState.StateIncoherent := FALSE;
END_IF;

// Les confirmations IHM restent les commandes fonctionnelles de référence
// benne, indépendantes du cycle global. Elles ne sont acceptées qu'à l'arrêt
// en maintenance : un front qualifie l'observation visuelle opérateur.
ConfirmOpenEdge(CLK := ConfirmOpenPosition);
IF ConfirmOpenEdge.Q
   AND (Mode = E_Mode.MAINT_N2)
   AND NOT Lifecycle.Busy AND NOT M1_Busy AND NOT M2_Busy THEN
    BucketState.IsOpen := TRUE;
    BucketState.IsClosed := FALSE;
    BucketState.LastPosM2Open := CablePosM2;
    BucketState.StateIncoherent := FALSE;
END_IF;

ConfirmCloseEdge(CLK := ConfirmClosePosition);
IF ConfirmCloseEdge.Q
   AND (Mode = E_Mode.MAINT_N2)
   AND NOT Lifecycle.Busy AND NOT M1_Busy AND NOT M2_Busy THEN
    BucketState.IsOpen := FALSE;
    BucketState.IsClosed := TRUE;
    BucketState.LastPosM2Close := CablePosM2;
    BucketState.StateIncoherent := FALSE;
END_IF;

IF MachineHomingCommitOpen AND NOT Lifecycle.Busy THEN
    BucketState.IsOpen := TRUE;
    BucketState.IsClosed := FALSE;
    BucketState.LastPosM2Open := CablePosM2;
    BucketState.StateIncoherent := FALSE;
END_IF;

IF MachineHomingCommitClose AND NOT Lifecycle.Busy THEN
    BucketState.IsOpen := FALSE;
    BucketState.IsClosed := TRUE;
    BucketState.LastPosM2Close := CablePosM2;
    BucketState.StateIncoherent := FALSE;
END_IF;
{endregion}

{region "§4 Séquencement mouvement benne"}
SevereError := Fault.Error;

// --- §4a Classification continue de l'etat benne sur la MESURE physique -----------------
// L'etat benne reflete directement la cinematique reelle Delta = M2 - M1.
// Tant que M1 et M2 sont references, la position relative de la benne est connue en continu.
DeltaPosition_M := CablePosM2 - CablePosM1;

ClassCanRun := HomedM1 AND HomedM2
               AND NOT SevereError;

NearClosed := ClassCanRun AND (ABS(DeltaPosition_M - Config.OffsetCloseM) <= Config.CoherenceLimitM);
NearOpen   := ClassCanRun AND (ABS(DeltaPosition_M - Config.OffsetOpenM)  <= Config.CoherenceLimitM);

// Classification continue instantanee (publiee en direct sur BucketState) :
IF ClassCanRun THEN
    BucketState.IsClosed       := NearClosed;
    BucketState.IsOpen         := NearOpen;
    BucketState.IsIntermediate := NOT NearClosed AND NOT NearOpen
                                  AND (DeltaPosition_M >= (Config.OffsetOpenM - Config.CoherenceLimitM))
                                  AND (DeltaPosition_M <= (Config.OffsetCloseM + Config.CoherenceLimitM));
    BucketState.TooOpen        := DeltaPosition_M <  (Config.OffsetOpenM  - Config.CoherenceLimitM);
    BucketState.TooClosed      := DeltaPosition_M >  (Config.OffsetCloseM + Config.CoherenceLimitM);
    BucketState.StateIncoherent := FALSE;
    IF NearClosed THEN
        BucketState.LastPosM2Close := CablePosM2;
    ELSIF NearOpen THEN
        BucketState.LastPosM2Open  := CablePosM2;
    END_IF;
ELSE
    BucketState.IsClosed       := FALSE;
    BucketState.IsOpen         := FALSE;
    BucketState.IsIntermediate := FALSE;
    BucketState.TooOpen        := FALSE;
    BucketState.TooClosed      := FALSE;
END_IF;

MotionRequestConflict := ReqAscent AND ReqDescend;
MotionRequestActive := (ReqAscent OR ReqDescend) AND NOT MotionRequestConflict;

IF SevereError THEN
    M2_RunRequest := FALSE;
    M2_ReqAscent := FALSE;
    M2_ReqDescend := FALSE;
    M2_BucketJogLimit := FALSE;
    CloseReq := FALSE;
    OpenReq := FALSE;
    Lifecycle.Busy := FALSE;
    Lifecycle.Done := FALSE;
ELSE
    // Prise en compte des demandes IHM — anti-traversée (TC-P10-025) :
    // demande benne refusée si un treuil agit (M1_Busy OR M2_Busy) à l'entrée READY.
    IF CmdOpen_IHM AND NOT Lifecycle.Busy AND NOT M1_Busy AND NOT M2_Busy THEN
        OpenReq := TRUE;
        CloseReq := FALSE;
    ELSIF CmdClose_IHM AND NOT Lifecycle.Busy AND NOT M1_Busy AND NOT M2_Busy THEN
        CloseReq := TRUE;
        OpenReq := FALSE;
    END_IF;

    BusyEdge(CLK := (CloseReq OR OpenReq) AND MotionRequestActive);

    IF BusyEdge.Q THEN
        M1RefPosM := CablePosM1;
        M2StartPosM := CablePosM2;
        WasOpenAtStart := BucketState.IsOpen;
        WasClosedAtStart := BucketState.IsClosed;
        LeftStartSinceArm := FALSE;
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
    END_IF;

    IF Lifecycle.Busy THEN
        IF CloseReq THEN
            RemainingTravelM := MAX(0.0, (CablePosM1 + Config.OffsetCloseM) - CablePosM2);
            M2_BucketJogLimit := TRUE;
            IF MotionRequestActive AND ReqAscent AND EffectivePermitBucket_Close THEN
                M2_RunRequest := TRUE;
                M2_ReqAscent := TRUE;
                M2_ReqDescend := FALSE;
            ELSIF MotionRequestActive AND ReqDescend AND EffectivePermitBucket_Open THEN
                M2_RunRequest := TRUE;
                M2_ReqAscent := FALSE;
                M2_ReqDescend := TRUE;
            ELSE
                M2_RunRequest := FALSE;
                M2_ReqAscent := FALSE;
                M2_ReqDescend := FALSE;
            END_IF;
        ELSIF OpenReq THEN
            RemainingTravelM := MAX(0.0, CablePosM2 - (CablePosM1 + Config.OffsetOpenM));
            M2_BucketJogLimit := TRUE;
            IF MotionRequestActive AND ReqDescend AND EffectivePermitBucket_Open THEN
                M2_RunRequest := TRUE;
                M2_ReqAscent := FALSE;
                M2_ReqDescend := TRUE;
            ELSIF MotionRequestActive AND ReqAscent AND EffectivePermitBucket_Close THEN
                M2_RunRequest := TRUE;
                M2_ReqAscent := TRUE;
                M2_ReqDescend := FALSE;
            ELSE
                M2_RunRequest := FALSE;
                M2_ReqAscent := FALSE;
                M2_ReqDescend := FALSE;
            END_IF;
        ELSE
            M2_RunRequest := FALSE;
            M2_ReqAscent := FALSE;
            M2_ReqDescend := FALSE;
            M2_BucketJogLimit := FALSE;
        END_IF;

        IF (CloseReq AND (CablePosM2 > M2StartPosM)) OR (OpenReq AND (CablePosM2 < M2StartPosM)) THEN
            LeftStartSinceArm := TRUE;
        END_IF;

        // Arrêt fermeture
        IF CloseReq THEN
            IF CablePosM2 >= (CablePosM1 + Config.OffsetCloseM - Config.CloseAnticipationM) THEN
                M2_RunRequest := FALSE;
                M2_ReqAscent := FALSE;
                M2_ReqDescend := FALSE;
                BucketState.IsOpen := FALSE;
                BucketState.IsClosed := TRUE;
                BucketState.LastPosM2Close := CablePosM2;
                BucketState.StateIncoherent := FALSE;
                CloseReq := FALSE;
                Lifecycle.Busy := FALSE;
                Lifecycle.Done := TRUE;
            ELSIF LeftStartSinceArm AND (CablePosM2 <= M2StartPosM) THEN
                M2_RunRequest := FALSE;
                M2_ReqAscent := FALSE;
                M2_ReqDescend := FALSE;
                BucketState.IsOpen := WasOpenAtStart;
                BucketState.IsClosed := WasClosedAtStart;
                CloseReq := FALSE;
                Lifecycle.Busy := FALSE;
                Lifecycle.Done := TRUE;
            END_IF;
        END_IF;

        // Arrêt ouverture
        IF OpenReq THEN
            IF CablePosM2 <= (CablePosM1 + Config.OffsetOpenM + Config.OpenAnticipationM) THEN
                M2_RunRequest := FALSE;
                M2_ReqAscent := FALSE;
                M2_ReqDescend := FALSE;
                BucketState.IsOpen := TRUE;
                BucketState.IsClosed := FALSE;
                BucketState.LastPosM2Open := CablePosM2;
                BucketState.StateIncoherent := FALSE;
                OpenReq := FALSE;
                Lifecycle.Busy := FALSE;
                Lifecycle.Done := TRUE;
            ELSIF LeftStartSinceArm AND (CablePosM2 >= M2StartPosM) THEN
                M2_RunRequest := FALSE;
                M2_ReqAscent := FALSE;
                M2_ReqDescend := FALSE;
                BucketState.IsOpen := WasOpenAtStart;
                BucketState.IsClosed := WasClosedAtStart;
                OpenReq := FALSE;
                Lifecycle.Busy := FALSE;
                Lifecycle.Done := TRUE;
            END_IF;
        END_IF;
    ELSIF Lifecycle.Done THEN
        M2_RunRequest := FALSE;
        M2_ReqAscent := FALSE;
        M2_ReqDescend := FALSE;
        M2_BucketJogLimit := FALSE;
        RemainingTravelM := 0.0;
        IF NOT MotionRequestActive THEN
            Lifecycle.Done := FALSE;
        END_IF;
    END_IF;
END_IF;

// --- Distance restante publiee en PERMANENCE (auto ET jog manuel M2) -----------------
// Hors sequence commandee (Lifecycle.Busy, qui calcule deja RemainingTravelM au plus
// juste), on publie la distance geometrique vers la cible OPPOSEE a l'etat courant :
// benne fermee -> reste a parcourir pour ouvrir ; benne ouverte -> reste pour fermer.
// Permet l'affichage IHM du "reste a faire" meme en pilotage unitaire M2 (WinchSel=2).
IF NOT Lifecycle.Busy AND NOT SevereError THEN
    IF BucketState.IsClosed AND NOT BucketState.IsOpen THEN
        RemainingTravelM := MAX(0.0, CablePosM2 - (CablePosM1 + Config.OffsetOpenM));
    ELSIF BucketState.IsOpen AND NOT BucketState.IsClosed THEN
        RemainingTravelM := MAX(0.0, (CablePosM1 + Config.OffsetCloseM) - CablePosM2);
    ELSE
        RemainingTravelM := 0.0;
    END_IF;
END_IF;

// --- Ouverture benne en % (0..100), calcul CONTINU sur l'ecart mesure ------------------
// 0 % = benne fermee (Delta ~ OffsetCloseM), 100 % = benne ouverte (Delta ~ OffsetOpenM).
// Independant de l'etat latche : donne toujours la position reelle, meme mi-course / non
// confirme. Borne [0..100]. (Config invalide OffsetOpenM >= OffsetCloseM -> deja CfgFault.)
IF (Config.OffsetCloseM - Config.OffsetOpenM) > 0.001 THEN
    BucketOpening_Pct := LIMIT(0.0,
        100.0 * (Config.OffsetCloseM - DeltaPosition_M)
              / (Config.OffsetCloseM - Config.OffsetOpenM),
        100.0);
ELSE
    BucketOpening_Pct := 0.0;
END_IF;

{endregion}

{region "§5 Offset actif et validite"}
// DeltaPosition_M deja calcule en §4a (classification etat).

// --- Cible d'offset OffsetTargetM (avant limitation de pente) ---------------------------
// Priorite : (1) manoeuvre en cours = ecart reel live ; (2) recalage sur la bande mesuree
// CONFIRMEE CST_BandStableTime (anti-chatter au bord de bande, R3) ; (3) etat memorise /
// demande ; (4) sinon dernier connu.
TonBandClosed(IN := NearClosed, PT := CST_BandStableTime);
TonBandOpen(IN := NearOpen,   PT := CST_BandStableTime);
NearClosedStable := TonBandClosed.Q;
NearOpenStable   := TonBandOpen.Q;

IF Lifecycle.Busy THEN
    OffsetTargetM := CablePosM2 - CablePosM1;
ELSIF NearClosedStable THEN
    OffsetTargetM := Config.OffsetCloseM;
ELSIF NearOpenStable THEN
    OffsetTargetM := Config.OffsetOpenM;
ELSIF CloseReq OR BucketState.IsClosed THEN
    OffsetTargetM := Config.OffsetCloseM;
ELSIF OpenReq OR BucketState.IsOpen THEN
    OffsetTargetM := Config.OffsetOpenM;
ELSE
    // Etat indetermine (latch efface par A, ou jamais latche) : on GELE le dernier offset
    // franc connu (HoldOffsetM). Ne PAS suivre l'ecart mesure ici -> sinon
    // ExpectedOtherWinchPosM (FB_Safety_Winch) suivrait la mesure et rendrait la
    // surveillance d'ecart croise M1/M2 aveugle en mouvement couple (challenge 2026-09-04).
    // L'incoherence est signalee par OffsetStateMismatchWarn (§5a).
    OffsetTargetM := HoldOffsetM;
END_IF;

// --- ActiveOffsetM : suivi de la cible A PENTE LIMITEE (R2/R3) --------------------------
// Un pas brut de 0 <-> OffsetCloseM (~15 m) en un scan faisait : latcher SyncDeviationWarn
// (FB_SyncDeviation, seuil 0.10 m, RAZ sur Reset seulement) et sauter PosStepDetected
// (FB_Safety_Winch, 0.5 m) -> RAZ + inhibition MecaA/MecaE. On converge donc a pente
// bornee ; pendant la convergence l'offset n'est pas "fiable" (voir ActiveOffsetSettled)
// et la synchro est inhibee cote PRG_04.
IF Lifecycle.Busy THEN
    ActiveOffsetM := OffsetTargetM;                                   // suit l'ecart reel (deplacement lent du treuil, aucun pas)
ELSE
    ActiveOffsetM := ActiveOffsetM
                     + LIMIT(-CST_OffsetSlewMPerScan,
                              OffsetTargetM - ActiveOffsetM,
                              CST_OffsetSlewMPerScan);
END_IF;
HoldOffsetM := ActiveOffsetM;

// --- ActiveOffsetSettled : ActiveOffsetM n'est PAS en cours de recalage --------------
// Vrai des que la valeur colle a sa cible depuis CST_OffsetResettleTime. Reste vrai en
// mouvement couple nominal (cible == valeur, aucun pas). Retombe UNIQUEMENT quand un
// nouveau recalage est engage (sortie de manoeuvre, re-latch d'etat apres correction).
// -> c'est CE flag qui autorise la synchro (PRG_04) : elle n'est coupee que pendant le
//    transitoire de recalage, pas en fonctionnement couple.
TonOffsetResettle(IN := (ABS(OffsetTargetM - ActiveOffsetM) <= CST_OffsetStepThresholdM),
                  PT := CST_OffsetResettleTime);
ActiveOffsetSettled := TonOffsetResettle.Q;

// --- ActiveOffsetValid : offset semantiquement fiable (consommateurs cycle/homing) -----
// L'offset benne est valide des lors que le bloc est actif, les codeurs M1 et M2 references,
// et qu'aucun defaut n'invalide la mesure physique. L'etat intermediaire n'invalide PAS la reference.
ActiveOffsetValid := Enable AND PowerContactorEngaged
                     AND HomedM1 AND HomedM2
                     AND NOT BucketState.StateIncoherent
                     AND (Fault.ErrorId = 0);
BucketState.ActiveOffsetValid := ActiveOffsetValid;

// --- §5a Filet : avertissement incoherence geometrique benne (R1) -----------------
// Avertit si l'ecart mesure depasse les bornes plausibles [OffsetOpen - Coherence .. OffsetClose + Coherence]
TonOffsetMismatch(
    IN := ClassCanRun
          AND (BucketState.TooOpen OR BucketState.TooClosed),
    PT := T#2s);
OffsetStateMismatchWarn := TonOffsetMismatch.Q;
{endregion}

// === IMPLEMENTATION ===

Ready := Enable;

IF NOT Enable THEN
    CmdOpen_IHM  := FALSE;
    CmdClose_IHM := FALSE;
    KoboldContactorCmdArbitrated := FALSE;
    WinchBothDiveBucketOpenArmed    := FALSE;
    WinchBothAscentBucketCloseArmed := FALSE;
ELSE
    // ── Règle absolue en pilotage both normal (bit-identique PRG_04 §1) ──
    // Descente autorisée UNIQUEMENT benne ouverte, montée UNIQUEMENT benne fermée.
    WinchBothDiveBucketOpenArmed := Context.TglEnableCoupledBucketSequencing
        AND (Auth.Mode <> E_Mode.SEMI_AUTO)
        AND Context.MotionActive AND Context.ReqDescend
        AND NOT Context.BucketIsOpen;
    WinchBothAscentBucketCloseArmed := Context.TglEnableCoupledBucketSequencing
        AND (Auth.Mode <> E_Mode.SEMI_AUTO)
        AND Context.MotionActive AND Context.ReqAscent
        AND NOT Context.BucketIsClosed;

    // ── Ouverture benne : bouton IHM OU séquencement couplé descente benne ouverte
    //    OU demande cycle (bit-identique PRG_04 §2) ──
    CmdOpen_IHM := IHM.BtnOpen OR WinchBothDiveBucketOpenArmed OR ReqBucket.ReqOpen;

    // ── Fermeture benne : demande cycle > séquencement couplé montée benne fermée
    //    > bouton IHM (bit-identique PRG_04 §1) ──
    IF ReqBucket.ReqClose THEN
        CmdClose_IHM := TRUE;
    ELSIF WinchBothAscentBucketCloseArmed THEN
        CmdClose_IHM := TRUE;
    ELSE
        CmdClose_IHM := IHM.BtnClose;
    END_IF;

    // ── Contacteur Kobold : demande cycle (source unique PRG_03, bit-identique PRG_04 §1) ──
    KoboldContactorCmdArbitrated := ReqBucket.ReqKoboldMeasureEnable;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

IF NOT Enable THEN
    Cmd := FALSE;
    Ready := FALSE;
    Allowed := FALSE;
    InhibitActive := FALSE;
    ActivationLatched := FALSE;
    TonInterval(IN := FALSE);
ELSE
    Ready := TRUE;
    ReqFall(CLK := Request);

    // Intervalle : arme a la retombee d'une activation, tient Cfg_MinInterval
    IF ReqFall.Q THEN
        InhibitActive := TRUE;
    END_IF;
    TonInterval(IN := InhibitActive, PT := Cfg_MinInterval);
    IF TonInterval.Q THEN
        InhibitActive := FALSE;
    END_IF;

    // Une demande passe integralement (non decoupee) tant qu'elle est maintenue, mais ne
    // peut (re)demarrer que hors intervalle. Test de niveau : robuste si Request est deja
    // TRUE au demarrage (pas de front observe).
    IF Request AND NOT InhibitActive THEN
        ActivationLatched := TRUE;
    END_IF;
    IF NOT Request THEN
        ActivationLatched := FALSE;
    END_IF;

    Allowed := NOT InhibitActive;
    Cmd := ActivationLatched;
END_IF;

{region "§1 Fronts, remises a zero de tete de scan, verrou M3"}
// === §1 FRONTS + RAZ TETE DE SCAN + VERROU M3 =========================

// Sorties impulsionnelles / mouvement : remises a FALSE en tete de scan.
// Seul un step actif les remonte -> HX0 (etape initiale pure) n'ecrit rien.
M1Demand.HomeReq := FALSE;
M2Demand.HomeReq := FALSE;
BucketCommit.CommitOpen  := FALSE;
BucketCommit.CommitClose := FALSE;
CmdBucketOpen  := FALSE;
CmdBucketClose := FALSE;
CmdWinchM1.RunRequest := FALSE; CmdWinchM1.ReqAscent := FALSE; CmdWinchM1.ReqDescend := FALSE; CmdWinchM1.StepTgt := 0;
CmdWinchM2.RunRequest := FALSE; CmdWinchM2.ReqAscent := FALSE; CmdWinchM2.ReqDescend := FALSE; CmdWinchM2.StepTgt := 0;
ExplicitValidationPulse := FALSE;

// Detection de fronts.
ResetEdge(CLK := Reset);
LatchedEdge(CLK := Fault.Latched);
TopLostEdge(CLK := TopPositionSensor);

// Miroirs booleens de contexte GRAFCET.
IsInMovePhase := (SeqStep = E_MachineHomingTxState.HX2_CLIMB)
              OR (SeqStep = E_MachineHomingTxState.HX3_HOME_AXES);
CycleRunning := (SeqStep <> E_MachineHomingTxState.HX0_REPOS)
             AND (SeqStep <> E_MachineHomingTxState.HX1_CHOICE);

// M3Locked est calcule en §9 (apres le CASE) pour verrouiller des le scan d'entree en cycle.
{endregion}

{region "§2 Conditions intermediaires & motif de validation 3 appuis"}
// === §2 CONDITIONS NOMMEES + VALIDATION EXPLICITE =====================
BothAxesHomed       := M1Status.HomedAndReliable AND M2Status.HomedAndReliable;
CommitOrOffsetValid := CommitPublished OR BucketOffsetValid;
ClimbPermit         := DeadmanArmed AND JoystickPull;
DescendPermit       := DeadmanArmed AND JoystickPush;
BucketPermit        := DeadmanArmed AND JoystickDeflected;

// Fenetre de grace deceleration : armee des qu'on entre un step d'arret depuis une phase mouvement.
// Fenetre de grace deceleration : armee sur tous les steps a l'arret (HX2N/HX3N +
// HX4/HX5 ou les treuils doivent rester immobiles).
SettleGraceTimer(IN := (SeqStep = E_MachineHomingTxState.HX2N_NEUTRAL)
                       OR (SeqStep = E_MachineHomingTxState.HX3N_PAUSE)
                       OR (SeqStep = E_MachineHomingTxState.HX4_BUCKET_ADJUST)
                       OR (SeqStep = E_MachineHomingTxState.HX5_BUCKET_COMMIT), PT := CST_SettleGrace);

// Conditions d'abandon fail-safe, chacune <= 3 termes (std 2quater).
AxisHomingError  := M1Status.HomingError OR M2Status.HomingError;
MotionOutOfPhase := CycleRunning AND NOT IsInMovePhase
                    AND NOT WinchesMechanicallyStopped AND SettleGraceTimer.Q;
ClimbTimedOut    := (SeqStep = E_MachineHomingTxState.HX2_CLIMB) AND ClimbTimer.Q;
HomeAxesTimedOut := (SeqStep = E_MachineHomingTxState.HX3_HOME_AXES) AND HomeAxesTimer.Q AND NOT BothAxesHomed;
// Sortie de MAINT_N2 alors qu'un step mouvement/commit est engage : abandon fail-safe.
ModeLostDuringCycle := CycleRunning AND (Mode <> E_Mode.MAINT_N2);
TransactionAbort := CycleRunning
                    AND (AxisHomingError OR MotionOutOfPhase OR ClimbTimedOut
                         OR HomeAxesTimedOut OR ModeLostDuringCycle);

// Auto-armement HX0->HX1 : machine non referencee en maintenance (N1 ou N2), le cycle
// se propose de lui-meme (HX1 = annonce + choix, AUCUN mouvement). Debounce anti-flapping
// sur MachineHomed + garde 1er scan (statuts codeurs non stables au boot). Jamais apres
// defaut non acquitte (regle C : Reset conscient).
AutoArmCandidate := FirstScanDone
                    AND NOT MachineHomed AND NOT MachineHomingFailed
                    AND NOT ReHomingAckRequired AND NOT HomingLossLatched
                    AND ((Mode = E_Mode.MAINT_N1) OR (Mode = E_Mode.MAINT_N2));
AutoArmTimer(IN := AutoArmCandidate, PT := CST_ValidationHold);

// --- Motif "3 appuis successifs" -> ExplicitValidationPulse ---
// Pre-conditions permanentes : joystick centre + aucun mouvement + homme-mort arme.
ValidationBtnEdgeR(CLK := BtnValidation);
ValidationBtnEdgeF(CLK := BtnValidation);
StartEdge(CLK := StartRequest);
ValidationHoldTimer(IN := BtnValidation, PT := CST_ValidationPressHold);
ValidationGapTimer(IN := (ValidationPressCount > 0) AND NOT BtnValidation, PT := CST_ValidationGap);

// Latch "appui maintenu assez longtemps" : lu au relachement (le TON retombe le meme
// scan que la chute de BtnValidation, donc on ne peut pas tester holdTimer.Q sur le front F).
IF BtnValidation AND ValidationHoldTimer.Q THEN
    ValidationHeldOk := TRUE;
END_IF;

// Motif = geste STANDALONE (3 appuis courts sur le BP joystick, joystick centre,
// treuils arretes). Ne PAS exiger DeadmanArmed : le BP joystick EST le bouton
// homme-mort ; on ne peut pas le maintenir arme ET faire des appuis courts.
IF JoystickDeflected OR NOT WinchesMechanicallyStopped THEN
    ValidationPressCount := 0;
    ValidationHeldOk     := FALSE;
ELSIF ValidationGapTimer.Q THEN
    ValidationPressCount := 0;                       // fenetre entre appuis depassee
    ValidationHeldOk     := FALSE;
ELSIF ValidationBtnEdgeF.Q AND ValidationHeldOk THEN
    ValidationPressCount := ValidationPressCount + 1; // appui maintenu >= 300 ms puis relache -> compte
    ValidationHeldOk     := FALSE;
END_IF;

IF ValidationPressCount >= CST_ValidationCount THEN
    ExplicitValidationPulse := TRUE;                 // impulsion 1 scan
    ValidationPressCount    := 0;
END_IF;
{endregion}

{region "§3 Detection de perte de datum (independante de Fault)"}
// === §3 DETECTION DE PERTE DE DATUM ==================================
MachineHomedRaw := BothAxesHomed AND CommitOrOffsetValid
                   AND NOT MachineHomingFailed AND NOT ReHomingAckRequired;

// La PERTE DE DATUM (SafeStop + acquittement conscient) ne concerne QUE la reference
// des codeurs M1/M2. Un offset benne devenu invalide (benne mi-course pendant une
// ouverture/fermeture) N'EST PAS une perte de reference machine : il se traite par une
// reconfirmation position benne, pas par un arret controle + re-homing.
AxesDatumRaw := BothAxesHomed
                AND NOT MachineHomingFailed AND NOT ReHomingAckRequired;

IF AxesDatumRaw THEN
    MachineWasHomed := TRUE;
END_IF;
IF MachineWasHomed AND NOT AxesDatumRaw AND NOT WinchesMechanicallyStopped THEN
    HomingLossLatched := TRUE;
END_IF;
IF NOT AxesDatumRaw AND WinchesMechanicallyStopped THEN
    MachineWasHomed := FALSE;
END_IF;
IF HomingLossLatched AND WinchesMechanicallyStopped THEN
    HomingLossLatched := FALSE;
END_IF;

(* C : pas de redemarrage automatique. Une perte de datum en mouvement exige un
   acquittement conscient (front Reset) avant que MachineHomed puisse revenir. *)
IF HomingLossLatched AND NOT ReHomingAckRequired THEN
    ReHomingAckRequired := TRUE;
END_IF;

MachineHomingLossSafeStop := HomingLossLatched;
{endregion}

{region "§4 Purge sur front Reset (abandon cycle / acquittement)"}
// === §4 PURGE SUR FRONT RESET =======================================
IF ResetEdge.Q THEN
    SeqStep             := E_MachineHomingTxState.HX0_REPOS;
    PendingClose        := FALSE;
    CommitPublished     := FALSE;
    CommitDone          := FALSE;
    HomeReqDone         := FALSE;
    SeenNeutral         := FALSE;
    ValidationPressCount := 0;
    ValidationHeldOk    := FALSE;
    MachineHomingFailed := FALSE;
    MachineWasHomed     := FALSE;
    HomingLossLatched   := FALSE;
    ReHomingAckRequired := FALSE;
END_IF;
{endregion}

{region "§4bis MISE EN SERVICE : forcage de step (encadre, impulsion sur front)"}
// === §4bis FORCAGE DE STEP (aide mise en service) ====================
// Deverrouille UNIQUEMENT si : case IHM mise en service ET MAINT_N2. Autorise MEME
// sur defaut latche (le forcage est justement l'action de recuperation : on sort du
// step bloque puis on acquitte). Impulsion sur front (pas un force continu) : on pose
// SeqStep + on purge les latches incoherents, le GRAFCET reprend au scan suivant.
ForceStepApplyEdge(CLK := CfgForceStepApply);
IF ForceStepApplyEdge.Q
   AND CfgCommissioningEnable
   AND (Mode = E_Mode.MAINT_N2) THEN
    ForceStepClamped := LIMIT(0, CfgForceStepTarget, 9);
    CASE ForceStepClamped OF
        0: SeqStep := E_MachineHomingTxState.HX0_REPOS;
        1: SeqStep := E_MachineHomingTxState.HX1_CHOICE;
        2: SeqStep := E_MachineHomingTxState.HX2_CLIMB;
        3: SeqStep := E_MachineHomingTxState.HX2N_NEUTRAL;
        4: SeqStep := E_MachineHomingTxState.HX3_HOME_AXES;
        5: SeqStep := E_MachineHomingTxState.HX3N_PAUSE;
        6: SeqStep := E_MachineHomingTxState.HX4_BUCKET_ADJUST;
        7: SeqStep := E_MachineHomingTxState.HX5_BUCKET_COMMIT;
        8: SeqStep := E_MachineHomingTxState.HX6_HOMED;
        9: SeqStep := E_MachineHomingTxState.HXF_FAILED;
    END_CASE;
    HomeReqDone  := FALSE;
    SeenNeutral  := FALSE;
    CommitDone   := FALSE;
    PendingClose := FALSE;
    ValidationPressCount := 0;
    ValidationHeldOk     := FALSE;
    MachineHomingFailed  := FALSE;   // le forcage annule l'etat "sequence abandonnee"
END_IF;
{endregion}

{region "§5 Table des causes & socle defaut"}
// === §5 TABLE DES CAUSES + SOCLE DEFAUT ==============================
instCauses[CST_CauseHomingLostInMotion].Active   := HomingLossLatched OR ReHomingAckRequired;
instCauses[CST_CauseHomingLostInMotion].Latching := TRUE;
instCauses[CST_CauseHomingLostInMotion].Texte    := 'Perte de datum machine en mouvement : re-referencer';

instCauses[CST_CauseClimbTimeout].Active   := ClimbTimedOut;
instCauses[CST_CauseClimbTimeout].Latching := TRUE;
instCauses[CST_CauseClimbTimeout].Texte    := 'Montee au capteur haut non aboutie dans le temps imparti';

instCauses[CST_CauseMotionOutOfPhase].Active   := MotionOutOfPhase;
instCauses[CST_CauseMotionOutOfPhase].Latching := TRUE;
instCauses[CST_CauseMotionOutOfPhase].Texte    := 'Mouvement treuil detecte hors phase autorisee du cycle';

instCauses[CST_CauseHomingErrorM1].Active   := CycleRunning AND M1Status.HomingError;
instCauses[CST_CauseHomingErrorM1].Latching := TRUE;
instCauses[CST_CauseHomingErrorM1].Texte    := 'Erreur de homing codeur M1 pendant le referencement conjoint';

instCauses[CST_CauseHomingErrorM2].Active   := CycleRunning AND M2Status.HomingError;
instCauses[CST_CauseHomingErrorM2].Latching := TRUE;
instCauses[CST_CauseHomingErrorM2].Texte    := 'Erreur de homing codeur M2 pendant le referencement conjoint';

instCauses[CST_CauseHomeAxesTimeout].Active   := HomeAxesTimedOut;
instCauses[CST_CauseHomeAxesTimeout].Latching := TRUE;
instCauses[CST_CauseHomeAxesTimeout].Texte    := 'Homing des axes non obtenu dans le temps imparti';

// Socle defaut : appele AVANT la gate NOT Enable (Reset jamais conditionne, std 9).
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§6 Gate initialisation (NOT Enable)"}
// === §6 GATE NOT ENABLE : SORTIES SURES + RETURN =====================
IF NOT Enable THEN
    SeqStep                  := E_MachineHomingTxState.HX0_REPOS;
    MachineHomingStep        := E_MachineHomingStep.IDLE;
    MachineHomingSeqStep     := E_MachineHomingTxState.HX0_REPOS;
    MachineHomingInstruction := 'Homing indisponible';
    MachineHomed             := FALSE;
    MachineHomingActive      := FALSE;
    M1Demand.HomeReq          := FALSE; M1Demand.UseDynamicTarget := FALSE;
    M2Demand.HomeReq          := FALSE; M2Demand.UseDynamicTarget := FALSE;
    CmdWinchM1.RunRequest := FALSE; CmdWinchM1.ReqAscent := FALSE; CmdWinchM1.ReqDescend := FALSE; CmdWinchM1.StepTgt := 0;
    CmdWinchM2.RunRequest := FALSE; CmdWinchM2.ReqAscent := FALSE; CmdWinchM2.ReqDescend := FALSE; CmdWinchM2.StepTgt := 0;
    CmdBucketOpen  := FALSE;
    CmdBucketClose := FALSE;
    BucketCommit.CommitOpen  := FALSE;
    BucketCommit.CommitClose := FALSE;
    Lifecycle.Busy           := FALSE;
    Lifecycle.Done           := FALSE;
    Ready                    := FALSE;
    M3Locked                 := FALSE;
    CycleRunning             := FALSE;
    HomeReqDone              := FALSE;
    SeenNeutral              := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§7 Cible M2 & temporisations de garde"}
// === §7 CIBLE HOMING M2 + GARDES ====================================
// HX3 = referencement des AXES M1/M2 au vol, PAS la benne (GEL homing) : M1 et M2
// montent lies au meme capteur haut -> M2 se reference a la MEME position que M1
// (cible nominale = CfgTopHomingTarget_M). L'offset geometrique benne fermee
// (CfgOffsetClose_M) est applique par le COMMIT benne (HX5 -> FB_Bucket), pas au
// datum de l'axe. Cible dynamique (top + offset ~23 m) supprimee ici : elle creait
// un ecart apparent M1/M2 de ~15 m au preset -> FB_WinchSync SafeStop -> Fault.Latched.
M1Demand.UseDynamicTarget := FALSE;
M2Demand.UseDynamicTarget := FALSE;
M2Demand.DynamicTarget_M  := 0.0;

ClimbTimer(IN := (SeqStep = E_MachineHomingTxState.HX2_CLIMB) AND (Cfg.CfgTimeoutClimb > T#0s),
           PT := Cfg.CfgTimeoutClimb);
HomeAxesTimer(IN := (SeqStep = E_MachineHomingTxState.HX3_HOME_AXES) AND (Cfg.CfgTimeoutHomeAxes > T#0s),
              PT := Cfg.CfgTimeoutHomeAxes);
{endregion}

{region "§8 GRAFCET de referencement machine (CASE SeqStep)"}
// === §8 GRAFCET (CASE SeqStep) ======================================
// Carte des steps HX0..HX6 + HXF, actions et receptivites : voir
//   DOC/AF/AF_Partie-09_Fonction_Encoder_v2.4.md (F09.08 - cycle de homing machine).
// Chaque arme du CASE porte 1 ligne de rappel ; la source de verite reste l'AF.
// ====================================================================
CASE SeqStep OF

    E_MachineHomingTxState.HX0_REPOS:
        // Etape initiale pure : aucune action de sortie ici.
        // HT0 : lancement explicite (commande IHM / motif 3 appuis) OU perte de datum OU
        // auto (machine non referencee en maintenance N1/N2). Vers HX1 = annonce + choix,
        // AUCUN mouvement. CommitPublished N'est PAS efface ici (fait a HT1b, cf. glitch).
        // Garde MES : seul le bouton IHM dedie (StartEdge) peut RE-referencer une machine
        // deja homed. Les gestes indirects (3 appuis BP joystick, auto-armement) sont
        // ignores si M1 ET M2 sont deja references -> evite le passage en homing pendant
        // un travail benne en MAINT (appuis repetes du BP homme-mort).
        // D : la perte de datum ne RELANCE le cycle que si un CODEUR a reellement perdu sa
        // reference (NOT BothAxesHomed). Une simple invalidation de l'offset benne
        // (ActiveOffsetValid -> MachineHomed FALSE) ne doit PAS reproposer le homing : elle
        // se traite par une reconfirmation position benne, pas par un cycle machine.
        IF (StartEdge.Q
            OR ((ExplicitValidationPulse OR AutoArmTimer.Q) AND NOT BothAxesHomed)
            OR (MachineWasHomed AND NOT MachineHomedRaw AND NOT BothAxesHomed))
           AND ((Mode = E_Mode.MAINT_N1) OR (Mode = E_Mode.MAINT_N2)) THEN
            HomeReqDone := FALSE;
            SeqStep     := E_MachineHomingTxState.HX1_CHOICE;
        END_IF;

    E_MachineHomingTxState.HX1_CHOICE:
        // Annonce + choix. Aucun ordre mouvement (garanti par la RAZ de tete de scan).
        // Retour HX0 si le datum redevient valide (recuperation transitoire) ou si on
        // quitte la maintenance. Le referencement (mouvement) exige MAINT_N2.
        IF MachineHomed
           OR ((Mode <> E_Mode.MAINT_N1) AND (Mode <> E_Mode.MAINT_N2)) THEN
            SeqStep := E_MachineHomingTxState.HX0_REPOS;
        ELSIF ExplicitValidationPulse AND (Mode = E_Mode.MAINT_N2) THEN
            CommitPublished := FALSE;   // datum invalide tant qu'il est refait (HT1b, deplace de HX0)
            CommitDone      := FALSE;
            IF NOT TopPositionSensor THEN
                SeqStep := E_MachineHomingTxState.HX2_CLIMB;
            ELSE
                SeenNeutral := NOT JoystickDeflected;
                SeqStep     := E_MachineHomingTxState.HX2N_NEUTRAL;
            END_IF;
        END_IF;
        // HT1a (abandon) traite par la purge §4 sur front Reset.

    E_MachineHomingTxState.HX2_CLIMB:
        // Montee couplee M1+M2 palier 1, uniquement sous permis maintenu (manche tire).
        IF ClimbPermit THEN
            CmdWinchM1.RunRequest := TRUE; CmdWinchM1.ReqAscent := TRUE; CmdWinchM1.StepTgt := CST_StepSlow;
            CmdWinchM2.RunRequest := TRUE; CmdWinchM2.ReqAscent := TRUE; CmdWinchM2.StepTgt := CST_StepSlow;
        END_IF;
        IF TransactionAbort THEN
            MachineHomingFailed := TRUE;
            SeqStep := E_MachineHomingTxState.HXF_FAILED;
        ELSIF TopPositionSensor THEN
            SeenNeutral := NOT JoystickDeflected;
            SeqStep     := E_MachineHomingTxState.HX2N_NEUTRAL;
        END_IF;

    E_MachineHomingTxState.HX2N_NEUTRAL:
        // Mouvement nul obligatoire entre montee (tire) et descente (pousse).
        IF NOT JoystickDeflected THEN
            SeenNeutral := TRUE;
        END_IF;
        IF TransactionAbort THEN
            MachineHomingFailed := TRUE;
            SeqStep := E_MachineHomingTxState.HXF_FAILED;
        ELSIF WinchesMechanicallyStopped AND SeenNeutral AND DescendPermit
              AND TopPositionSensor THEN
            HomeReqDone := FALSE;
            SeqStep     := E_MachineHomingTxState.HX3_HOME_AXES;
        END_IF;

    E_MachineHomingTxState.HX3_HOME_AXES:
        // Descente couplee M1+M2 palier 1 sous permis maintenu (manche pousse).
        IF DescendPermit THEN
            CmdWinchM1.RunRequest := TRUE; CmdWinchM1.ReqDescend := TRUE; CmdWinchM1.StepTgt := CST_StepSlow;
            CmdWinchM2.RunRequest := TRUE; CmdWinchM2.ReqDescend := TRUE; CmdWinchM2.StepTgt := CST_StepSlow;
        END_IF;
        // Homing des AXES seulement, au vol, sur le front DESCENDANT du capteur.
        IF TopLostEdge.Q AND NOT HomeReqDone THEN
            M1Demand.HomeReq := TRUE;
            M2Demand.HomeReq := TRUE;
            HomeReqDone      := TRUE;
        END_IF;
        IF TransactionAbort THEN
            MachineHomingFailed := TRUE;
            SeqStep := E_MachineHomingTxState.HXF_FAILED;
        ELSIF NOT TopPositionSensor AND M1Status.HomedAndReliable AND M2Status.HomedAndReliable THEN
            SeenNeutral := NOT JoystickDeflected;
            SeqStep     := E_MachineHomingTxState.HX3N_PAUSE;
        END_IF;

    E_MachineHomingTxState.HX3N_PAUSE:
        // Arret avant benne : treuils + benne a 0 (RAZ tete de scan), retour au neutre.
        IF NOT JoystickDeflected THEN
            SeenNeutral := TRUE;
        END_IF;
        IF TransactionAbort THEN
            MachineHomingFailed := TRUE;
            SeqStep := E_MachineHomingTxState.HXF_FAILED;
        ELSIF WinchesMechanicallyStopped AND SeenNeutral THEN
            SeqStep := E_MachineHomingTxState.HX4_BUCKET_ADJUST;
        END_IF;

    E_MachineHomingTxState.HX4_BUCKET_ADJUST:
        // Benne palier 1 SANS FDC soft, 2 sens ; treuils a 0.
        IF BucketPermit AND JoystickPull THEN
            CmdBucketClose := TRUE;
        ELSIF BucketPermit AND JoystickPush THEN
            CmdBucketOpen := TRUE;
        END_IF;
        // Fail-safe : erreur codeur OU treuil qui flue hors phase OU sortie de MAINT_N2.
        IF AxisHomingError OR MotionOutOfPhase OR ModeLostDuringCycle THEN
            MachineHomingFailed := TRUE;
            SeqStep := E_MachineHomingTxState.HXF_FAILED;
        ELSIF ExplicitValidationPulse AND NOT JoystickDeflected AND WinchesMechanicallyStopped THEN
            PendingClose := TRUE;
            CommitDone   := FALSE;
            SeqStep      := E_MachineHomingTxState.HX5_BUCKET_COMMIT;
        END_IF;

    E_MachineHomingTxState.HX5_BUCKET_COMMIT:
        // Commit atomique de l'etat benne : impulsion 1 scan garantie via CommitDone.
        IF AxisHomingError OR NOT BothAxesHomed OR MotionOutOfPhase OR ModeLostDuringCycle THEN
            MachineHomingFailed := TRUE;
            SeqStep := E_MachineHomingTxState.HXF_FAILED;
        ELSIF NOT CommitDone THEN
            BucketCommit.CommitClose := PendingClose;
            CommitPublished          := TRUE;
            CommitDone               := TRUE;
        ELSE
            PendingClose := FALSE;
            SeqStep      := E_MachineHomingTxState.HX6_HOMED;
        END_IF;

    E_MachineHomingTxState.HX6_HOMED:
        // MachineHomed calcule en §9. Retour immediat a l'etape initiale.
        SeqStep := E_MachineHomingTxState.HX0_REPOS;

    E_MachineHomingTxState.HXF_FAILED:
        // Sortie uniquement sur front Reset conscient (purge §4).
        ;

END_CASE;
{endregion}

{region "§9 Cycle de vie & qualification de sortie"}
// === §9 CYCLE DE VIE + QUALIFICATION ================================
CycleRunning := (SeqStep <> E_MachineHomingTxState.HX0_REPOS)
             AND (SeqStep <> E_MachineHomingTxState.HX1_CHOICE);
// Verrou translation : interdite des qu'on quitte l'etape initiale (calcul post-CASE : sans retard).
// Verrou translation : actif uniquement quand le cycle est reellement engage
// (HX2..HX6), pas en HX1 (annonce + choix, aucun mouvement) qui peut s'armer seul
// apres une perte de datum. Consomme par PRG_05 (M3_SafeStop_Aggregate).
M3Locked             := CycleRunning;
MachineHomingActive  := CycleRunning;
Lifecycle.Busy       := CycleRunning;
Lifecycle.Done       := CommitPublished AND (SeqStep = E_MachineHomingTxState.HX0_REPOS);
MachineHomingSeqStep := SeqStep;

// Qualification de sortie — calcul UNIQUE, apres le deroule GRAFCET (§8).
CommitOrOffsetValid := CommitPublished OR BucketOffsetValid;
MachineHomed := BothAxesHomed AND CommitOrOffsetValid
                AND NOT MachineHomingFailed AND NOT ReHomingAckRequired
                AND NOT Fault.Latched;
{endregion}

{region "§10 Guide operateur — echelle de priorite (IF/ELSIF, pas un dispatch d'etat)"}
// === §10 GUIDE OPERATEUR (echelle de priorite) ======================
// MachineHomingStep est RECALCULE chaque scan a partir des conditions courantes :
// l'etape est le resultat, pas l'etat ou l'on dispatche. La vraie machine a etats
// est le GRAFCET (§8, CASE SeqStep). Precedent : FB_Modes.st (echelle IF/ELSIF).
IF Fault.Latched THEN
    MachineHomingStep := E_MachineHomingStep.FAILED;
    MachineHomingInstruction := 'Erreur ou Echec homing - Acquitter (Reset)';
ELSIF MachineHomingFailed OR (SeqStep = E_MachineHomingTxState.HXF_FAILED) THEN
    MachineHomingStep := E_MachineHomingStep.FAILED;
    MachineHomingInstruction := 'HXF - Homing incomplet - Recommencer en N2';
ELSIF MachineHomingLossSafeStop THEN
    MachineHomingStep := E_MachineHomingStep.LOSS_SAFESTOP;
    MachineHomingInstruction := 'Reference perdue - Arret controle';
ELSIF MachineHomed AND NOT CycleRunning THEN
    // Machine referencee et cycle homing a l'arret : AUCUN message homing a l'IHM.
    // (les branches HXn ci-dessous ne s'appliquent qu'a un cycle en cours ou une
    //  reference absente / incomplete). Un defaut latche reste prioritaire (ci-dessus).
    MachineHomingStep := E_MachineHomingStep.VALID;
    MachineHomingInstruction := '';
ELSIF (SeqStep = E_MachineHomingTxState.HX2_CLIMB) THEN
    MachineHomingStep := E_MachineHomingStep.NEED_TOP_POSITION;
    MachineHomingInstruction := 'HX2 - RefHoming Tirer JOY palier 1 vers FDC haut';
ELSIF (SeqStep = E_MachineHomingTxState.HX2N_NEUTRAL) THEN
    MachineHomingStep := E_MachineHomingStep.NEED_MECHANICAL_STOP;
    MachineHomingInstruction := 'HX2N - RefHoming JOY au neutre puis pousser (descente)';
ELSIF (SeqStep = E_MachineHomingTxState.HX3_HOME_AXES) THEN
    MachineHomingStep := E_MachineHomingStep.HOMING_IN_PROGRESS;
    MachineHomingInstruction := 'HX3 - RefHoming Pousser JOY palier 1, homing M1/M2 au vol';
ELSIF (SeqStep = E_MachineHomingTxState.HX3N_PAUSE) THEN
    MachineHomingStep := E_MachineHomingStep.NEED_MECHANICAL_STOP;
    MachineHomingInstruction := 'HX3N - RefHoming JOY au neutre (arret avant benne)';
ELSIF (SeqStep = E_MachineHomingTxState.HX4_BUCKET_ADJUST) THEN
    MachineHomingStep := E_MachineHomingStep.AWAIT_BUCKET_CONFIRM;
    MachineHomingInstruction := 'HX4 - RefHoming Fermer benne puis valider (3 appuis JOY)';
ELSIF (SeqStep = E_MachineHomingTxState.HX5_BUCKET_COMMIT)
      OR (SeqStep = E_MachineHomingTxState.HX6_HOMED) THEN
    MachineHomingStep := E_MachineHomingStep.VALID;
    MachineHomingInstruction := 'HX5 - RefHoming Etat benne enregistre - fin homing';
ELSIF (SeqStep = E_MachineHomingTxState.HX1_CHOICE) THEN
    IF Mode <> E_Mode.MAINT_N2 THEN
        MachineHomingStep := E_MachineHomingStep.OFFSET_UNKNOWN;
        MachineHomingInstruction := 'HX1 - RefHoming Passer en MAINT_N2 pour referencer';
    ELSIF NOT TopPositionSensor THEN
        MachineHomingStep := E_MachineHomingStep.NEED_TOP_POSITION;
        MachineHomingInstruction := 'HX1 - RefHoming Valider (3 appuis JOY) pour lancer';
    ELSE
        MachineHomingStep := E_MachineHomingStep.AWAIT_BUCKET_CONFIRM;
        MachineHomingInstruction := 'HX1 - RefHoming Sur FDC haut - valider (3 appuis JOY)';
    END_IF;
ELSIF NOT M1Status.HomedAndReliable AND NOT M2Status.HomedAndReliable THEN
    MachineHomingStep := E_MachineHomingStep.BOTH_NOT_HOMED;
    MachineHomingInstruction := 'HX0 - RefHoming M1+M2 non ref - lancer (3 appuis JOY ou IHM)';
ELSIF NOT M1Status.HomedAndReliable THEN
    MachineHomingStep := E_MachineHomingStep.M1_NOT_HOMED;
    MachineHomingInstruction := 'HX0 - RefHoming M1 non ref - relancer le homing';
ELSIF NOT M2Status.HomedAndReliable THEN
    MachineHomingStep := E_MachineHomingStep.M2_NOT_HOMED;
    MachineHomingInstruction := 'HX0 - RefHoming M2 non ref - relancer le homing';
ELSIF NOT (CommitPublished OR BucketOffsetValid) THEN
    IF Mode <> E_Mode.MAINT_N2 THEN
        MachineHomingStep := E_MachineHomingStep.OFFSET_UNKNOWN;
        MachineHomingInstruction := 'HX0 - RefHoming Offset benne inconnu - passer en N2';
    ELSE
        MachineHomingStep := E_MachineHomingStep.AWAIT_BUCKET_CONFIRM;
        MachineHomingInstruction := 'HX0 - RefHoming Lancer le homing (etat benne)';
    END_IF;
ELSE
    MachineHomingStep := E_MachineHomingStep.VALID;
    MachineHomingInstruction := 'Reference machine valide';
END_IF;

// R9 : capture de l'etape APRES recalcul du guide, au front d'apparition du defaut latche.
IF LatchedEdge.Q THEN
    MachineHomingStepAtError := MachineHomingStep;
END_IF;

Ready := Enable AND NOT Fault.Latched;

// Garde 1er scan : bloque l'auto-armement tant que les statuts codeurs ne sont pas stables.
FirstScanDone := TRUE;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut"}
// 🔑 1. FRONTS ET CAUSES
ResetEdge(CLK := Reset);
StartEdge(CLK := StartCycle);
DeadmanArmedEdge(CLK := DeadmanArmed);
AbortEdge(CLK := AbortCycle);
SkipDrainEdge(CLK := SkipDrainRequest);
KoboldRiseEdge(CLK := KoboldImmersed);
KoboldFallEdge(CLK := KoboldImmersed);
JoyDeflectedEdge(CLK := JoystickDeflected);

// Config diving/extraction bornee (repli defaut interne si non reglee / valeur implausible).
// DiveStartMinM = altimetrie de lancement Kobold dans le referentiel M1_CablePosM
// (positif, ~7,5 m au FDC haut, decroissant a la descente). Plage plausible 0,5..8,0 m ;
// hors plage -> repli 4,0 m.
IF (DiveStartMinM >= 0.5) AND (DiveStartMinM <= 8.0) THEN
    DiveStartMinEff := DiveStartMinM;
ELSE
    DiveStartMinEff := 4.0;
END_IF;
RaiseOffBottomEff := SEL(CfgRaiseOffBottomM > 0.0, CST_RaiseOffBottomDefaultM, CfgRaiseOffBottomM);
CtrlAscentMaxStepEff := LIMIT(1, CfgCtrlAscentMaxStep, 2);

// ⏱️ Chronomètre du cycle : compte tant que le séquenceur est actif (Lifecycle.Busy).
// .ET = durée écoulée du cycle en cours ; figée dans LastCycleDuration à l'achèvement (X13).
CycleRunTimer(IN := Lifecycle.Busy, PT := T#12h);
CurrentCycleElapsed := CycleRunTimer.ET;

// Durée d'égouttage effective : config IHM si valide, sinon défaut interne.
DrainTimeEff := SEL(CfgDrainTime <= T#0s, CfgDrainTime, DrainingTime);

// ⏱️ Surveillance indépendante de la remontée lente de controle
// AX11_CTRL_ASCENT -> AX12_LOADED_ASCENT : TON de stabilisation palier lent.
StabilizationTimer(IN := (State = E_AutoCycleStep.AX11_CTRL_ASCENT), PT := CtrlAscentTimeout);

// ⏱️ AX5_KOBOLD_INIT : fenetre de confirmation du retour contacteur Kobold.
KoboldInitTimer(IN := (State = E_AutoCycleStep.AX5_KOBOLD_INIT), PT := CST_KoboldInitTimeout);

// 📏 Comparaison vitesse réelle M1/M2
SpeedMismatchMps := ABS(M1_MeasuredSpeedMps - M2_MeasuredSpeedMps);
SpeedMismatchActive := (State = E_AutoCycleStep.AX11_CTRL_ASCENT)
                       AND JoystickDeflected
                       AND (SpeedMismatchThresholdMps > 0.0)
                       AND (SpeedMismatchTimeout > T#0ms)
                       AND (SpeedMismatchMps > SpeedMismatchThresholdMps);
// AX11_CTRL_ASCENT -> AX_STAB : TON confirmation écart vitesse.
SpeedMismatchTimer(IN := SpeedMismatchActive, PT := SpeedMismatchTimeout);
SpeedMismatchConfirmed := SpeedMismatchTimer.Q;

// Tempo max d'étape (R5) — backstop durée d'état, lancé SEULEMENT si pilotage joystick actif.
// Xi -> AX_STAB sur dépassement. Réarmé à CHAQUE changement d'étape (IN=FALSE 1 scan) :
// chaque étape dispose de sa propre fenêtre StepMaxTimeout, la tempo n'est PAS cumulative
// sur l'ensemble du cycle (un cycle réel long ne tombe plus en AX_STAB intempestif).
StepMaxTimer(IN := (State = StepMaxPrevState)
                  AND JoystickDeflected
                  AND (State <> E_AutoCycleStep.AX0_REPOS)
                  AND (State <> E_AutoCycleStep.AX18_DONE_SYNC)
                  AND (State <> E_AutoCycleStep.AX_STAB)
                  AND (State <> E_AutoCycleStep.AX_DIVING_RETRY),
             PT := StepMaxTimeout);
StepMaxPrevState := State;

// Egouttage AX13 : TON gaté sur l'étape (remis à 0 hors AX13). Remplace l'ancien IN:=TRUE câblé
// qui pouvait laisser Q déjà vrai à l'entrée en AX13 (temps d'égouttage non respecté).
DrainingTimer(IN := (State = E_AutoCycleStep.AX13_DRAIN_PAUSE), PT := DrainTimeEff);

// GT-dive-retry (GEL Q11) : en AX5/AX6/AX7, erreur sequence Kobold (retour contacteur
// absent apres CST_KoboldInitTimeout) OU joystick relache (>= 200 ms, anti-rebond) OU
// palier applique <> 4 sur M1 ou M2 (feedback si cable) -> reprise AX_DIVING_RETRY
// (PAS un defaut latche).
RetryJoyReleaseTimer(IN := ((State = E_AutoCycleStep.AX5_KOBOLD_INIT)
                             OR (State = E_AutoCycleStep.AX6_SEARCH_IMMERSION)
                             OR (State = E_AutoCycleStep.AX7_SEARCH_BOTTOM))
                            AND NOT JoystickDeflected,
                     PT := T#200ms);
// Palier bloque SOUS 4 pendant la plongee : on TOLERE la rampe 1->4 (tempo contacteurs,
// GEL AX4) ; seul un blocage confirme > 4 s en AX5..AX7 declenche la reprise. Palier 5
// (> 4) est traite instantanement par la cause de defaut 8 (latche), pas ici.
PalierNot4Timer(IN := ((State = E_AutoCycleStep.AX5_KOBOLD_INIT)
                        OR (State = E_AutoCycleStep.AX6_SEARCH_IMMERSION)
                        OR (State = E_AutoCycleStep.AX7_SEARCH_BOTTOM))
                       AND JoystickDeflected
                       AND ( ((M1_SpeedStepApplied > 0) AND (M1_SpeedStepApplied < CST_StepDive))
                          OR ((M2_SpeedStepApplied > 0) AND (M2_SpeedStepApplied < CST_StepDive)) ),
                PT := T#5s);
DivingRetryTrig := ((State = E_AutoCycleStep.AX5_KOBOLD_INIT)
                     OR (State = E_AutoCycleStep.AX6_SEARCH_IMMERSION)
                     OR (State = E_AutoCycleStep.AX7_SEARCH_BOTTOM))
                   AND ( (KoboldInitTimer.Q AND NOT KoboldContactorFeedback)
                         OR RetryJoyReleaseTimer.Q
                         OR PalierNot4Timer.Q );

// Table des causes de défaut
instCauses[0].Active   := LimitLegalReached
                          AND ((State = E_AutoCycleStep.AX4_DESCEND_DIVING)
                            OR (State = E_AutoCycleStep.AX5_KOBOLD_INIT)
                            OR (State = E_AutoCycleStep.AX6_SEARCH_IMMERSION)
                            OR (State = E_AutoCycleStep.AX7_SEARCH_BOTTOM));
instCauses[0].Latching := TRUE;
instCauses[0].Texte    := 'Limite legale de profondeur atteinte pendant descente';

instCauses[1].Active   := WinchSyncError AND (State <> E_AutoCycleStep.AX0_REPOS) AND (State <> E_AutoCycleStep.AX_STAB);
instCauses[1].Latching := TRUE;
instCauses[1].Texte    := 'Desynchronisme treuils M1/M2 bloquant';

instCauses[2].Active   := SpeedMismatchConfirmed AND (State <> E_AutoCycleStep.AX0_REPOS) AND (State <> E_AutoCycleStep.AX_STAB);
instCauses[2].Latching := TRUE;
instCauses[2].Texte    := 'Ecart de vitesse M1/M2 confirme en montee';

instCauses[3].Active   := NOT HeartbeatIhmOk AND (State <> E_AutoCycleStep.AX0_REPOS) AND (State <> E_AutoCycleStep.AX_STAB);
instCauses[3].Latching := TRUE;
instCauses[3].Texte    := 'Perte communication IHM pendant cycle';

instCauses[4].Active   := StepMaxTimer.Q AND (State <> E_AutoCycleStep.AX_STAB);
instCauses[4].Latching := TRUE;
instCauses[4].Texte    := 'Depassement tempo maximale d etape (blocage mouvement)';

instCauses[5].Active   := (StabilizationTimer.Q OR (ABS(M1_CablePosM - M2_CablePosM) > CtrlAscentToleranceM))
                          AND (State = E_AutoCycleStep.AX11_CTRL_ASCENT);
instCauses[5].Latching := TRUE;
instCauses[5].Texte    := 'Defaut de stabilisation / tolerance ecart codeurs en remontee controle';

// Backstop anti-telescopage : ecart de position M1/M2 excessif pendant une phase
// reellement couplee. AX11 a deja son propre controle (instCauses[5]). Seuil grossier
// (0,50 m) : filet local si FB_SyncDeviation (PRG_04) ne coupe pas.
instCauses[6].Active   := (ABS(M1_CablePosM - M2_CablePosM) > CST_CoupledPosBacklashM)
                          AND JoystickDeflected
                          AND ((State = E_AutoCycleStep.AX4_DESCEND_DIVING)
                            OR (State = E_AutoCycleStep.AX5_KOBOLD_INIT)
                            OR (State = E_AutoCycleStep.AX6_SEARCH_IMMERSION)
                            OR (State = E_AutoCycleStep.AX7_SEARCH_BOTTOM)
                            OR (State = E_AutoCycleStep.AX9_RAISE_OFF_BOTTOM)
                            OR (State = E_AutoCycleStep.AX12_LOADED_ASCENT)
                            OR (State = E_AutoCycleStep.AX15C_DUMP_REPOSITION));
instCauses[6].Latching := TRUE;
instCauses[6].Texte    := 'Ecart de position M1/M2 excessif en phase couplee (anti-telescopage)';

// AX2 : pendant la translation vers P1 les treuils M1/M2 doivent RESTER au FDC
// logiciel haut (WinchesAtTopWindow, calcul PRG_03). S'ils quittent la fenetre
// -> defaut latche, sortie cycle (GEL SEMI_AUTO cause 7 / Q10).
instCauses[7].Active   := NOT WinchesAtTopWindow AND (State = E_AutoCycleStep.AX2_TRANSLATE_P1);
instCauses[7].Latching := TRUE;
instCauses[7].Texte    := 'Treuils M1/M2 hors FDC haut pendant la translation vers P1';

// GEL cause 8 : palier vitesse > 4 (palier 5) applique pendant la plongee. Le FB commande
// toujours CST_StepDive = 4 ; un palier 5 en retour feedback = anomalie aval -> defaut latche.
// (Un palier < 4 en retour est traite en reprise par GT-dive-retry, pas ici.)
instCauses[8].Active   := (((M1_SpeedStepApplied > CST_StepDive) OR (M2_SpeedStepApplied > CST_StepDive)))
                          AND ((State = E_AutoCycleStep.AX4_DESCEND_DIVING)
                            OR (State = E_AutoCycleStep.AX5_KOBOLD_INIT)
                            OR (State = E_AutoCycleStep.AX6_SEARCH_IMMERSION)
                            OR (State = E_AutoCycleStep.AX7_SEARCH_BOTTOM));
instCauses[8].Latching := TRUE;
instCauses[8].Texte    := 'Palier vitesse > 4 (palier 5) pendant la plongee - interdit';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
ErrorEdge(CLK := Fault.Error);
{endregion}

{region "§2 Gate securite & Bascule Mode"}
// 🛑 2. GATES DE SÉCURITÉ ET NEUTRALISATION
// Le mode SEMI_AUTO peut être sélectionné sous AU/défaut (FB_Modes), mais le cycle
// ne tourne JAMAIS sans puissance (PowerContactorEngaged) ni avec un codeur défaillant
// (EncoderFaultPresent) — les données de position invalides rendraient le Grafcet erroné.
IF NOT Enable OR NOT PowerContactorEngaged OR EncoderFaultPresent THEN
    WinchM1Cmd.RunRequest     := FALSE;
    WinchM1Cmd.ReqAscent      := FALSE;
    WinchM1Cmd.ReqDescend     := FALSE;
    WinchM1Cmd.StepTgt        := 0;

    WinchM2Cmd.RunRequest     := FALSE;
    WinchM2Cmd.ReqAscent      := FALSE;
    WinchM2Cmd.ReqDescend     := FALSE;
    WinchM2Cmd.StepTgt        := 0;

    TranslationCmd.ReqStart   := FALSE;
    TranslationCmd.PositionTgt  := 0;

    BucketCmd.ReqOpen         := FALSE;
    BucketCmd.ReqClose        := FALSE;
    BucketCmd.ReqKoboldMeasureEnable := FALSE;

    // Si on quitte le semi-auto alors qu'un cycle était en cours, on mémorise l'étape pour la pause
    IF (State <> E_AutoCycleStep.AX0_REPOS) AND (State <> E_AutoCycleStep.AX18_DONE_SYNC) AND (State <> E_AutoCycleStep.AX_STAB) THEN
        PausedState := State;
        WaitingResume := TRUE;
    END_IF;

    CycleStep            := State;
    CycleStateStr        := 'Cycle desactive : securite/codeur/mode';
    Ready                := FALSE;
    Lifecycle.Busy       := FALSE;
    Lifecycle.Done       := FALSE;
    SpeedMismatchTimer(IN := FALSE, PT := SpeedMismatchTimeout);
    SpeedMismatchMps := 0.0;
    SpeedMismatchActive := FALSE;
    SpeedMismatchConfirmed := FALSE;
    OperatorActionId := 0;
    IF EncoderFaultPresent THEN
        OperatorAction := 'Cycle non autorise : defaut codeur present. Reinitialiser le defaut codeur.';
    ELSE
        OperatorAction := 'Passer en mode Semi-Auto et engager la securite pour activer le cycle.';
    END_IF;
    ExpectedAxis := E_OperatorAxis.NONE;
    ExpectedDirection := 0;
    WaitingForOperator := FALSE;
    WaitingForProcess := FALSE;
    RequestActive := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;

// 🛡️ Gate continu homme-mort : le mouvement n'est autorisé que si le manche est
// défléchi (JoystickDeflected) ET l'homme-mort est armé (DeadmanArmed). Chaque
// commande de mouvement est gatée par ce permis à chaque scan (pas seulement au
// démarrage). Le séquenceur (transitions X0→X13) reste piloté par JoystickDeflected.
CycleMotionPermit := JoystickDeflected AND DeadmanArmed;

// Au retour en Semi-Auto, si une étape était en cours, on exige une reprise consciente
IF WaitingResume THEN
    // 🔒 Sécurité anti-redémarrage automatique (AF-04 §4.1) : le cycle ne reprend
    // PAS sur manche + homme-mort seuls. Il reste en attente d'un geste conscient
    // (StartCycle) avant de restaurer l'étape mémorisée.
    IF StartEdge.Q THEN
        State := PausedState;   // reprise consciente : restaure l'étape mémorisée
        WaitingResume := FALSE;
    ELSE
        // Hold : neutralise toute demande de mouvement et affiche l'attente.
        WinchM1Cmd.RunRequest := FALSE; WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := FALSE; WinchM1Cmd.StepTgt := 0;
        WinchM2Cmd.RunRequest := FALSE; WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := FALSE; WinchM2Cmd.StepTgt := 0;
        TranslationCmd.ReqStart := FALSE; TranslationCmd.PositionTgt := 0;
        BucketCmd.ReqOpen := FALSE; BucketCmd.ReqClose := FALSE; BucketCmd.ReqKoboldMeasureEnable := FALSE;
        CycleStep := PausedState;
        CycleStateStr := 'Cycle en pause : reprise consciente requise (StartCycle)';
        Lifecycle.Busy := FALSE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.BUTTON;
        ExpectedDirection := 0;
        WaitingForOperator := TRUE;
        WaitingForProcess := FALSE;
        OperatorActionId := 16#0400;
        OperatorAction := 'Reprendre le cycle : appuyer sur StartCycle (geste conscient).';
        RequestActive := FALSE;
    END_IF;
END_IF;

// 🧊 R9 — capture l'étape spécifique AVANT la bascule vers AX_STAB
IF ErrorEdge.Q THEN
    CycleStepAtError := State;
    State := E_AutoCycleStep.AX_STAB;
    WaitingResume := FALSE;   // un défaut abroge la reprise consciente : repli AX_STAB
END_IF;

// GT-dive-retry (GEL Q11) : reprise de plongee (PAS un defaut latche). Prioritaire
// apres le repli defaut : une vraie erreur (ErrorEdge) l'emporte.
IF DivingRetryTrig AND (State <> E_AutoCycleStep.AX_STAB) THEN
    State := E_AutoCycleStep.AX_DIVING_RETRY;
END_IF;

IF ResetEdge.Q THEN
    SavedState := E_AutoCycleStep.AX0_REPOS;
    BottomTouched := FALSE;
    IF State = E_AutoCycleStep.AX_STAB THEN
        State := E_AutoCycleStep.AX0_REPOS;
    END_IF;
END_IF;

// Gestion de l'Abandon explicite
IF AbortEdge.Q THEN
    State := E_AutoCycleStep.AX0_REPOS;
    WaitingResume := FALSE;
    PausedState := E_AutoCycleStep.AX0_REPOS;
END_IF;

// SEMI_AUTO : FB_CycleSemiAuto est le SEUL producteur des demandes benne. Les champs
// assistants (DiveSearch/ExtractionAssist) sont inactifs en cycle automatique
// -> valeurs neutres déterministes (identiques à la branche SEMI_AUTO de PRG_03).
BucketCmd.DescendPermitDiveBucketOpen := TRUE;
BucketCmd.ExtractionControlActive := FALSE;
BucketCmd.MinStepDown := 0;
{endregion}

{region "§3 Machine etat cycle automatique"}
// 🔁 2. LOGIQUE DU SÉQUENCEUR (Machine d'état) — CASE sur enum unique (R1)
// Pendant une reprise consciente (WaitingResume), le séquenceur est gelé :
// l'étape mémorisée ne s'exécute pas tant que StartCycle n'a pas été appuyé.
IF NOT WaitingResume THEN
CASE State OF

    E_AutoCycleStep.AX0_REPOS:
        CycleStep := E_AutoCycleStep.AX0_REPOS;
        CycleStateStr := 'AX0 - Verification coherence systeme';
        WinchM1Cmd.RunRequest := FALSE; WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := FALSE; WinchM1Cmd.StepTgt := 0;
        WinchM2Cmd.RunRequest := FALSE; WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := FALSE; WinchM2Cmd.StepTgt := 0;
        TranslationCmd.ReqStart := FALSE; TranslationCmd.PositionTgt := 0;
        BucketCmd.ReqOpen := FALSE; BucketCmd.ReqClose := FALSE; BucketCmd.ReqKoboldMeasureEnable := FALSE;
        Lifecycle.Busy := FALSE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.BUTTON;
        ExpectedDirection := 0;
        WaitingForOperator := TRUE;
        WaitingForProcess := FALSE;
        OperatorActionId := 16#0400;
        OperatorAction := 'AX0 - Demander le demarrage du cycle (Bouton IHM ou armement Homme-Mort).';
        SampleCountDone := FALSE;   // F2: réarmement du front de comptage à chaque entrée en X0
        BottomTouched   := FALSE;   // info fond touche effacee au repos

        // Transition si système sain et réarmé (front reset ou démarrage).
        // 🔫 D2 : démarrage par bouton IHM (StartEdge) OU armement homme-mort joystick
        IF (StartEdge.Q OR DeadmanArmedEdge.Q) AND NOT Fault.Latched THEN
            WaitingResume := FALSE;
            State := E_AutoCycleStep.AX1_INIT;
        END_IF;

    E_AutoCycleStep.AX1_INIT:
        CycleStep := E_AutoCycleStep.AX1_INIT;
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedDirection := 0;

        // AX1_INIT : verification des CONDITIONS INITIALES du cycle. AUCUN ordre de
        // mouvement, aucun referencement (datum M1/M2/benne = responsabilite exclusive
        // FB_CycleMachineHoming). Conditions : codeurs M1/M2 references, aucun defaut
        // latche, treuils au FDC logiciel haut (TopPositionSensor), et posture de depart
        // OK (InitPositionOk : chariot M3 PAS a droite de P1 + treuils dans la plage
        // +/- 0,4 m autour du FDC haut, calcul PRG_03 ; positionnement fin P1 = AX2).
        InitConditionsOk := HomedM1 AND HomedM2 AND NOT Fault.Latched
                            AND TopPositionSensor AND InitPositionOk;
        IF InitConditionsOk THEN
            CycleStateStr := 'AX1 - Conditions initiales OK';
            ExpectedAxis := E_OperatorAxis.NONE;
            WaitingForOperator := FALSE;
            WaitingForProcess := TRUE;
            OperatorActionId := 0;
            OperatorAction := '';
            State := E_AutoCycleStep.AX2_TRANSLATE_P1;   // franchie sans mouvement
        ELSIF NOT (HomedM1 AND HomedM2) THEN
            CycleStateStr := 'AX1 - Machine non referencee';
            ExpectedAxis := E_OperatorAxis.BUTTON;
            WaitingForOperator := TRUE;
            WaitingForProcess := FALSE;
            OperatorActionId := 16#0401;
            OperatorAction := 'AX1 - Machine non referencee : passer en maintenance pour le referencement.';
        ELSE
            CycleStateStr := 'AX1 - Conditions initiales non remplies';
            ExpectedAxis := E_OperatorAxis.BUTTON;
            WaitingForOperator := TRUE;
            WaitingForProcess := FALSE;
            OperatorActionId := 16#0401;
            OperatorAction := 'AX1 - Amener les treuils au FDC haut.';
        END_IF;

    E_AutoCycleStep.AX2_TRANSLATE_P1:
        CycleStep := E_AutoCycleStep.AX2_TRANSLATE_P1;
        CycleStateStr := 'AX2 - Mise en position P1 (translation)';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_X;
        // GEL SEMI_AUTO Q10 : le cycle n'emet AUCUNE commande M3 automatique (pas de
        // selection de cible). L'operateur pousse le joystick VERS LA DROITE et amene M3
        // a P1 ; ralenti PV + arret sur FDC P1 assures par PRG_05/FB_Translation (comme en
        // maintenance). Le cycle SURVEILLE en permanence que les treuils M1/M2 RESTENT au
        // FDC logiciel haut (WinchesAtTopWindow) : sortie sur defaut latche (cause 7) sinon.
        // Le controle "chariot pas a droite de P1" est fait en AX1_INIT, pas ici.
        WinchM1Cmd.RunRequest := FALSE; WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := FALSE; WinchM1Cmd.StepTgt := 0;
        WinchM2Cmd.RunRequest := FALSE; WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := FALSE; WinchM2Cmd.StepTgt := 0;
        TranslationCmd.PositionTgt := 3;          // repere P1 pour PRG_05 (info ; pas de pilotage cycle)

        IF Translation_At_P1 THEN
            ExpectedDirection := 0;
            WaitingForOperator := FALSE;
            WaitingForProcess := TRUE;
            OperatorActionId := 16#0402;
            OperatorAction := 'AX2 - Position P1 atteinte.';
            TranslationCmd.ReqStart := FALSE;
            State := E_AutoCycleStep.AX3_OPEN_BUCKET;
        ELSE
            // Entre tremie et P1 : l'operateur pousse le joystick VERS LA DROITE (axe
            // Tremie--P2--P1--Maintenance : P1 est a droite de la tremie). Maintien requis ;
            // ralenti PV + arret FDC P1 assures par PRG_05. Transition sur P1 STABILISE.
            ExpectedDirection := 1;
            WaitingForOperator := NOT JoystickDeflected;
            WaitingForProcess := JoystickDeflected;
            OperatorActionId := 16#0402;
            OperatorAction := 'AX2 - Pousser le joystick vers la droite : arret automatique sur P1.';
            TranslationCmd.ReqStart := CycleMotionPermit;
        END_IF;

    E_AutoCycleStep.AX3_OPEN_BUCKET:
        CycleStep := E_AutoCycleStep.AX3_OPEN_BUCKET;
        CycleStateStr := 'AX3 - Ouverture benne';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := 0;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#0403;
        OperatorAction := 'AX3 - Joystick pousse : ouverture benne jusqu au FDC logiciel benne ouverte.';

        // X3 = etape benne seule : treuils explicitement neutralises (config treuil unique par etape).
        WinchM1Cmd.RunRequest := FALSE; WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := FALSE; WinchM1Cmd.StepTgt := 0;
        WinchM2Cmd.RunRequest := FALSE; WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := FALSE; WinchM2Cmd.StepTgt := 0;

        IF Benne_IsOpen THEN
            State := E_AutoCycleStep.AX4_DESCEND_DIVING;
        ELSE
            BucketCmd.ReqOpen := CycleMotionPermit;
            IF JoystickDeflected AND Benne_Done AND Benne_IsOpen THEN
                BucketCmd.ReqOpen := FALSE;
                State := E_AutoCycleStep.AX4_DESCEND_DIVING;
            END_IF;
        END_IF;

    (* ===================== DIVING (AX4..AX8 + AX_DIVING_RETRY) ===================== *)

    E_AutoCycleStep.AX4_DESCEND_DIVING:
        CycleStep := E_AutoCycleStep.AX4_DESCEND_DIVING;
        CycleStateStr := 'AX4 - Plongee couplee palier 4 jusqu a l altimetrie de lancement';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := -1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#0404;
        OperatorAction := 'AX4 - Maintenir la descente palier 4 (Kobold pas encore enclenche).';

        // Palier 4 MINI ET MAXI (CST_StepDive), palier 5 interdit (cause 8). Tempo
        // sequencement contacteurs conservee en aval (PRG_04 : montee progressive 1->4).
        // Contacteur Kobold PAS enclenche a cette etape.
        WinchM1Cmd.RunRequest := CycleMotionPermit;
        WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := TRUE;
        WinchM1Cmd.StepTgt  := CST_StepDive;
        WinchM2Cmd.RunRequest := CycleMotionPermit;
        WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := TRUE;
        WinchM2Cmd.StepTgt  := CST_StepDive;
        BucketCmd.ReqKoboldMeasureEnable := FALSE;

        // AT4 : altimetrie de lancement atteinte (M1 ET M2 <= DiveStartMinEff).
        IF JoystickDeflected
           AND (M1_CablePosM <= DiveStartMinEff) AND (M2_CablePosM <= DiveStartMinEff) THEN
            State := E_AutoCycleStep.AX5_KOBOLD_INIT;
        END_IF;

    E_AutoCycleStep.AX5_KOBOLD_INIT:
        CycleStep := E_AutoCycleStep.AX5_KOBOLD_INIT;
        CycleStateStr := 'AX5 - Activation contacteur Kobold au vol';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := -1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#0405;
        OperatorAction := 'AX5 - Maintenir la descente palier 4 : initialisation Kobold en cours.';

        // Descente palier 4 maintenue ; enclenche le contacteur Kobold et attend le retour.
        WinchM1Cmd.RunRequest := CycleMotionPermit;
        WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := TRUE;
        WinchM1Cmd.StepTgt  := CST_StepDive;
        WinchM2Cmd.RunRequest := CycleMotionPermit;
        WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := TRUE;
        WinchM2Cmd.StepTgt  := CST_StepDive;
        BucketCmd.ReqKoboldMeasureEnable := CycleMotionPermit;

        // AT5 : retour contacteur Kobold coherent -> recherche immersion.
        // (echec init / joystick relache / palier <> 4 -> AX_DIVING_RETRY via GT-dive-retry §1)
        IF JoystickDeflected AND KoboldContactorFeedback THEN
            State := E_AutoCycleStep.AX6_SEARCH_IMMERSION;
        END_IF;

    E_AutoCycleStep.AX6_SEARCH_IMMERSION:
        CycleStep := E_AutoCycleStep.AX6_SEARCH_IMMERSION;
        CycleStateStr := 'AX6 - Recherche entree dans l eau (front DI Kobold 0->1)';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := -1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#0406;
        OperatorAction := 'AX6 - Maintenir la descente palier 4 : entree dans l eau attendue.';

        WinchM1Cmd.RunRequest := CycleMotionPermit;
        WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := TRUE;
        WinchM1Cmd.StepTgt  := CST_StepDive;
        WinchM2Cmd.RunRequest := CycleMotionPermit;
        WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := TRUE;
        WinchM2Cmd.StepTgt  := CST_StepDive;
        BucketCmd.ReqKoboldMeasureEnable := CycleMotionPermit;

        // AT6 : front montant DI Kobold (immersion confirmee) -> recherche du fond.
        IF JoystickDeflected AND KoboldRiseEdge.Q THEN
            State := E_AutoCycleStep.AX7_SEARCH_BOTTOM;
        END_IF;

    E_AutoCycleStep.AX7_SEARCH_BOTTOM:
        CycleStep := E_AutoCycleStep.AX7_SEARCH_BOTTOM;
        CycleStateStr := 'AX7 - Recherche du fond (front DI Kobold 1->0)';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := -1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#0407;
        OperatorAction := 'AX7 - Maintenir la descente palier 4 sous l eau : detection du fond.';

        WinchM1Cmd.RunRequest := CycleMotionPermit;
        WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := TRUE;
        WinchM1Cmd.StepTgt  := CST_StepDive;
        WinchM2Cmd.RunRequest := CycleMotionPermit;
        WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := TRUE;
        WinchM2Cmd.StepTgt  := CST_StepDive;
        BucketCmd.ReqKoboldMeasureEnable := CycleMotionPermit;

        // AT7 : front descendant DI Kobold (ou retour dedie KoboldContactFond) = fond.
        IF JoystickDeflected AND (KoboldFallEdge.Q OR KoboldContactFond) THEN
            State := E_AutoCycleStep.AX8_BOTTOM_CONFIRMED;
        END_IF;

    E_AutoCycleStep.AX8_BOTTOM_CONFIRMED:
        CycleStep := E_AutoCycleStep.AX8_BOTTOM_CONFIRMED;
        CycleStateStr := 'AX8 - Fond confirme : coupure treuils, memorisation';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.NONE;
        ExpectedDirection := 0;
        WaitingForOperator := FALSE;
        WaitingForProcess := TRUE;
        OperatorActionId := 16#0408;
        OperatorAction := 'AX8 - Fond touche.';

        // Coupure INSTANTANEE de toutes les commandes treuils (meme scan) + Kobold coupe.
        WinchM1Cmd.RunRequest := FALSE; WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := FALSE; WinchM1Cmd.StepTgt := 0;
        WinchM2Cmd.RunRequest := FALSE; WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := FALSE; WinchM2Cmd.StepTgt := 0;
        BucketCmd.ReqKoboldMeasureEnable := FALSE;

        TouchPositionM := M1_CablePosM;
        BottomTouched  := TRUE;   // variable d'info latchee (GEL AX8) - effacee a AX0 / AX_STAB / Reset
        IF LimitLegalDepthM < -0.01 THEN
            RaiseTargetM := MAX(TouchPositionM + RaiseOffBottomEff, LimitLegalDepthM + RaiseOffBottomEff);
        ELSE
            RaiseTargetM := TouchPositionM + RaiseOffBottomEff;
        END_IF;
        State := E_AutoCycleStep.AX9_RAISE_OFF_BOTTOM;

    E_AutoCycleStep.AX_DIVING_RETRY:
        CycleStep := E_AutoCycleStep.AX_DIVING_RETRY;
        CycleStateStr := 'AX_DIVING_RETRY - Reprise plongee : remonter au FDC haut';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := 1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#0481;
        OperatorAction := 'AX_DIVING_RETRY - Reprise plongee : monter jusqu au FDC haut, puis relancer.';

        // Remontee assistee palier lent, Kobold coupe.
        WinchM1Cmd.RunRequest := CycleMotionPermit;
        WinchM1Cmd.ReqAscent := TRUE; WinchM1Cmd.ReqDescend := FALSE;
        WinchM1Cmd.StepTgt  := CST_StepSlow;
        WinchM2Cmd.RunRequest := CycleMotionPermit;
        WinchM2Cmd.ReqAscent := TRUE; WinchM2Cmd.ReqDescend := FALSE;
        WinchM2Cmd.StepTgt  := CST_StepSlow;
        BucketCmd.ReqKoboldMeasureEnable := FALSE;

        // AT-retry : treuils revenus au FDC haut -> nouvelle tentative de plongee.
        IF JoystickDeflected AND (WinchesAtTopWindow OR TopPositionSensor) THEN
            WinchM1Cmd.RunRequest := FALSE;
            WinchM2Cmd.RunRequest := FALSE;
            State := E_AutoCycleStep.AX4_DESCEND_DIVING;
        END_IF;

    (* ===================== EXTRACTION (AX9..AX12) ===================== *)

    E_AutoCycleStep.AX9_RAISE_OFF_BOTTOM:
        CycleStep := E_AutoCycleStep.AX9_RAISE_OFF_BOTTOM;
        CycleStateStr := 'AX9 - Retente les cables (palier 1), decollement du fond';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := 1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#0409;
        OperatorAction := 'AX9 - Maintenir la montee palier 1 : retente des cables, decollement du fond.';

        // Palier 1 (doux). Selecteur couplage BOTH/M1/M2 = garde cote PRG_04 (GEL Q15),
        // le sequenceur commande toujours les deux treuils symetriquement.
        WinchM1Cmd.RunRequest := CycleMotionPermit;
        WinchM1Cmd.ReqAscent := TRUE; WinchM1Cmd.ReqDescend := FALSE;
        WinchM1Cmd.StepTgt := CST_StepSlow;
        WinchM2Cmd.RunRequest := CycleMotionPermit;
        WinchM2Cmd.ReqAscent := TRUE; WinchM2Cmd.ReqDescend := FALSE;
        WinchM2Cmd.StepTgt := CST_StepSlow;

        IF JoystickDeflected AND (M1_CablePosM >= RaiseTargetM) AND (M2_CablePosM >= RaiseTargetM) THEN
            WinchM1Cmd.RunRequest := FALSE;
            WinchM2Cmd.RunRequest := FALSE;
            State := E_AutoCycleStep.AX10_CLOSE_BUCKET;
        END_IF;

    E_AutoCycleStep.AX10_CLOSE_BUCKET:
        CycleStep := E_AutoCycleStep.AX10_CLOSE_BUCKET;
        CycleStateStr := 'AX10 - Fermeture benne (tolerance a peu pres ferme)';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := 1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#040A;
        OperatorAction := 'AX10 - Maintenir la commande : fermeture de la benne.';

        // Etape benne seule : les DEUX treuils explicitement neutralises.
        WinchM1Cmd.RunRequest := FALSE; WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := FALSE; WinchM1Cmd.StepTgt := 0;
        WinchM2Cmd.RunRequest := FALSE; WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := FALSE; WinchM2Cmd.StepTgt := 0;
        BucketCmd.ReqClose := CycleMotionPermit;

        IF JoystickDeflected AND (Benne_Done AND (Benne_IsClosed OR Benne_IsRoughlyClosed)) THEN
            BucketCmd.ReqClose := FALSE;
            // C1e (GEL principe 4) : AX10 -> AX11 sans temps mort. M1+M2 lances le MEME
            // scan que la sortie AX10_CLOSE_BUCKET (pas de creux RunRequest a la frontiere).
            WinchM1Cmd.RunRequest := CycleMotionPermit;
            WinchM1Cmd.ReqAscent := TRUE; WinchM1Cmd.ReqDescend := FALSE;
            WinchM1Cmd.StepTgt  := CtrlAscentMaxStepEff;
            WinchM2Cmd.RunRequest := CycleMotionPermit;
            WinchM2Cmd.ReqAscent := TRUE; WinchM2Cmd.ReqDescend := FALSE;
            WinchM2Cmd.StepTgt  := CtrlAscentMaxStepEff;
            State := E_AutoCycleStep.AX11_CTRL_ASCENT;
        END_IF;

    E_AutoCycleStep.AX11_CTRL_ASCENT:
        CycleStep := E_AutoCycleStep.AX11_CTRL_ASCENT;
        CycleStateStr := 'AX11 - Remontee lente de controle';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := 1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#040B;
        OperatorAction := 'AX11 - Maintenir la montee de controle : palier et synchronisme.';

        // Palier max reglable IHM, borne [1..2] (defaut 1 / P1 ; P2 possible au besoin).
        WinchM1Cmd.RunRequest := CycleMotionPermit;
        WinchM1Cmd.ReqAscent := TRUE; WinchM1Cmd.ReqDescend := FALSE;
        WinchM1Cmd.StepTgt  := CtrlAscentMaxStepEff;
        WinchM2Cmd.RunRequest := CycleMotionPermit;
        WinchM2Cmd.ReqAscent := TRUE; WinchM2Cmd.ReqDescend := FALSE;
        WinchM2Cmd.StepTgt  := CtrlAscentMaxStepEff;

        IF JoystickDeflected
           AND (M1_CablePosM >= (TouchPositionM + CtrlAscentDistM))
           AND (M2_CablePosM >= (TouchPositionM + CtrlAscentDistM))
           AND (ABS(M1_CablePosM - M2_CablePosM) <= CtrlAscentToleranceM) THEN
            State := E_AutoCycleStep.AX12_LOADED_ASCENT;
        END_IF;

    E_AutoCycleStep.AX12_LOADED_ASCENT:
        CycleStep := E_AutoCycleStep.AX12_LOADED_ASCENT;
        CycleStateStr := 'AX12 - Remontee en charge';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := 1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#040C;
        OperatorAction := 'AX12 - Maintenir la montee en charge jusqu a la limite haute.';

        // Benne bien fermee -> palier 4 ; benne mal fermee (a peu pres) -> palier 1.
        // Pas de ralentissement 1 m avant la position top (montee franche).
        WinchM1Cmd.RunRequest := CycleMotionPermit;
        WinchM1Cmd.ReqAscent := TRUE; WinchM1Cmd.ReqDescend := FALSE;
        WinchM1Cmd.StepTgt  := SEL(Benne_IsClosed, CST_StepSlow, CST_StepLoaded);
        WinchM2Cmd.RunRequest := CycleMotionPermit;
        WinchM2Cmd.ReqAscent := TRUE; WinchM2Cmd.ReqDescend := FALSE;
        WinchM2Cmd.StepTgt  := SEL(Benne_IsClosed, CST_StepSlow, CST_StepLoaded);

        IF JoystickDeflected AND M1_CablePosM >= CableLimitM1AscentM THEN
            WinchM1Cmd.RunRequest := FALSE;
            WinchM2Cmd.RunRequest := FALSE;
            State := E_AutoCycleStep.AX13_DRAIN_PAUSE;
        END_IF;

    (* ===================== DECHARGE (AX13..AX18) ===================== *)

    E_AutoCycleStep.AX13_DRAIN_PAUSE:
        CycleStep := E_AutoCycleStep.AX13_DRAIN_PAUSE;
        CycleStateStr := 'AX13 - Egouttage du godet en cours';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.NONE;
        ExpectedDirection := 0;
        WaitingForOperator := FALSE;
        WaitingForProcess := TRUE;
        OperatorActionId := 16#0409;
        OperatorAction := 'AX13 - Egouttage : attendre la tempo ou appuyer sur "passer egouttage".';
        WinchM1Cmd.RunRequest := FALSE;
        WinchM2Cmd.RunRequest := FALSE;

        // Tempo d'egouttage armee/remise a zero en §1 (gate sur State = AX13, PT = DrainTimeEff).
        // Duree reglable IHM (CfgDrainTime) + bypass immediat (SkipDrainEdge).
        IF JoystickDeflected AND (DrainingTimer.Q OR SkipDrainEdge.Q) THEN
            State := E_AutoCycleStep.AX14_TRANSLATE_DUMP;
        END_IF;

    E_AutoCycleStep.AX14_TRANSLATE_DUMP:
        CycleStep := E_AutoCycleStep.AX14_TRANSLATE_DUMP;
        CycleStateStr := 'AX14 - Deplacement vers tremie (grille/crible libres)';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_X;
        ExpectedDirection := -1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#040A;
        OperatorAction := 'AX14 - Maintenir la translation vers la tremie de dechargement.';

        TranslationCmd.PositionTgt := 1; // Trémie
        TranslationCmd.ReqStart := CycleMotionPermit;

        IF JoystickDeflected AND Translation_At_Tremie THEN
            TranslationCmd.ReqStart := FALSE;
            State := E_AutoCycleStep.AX15A_DUMP_ARRIVE;
        END_IF;

    E_AutoCycleStep.AX15A_DUMP_ARRIVE:
        CycleStep := E_AutoCycleStep.AX15A_DUMP_ARRIVE;
        CycleStateStr := 'AX15a - Arrivee tremie : treuils arretes, attente ouverture';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := -1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#040B;
        OperatorAction := 'AX15a - A la tremie : deflechir vers le bas pour ouvrir la benne et vider.';

        // Config treuil UNIQUE : arret des deux treuils (aucune descente couplee ici).
        WinchM1Cmd.RunRequest := FALSE; WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := FALSE; WinchM1Cmd.StepTgt := 0;
        WinchM2Cmd.RunRequest := FALSE; WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := FALSE; WinchM2Cmd.StepTgt := 0;

        // Geste operateur (manche defleci) -> phase d'ouverture benne.
        IF JoystickDeflected THEN
            State := E_AutoCycleStep.AX15B_DUMP_OPEN;
        END_IF;

    E_AutoCycleStep.AX15B_DUMP_OPEN:
        CycleStep := E_AutoCycleStep.AX15B_DUMP_OPEN;
        CycleStateStr := 'AX15b - Vidage : ouverture benne pour vider le contenu, treuils arretes';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := -1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#040B;
        OperatorAction := 'AX15b - Maintenir : ouverture complete de la benne, vidage a la tremie.';

        // Config treuil UNIQUE : etape benne seule, les deux treuils neutralises
        // (plus de descente couplee M1+M2 simultanee a l'ouverture benne -> plus
        // d'ecart M1/M2 volontaire ni de faux SafeStop concordance contacteurs).
        WinchM1Cmd.RunRequest := FALSE; WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := FALSE; WinchM1Cmd.StepTgt := 0;
        WinchM2Cmd.RunRequest := FALSE; WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := FALSE; WinchM2Cmd.StepTgt := 0;

        BucketCmd.ReqOpen := CycleMotionPermit;

        // Option operateur (bit IHM) : descendre la benne dans la gueule de tremie
        // pour aider la vidange -> repositionnement couple M1+M2 (AX15C). Prioritaire
        // sur la fin de vidage.
        IF RepositionRequest THEN
            State := E_AutoCycleStep.AX15C_DUMP_REPOSITION;
        ELSIF JoystickDeflected AND Benne_Done AND Benne_IsOpen THEN
            BucketCmd.ReqOpen := FALSE;
            State := E_AutoCycleStep.AX18_DONE_SYNC;
        END_IF;

    E_AutoCycleStep.AX15C_DUMP_REPOSITION:
        CycleStep := E_AutoCycleStep.AX15C_DUMP_REPOSITION;
        CycleStateStr := 'AX15c - Repositionnement couple M1+M2 (aide vidange tremie)';
        Lifecycle.Busy := TRUE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_Y;
        ExpectedDirection := -1;
        WaitingForOperator := NOT JoystickDeflected;
        WaitingForProcess := JoystickDeflected;
        OperatorActionId := 16#040C;
        OperatorAction := 'AX15c - Descente couplee M1+M2 ; relacher l option pour reprendre le vidage.';

        // Descente couplee M1+M2, palier lent, sous homme-mort. Commandes SYMETRIQUES
        // (meme sens, meme palier) -> FB_SyncDeviation actif, pas d'ecart volontaire.
        WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := TRUE;
        WinchM1Cmd.RunRequest := CycleMotionPermit;
        WinchM1Cmd.StepTgt := CST_StepSlow;
        WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := TRUE;
        WinchM2Cmd.RunRequest := CycleMotionPermit;
        WinchM2Cmd.StepTgt := CST_StepSlow;

        // La benne reste ouverte pendant le repositionnement (on finit l'ouverture si besoin).
        BucketCmd.ReqOpen := CycleMotionPermit AND NOT Benne_IsOpen;

        // Retour a AX15B des que l'operateur relache l'option de repositionnement.
        IF NOT RepositionRequest THEN
            WinchM1Cmd.RunRequest := FALSE;
            WinchM2Cmd.RunRequest := FALSE;
            State := E_AutoCycleStep.AX15B_DUMP_OPEN;
        END_IF;

    E_AutoCycleStep.AX18_DONE_SYNC:
        CycleStep := E_AutoCycleStep.AX18_DONE_SYNC;
        CycleStateStr := 'AX18 - Passe terminee : aller en P1 pour recommencer';
        WinchM1Cmd.RunRequest := FALSE;
        WinchM2Cmd.RunRequest := FALSE;
        TranslationCmd.ReqStart := FALSE;
        Lifecycle.Done := TRUE;
        Lifecycle.Busy := FALSE;
        ExpectedAxis := E_OperatorAxis.JOYSTICK_X;
        ExpectedDirection := 1;
        WaitingForOperator := TRUE;
        WaitingForProcess := FALSE;
        OperatorActionId := 16#040D;
        OperatorAction := 'AX18 - Cycle termine. Aller en P1 (joystick vers la droite) pour recommencer.';

        // Compteur de prélèvements (RETAIN) + durée du cycle — F2: cadré par front (1 seul par cycle)
        IF NOT SampleCountDone THEN
            SampleCount := SampleCount + 1;
            LastCycleDuration := CurrentCycleElapsed;   // fige la durée du cycle qui vient de s'achever
            SampleCountDone := TRUE;
        END_IF;

        // Rebouclage DIRECT sur AX2_TRANSLATE_P1 (GEL Q14) : la machine est deja
        // referencee, la passe suivante enchaine sur la translation P1 (pas de retour AX0).
        // Relance sur StartCycle OU FRONT joystick (geste franc) - pas sur simple maintien,
        // pour que AX18 (Lifecycle.Done + msg) soit reellement observable / tracable.
        IF StartEdge.Q OR JoyDeflectedEdge.Q THEN
            SampleCountDone := FALSE;
            Lifecycle.Done := FALSE;
            State := E_AutoCycleStep.AX2_TRANSLATE_P1;
        END_IF;

    E_AutoCycleStep.AX_STAB:
        CycleStep := E_AutoCycleStep.AX_STAB;
        CycleStateStr := 'AX_STAB - Cycle en attente / stabilisation sur anomalie';
        WinchM1Cmd.RunRequest := FALSE; WinchM1Cmd.ReqAscent := FALSE; WinchM1Cmd.ReqDescend := FALSE;
        WinchM2Cmd.RunRequest := FALSE; WinchM2Cmd.ReqAscent := FALSE; WinchM2Cmd.ReqDescend := FALSE;
        TranslationCmd.ReqStart := FALSE;
        BucketCmd.ReqOpen := FALSE;
        BucketCmd.ReqClose := FALSE;
        BucketCmd.ReqKoboldMeasureEnable := FALSE;   // Coupure contacteur Kobold au repli defaut (0 ordre residuel)
        Lifecycle.Busy := FALSE;
        Lifecycle.Done := FALSE;
        ExpectedAxis := E_OperatorAxis.BUTTON;
        ExpectedDirection := 0;
        WaitingForOperator := TRUE;
        WaitingForProcess := FALSE;
        OperatorActionId := 16#0480;
        OperatorAction := 'AX_STAB - Cycle stabilise sur anomalie : acquitter le defaut pour reinitialiser.';

END_CASE;
END_IF;
{endregion}

{region "§4 Repli homme mort & Syntheses"}
// 🛑 Relâchement du manche (retour au centre) OU de l'homme-mort : neutralisation
// des demandes actives. Gate continu : aucune commande d'actionneur ne survit à la
// perte du permis opérateur (manche défléchi ET homme-mort armé).
IF Lifecycle.Busy AND NOT CycleMotionPermit THEN
    WinchM1Cmd.RunRequest := FALSE;
    WinchM2Cmd.RunRequest := FALSE;
    TranslationCmd.ReqStart := FALSE;
    BucketCmd.ReqOpen := FALSE;
    BucketCmd.ReqClose := FALSE;
    BucketCmd.ReqKoboldMeasureEnable := FALSE;
END_IF;

RequestActive := WinchM1Cmd.RunRequest OR WinchM2Cmd.RunRequest OR TranslationCmd.ReqStart OR BucketCmd.ReqOpen OR BucketCmd.ReqClose OR BucketCmd.ReqKoboldMeasureEnable; // Somme logique complete des demandes (contacteur Kobold inclus)
{endregion}

{region "§1 Acquisition temps"}
// 1. ACQUISITION DU TEMPS SYSTÈME
TimeCurrent := TIME();
{endregion}

{region "§2 Initialisation"}
// 2. INITIALISATION UNIQUE AU PREMIER CYCLE
IF NOT InitDone THEN
    TimeLast := TimeCurrent;
    InitDone := TRUE;
    CycleTimeS := DefaultValueS;
    RETURN;
END_IF;
{endregion}

{region "§3 Calcul delta"}
// 3. CALCUL DU DELTA EN MILLISECONDES
DeltaTimeMs := TIME_TO_UDINT(TimeCurrent - TimeLast);
{endregion}

{region "§4 Conversion, secours et bornage"}
// 4. CONVERSION EN SECONDES, AVEC DOUBLE BORNAGE DU DELTA
//
// TIME() est un compteur systeme 32 bits en millisecondes depuis le demarrage de
// l'automate. Il n'est PAS absolu : il reboucle a 0 tous les 2^32 ms (~49,7 jours).
// La soustraction TimeCurrent - TimeLast est modulo 2^32 : au passage du rebouclage,
// tant que l'ecart reel entre deux scans reste < 49,7 j (toujours vrai a 10 ms),
// DeltaTimeMs reste correct. Le rebouclage seul n'est donc pas le risque principal.
//
// Le vrai risque est un DeltaTimeMs REELLEMENT > CST_MaxCycleDeltaMs : reprise apres
// un online-change, sortie d'un point d'arret / pas-a-pas debug, ou fenetre du
// rebouclage TIME(). Le chien de garde tache (200 ms, sensibilite 1) borne deja les
// gels en fonctionnement ; ce plafond couvre les cas hors surveillance.
// Un dt aberrant publie tel quel donnerait un CycleTimeS enorme, propage en un seul
// scan dans les rampes de vitesse et les integrateurs de position/frein -> saut
// physique. Fail-safe : hors de la plage nominale (0 < dt <= plafond), on publie la
// valeur de secours DefaultValueS au lieu de l'artefact. Pas de redemarrage auto.
//
// Borne basse dt = 0 (anti-zero, ex. premier appel du scan) et borne haute
// dt > CST_MaxCycleDeltaMs (anti-artefact) partagent la meme branche de secours.
IF (DeltaTimeMs > 0) AND (DeltaTimeMs <= CST_MaxCycleDeltaMs) THEN
    CycleTimeS := UDINT_TO_REAL(DeltaTimeMs) / 1000.0;
ELSE
    CycleTimeS := DefaultValueS;
END_IF;
{endregion}

{region "§5 Archivage"}
// 5. ARCHIVAGE POUR LE PROCHAIN CYCLE
TimeLast := TimeCurrent;
{endregion}

{region "§1 Gate"}
// 🛑 1. GATE : Désactivation logique si Enable = FALSE
IF NOT Enable THEN
    Ready := FALSE;
    DeviceJoystick.State := E_Diag_State.DISABLED;
    DeviceJoystick.Online := FALSE;
    DeviceJoystick.Operational := FALSE;
    DeviceJoystick.Error := FALSE;
    DeviceJoystick.ErrorId := 16#0000;
    DeviceCanOpenMaster.State := E_Diag_State.DISABLED;
    DeviceCanOpenMaster.Online := FALSE;
    DeviceCanOpenMaster.Operational := FALSE;
    DeviceCanOpenMaster.Error := FALSE;
    DeviceCanOpenMaster.ErrorId := 16#0000;
    RETURN;
END_IF;

Ready := TRUE;
{endregion}

{region "§2 Interprétation valeurs brutes"}
// 🧮 2. INTERPRÉTATION DES VALEURS BRUTES
CANbusOnlineReal         := (CANbusStateRaw = 2);
DeviceJoystickOnlineReal := (DeviceJoystickStateRaw = DEVICE_STATE.RUNNING);

CANbusOnlineEff          := CANbusOnlineReal OR SimBypassActive OR NetworkBypassActive OR CanBusBypassActive;
DeviceJoystickOnlineEff  := DeviceJoystickOnlineReal OR SimBypassActive OR NetworkBypassActive OR JoystickBypassActive;
{endregion}

{region "§3 Reset front"}
// 🔑 3. RESET FRONT — Efface les défauts si la cause a disparu
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    IF (CANbusOnlineEff AND DeviceJoystickOnlineEff) THEN
        DeviceJoystick.ErrorId := 16#0000;
        DeviceJoystick.StateAtError := E_Diag_State.DISABLED;
    END_IF;
END_IF;
{endregion}

{region "§4 Diagnostic joystick"}
// 🔍 4. DIAGNOSTIC JOYSTICK
// Bit 0 : Perte de communication CAN
IF NOT CANbusOnlineEff THEN
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId OR 16#0001;  (* Perte liaison CAN joystick *)
ELSE
    DeviceJoystick.Online := TRUE;
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId AND 16#FFFE; (* Effacement auto si la liaison revient *)
END_IF;

// Bit 1 : Mode non-opérationnel (esclave CANopen en pré-op ou défaut)
IF NOT DeviceJoystickOnlineEff THEN
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId OR 16#0002;  (* Joystick pas opérationnel *)
    DeviceJoystick.Operational := FALSE;
ELSE
    DeviceJoystick.Operational := TRUE;
    DeviceJoystick.ErrorId := DeviceJoystick.ErrorId AND 16#FFFD; (* Effacement auto dès que RUNNING *)
END_IF;
{endregion}

{region "§5 Machine etat joystick"}
// 🚦 5. MACHINE D'ÉTAT JOYSTICK
IF DeviceJoystick.ErrorId <> 0 THEN
    DeviceJoystick.State := E_Diag_State.ERROR;
ELSIF NOT (DeviceJoystick.Online AND DeviceJoystick.Operational) THEN
    DeviceJoystick.State := E_Diag_State.INIT;
ELSIF (SimBypassActive OR NetworkBypassActive OR JoystickBypassActive) AND NOT (CANbusOnlineReal AND DeviceJoystickOnlineReal) THEN
    DeviceJoystick.State := E_Diag_State.SIMULATED;
ELSE
    DeviceJoystick.State := E_Diag_State.READY;
END_IF;
{endregion}

{region "§6 Sorties globales"}
// 📤 6. SORTIES GLOBALES
DeviceJoystick.Error := (DeviceJoystick.ErrorId <> 0);

DeviceCanOpenMaster.Operational := CANbusOnlineEff;
DeviceCanOpenMaster.Online := CANbusOnlineEff;
DeviceCanOpenMaster.Error := NOT CANbusOnlineEff;

IF NOT CANbusOnlineEff THEN
    DeviceCanOpenMaster.ErrorId := 16#0001;
    DeviceCanOpenMaster.State := E_Diag_State.ERROR;
    IF DeviceCanOpenMaster.StateAtError = E_Diag_State.DISABLED THEN
        DeviceCanOpenMaster.StateAtError := E_Diag_State.INIT;
    END_IF;
ELSIF (SimBypassActive OR NetworkBypassActive OR CanBusBypassActive) AND NOT CANbusOnlineReal THEN
    DeviceCanOpenMaster.ErrorId := 16#0000;
    DeviceCanOpenMaster.State := E_Diag_State.SIMULATED;
ELSE
    DeviceCanOpenMaster.ErrorId := 16#0000;
    DeviceCanOpenMaster.State := E_Diag_State.READY;
END_IF;
{endregion}

{region "§1 Gate de desactivation"}
// 🛑 1. GATE : Désactivation si Enable = FALSE
IF NOT Enable THEN
    Ready := FALSE;
    DeviceVariateur.State := E_Diag_State.DISABLED;
    DeviceEncoderM1.State := E_Diag_State.DISABLED;
    DeviceEncoderM2.State := E_Diag_State.DISABLED;
    DeviceVariateur.Online := FALSE;
    DeviceEncoderM1.Online := FALSE;
    DeviceEncoderM2.Online := FALSE;
    DeviceVariateur.Operational := FALSE;
    DeviceEncoderM1.Operational := FALSE;
    DeviceEncoderM2.Operational := FALSE;
    DeviceVariateur.Error := FALSE;
    DeviceEncoderM1.Error := FALSE;
    DeviceEncoderM2.Error := FALSE;
    DeviceEthercatMaster.State := E_Diag_State.DISABLED;
    DeviceEthercatMaster.Online := FALSE;
    DeviceEthercatMaster.Operational := FALSE;
    DeviceEthercatMaster.Error := FALSE;
    DeviceEthercatMaster.ErrorId := 16#0000;
    RETURN;
END_IF;

Ready := TRUE;

{endregion}

{region "§2 Interpretation etats bruts et bypass"}
// 🧮 2. INTERPRÉTATION DES VALEURS BRUTES
VariateurOnlineReal := (DeviceVariateurStateRaw = DEVICE_STATE.RUNNING);
EncoderM1OnlineReal := (DeviceEncoderM1StateRaw = DEVICE_STATE.RUNNING);
EncoderM2OnlineReal := (DeviceEncoderM2StateRaw = DEVICE_STATE.RUNNING);

VariateurBypass := DeviceVariateurSimBypass OR NetworkBypassActive OR VariateurBypassActive;
EncoderM1Bypass := DeviceEncoderM1SimBypass OR NetworkBypassActive OR EncoderM1BypassActive;
EncoderM2Bypass := DeviceEncoderM2SimBypass OR NetworkBypassActive OR EncoderM2BypassActive;

VariateurOnlineEff := VariateurOnlineReal OR VariateurBypass;
EncoderM1OnlineEff := EncoderM1OnlineReal OR EncoderM1Bypass;
EncoderM2OnlineEff := EncoderM2OnlineReal OR EncoderM2Bypass;

// 🔑 3. RESET FRONT
ResetEdge(CLK := Reset);

{endregion}

{region "§3 Diagnostic par equipement"}
// 🔍 4. DIAGNOSTIC VARIATEUR (AC600_ECAT_Drive / Translation M3)
DeviceVariateur.Online := VariateurOnlineEff;
DeviceVariateur.Operational := VariateurOnlineEff;

IF NOT DeviceVariateur.Online THEN
    DeviceVariateur.ErrorId := DeviceVariateur.ErrorId OR 16#0010;  (* Perte liaison physique variateur *)
ELSE
    DeviceVariateur.ErrorId := DeviceVariateur.ErrorId AND 16#FFEF; (* Effacement auto dès que RUNNING *)
END_IF;

// 🔍 5. DIAGNOSTIC ENCODEUR M1 (COD1_CODEUR / WinchM1)
DeviceEncoderM1.Online := EncoderM1OnlineEff;
DeviceEncoderM1.Operational := EncoderM1OnlineEff;

IF NOT DeviceEncoderM1.Online THEN
    DeviceEncoderM1.ErrorId := DeviceEncoderM1.ErrorId OR 16#0020;  (* Perte liaison encodeur M1 *)
ELSE
    DeviceEncoderM1.ErrorId := DeviceEncoderM1.ErrorId AND 16#FFDF; (* Effacement auto dès que RUNNING *)
END_IF;

// 🔍 6. DIAGNOSTIC ENCODEUR M2 (COD2_CODEUR / WinchM2)
DeviceEncoderM2.Online := EncoderM2OnlineEff;
DeviceEncoderM2.Operational := EncoderM2OnlineEff;

IF NOT DeviceEncoderM2.Online THEN
    DeviceEncoderM2.ErrorId := DeviceEncoderM2.ErrorId OR 16#0030;  (* Perte liaison encodeur M2 *)
ELSE
    DeviceEncoderM2.ErrorId := DeviceEncoderM2.ErrorId AND 16#FFCF; (* Effacement auto dès que RUNNING *)
END_IF;

{endregion}

{region "§4 Etats diagnostic par equipement"}
// 🚦 7. STATE MACHINES DE CHAQUE APPAREIL
IF DeviceVariateur.ErrorId <> 0 THEN
    DeviceVariateur.State := E_Diag_State.ERROR;
ELSIF NOT VariateurOnlineEff THEN
    DeviceVariateur.State := E_Diag_State.INIT;
ELSIF VariateurBypass AND NOT VariateurOnlineReal THEN
    DeviceVariateur.State := E_Diag_State.SIMULATED;
ELSE
    DeviceVariateur.State := E_Diag_State.READY;
END_IF;

IF DeviceEncoderM1.ErrorId <> 0 THEN
    DeviceEncoderM1.State := E_Diag_State.ERROR;
ELSIF NOT EncoderM1OnlineEff THEN
    DeviceEncoderM1.State := E_Diag_State.INIT;
ELSIF EncoderM1Bypass AND NOT EncoderM1OnlineReal THEN
    DeviceEncoderM1.State := E_Diag_State.SIMULATED;
ELSE
    DeviceEncoderM1.State := E_Diag_State.READY;
END_IF;

IF DeviceEncoderM2.ErrorId <> 0 THEN
    DeviceEncoderM2.State := E_Diag_State.ERROR;
ELSIF NOT EncoderM2OnlineEff THEN
    DeviceEncoderM2.State := E_Diag_State.INIT;
ELSIF EncoderM2Bypass AND NOT EncoderM2OnlineReal THEN
    DeviceEncoderM2.State := E_Diag_State.SIMULATED;
ELSE
    DeviceEncoderM2.State := E_Diag_State.READY;
END_IF;

{endregion}

{region "§5 Synthese EtherCAT et sorties"}
// 📤 8. RÉSUMÉ ET DÉFAUTS
DeviceVariateur.Error := (DeviceVariateur.ErrorId <> 0);
DeviceEncoderM1.Error := (DeviceEncoderM1.ErrorId <> 0);
DeviceEncoderM2.Error := (DeviceEncoderM2.ErrorId <> 0);

DeviceEthercatMaster.Online := (VariateurOnlineEff AND EncoderM1OnlineEff AND EncoderM2OnlineEff) OR NetworkBypassActive OR EcatBusBypassActive;
DeviceEthercatMaster.Operational := DeviceEthercatMaster.Online;
DeviceEthercatMaster.Error := NOT DeviceEthercatMaster.Operational;

IF DeviceEthercatMaster.Error THEN
    DeviceEthercatMaster.ErrorId := 16#0001;
    DeviceEthercatMaster.State := E_Diag_State.ERROR;
ELSIF (VariateurBypass OR EncoderM1Bypass OR EncoderM2Bypass OR EcatBusBypassActive) THEN
    DeviceEthercatMaster.ErrorId := 16#0000;
    DeviceEthercatMaster.State := E_Diag_State.SIMULATED;
ELSE
    DeviceEthercatMaster.ErrorId := 16#0000;
    DeviceEthercatMaster.State := E_Diag_State.READY;
END_IF;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Gate"}
// 🛑 Sans Enable, aucune valeur mémorisée ne peut déclarer l'IHM valide.
IF NOT Enable THEN
    HeartbeatIhmOk := FALSE;
    HeartbeatIhmTimeout := TRUE;
    TglHeartbeatPlc := FALSE;
    TimeSinceIhmEdge := T#0s;
    LastIhmToggle := TglHeartbeatIhm;
    IhmEdgeSeen := FALSE;
    IhmTimeoutTon(IN := FALSE, PT := IhmTimeout);
    PlcToggleTon(IN := FALSE, PT := PlcTogglePeriod);
    RETURN;
END_IF;
{endregion}

{region "§2 Front IHM"}
// 📥 Front par comparaison : l'IHM écrit un BOOL toggle, pas une impulsion courte.
IhmEdgeDetected := (TglHeartbeatIhm <> LastIhmToggle);
LastIhmToggle := TglHeartbeatIhm;
IF IhmEdgeDetected THEN
    IhmEdgeSeen := TRUE;
END_IF;
{endregion}

{region "§3 Timeout IHM"}
// ⏱️ Le timer repart à chaque front. Au boot, il atteint le timeout au bout de IhmTimeout.
// HeartbeatIhmOk reste TRUE tant que le timeout n'est pas expiré (boot propre sans alarme au scan 1).
IhmTimeoutTon(IN := NOT IhmEdgeDetected, PT := IhmTimeout);
TimeSinceIhmEdge := IhmTimeoutTon.ET;
HeartbeatIhmTimeout := IhmTimeoutTon.Q;
HeartbeatIhmOk := NOT HeartbeatIhmTimeout;
{endregion}

{region "§4 Clignotant PLC"}
// 💡 Clignotant PLC indépendant : information de vie pour l'IHM, jamais signal Signal Safety autonome.
PlcToggleTon(IN := NOT PlcToggleTon.Q, PT := PlcTogglePeriod);
IF PlcToggleTon.Q THEN
    TglHeartbeatPlc := NOT TglHeartbeatPlc;
END_IF;
{endregion}

{region "§1 Fronts, calculs et causes"}
ResetEdge(CLK := Reset);
KoboldRiseEdge(CLK := Inputs.KoboldImmersed);
KoboldFallEdge(CLK := Inputs.KoboldImmersed);

// Les valeurs par defaut du DUT couvrent l'appel sans configuration explicite.
// Le repli runtime protege aussi un appel avec une structure entierement nulle.
EffectiveDiveSpeedMin_Mps := Inputs.Config.DiveSpeedMin_Mps;
IF EffectiveDiveSpeedMin_Mps <= 0.0 THEN EffectiveDiveSpeedMin_Mps := 0.15; END_IF;
EffectiveTimeoutMargin := Inputs.Config.TimeoutMarginFactor;
IF EffectiveTimeoutMargin <= 0.0 THEN EffectiveTimeoutMargin := 1.5; END_IF;
EffectiveTimeoutMinCourse_M := Inputs.Config.TimeoutMinCourse_M;
IF EffectiveTimeoutMinCourse_M <= 0.0 THEN EffectiveTimeoutMinCourse_M := 1.0; END_IF;
EffectiveTimeoutMaxCourse_M := Inputs.Config.TimeoutMaxCourse_M;
IF EffectiveTimeoutMaxCourse_M < EffectiveTimeoutMinCourse_M THEN EffectiveTimeoutMaxCourse_M := 200.0; END_IF;
EffectiveSecToMs := Inputs.Config.SecToMs;
IF EffectiveSecToMs <= 0.0 THEN EffectiveSecToMs := 1000.0; END_IF;

ErrorCausePresent := (Inputs.CycleTime <= T#0ms)
                 OR (NOT Inputs.BypassPreconditions AND (
                       (Inputs.DiveStartMin_M < Inputs.ImmersionUpper_M)
                    OR (Inputs.ImmersionUpper_M <= Inputs.ImmersionLower_M)
                    OR (Inputs.ImmersionLower_M <= Inputs.LimitLegalDepthMin_M)
                    OR (Inputs.CableLimitAscent_M <= Inputs.ImmersionLower_M)));

ImmersionCourse_M := LIMIT(EffectiveTimeoutMinCourse_M,
                           Inputs.CableLimitAscent_M - Inputs.ImmersionLower_M,
                           EffectiveTimeoutMaxCourse_M);
BottomCourse_M := LIMIT(EffectiveTimeoutMinCourse_M,
                        Inputs.ImmersionLower_M - Inputs.LimitLegalDepthMin_M,
                        EffectiveTimeoutMaxCourse_M);
CalculatedImmersionTimeout := UDINT_TO_TIME(REAL_TO_UDINT(
    ImmersionCourse_M / EffectiveDiveSpeedMin_Mps * EffectiveTimeoutMargin * EffectiveSecToMs));
CalculatedBottomTimeout := UDINT_TO_TIME(REAL_TO_UDINT(
    BottomCourse_M / EffectiveDiveSpeedMin_Mps * EffectiveTimeoutMargin * EffectiveSecToMs));

IF (Outputs.StepState = E_DiveSearchState.SEARCHING_IMMERSION)
   AND Inputs.MotionRequestActive AND (Inputs.MotionDirection = -1) THEN
    ImmersionTimerAcc := ImmersionTimerAcc + Inputs.CycleTime;
    IF ImmersionTimerAcc >= CalculatedImmersionTimeout THEN TimeoutImmersionFault := TRUE; END_IF;
END_IF;

IF (Outputs.StepState = E_DiveSearchState.SEARCHING_BOTTOM)
   AND Inputs.MotionRequestActive AND (Inputs.MotionDirection = -1) THEN
    BottomTimerAcc := BottomTimerAcc + Inputs.CycleTime;
    IF BottomTimerAcc >= CalculatedBottomTimeout THEN TimeoutBottomFault := TRUE; END_IF;
END_IF;

IF ResetEdge.Q AND NOT ErrorCausePresent AND NOT Inputs.KoboldImmersed
   AND NOT Inputs.MotionRequestActive AND NOT (Inputs.CurrentSpeedStep > 4) THEN
    SeqErrorFault := FALSE;
    Palier5ForbiddenFault := FALSE;
    TimeoutImmersionFault := FALSE;
    TimeoutBottomFault := FALSE;
    ImmersionTimerAcc := T#0ms;
    BottomTimerAcc := T#0ms;
    ImmersionConfirmed := FALSE;
    Outputs.BottomTouchConfirmed := FALSE;
    Outputs.StepAtFault := E_DiveSearchState.WAIT_PRECONDITIONS;
    StepAtFaultCaptured := FALSE;
    Outputs.StepState := E_DiveSearchState.WAIT_PRECONDITIONS;
END_IF;

instCauses[0].Active := SeqErrorFault;
instCauses[0].Latching := TRUE;
instCauses[0].Texte := 'Incoherence sequence immersion Kobold';
instCauses[1].Active := ErrorCausePresent;
instCauses[1].Latching := TRUE;
instCauses[1].Texte := 'Parametrage invalide des seuils de plongee';
instCauses[2].Active := Palier5ForbiddenFault;
instCauses[2].Latching := TRUE;
instCauses[2].Texte := 'Palier 5 interdit pendant la mesure Kobold';
instCauses[3].Active := TimeoutImmersionFault;
instCauses[3].Latching := TRUE;
instCauses[3].Texte := 'Timeout recherche immersion Kobold';
instCauses[4].Active := TimeoutBottomFault;
instCauses[4].Latching := TRUE;
instCauses[4].Texte := 'Timeout recherche fond Kobold';

instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

ErrorEdge(CLK := Fault.Error);
IF ErrorEdge.Q AND NOT StepAtFaultCaptured THEN
    Outputs.StepAtFault := PrevState;
    StepAtFaultCaptured := TRUE;
ELSIF ResetEdge.Q AND NOT ErrorCausePresent AND NOT Inputs.KoboldImmersed
      AND NOT Inputs.MotionRequestActive AND NOT (Inputs.CurrentSpeedStep > 4) THEN
    Outputs.StepAtFault := E_DiveSearchState.WAIT_PRECONDITIONS;
END_IF;
{endregion}

{region "§2 Neutralisation et machine d'etat"}
IF NOT Enable OR NOT Inputs.PowerContactorEngaged THEN
    Ready := FALSE;
    Lifecycle.Busy := FALSE;
    Lifecycle.Done := FALSE;
    Outputs.DescendPermit := FALSE;
    Outputs.KoboldContactorCmd := FALSE;
    Outputs.BottomTouchConfirmed := FALSE;
    Outputs.StepState := E_DiveSearchState.WAIT_PRECONDITIONS;
    Outputs.OperatorActionId := 0;
    Outputs.OperatorAction := '';
    ImmersionConfirmed := FALSE;
    ImmersionTimerAcc := T#0ms;
    BottomTimerAcc := T#0ms;
    Outputs.MinStepDown := 0;
    PrevState := E_DiveSearchState.WAIT_PRECONDITIONS;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
Outputs.DescendPermit := FALSE;
Outputs.KoboldContactorCmd := FALSE;
Lifecycle.Busy := FALSE;
Lifecycle.Done := FALSE;
Outputs.OperatorActionId := 0;
Outputs.OperatorAction := '';

DescentActive := Inputs.MotionRequestActive AND (Inputs.MotionDirection = -1)
              AND ((Inputs.Mode = E_Mode.MAINT_N1) OR (Inputs.Mode = E_Mode.MAINT_N2))
              AND NOT (Inputs.CurrentSpeedStep > 4)
              AND NOT SeqErrorFault;

IF Fault.Error OR Fault.Latched THEN
    Outputs.StepState := E_DiveSearchState.ERROR_HOLD;
    Outputs.KoboldContactorCmd := FALSE;
    Outputs.OperatorActionId := 16#0180;
    Outputs.OperatorAction := 'Verifier les conditions puis rearmer avant une nouvelle plongee.';
ELSE
    CASE Outputs.StepState OF
        E_DiveSearchState.WAIT_PRECONDITIONS:
            IF NOT Inputs.BypassPreconditions
               AND (NOT Inputs.BucketIsOpen OR NOT Inputs.PositionsValid OR Inputs.KoboldImmersed
                    OR (Inputs.M1Position_M < Inputs.DiveStartMin_M)
                    OR (Inputs.M2Position_M < Inputs.DiveStartMin_M)) THEN
                Outputs.OperatorActionId := 16#0100;
                Outputs.OperatorAction := 'Verifier benne ouverte, positions et Kobold au repos.';
            ELSE
                Outputs.StepState := E_DiveSearchState.READY_TO_DESCEND;
            END_IF;

        E_DiveSearchState.READY_TO_DESCEND:
            Ready := TRUE;
            Outputs.OperatorActionId := 16#0101;
            Outputs.OperatorAction := 'Demander une descente pour rechercher le fond.';
            IF Inputs.MotionRequestActive AND (Inputs.MotionDirection = -1) THEN
                ImmersionTimerAcc := T#0ms;
                Outputs.StepState := E_DiveSearchState.SEARCHING_IMMERSION;
            END_IF;

        E_DiveSearchState.SEARCHING_IMMERSION:
            Lifecycle.Busy := TRUE;
            Outputs.DescendPermit := DescentActive;
            Outputs.KoboldContactorCmd := DescentActive;
            Outputs.OperatorActionId := 16#0102;
            Outputs.OperatorAction := 'Maintenir la descente : recherche immersion Kobold.';
            IF Inputs.CurrentSpeedStep > 4 THEN
                IF NOT StepAtFaultCaptured THEN
                    Outputs.StepAtFault := Outputs.StepState;
                    StepAtFaultCaptured := TRUE;
                END_IF;
                Palier5ForbiddenFault := TRUE;
            END_IF;
            IF KoboldRiseEdge.Q THEN
                IF (Inputs.M1Position_M <= Inputs.ImmersionUpper_M)
                   AND (Inputs.M1Position_M >= Inputs.ImmersionLower_M)
                   AND (Inputs.M2Position_M <= Inputs.ImmersionUpper_M)
                   AND (Inputs.M2Position_M >= Inputs.ImmersionLower_M) THEN
                    ImmersionConfirmed := TRUE;
                    BottomTimerAcc := T#0ms;
                    Outputs.StepState := E_DiveSearchState.SEARCHING_BOTTOM;
                ELSE
                    IF NOT StepAtFaultCaptured THEN
                        Outputs.StepAtFault := Outputs.StepState;
                        StepAtFaultCaptured := TRUE;
                    END_IF;
                    SeqErrorFault := TRUE;
                END_IF;
            ELSIF (Inputs.M1Position_M < Inputs.ImmersionLower_M)
               OR (Inputs.M2Position_M < Inputs.ImmersionLower_M) THEN
                IF NOT StepAtFaultCaptured THEN
                    Outputs.StepAtFault := Outputs.StepState;
                    StepAtFaultCaptured := TRUE;
                END_IF;
                SeqErrorFault := TRUE;
            END_IF;

        E_DiveSearchState.SEARCHING_BOTTOM:
            Lifecycle.Busy := TRUE;
            Outputs.DescendPermit := DescentActive;
            Outputs.KoboldContactorCmd := DescentActive;
            Outputs.OperatorActionId := 16#0103;
            Outputs.OperatorAction := 'Maintenir la descente : immersion validee, recherche du fond.';
            IF Inputs.CurrentSpeedStep > 4 THEN
                IF NOT StepAtFaultCaptured THEN
                    Outputs.StepAtFault := Outputs.StepState;
                    StepAtFaultCaptured := TRUE;
                END_IF;
                Palier5ForbiddenFault := TRUE;
            END_IF;
            IF KoboldFallEdge.Q AND ImmersionConfirmed THEN
                Outputs.BottomTouchConfirmed := TRUE;
                ImmersionConfirmed := FALSE;
                Outputs.KoboldContactorCmd := FALSE;
                Outputs.StepState := E_DiveSearchState.BOTTOM_CONFIRMED;
            END_IF;

        E_DiveSearchState.BOTTOM_CONFIRMED:
            Lifecycle.Done := TRUE;
            Outputs.KoboldContactorCmd := FALSE;
            Outputs.OperatorActionId := 16#0104;
            Outputs.OperatorAction := 'Fond detecte : demander la fermeture ou extraction.';

        E_DiveSearchState.ERROR_HOLD:
            Outputs.KoboldContactorCmd := FALSE;
    END_CASE;
END_IF;

IF DescentActive AND ((Outputs.StepState = E_DiveSearchState.SEARCHING_IMMERSION)
                   OR (Outputs.StepState = E_DiveSearchState.SEARCHING_BOTTOM)) THEN
    Outputs.MinStepDown := LIMIT(0, Inputs.CfgDiveFloorStep, 5);
ELSE
    Outputs.MinStepDown := 0;
END_IF;

PrevState := Outputs.StepState;
{endregion}

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_DriftGuard) ===

IF Arm THEN
    IF NOT WasArmed THEN
        RefPosM := PositionM;   // Capture au 1er cycle armé uniquement
        WasArmed := TRUE;
    END_IF;
    DriftM := ABS(PositionM - RefPosM);
    Violation := DriftM > ToleranceM;
ELSE
    WasArmed := FALSE;
    DriftM := 0.0;
    Violation := FALSE;
END_IF;

{region "§1 Gate neutralisation"}
IF NOT Enable THEN
    Ready := FALSE;
    Measurement.RawPos := 0; Measurement.EncoderAvailable := FALSE;
    Measurement.CablePosM := 0.0; Measurement.CablePosMSafe := 0.0; Measurement.EncoderIncoherent := FALSE;
    Measurement.Speed_Mps := 0.0; Measurement.SignedSpeed_Mps := 0.0; Measurement.SpeedValid := FALSE;
    Measurement.HomingFault.Error := FALSE; Measurement.HomingFault.ErrorId := 0;
    Measurement.HomingLifecycle.Busy := FALSE; Measurement.HomingLifecycle.Done := FALSE;
    Measurement.AbsFault.Error := FALSE;    Measurement.AbsFault.ErrorId := 0;
    EncoderFault := TRUE;
    HomedAndReliable := FALSE;
    // Frontiere HW sortie : aucun ordre preset publie hors autorisation
    // (sinon PRG_02_Acquisition relaie une valeur perimee au codeur absolu -> preset parasite, reference corrompue)
    HwOut.PresetTriggerCmd := 0; HwOut.CodeSeqTriggerCmd := 0; HwOut.PresetValueOut := 0;
    // Reference connue MAINTENUE depuis Calib (RETAIN) meme FB desactive (AF09 §4) :
    // un FB desactive ne doit pas faire perdre la reference aux consommateurs aval (PRG_04, FB_Encoder_Scale).
    Homed := Calib.Homed;
    HomingSuspect := Calib.HomingSuspect;
    Measurement.HomingRefRaw := Calib.HomingRefRaw;
    // PresetConfirmationFailed est un diagnostic latch : il reste gele hors Enable
    // et ne doit pas etre efface par ce gate (AC3).
    // Socle appele meme Enable=FALSE : maintient le latch non acquitte et traite le Reset
    // hors autorisation (AC4). Les causes ne sont pas evaluees (Enable=FALSE -> vue live a 0),
    // les latches sont preserves.
    instFault(Enable := FALSE, Reset := Reset, Causes := instCauses);
    Fault := instFault.Fault;
    RETURN;
END_IF;
Ready := TRUE;
{endregion}

{region "§2 Abs"}
    instAbs(
    Enable              := Enable,
    Reset               := Reset,
    RawPosIn            := HwIn.RawPosIn,
    AlarmsIn            := HwIn.AlarmsIn,
    WarningsIn          := HwIn.WarningsIn,
    SlaveOperational    := HwIn.SlaveOperational,
    PresetRequest       := instHoming.PresetRequest,
    PresetValue         := instHoming.PresetValue,
    PointsPerRev        := PointsPerRev
);
{endregion}

{region "§3 Homing"}
instHoming(
    Enable               := Enable,
    Reset                := Reset,
    Home                 := HomingAtTargetM,
    HomingPermit         := HomingPermit,
    BtnConfirmCoherence  := ConfirmCoherence,
    UseDynamicTarget     := UseDynamicTarget,
    DynamicHomingTargetM := DynamicHomingTargetM,
    CfgHomingTargetM     := CfgHomingTargetM,
    CfgTopSensorPosM     := SEL(HomingAtZero, CfgTopSensorPosM, 0.0),
    TopPositionSensor    := TopPositionSensor,
    RawPos               := instAbs.RawPos,
    EncoderAvailable     := instAbs.EncoderAvailable,
    PresetStatusBit      := HwIn.PresetStatusBit,
    Cfg                  := Cfg,
    PointsPerRev         := PointsPerRev,
    MultiTurnRevsMax     := 4096,
    CableM_PerRev        := CableM_PerRev,
    BypassGlobal         := BypassGlobal,
    Calib                := Calib
);
{endregion}

{region "§4 Scale"}
instScale(
    RawPos       := instAbs.RawPos,
    HomingRefRaw := instHoming.HomingRefRaw,
    CableM_PerRev := CableM_PerRev,
    PointsPerRev := PointsPerRev
);
{endregion}

{region "§5 Safety"}
instSafety(
    Enable             := Enable,
    Reset              := Reset,
    CablePosM          := instScale.CablePosM,
    HomingSuspect      := instHoming.HomingSuspect,
    PositionMinM       := PositionMinM,
    PositionMaxM       := PositionMaxM,
    BypassGlobal       := BypassGlobal
);
{endregion}

{region "§6 Reliability"}
instRel(
    EncoderAvailable  := instAbs.EncoderAvailable,
    Homed             := instHoming.Homed,
    EncoderIncoherent := instSafety.EncoderIncoherent
);
{endregion}

{region "§7 Speed"}
instSpeed(
    Enable        := Enable,
    Reset         := Reset,
    Position_M    := instSafety.CablePosMSafe,
    PositionValid := NOT instRel.EncoderFault
);
{endregion}

{region "§8 Remplissage struct et synthese"}
Measurement.RawPos            := instAbs.RawPos;
Measurement.EncoderAvailable  := instAbs.EncoderAvailable;
Measurement.CablePosM         := instSafety.CablePosMSafe;
Measurement.CablePosMSafe     := instSafety.CablePosMSafe;
Measurement.EncoderIncoherent := instSafety.EncoderIncoherent;
Measurement.Speed_Mps         := instSpeed.Speed_Mps;
Measurement.SignedSpeed_Mps   := instSpeed.SignedSpeed_Mps;
Measurement.SpeedValid        := instSpeed.Valid;
Measurement.HomingFault        := instHoming.Fault;
Measurement.HomingLifecycle    := instHoming.Lifecycle;
Measurement.AbsFault           := instAbs.Fault;
Measurement.HomingRefRaw      := instHoming.HomingRefRaw;

// Frontiere HW sortie (preset)
HwOut.PresetTriggerCmd := instAbs.PresetTriggerCmd;
HwOut.CodeSeqTriggerCmd := instAbs.CodeSeqTriggerCmd;
HwOut.PresetValueOut    := instAbs.PresetValueOut;

// Etats codeur
Homed            := instHoming.Homed;
HomingSuspect    := instHoming.HomingSuspect;
EncoderFault     := instRel.EncoderFault;
HomedAndReliable := instRel.HomedAndReliable;
PresetConfirmationFailed := instHoming.PresetConfirmationFailed;

// Synthese statut facade : brique defaut socle (Fault:ST_Fault), pattern FB_Joystick.
// Causes exprimees en CLAIR (ST_FaultCause), alimentees UNIQUEMENT depuis les sorties
// publiques des sous-FB (encapsulation stricte, jamais de lecture VAR interne).
//   - Cause 0/1 : LIVE (Latching=FALSE) -> Fault.Error, retombe seule.
//   - Cause 2   : LATCHED (Latching=TRUE) -> arme Fault.Latched, acquittee au Reset front.
// Interlock machine toujours sur les faits bruts (EncoderFault, HomedAndReliable,
// EncoderIncoherent), jamais sur Fault.Latched (conservation).
instCauses[0].Active := NOT instAbs.EncoderAvailable; instCauses[0].Latching := FALSE;
instCauses[0].Texte := 'Perte materiel / communication codeur EtherCAT';
instCauses[1].Active := instSafety.EncoderIncoherent; instCauses[1].Latching := FALSE;
instCauses[1].Texte := 'Incoherence mesure / saut de position codeur';
instCauses[2].Active := instHoming.PresetConfirmationFailed; instCauses[2].Latching := TRUE;
instCauses[2].Texte := 'Echec confirmation transaction preset codeur';

// Socle appele APRES le pipeline : causes du scan courant, aucun scan de retard (AC4).
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;     // source de verite = socle
Ready := Enable AND NOT Fault.Latched;
{endregion}

// 🛡️ 1. GATE GENERAL (D-A11, C1) — PAS de Homed : non-reference ≠ incoherent.
//    Ce gate sert a la fiabilite de la mesure (vitesse, mouvements, PositionsValid).
EncoderFault := (NOT EncoderAvailable) OR EncoderIncoherent;

// 🎯 2. GATE STRICT — reserve a l'interlock hauteur M3 (C1) : on ne translate pas
//    si la hauteur est inconnue (jamais home) ou douteuse.
HomedAndReliable := EncoderAvailable AND Homed AND (NOT EncoderIncoherent);

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Abs) ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. RESET FRONT
ResetEdge(CLK := Reset);

// 🔍 2. DIAGNOSTIC BUS / ALARME (Cause 0 : live)
instCauses[0].Active   := (AlarmsIn <> 0) OR NOT SlaveOperational;
instCauses[0].Latching := FALSE;
instCauses[0].Texte    := 'Defaut communication EtherCAT codeur absolu';

// ⏱️ 3. TIMEOUT PRESET (Cause 1 : latched)
IF ResetEdge.Q AND (PresetSeqStep = 0) THEN
    PresetTimeoutError := FALSE;
END_IF;
instCauses[1].Active   := PresetTimeoutError;
instCauses[1].Latching := TRUE;
instCauses[1].Texte    := 'Timeout sequence preset SDO codeur';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

EncoderAvailable := NOT instCauses[0].Active;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable THEN
    EncoderAvailable := FALSE;
    Ready := FALSE;
    PresetTriggerCmd := 0; CodeSeqTriggerCmd := 0; PresetValueOut := 0;
    PresetSeqStep := 0;
    PresetCompleted := FALSE;
    PresetTimer(IN := FALSE, PT := PresetTimeout);
    PresetTimerVisual(IN := FALSE, PT := T#500MS);
    // RawPos, AngleRaw et TurnCount sont volontairement gelés hors Enable
    // (AF09 F09.01 / AC5) : aucune lecture bus ni remise a zero dans ce gate.
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Lecture position"}
// 📥 3. LECTURE POSITION — GELER SUR DOUTE (Partie10 §6)
// Si EncoderAvailable=FALSE : RawPos/AngleRaw/TurnCount conservent leur dernière valeur (pas de RETURN
// global ici pour ne pas geler aussi la séquence preset/l'état — seule la lecture est gelée).
IF EncoderAvailable THEN
    RawPos := RawPosIn;   // Sens de comptage géré côté codeur (CoE 6000h bit0, startup parameter CODESYS) — voir Partie10 §3bis. Plus de calcul ici.
    AngleRaw := UDINT_TO_UINT(RawPos MOD PointsPerRev);
    TurnCount := RawPos / PointsPerRev;
END_IF;
{endregion}

{region "§4 Séquence preset"}
// 🔧 4. SÉQUENCE PRESET (écriture bus)
// PresetTriggerCmd := 2 déclenche le référencement à PresetValue (valeur de commande, pas un
// masque de bits). CodeSeqTriggerCmd : rôle non identifié — laissé à 0, PAS piloté tant que sa
// fonction n'est pas confirmée. Ne jamais lui donner une valeur arbitraire.
PresetReqEdge(CLK := PresetRequest);
PresetCompleted := FALSE;
CodeSeqTriggerCmd := 0;                 // non piloté — rôle inconnu, voir note ci-dessus
CASE PresetSeqStep OF
    0: // IDLE
        PresetTriggerCmd := 0;
        IF PresetReqEdge.Q AND EncoderAvailable THEN
            PresetValueOut := PresetValue;
            PresetSeqStep := 1;
            PresetTimer(IN := TRUE, PT := PresetTimeout);
        END_IF;
    1: // Déclenchement preset (laissé actif pendant 0.5s pour confort visuel en simulation/bus)
        PresetTriggerCmd := 2;   // Référence le codeur à PresetValueOut
        RawDiff := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(PresetValueOut);
        IF ABS(RawDiff) <= UDINT_TO_DINT(PresetTolerancePts) THEN
            PresetTimer(IN := FALSE, PT := PresetTimeout);
            PresetTimerVisual(IN := TRUE, PT := T#500MS);
            IF PresetTimerVisual.Q THEN
                PresetTriggerCmd := 0;
                PresetCompleted := TRUE;
                PresetSeqStep := 0;
                PresetTimerVisual(IN := FALSE, PT := T#500MS);
            END_IF;
        ELSIF PresetTimer.Q THEN
            PresetTriggerCmd := 0;
            PresetTimeoutError := TRUE;
            PresetSeqStep := 0;
            PresetTimer(IN := FALSE, PT := PresetTimeout);
            PresetTimerVisual(IN := FALSE, PT := T#500MS);
        END_IF;
END_CASE;
{endregion}

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Homing) ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. FRONTS
ResetEdge(CLK := Reset);
HomeEdge(CLK := Home);
ConfirmCoherenceEdge(CLK := BtnConfirmCoherence);

// Effacement des latches d'erreur sur Reset conscient
IF ResetEdge.Q THEN
    PresetConfirmationFailed := FALSE;
    HomingModeError := FALSE;
    TargetOutOfRangeError := FALSE;
    PresetFailError := FALSE;
END_IF;

// Levée de doute incohérence boot (BtnConfirmCoherence)
IF ConfirmCoherenceEdge.Q AND HomingPermit THEN
    Calib.HomingSuspect := FALSE;
    BootIncoherentError := FALSE;
END_IF;

// Configuration des causes nommées
instCauses[0].Active   := HomingModeError;
instCauses[0].Latching := TRUE;
instCauses[0].Texte    := 'Homing non autorise dans ce mode';

instCauses[1].Active   := TargetOutOfRangeError;
instCauses[1].Latching := TRUE;
instCauses[1].Texte    := 'Cible de homing hors plage';

instCauses[2].Active   := PresetFailError;
instCauses[2].Latching := TRUE;
instCauses[2].Texte    := 'Echec confirmation transaction preset';

instCauses[3].Active   := BootIncoherentError;
instCauses[3].Latching := TRUE;
instCauses[3].Texte    := 'Incoherence position codeur au demarrage';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE — neutralisation ; on continue toutefois d'exposer le dernier état RETAIN connu
// (FB_Encoder_Scale a besoin de HomingRefRaw même si ce FB est désactivé)
IF NOT Enable THEN
    PresetRequest := FALSE;
    PresetValue := 0;
    Ready := FALSE;
    Lifecycle.Busy := FALSE;
    Lifecycle.Done := FALSE;
    InitDone := FALSE;   // Force un nouveau contrôle à la prochaine activation
    PresetVerificationActive := FALSE;
    PresetVerifyTimer(IN := FALSE, PT := CST_PresetVerifyTime);
    Homed := Calib.Homed;
    HomingSuspect := Calib.HomingSuspect;
    HomingRefRaw := Calib.HomingRefRaw;
    // PresetConfirmationFailed est un diagnostic latch : il est gelé hors Enable
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Cohérence au redémarrage"}
// 🔍 3. COHÉRENCE AU REDÉMARRAGE — une fois par session Enable, dès que le codeur répond
IF NOT InitDone THEN
    IF EncoderAvailable THEN
        RawDiffRestart := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(Calib.LastKnownRawPos);
        IF Calib.Homed AND (ABS(RawDiffRestart) > UDINT_TO_DINT(Calib.RestartCoherenceTolerancePts)) THEN
            Calib.HomingSuspect := TRUE;
            BootIncoherentError := TRUE;
        END_IF;
        InitDone := TRUE;
    END_IF;
END_IF;
{endregion}

{region "§4 Demande et déclenchement homing"}
// ⚙️ 4. DEMANDE & DÉCLENCHEMENT HOMING
PresetRequest := FALSE;
PresetValue := 0;
TopSensorEdge(CLK := TopPositionSensor);
DynamicTargetEdge(CLK := UseDynamicTarget);

HomingModeOk := HomingPermit;

IF HomeEdge.Q AND NOT HomingModeOk THEN
    HomingModeError := TRUE;
END_IF;

NominalHomingTrigger := HomingModeOk AND NOT UseDynamicTarget
                         AND ((Home AND TopSensorEdge.Q) OR (HomeEdge.Q AND TopPositionSensor));

UnitaryHomingTrigger := HomingModeOk AND NOT UseDynamicTarget AND HomeEdge.Q;

DynamicHomingTrigger := HomingModeOk AND (DynamicTargetEdge.Q OR (UseDynamicTarget AND HomeEdge.Q));

HomingTrigger := (NominalHomingTrigger OR UnitaryHomingTrigger OR DynamicHomingTrigger)
                 AND NOT PresetVerificationActive;

IF HomingTrigger THEN
    IF UseDynamicTarget THEN
        TargetPositionM := DynamicHomingTargetM;
    ELSIF NominalHomingTrigger THEN
        TargetPositionM := CfgTopSensorPosM;
    ELSE
        TargetPositionM := CfgHomingTargetM;
    END_IF;

    // Bornage obligatoire avant écriture (CODE_QUALITY_STANDARDS §6) [-99;+99] m
    IF (TargetPositionM < -99.0) OR (TargetPositionM > 99.0) THEN
        TargetOutOfRangeError := TRUE;
    ELSE
        TargetPoints := REAL_TO_DINT(TargetPositionM * UDINT_TO_REAL(PointsPerRev) / CableM_PerRev);
        PendingHomingRefRaw := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) - TargetPoints);
        PresetValue := RawPos;
        PresetRequest := TRUE;
        PresetVerificationActive := TRUE;
        Lifecycle.Done := FALSE;
    END_IF;
END_IF;
{endregion}

{region "§5 Suivi de transaction preset"}
// ⏳ 5. SUIVI DE LA TRANSACTION PRESET
PresetVerifyTimer(IN := PresetVerificationActive, PT := CST_PresetVerifyTime);
IF PresetVerificationActive AND PresetVerifyTimer.Q THEN
    CandidateRawDiff := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(PendingHomingRefRaw);
    IF PointsPerRev <> 0 THEN
        CandidateCablePosM := DINT_TO_REAL(CandidateRawDiff) * CableM_PerRev / UDINT_TO_REAL(PointsPerRev);
    ELSE
        CandidateCablePosM := 0.0;
    END_IF;
    ReadbackOk := ABS(CandidateCablePosM - TargetPositionM) <= CST_HomingVerifyToleranceM;
    StatusBitOk := PresetStatusBit;

    CASE Cfg.PresetConfirmMode OF
        E_PresetConfirmMode.READBACK_ONLY:
            PresetConfirmed := ReadbackOk;
        E_PresetConfirmMode.READBACK_AND_STATUSBIT:
            PresetConfirmed := ReadbackOk AND StatusBitOk;
        E_PresetConfirmMode.STATUSBIT_ONLY:
            PresetConfirmed := StatusBitOk;
        ELSE
            PresetConfirmed := FALSE;
    END_CASE;

    IF PresetConfirmed THEN
        Calib.HomingRefRaw := PendingHomingRefRaw;
        Calib.Homed := TRUE;
        Calib.HomingSuspect := FALSE;
        Calib.LastKnownRawPos := RawPos;
        PresetConfirmationFailed := FALSE;
        PresetFailError := FALSE;
        Lifecycle.Done := TRUE;
    ELSE
        Calib.HomingSuspect := TRUE;
        PresetConfirmationFailed := TRUE;
        PresetFailError := TRUE;
        Lifecycle.Done := FALSE;
    END_IF;

    PresetVerificationActive := FALSE;
    PresetVerifyTimer(IN := FALSE, PT := CST_PresetVerifyTime);
END_IF;
{endregion}

{region "§6 Sorties état & calibration"}
// 📤 6. SORTIES ÉTAT & CALIBRATION
IF EncoderAvailable AND NOT PresetVerificationActive THEN
    Calib.LastKnownRawPos := RawPos;
END_IF;

Lifecycle.Busy := PresetVerificationActive;
Homed := Calib.Homed AND NOT Calib.HomingSuspect;
HomingSuspect := Calib.HomingSuspect;
HomingRefRaw := Calib.HomingRefRaw;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. RESET FRONT
ResetEdge(CLK := Reset);

// 🔍 2. SURVEILLANCE BORNAGE & INCOHÉRENCE BOOT
instCauses[0].Active   := NOT BypassGlobal AND ((CablePosM < PositionMinM) OR (CablePosM > PositionMaxM));
instCauses[0].Latching := FALSE;
instCauses[0].Texte    := 'Depassement bornes physiques absolues cable';

instCauses[1].Active   := NOT BypassGlobal AND HomingSuspect;
instCauses[1].Latching := FALSE;
instCauses[1].Texte    := 'Incoherence position au redemarrage';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable THEN
    Ready := FALSE;
    CablePosMSafe := CablePosM;
    EncoderIncoherent := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Transmission mesure et sécurité"}
// 📏 3. TRANSMISSION DE LA MESURE & SÉCURITÉ
CablePosMSafe := CablePosM;
EncoderIncoherent := Fault.Error;
{endregion}

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Encoder_Scale) ===

// 🧮 Écart signé sûr : conversion DINT AVANT soustraction (§3.1) — jamais l'inverse
RawDiff := UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(HomingRefRaw);

// 📏 Formule fixe points → mètres (Partie10 §2), garde division par zéro
IF PointsPerRev > 0 THEN
    CablePosM := DINT_TO_REAL(RawDiff) * (CableM_PerRev / UDINT_TO_REAL(PointsPerRev));
ELSE
    CablePosM := 0.0;
END_IF;

{region "§1 Horodatage et purge"}
// ⏱️ Horodatage natif : le calcul utilise le temps réellement écoulé, jamais un cycle supposé.
CurrentTimestamp := TIME();

// Purge des six positions sur rupture de confiance : aucune source antérieure ne peut contaminer la mesure.
IF NOT Enable OR Reset OR NOT PositionValid THEN
    Speed_Mps := 0.0;
    SignedSpeed_Mps := 0.0;
    Valid := FALSE;
    CollectedSamples := 0;
    TimestampInitialized := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§2 Première position"}
// 🕒 Première position de la nouvelle fenêtre.
IF NOT TimestampInitialized THEN
    Positions_M[0] := Position_M;
    Timestamps[0] := CurrentTimestamp;
    LastTimestamp := CurrentTimestamp;
    CollectedSamples := 1;
    TimestampInitialized := TRUE;
    Speed_Mps := 0.0;
    SignedSpeed_Mps := 0.0;
    Valid := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§3 Rebouclage TIME"}
// 🛡️ Rebouclage de TIME détecté localement : purge sans réutiliser le delta aberrant.
IF CurrentTimestamp < LastTimestamp THEN
    Positions_M[0] := Position_M;
    Timestamps[0] := CurrentTimestamp;
    LastTimestamp := CurrentTimestamp;
    CollectedSamples := 1;
    Speed_Mps := 0.0;
    SignedSpeed_Mps := 0.0;
    Valid := FALSE;
    RETURN;
END_IF;

ElapsedSinceSample := CurrentTimestamp - LastTimestamp;

// 🛡️ Delta nul : aucune division et aucun doublon d'échantillon.
IF ElapsedSinceSample <= T#0MS THEN
    RETURN;
END_IF;
{endregion}

{region "§4 Collecte échantillons"}
// 📥 Six positions espacées d'au moins 10 ms donnent cinq intervalles sur la fenêtre interne de 50 ms.
IF ElapsedSinceSample >= SamplePeriod THEN
    LastTimestamp := CurrentTimestamp;

    IF CollectedSamples < SampleCount THEN
        Positions_M[CollectedSamples] := Position_M;
        Timestamps[CollectedSamples] := CurrentTimestamp;
        CollectedSamples := CollectedSamples + 1;
    ELSE
        FOR Index := 0 TO 4 DO
            Positions_M[Index] := Positions_M[Index + 1];
            Timestamps[Index] := Timestamps[Index + 1];
        END_FOR;
        Positions_M[5] := Position_M;
        Timestamps[5] := CurrentTimestamp;
    END_IF;
{endregion}

{region "§5 Calcul vitesse"}
    IF CollectedSamples = SampleCount THEN
        // 🛡️ Ordre temporel et durée minimale contrôlés avant toute conversion/division.
        IF Timestamps[5] >= Timestamps[0] THEN
            WindowElapsed := Timestamps[5] - Timestamps[0];
            IF WindowElapsed >= WindowTime THEN
                SignedSpeed_Mps := (Positions_M[5] - Positions_M[0])
                                   / (UDINT_TO_REAL(TIME_TO_UDINT(WindowElapsed)) / 1000.0);
                Speed_Mps := ABS(SignedSpeed_Mps);
                Valid := TRUE;
            ELSE
                Speed_Mps := 0.0;
                SignedSpeed_Mps := 0.0;
                Valid := FALSE;
            END_IF;
        ELSE
            Speed_Mps := 0.0;
            SignedSpeed_Mps := 0.0;
            Valid := FALSE;
            CollectedSamples := 0;
            TimestampInitialized := FALSE;
        END_IF;
    END_IF;
END_IF;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. FRONTS
ResetEdge(CLK := Reset);
// Parametrage invalide : distance nulle, backstop nul, base de temps nulle, ou backstop
// qui fauterait AVANT le watchdog benne (masquerait BucketError - ordre des watchdogs).
ErrorCausePresent := (ControlAscentDistance_M <= 0.0)
                  OR (CfgBucketCloseTimeout <= T#0ms)
                  OR (CycleTime <= T#0ms)
                  OR (CfgBucketCloseTimeout <= BucketMoveTimeout)
                  OR (CfgBucketCloseTimeout > CST_BackstopMax);  // borne haute : evite l'overflow de BucketCloseTimerAcc (F3)

// ⏱️ Plafond anti-blocage decollage calcule au runtime : course de controle bornee [plancher..plafond]
// avant conversion REAL->UDINT->TIME (anti-overflow sur valeur IHM aberrante, CQS §6).
CalculatedControlAscentTimeout := UDINT_TO_TIME(REAL_TO_UDINT(
    LIMIT(CST_TimeoutMinDistance_M, ControlAscentDistance_M, CST_TimeoutMaxDistance_M)
    / CST_MinSpeed_Mps * CST_ControlAscentMargin * CST_SecToMs));

// ⏱️ Integrateurs de temps de montee effective (anti-pompage homme-mort)
IF (ExtractionState = E_ExtractionAssistState.CLOSING_BUCKET) AND MotionRequestActive AND (MotionDirection = 1) THEN
    BucketCloseTimerAcc := BucketCloseTimerAcc + CycleTime;
    IF BucketCloseTimerAcc >= CfgBucketCloseTimeout THEN
        TimeoutBucketCloseFault := TRUE;
    END_IF;
END_IF;

IF (ExtractionState = E_ExtractionAssistState.CONTROL_ASCENT) AND MotionRequestActive AND (MotionDirection = 1) THEN
    ControlAscentTimerAcc := ControlAscentTimerAcc + CycleTime;
    IF ControlAscentTimerAcc >= CalculatedControlAscentTimeout THEN
        TimeoutControlAscentFault := TRUE;
    END_IF;
END_IF;

// Etat physique des causes treuil/benne : conditionne l'acquittement des latches a cause persistante (F2).
CausesPhysiquesEffacees := NOT BucketError AND NOT WinchSyncError
                        AND PositionsValid AND M1MeasuredSpeedValid AND M2MeasuredSpeedValid;
IF ResetEdge.Q AND NOT ErrorCausePresent AND NOT MotionRequestActive THEN
    // Latches sans cause physique persistante (timeouts, backstop) : acquittables sur simple front Reset.
    TimeoutBucketCloseFault   := FALSE;
    TimeoutControlAscentFault := FALSE;
    BucketCloseTimerAcc       := T#0ms;
    ControlAscentTimerAcc     := T#0ms;
    StepAtFaultCaptured       := FALSE;
    ExtractionState := E_ExtractionAssistState.WAIT_BOTTOM_CONFIRMATION;
    // Latches de cause physique : acquittables SEULEMENT si l'entree de defaut est revenue saine (F2).
    IF CausesPhysiquesEffacees THEN
        BucketErrorFault      := FALSE;
        SyncOrSpeedErrorFault := FALSE;
    END_IF;
END_IF;

instCauses[1].Active   := BucketErrorFault;
instCauses[1].Latching := TRUE;
instCauses[1].Texte    := 'Defaut sous-systeme benne pendant fermeture';

instCauses[2].Active   := SyncOrSpeedErrorFault;
instCauses[2].Latching := TRUE;
instCauses[2].Texte    := 'Defaut synchro ou capteurs treuils pendant remontee';

instCauses[3].Active   := ErrorCausePresent;
instCauses[3].Latching := TRUE;
instCauses[3].Texte    := 'Parametrage distance de controle ou backstop invalide';

instCauses[4].Active   := TimeoutBucketCloseFault;
instCauses[4].Latching := TRUE;
instCauses[4].Texte    := 'Depassement backstop fermeture benne';

instCauses[5].Active   := TimeoutControlAscentFault;
instCauses[5].Latching := TRUE;
instCauses[5].Texte    := 'Depassement tempo decollage controle';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

// 📸 Capture ordonnee de StepAtFault (D2). Les defauts leves dans le CASE se figent au site du
// latch (voir §3) ; ce bloc ne couvre que les defauts detectes en §1 (backstop, timeout, parametrage),
// ou ExtractionState/PrevState sont encore l'etape reelle. StepAtFaultCaptured evite l'ecrasement.
ErrorEdge(CLK := Fault.Error);
IF ErrorEdge.Q AND NOT StepAtFaultCaptured THEN
    StepAtFault := PrevState;
    StepAtFaultCaptured := TRUE;
ELSIF ResetEdge.Q AND NOT ErrorCausePresent AND NOT MotionRequestActive THEN
    StepAtFault := E_ExtractionAssistState.WAIT_BOTTOM_CONFIRMATION;
END_IF;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable OR NOT PowerContactorEngaged THEN
    Ready := FALSE;
    Lifecycle.Busy := FALSE;
    Lifecycle.Done := FALSE;
    BucketCloseRequest := FALSE;
    AscentPermit := FALSE;
    ExtractionControlActive := FALSE;
    BottomConfirmationConsumed := FALSE;
    ExtractionState := E_ExtractionAssistState.WAIT_BOTTOM_CONFIRMATION;
    // StepAtFault / StepAtFaultCaptured NON reinitialises ici : l'etape figee au defaut reste
    // lisible pour l'IHM/diagnostic apres un cycle Enable OFF->ON ; seul un front Reset l'efface.
    PrevState := E_ExtractionAssistState.WAIT_BOTTOM_CONFIRMATION;
    BucketCloseTimerAcc := T#0ms;
    ControlAscentTimerAcc := T#0ms;
    OperatorActionId := 0;
    OperatorAction := '';
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Machine etat fermeture remontee"}
BucketCloseRequest := FALSE;
AscentPermit := FALSE;
ExtractionControlActive := FALSE;
BottomConfirmationConsumed := FALSE;
Lifecycle.Busy := FALSE;
Lifecycle.Done := FALSE;

// Ascending assistee reellement demandee : sens ascending + mode maintenance (H5, double garde vs Enable PRG_03).
AssistPermit := MotionRequestActive AND (MotionDirection = 1)
            AND (Mode = E_Mode.MAINT_N1 OR Mode = E_Mode.MAINT_N2);
// Entrees [SAFE] saines : coupure meme-scan des permis si defaut treuil/synchro (H2), avant meme le latch.
AscentControlSafe := NOT WinchSyncError AND PositionsValid AND M1MeasuredSpeedValid AND M2MeasuredSpeedValid;
AscentNominalSafe := NOT WinchSyncError AND PositionsValid;

// Garde-fou non-redemarrage auto : un defaut latche non acquitte verrouille la machine
// d'etat en ERROR_HOLD, meme si la vue live Fault.Error retombe (cause disparue).
IF Fault.Error OR Fault.Latched THEN
    ExtractionState := E_ExtractionAssistState.ERROR_HOLD;
    OperatorActionId := 16#0280;
    OperatorAction := 'Vérifier la benne et les treuils puis réarmer avant de reprendre.';
ELSE
    CASE ExtractionState OF
        E_ExtractionAssistState.WAIT_BOTTOM_CONFIRMATION:
            IF BottomPositionConfirmed THEN
                ExtractionState := E_ExtractionAssistState.READY_TO_CLOSE;
            ELSE
                OperatorActionId := 16#0200;
                OperatorAction := 'Confirmer que la benne est posée au fond avant extraction.';
            END_IF;

        E_ExtractionAssistState.READY_TO_CLOSE:
            Ready := TRUE;
            OperatorActionId := 16#0201;
            OperatorAction := 'Demander la montée pour fermer la benne.';
            IF MotionRequestActive AND (MotionDirection = 1) THEN
                BottomConfirmationConsumed := TRUE;
                BucketCloseTimerAcc := T#0ms;   // ⏱️ RAZ a l'entree exacte de CLOSING_BUCKET
                ExtractionState := E_ExtractionAssistState.CLOSING_BUCKET;
            END_IF;

        E_ExtractionAssistState.CLOSING_BUCKET:
            Lifecycle.Busy := TRUE;
            BucketCloseRequest := AssistPermit AND NOT BucketError; // coupure meme-scan sur defaut benne (H2)
            // Autorisation de montee pendant la fermeture : la benne se ferme en montant.
            // Consommee par l'arbitrage (PRG_04) comme permis de montee assistee (H2).
            AscentPermit := AssistPermit AND AscentControlSafe;
            OperatorActionId := 16#0202;
            OperatorAction := 'Maintenir la montée : fermeture de la benne en cours.';
            IF BucketError THEN
                IF NOT StepAtFaultCaptured THEN
                    StepAtFault := ExtractionState;
                    StepAtFaultCaptured := TRUE;
                END_IF;
                BucketErrorFault := TRUE;
            ELSIF BucketIsClosed AND NOT BucketBusy THEN
                ControlStartM1Position_M := M1Position_M;
                ControlStartM2Position_M := M2Position_M;
                ControlAscentTimerAcc := T#0ms;   // ⏱️ RAZ a l'entree exacte de CONTROL_ASCENT
                ExtractionState := E_ExtractionAssistState.CONTROL_ASCENT;
            END_IF;

        E_ExtractionAssistState.CONTROL_ASCENT:
            Lifecycle.Busy := TRUE;
            AscentPermit := AssistPermit AND AscentControlSafe; // coupure meme-scan sur defaut synchro/capteurs (H2)
            ExtractionControlActive := AscentPermit;            // plafond palier 1 suit le permis de montee
            OperatorActionId := 16#0203;
            OperatorAction := 'Maintenir la montée : contrôle charge au palier minimal.';
            IF NOT AscentControlSafe THEN
                IF NOT StepAtFaultCaptured THEN
                    StepAtFault := ExtractionState;
                    StepAtFaultCaptured := TRUE;
                END_IF;
                SyncOrSpeedErrorFault := TRUE;
            ELSIF (M1Position_M >= (ControlStartM1Position_M + ControlAscentDistance_M))
               AND (M2Position_M >= (ControlStartM2Position_M + ControlAscentDistance_M)) THEN
                ExtractionState := E_ExtractionAssistState.NOMINAL_ASCENT;
            END_IF;

        E_ExtractionAssistState.NOMINAL_ASCENT:
            Lifecycle.Busy := TRUE;
            AscentPermit := AssistPermit AND AscentNominalSafe; // coupure meme-scan sur defaut synchro/position (H2)
            OperatorActionId := 16#0204;
            OperatorAction := 'Maintenir la montée : extraction en cours.';
            IF NOT AscentNominalSafe THEN
                IF NOT StepAtFaultCaptured THEN
                    StepAtFault := ExtractionState;
                    StepAtFaultCaptured := TRUE;
                END_IF;
                SyncOrSpeedErrorFault := TRUE;
            END_IF;

        E_ExtractionAssistState.ERROR_HOLD:
            ;
    END_CASE;
END_IF;

// 💾 Memorisation de la phase precedente en toute fin de scan (capture StepAtFault fiable)
PrevState := ExtractionState;
{endregion}

{region "§1 Reset (front, toujours effectif)"}
// Front Reset : efface tous les latches. Jamais conditionné, agit même Enable=FALSE (§9).
Ready := Enable;
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    FOR i := 0 TO 15 DO Latch[i] := FALSE; END_FOR;
END_IF;
{endregion}

{region "§2 Vue LIVE — Error / ErrorId"}
// Bitfield des causes présentes MAINTENANT. Retombe seule à 0 quand les causes disparaissent.
// Non évaluée si Enable=FALSE (pas de lecture de cause hors autorisation).
Fault.ErrorId := 0;
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active THEN
            Fault.ErrorId := Fault.ErrorId OR SHL(WORD#1, INT_TO_DWORD(i));
        END_IF;
    END_FOR;
END_IF;
Fault.Error := (Fault.ErrorId <> 0);
{endregion}

{region "§3 Armement des latches (causes à acquitter)"}
// Une cause Active ET Latching arme son bit ; le bit reste jusqu'au front Reset (§1),
// même si la cause disparaît. Réapparition => ré-armement (ré-alarme).
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active AND Causes[i].Latching THEN
            Latch[i] := TRUE;
        END_IF;
    END_FOR;
END_IF;
{endregion}

{region "§4 Vue LATCHÉE — Latched / LatchedId"}
// Toujours publiée, y compris Enable=FALSE : un défaut non acquitté reste visible.
Fault.LatchedId := 0;
FOR i := 0 TO 15 DO
    IF Latch[i] THEN
        Fault.LatchedId := Fault.LatchedId OR SHL(WORD#1, INT_TO_DWORD(i));
    END_IF;
END_FOR;
Fault.Latched := (Fault.LatchedId <> 0);
{endregion}

T := TIME_TO_REAL(TimeConst) / 1000.0; // ms → s

IF T <= 0.0 OR CycleTimeS <= 0.0 THEN
    ValueOut := ValueIn;
ELSE
    Alpha    := CycleTimeS / (T + CycleTimeS);
    ValueOut := Alpha * ValueIn + (1.0 - Alpha) * ValueOut;
END_IF;

IF NOT Enable THEN
    Banner.GlobalContextText     := '';
    Banner.SequenceProgressText  := '';
    Banner.SpecialConditionText  := '';
    Banner.OperatorActionText    := '';
    Banner.PositionM3Text        := '';
    Banner.AlarmBanner.HasAlarm  := FALSE;
    Banner.AlarmBanner.Text      := '';
    Banner.AlarmBanner.Index     := 0;
    Banner.AlarmBanner.Count     := 0;
    FOR i := 0 TO 49 DO
        Banner.AlarmBanner.AlarmArray[i] := '';
    END_FOR;
    TonAlarmBanner(IN := FALSE);
    TonBootInhibit(IN := FALSE);
    TofFaultLocalIo(IN := FALSE);
    TofFaultVh0800(IN := FALSE);
    TofFaultVh0808(IN := FALSE);
    TofFaultVh0008Er(IN := FALSE);
    TofFaultVh0008Er1(IN := FALSE);
    TofFaultCanBus(IN := FALSE);
    TofFaultJoy1(IN := FALSE);
    TofFaultEcatBus(IN := FALSE);
    TofFaultEncM1(IN := FALSE);
    TofFaultEncM2(IN := FALSE);
    TofFaultVarM3(IN := FALSE);
    RETURN;
END_IF;

// ⏱️ Garde au démarrage (inhibition 4s pendant init des bus et équipements)
TonBootInhibit(IN := Enable, PT := T#4s);

// 🌊 Filtrage anti-bagotement (TOF 1.5s sur perte de validité)
TofFaultLocalIo(IN := (NOT Network.InputModules.LocalDigitalIoOk) AND TonBootInhibit.Q, PT := T#1.5s);
TofFaultVh0800(IN := (NOT Network.InputModules.Vh0800EndOk) AND TonBootInhibit.Q, PT := T#1.5s);
TofFaultVh0808(IN := (NOT Network.InputModules.Vh0808EtpOk) AND TonBootInhibit.Q, PT := T#1.5s);
TofFaultVh0008Er(IN := (NOT Network.InputModules.Vh0008ErOk) AND TonBootInhibit.Q, PT := T#1.5s);
TofFaultVh0008Er1(IN := (NOT Network.InputModules.Vh0008Er1Ok) AND TonBootInhibit.Q, PT := T#1.5s);
TofFaultCanBus(IN := (NOT Network.BusCanOpen.Operational) AND TonBootInhibit.Q, PT := T#1.5s);
TofFaultJoy1(IN := (NOT Network.Joystick.Operational) AND TonBootInhibit.Q, PT := T#1.5s);
TofFaultEcatBus(IN := (NOT Network.BusEthercat.Operational) AND TonBootInhibit.Q, PT := T#1.5s);
TofFaultEncM1(IN := (NOT Network.EncoderM1.Operational) AND TonBootInhibit.Q, PT := T#1.5s);
TofFaultEncM2(IN := (NOT Network.EncoderM2.Operational) AND TonBootInhibit.Q, PT := T#1.5s);
TofFaultVarM3(IN := (NOT Network.VariateurM3.Operational) AND TonBootInhibit.Q, PT := T#1.5s);

LocalIoValid   := NOT TofFaultLocalIo.Q;
Vh0800Valid    := NOT TofFaultVh0800.Q;
Vh0808Valid    := NOT TofFaultVh0808.Q;
Vh0008ErValid  := NOT TofFaultVh0008Er.Q;
Vh0008Er1Valid := NOT TofFaultVh0008Er1.Q;
CanBusValid    := NOT TofFaultCanBus.Q;
Joy1Valid      := NOT TofFaultJoy1.Q;
EcatBusValid   := NOT TofFaultEcatBus.Q;
EncM1Valid     := NOT TofFaultEncM1.Q;
EncM2Valid     := NOT TofFaultEncM2.Q;
VarM3Valid     := NOT TofFaultVarM3.Q;

{region "§1 Contexte global"}
// ═══════════════════════════════════════════════════════════════
// 1. CONTEXTE GLOBAL — aucun numéro d'étape ici
// Format (AF-07 §5.1) : [RÉEL/SIMU] [MODE] [COUPLAGE]
// ═══════════════════════════════════════════════════════════════
IF SimulationModeActive THEN
    PrefixContext := '[SIMULATION] ';
ELSE
    PrefixContext := '[RÉEL] ';
END_IF;

CASE CurrentMode OF
    E_Mode.DISABLE:  ModeStr := '[DÉSACTIVÉ]';
    E_Mode.MAINT_N1: ModeStr := '[MAINT_N1]';
    E_Mode.MAINT_N2: ModeStr := '[MAINT_N2]';
    E_Mode.SEMI_AUTO: ModeStr := '[SEMI-AUTO]';
ELSE
    ModeStr := '[MODE INCONNU]';
END_CASE;

IF CurrentMode = E_Mode.SEMI_AUTO THEN
    CouplingStr := ' [CYCLE AUTO]';
ELSIF BothAxesCoupled THEN
    CouplingStr := ' [M1+M2 COUPLÉS]';
ELSIF WinchSelected = 1 THEN
    CouplingStr := ' [M1 SEUL]';
ELSIF WinchSelected = 2 THEN
    CouplingStr := ' [M2 SEUL]';
ELSE
    CouplingStr := ' [AUCUN AXE]';
END_IF;
Banner.GlobalContextText := CONCAT(CONCAT(PrefixContext, ModeStr), CouplingStr);
{endregion}

{region "§2 Progression"}
// ═══════════════════════════════════════════════════════════════
// 2. PROGRESSION — le numéro et l'étape restent exclusivement ici
// Format (AF-07 §5.1) : Macro: <Cycle> > Sous-cycle: <Étape>
// ═══════════════════════════════════════════════════════════════
// Guide homing machine : source unique = FB_CycleMachineHoming (1 texte par étape).
// Prioritaire tant que non valide (SEMI_AUTO est de toute façon interdit sans MachineHomed).
IF (MachineHomingStep > 0) AND (MachineHomingStep <> 60) THEN
    Banner.SequenceProgressText := CONCAT('Homing: ', MachineHomingInstruction);
ELSIF CurrentMode = E_Mode.SEMI_AUTO THEN
    // Détail de l'étape (FB_CycleSemiAuto.CycleStateStr) prioritaire ; label court en fallback.
    IF CycleStateStr <> '' THEN
        Banner.SequenceProgressText := CONCAT('Cycle: ', CycleStateStr);
    ELSE
        CASE CycleStep OF
            E_AutoCycleStep.AX0_REPOS: Banner.SequenceProgressText := 'Cycle: PRÉPARATION';
            E_AutoCycleStep.AX1_INIT: Banner.SequenceProgressText := 'Cycle: CONDITIONS INITIALES';
            E_AutoCycleStep.AX2_TRANSLATE_P1: Banner.SequenceProgressText := 'Cycle: TRANSLATION P1';
            E_AutoCycleStep.AX3_OPEN_BUCKET: Banner.SequenceProgressText := 'Cycle: OUVERTURE BENNE';
            E_AutoCycleStep.AX4_DESCEND_DIVING: Banner.SequenceProgressText := 'Cycle: PLONGÉE PALIER 4';
            E_AutoCycleStep.AX5_KOBOLD_INIT: Banner.SequenceProgressText := 'Cycle: INIT KOBOLD';
            E_AutoCycleStep.AX6_SEARCH_IMMERSION: Banner.SequenceProgressText := 'Cycle: RECHERCHE IMMERSION';
            E_AutoCycleStep.AX7_SEARCH_BOTTOM: Banner.SequenceProgressText := 'Cycle: RECHERCHE FOND';
            E_AutoCycleStep.AX8_BOTTOM_CONFIRMED: Banner.SequenceProgressText := 'Cycle: FOND CONFIRMÉ';
            E_AutoCycleStep.AX_DIVING_RETRY: Banner.SequenceProgressText := 'Cycle: REPRISE PLONGÉE';
            E_AutoCycleStep.AX9_RAISE_OFF_BOTTOM: Banner.SequenceProgressText := 'Cycle: RETENTE CÂBLES';
            E_AutoCycleStep.AX10_CLOSE_BUCKET: Banner.SequenceProgressText := 'Cycle: FERMETURE BENNE';
            E_AutoCycleStep.AX11_CTRL_ASCENT: Banner.SequenceProgressText := 'Cycle: MONTÉE CONTRÔLE';
            E_AutoCycleStep.AX12_LOADED_ASCENT: Banner.SequenceProgressText := 'Cycle: REMONTÉE CHARGÉE';
            E_AutoCycleStep.AX13_DRAIN_PAUSE: Banner.SequenceProgressText := 'Cycle: ÉGOUTTAGE';
            E_AutoCycleStep.AX14_TRANSLATE_DUMP: Banner.SequenceProgressText := 'Cycle: TRANSLATION TRÉMIE';
            E_AutoCycleStep.AX15A_DUMP_ARRIVE, E_AutoCycleStep.AX15B_DUMP_OPEN: Banner.SequenceProgressText := 'Cycle: VIDAGE BENNE';
            E_AutoCycleStep.AX15C_DUMP_REPOSITION: Banner.SequenceProgressText := 'Cycle: VIDAGE BENNE';
            E_AutoCycleStep.AX18_DONE_SYNC: Banner.SequenceProgressText := 'Cycle: TERMINÉ - ALLER P1';
            E_AutoCycleStep.AX_STAB: Banner.SequenceProgressText := 'Cycle: STABILISATION';
        ELSE
            Banner.SequenceProgressText := 'Cycle: ÉTAPE EN COURS';
        END_CASE;
    END_IF;
ELSIF CurrentMode = E_Mode.MAINT_N1 OR CurrentMode = E_Mode.MAINT_N2 THEN
    Banner.SequenceProgressText := 'Manuel: PILOTAGE DIRECT';
ELSE
    Banner.SequenceProgressText := 'Machine: ARRÊTÉE';
END_IF;
{endregion}

{region "§2bis Position M3"}
// État indépendant : ne participe pas aux arbitrages des quatre champs historiques
// ni au carrousel des défauts. M3AtP1 est publié par PRG_05 puis projeté par PRG_07.
IF M3AtP1 THEN
    Banner.PositionM3Text := 'Position M3 : P1';
ELSE
    Banner.PositionM3Text := '';
END_IF;
{endregion}

{region "§3 Condition spéciale"}
// ═══════════════════════════════════════════════════════════════
// 3. CONDITION SPÉCIALE — un seul indicateur bypass/dérogation
// Format (AF-07 §5.1) : ATTENTION: <Dérogation / Bridage / Alerte>
// 🧊 Warning → maintenu min (anti-clignotement), jamais critique.
// ⚠️ La simulation n'est PAS un bypass : elle n'apparaît que dans le
//    contexte global (champ 1), jamais ici.
// ═══════════════════════════════════════════════════════════════
AnyBypassActive := BypassGlobalActive
                OR BypassWinchM1Active
                OR BypassWinchM2Active
                OR BypassTranslation
                OR BypassSyncActive;
IF ModeChangePendingBlocked AND ModeChangeBlockReason <> '' THEN
    // Bascule de mode refusée : motif prioritaire (info opérateur, ex. "Chgt mode refuse : contacteur M1").
    SpecialConditionCandidate := ModeChangeBlockReason;
ELSIF AnyBypassActive THEN
    SpecialConditionCandidate := 'ATTENTION: Bypass actif';
ELSIF SyncDegradedActive THEN
    SpecialConditionCandidate := 'ATTENTION: Synchro bridée';
ELSIF LegalLimitReached THEN
    SpecialConditionCandidate := 'ATTENTION: Limite légale';
ELSE
    SpecialConditionCandidate := '';
END_IF;

AntiFlickSpecial(NewText := SpecialConditionCandidate, ForceInstant := FALSE, HoldTime := CST_BannerHoldTime);
Banner.SpecialConditionText := AntiFlickSpecial.Text;
{endregion}

{region "§4 Action opérateur"}
// ═══════════════════════════════════════════════════════════════
// 4. ACTION — cause fixe, sécurité d'abord, sans rotation
// Format (AF-07 §5.1) : [ORGANE] <Action physique> > <Fin>
// 🧊 Défauts (AU/puissance/SafeStop) + interlock DirectionBlocked
//    → affichés immédiatement (ForceInstant=TRUE) ; les autres états
//    → maintenus min (anti-clignotement).
// ═══════════════════════════════════════════════════════════════
IF CurrentMode = E_Mode.SEMI_AUTO THEN
    CurrentDirection := CycleRequestDirection;
ELSIF BothAxesCoupled THEN
    CurrentDirection := WinchBothMotionDirection;
ELSIF WinchSelected = 1 THEN
    CurrentDirection := M1LogicRequestDirection;
ELSIF WinchSelected = 2 THEN
    CurrentDirection := M2LogicRequestDirection;
ELSE
    CurrentDirection := 0;
END_IF;

DirectionBlocked := (CurrentDirection < 0 AND NOT DescendPermit)
                OR (CurrentDirection > 0 AND NOT AscentPermit);

// 🩹 Signaler la cause du dernier abandon de séquence AU (message cause+action),
// sans modifier le comportement de l'AU. Front descendant ArmingSeqStep (sequence en
// cours -> 0) = fin de sequence.
// 🐛 BUG A corrigé : l'ancien gating `NOT PowerContactorEngaged` supprimait le message
// d'abandon à l'étape 5 (PowerCutOff) car le contacteur venait d'être pulsé
// (PowerContactorEngaged=TRUE). On déclenche désormais sur la CAUSE (LastAbortCause <> 0),
// en excluant uniquement le SUCCÈS réel (séquence ayant atteint l'étape 6 de confirmation
// ET contacteur engagé au retour à IDLE) — un succès ne produit AUCUN message (AC4).
// Verrouillage : les causes SANS latch (CST_ABORT_POWER_CUTOFF, CST_ABORT_TIMEOUT_RESTORE_A/B)
// restauration) restent affichées jusqu'à Reset (ou nouvelle séquence) pour que
// l'opérateur voie l'échec. Les causes déjà latched (CST_ABORT_CHAIN_DROP/REDUNDANCY_A/B/
// TIMEOUT_CONTACTOR) et la coupe volontaire (CST_ABORT_CUT_IHM) ne sont pas verrouillées.
ArmingInProgress := (ArmingSeqStep <> 0);
LastAbortEdge(CLK := ArmingInProgress);
ResetEdge(CLK := Reset);
ArmStartEdge(CLK := ArmingInProgress);

// 🩹 Détection d'un SUCCÈS de séquence : la séquence a atteint l'étape 6 (confirmation).
// Ce drapeau est consommé par le test de LastAbortEdge ci-dessous AVANT d'être remis à
// zéro hors séquence (fin de bloc), pour distinguer un succès d'un abandon à l'étape 5.
IF ArmingSeqStep = 6 THEN
    SeqReachedConfirm := TRUE;
END_IF;

IF LastAbortEdge.Q AND (LastAbortCause <> 0) AND NOT (SeqReachedConfirm AND PowerContactorEngaged) THEN
    AbortMsgActive := TRUE;
    AbortMsgLatched := (LastAbortCause = INT_TO_WORD(CST_ABORT_POWER_CUTOFF)) OR (LastAbortCause = INT_TO_WORD(CST_ABORT_TIMEOUT_RESTORE_A)) OR (LastAbortCause = INT_TO_WORD(CST_ABORT_TIMEOUT_RESTORE_B));
    TonAbortHold(IN := FALSE);
END_IF;

// Effacement : Reset OU nouvelle séquence (évite le message périmé après réarmement réussi)
IF ResetEdge.Q OR ArmStartEdge.Q THEN
    AbortMsgActive := FALSE;
    AbortMsgLatched := FALSE;
    TonAbortHold(IN := FALSE);
END_IF;

// Remise à zéro du drapeau de confirmation hors séquence (après le test de LastAbortEdge
// ci-dessus, qui consomme sa valeur du scan précédent pour distinguer succès/abandon).
IF NOT ArmingInProgress THEN
    SeqReachedConfirm := FALSE;
END_IF;

// Maintien transitoire 5s UNIQUEMENT pour les causes non latched
IF AbortMsgActive AND NOT AbortMsgLatched THEN
    TonAbortHold(IN := TRUE, PT := CST_AbortHoldTime);
    IF TonAbortHold.Q THEN
        AbortMsgActive := FALSE;
        TonAbortHold(IN := FALSE);
    END_IF;
END_IF;
IF AbortMsgActive THEN
    IF LastAbortCause = INT_TO_WORD(CST_ABORT_CUT_IHM) THEN
        AbortMsgText := '[AU] Coupure volontaire IHM - relacher le bouton puis rearmer';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_CHAIN_DROP) THEN
        AbortMsgText := '[AU] Chute boucle urgence pendant test - relacher coup-de-poing puis rearmer';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_TIMEOUT_RESTORE_A) THEN
        AbortMsgText := '[AU] Chaine non remontee apres test A (200ms) - verifier boucle puis rearmer';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_TIMEOUT_RESTORE_B) THEN
        AbortMsgText := '[AU] Chaine non remontee apres test B (200ms) - verifier boucle puis rearmer';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_POWER_CUTOFF) THEN
        // 🩹 Décodage de la cause CST_ABORT_POWER_CUTOFF (PowerCutOff métier) en cause explicite
        // M1/M2/M3 + bit MecaA/MecaB/thermique, à partir des DUT Safety déjà en entrée.
        // Priorité : M3 (translation) puis M1 puis M2 ; MecaA > MecaB > thermique.
        IF TranslationSafety.ErrorMecaA THEN
            AbortMsgText := '[M3] MecaA (mouvement non commandé) - Reset puis réarmer';
        ELSIF TranslationSafety.ErrorMecaB THEN
            AbortMsgText := '[M3] MecaB (arrêt non confirmé) - Reset puis réarmer';
        ELSIF TranslationSafety.ErrorBrakeThermal THEN
            AbortMsgText := '[M3] Surchauffe frein - Reset puis réarmer';
        ELSIF WinchM1Safety.ErrorMecaA THEN
            AbortMsgText := '[M1] MecaA (mouvement non commandé) - Reset puis réarmer';
        ELSIF WinchM1Safety.ErrorMecaB THEN
            AbortMsgText := '[M1] MecaB (arrêt non confirmé) - Reset puis réarmer';
        ELSIF WinchM1Safety.ThermalFault THEN
            AbortMsgText := '[M1] Surchauffe moteur - Reset puis réarmer';
        ELSIF WinchM1Safety.ErrorBrakeThermal THEN
            AbortMsgText := '[M1] Surchauffe frein - Reset puis réarmer';
        ELSIF WinchM2Safety.ErrorMecaA THEN
            AbortMsgText := '[M2] MecaA (mouvement non commandé) - Reset puis réarmer';
        ELSIF WinchM2Safety.ErrorMecaB THEN
            AbortMsgText := '[M2] MecaB (arrêt non confirmé) - Reset puis réarmer';
        ELSIF WinchM2Safety.ThermalFault THEN
            AbortMsgText := '[M2] Surchauffe moteur - Reset puis réarmer';
        ELSIF WinchM2Safety.ErrorBrakeThermal THEN
            AbortMsgText := '[M2] Surchauffe frein - Reset puis réarmer';
        ELSE
            AbortMsgText := '[AU] Coupure securite metier active - lever la cause puis rearmer';
        END_IF;
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_REDUNDANCY_A) THEN
        AbortMsgText := '[AU] Defaut redondance canal A - verifier contacteur puis Reset';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_REDUNDANCY_B) THEN
        AbortMsgText := '[AU] Defaut redondance canal B - verifier contacteur puis Reset';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_TIMEOUT_CONTACTOR) THEN
        AbortMsgText := '[AU] Contacteur non engage sous 2s - verifier puis rearmer';
    ELSE
        AbortMsgText := '[AU] Rearmement interrompu - verifier et rearmer';
    END_IF;
END_IF;

IF NOT EmergencyChainClosed THEN
    OperatorActionCandidate := '[PUPITRE] Boucle urgence ouverte - réarmer';
ELSIF NOT LocalIoValid OR NOT Vh0800Valid OR NOT Vh0808Valid OR NOT Vh0008ErValid OR NOT Vh0008Er1Valid THEN
    OperatorActionCandidate := '[IO] Défaut module E/S - vérifier alimentation/coupleur';
ELSIF NOT CanBusValid THEN
    OperatorActionCandidate := '[CAN] Défaut bus CANopen - vérifier câblage';
ELSIF NOT Joy1Valid THEN
    OperatorActionCandidate := '[CAN] Joystick non détecté - vérifier liaison';
ELSIF NOT EcatBusValid THEN
    OperatorActionCandidate := '[ECAT] Défaut bus EtherCAT - vérifier liaison';
ELSIF NOT EncM1Valid OR NOT EncM2Valid THEN
    OperatorActionCandidate := '[ECAT] Codeurs non détectés - vérifier liaison';
ELSIF NOT VarM3Valid THEN
    OperatorActionCandidate := '[ECAT] Variateur non détecté - vérifier liaison';
ELSIF AbortMsgActive THEN
    // 🩹 Cause du dernier abandon de séquence AU (message explicite cause+action).
    // 🐛 BUG B corrigé : placé AVANT PowerCutOffActiveAny pour que la cause racine
    // (dont CST_ABORT_POWER_CUTOFF décodée en M1/M2/M3 + MecaA/MecaB/thermique) prime sur
    // le message générique de coupure puissance. Placé aussi avant
    // RedundancyTestFailed/EmergencyArmingFailed/SafeStop pour que chaque cause montre
    // son message spécifique — le message d'abandon est la CAUSE RACINE (plus pertinente
    // que le SafeStop qui en est une conséquence) — il prime sur SafeStop/DirectionBlocked.
    OperatorActionCandidate := AbortMsgText;
ELSIF PowerCutOffActiveAny THEN
    OperatorActionCandidate := '[SÉCURITÉ] Coupure puissance active - acquitter défaut treuil/pont';
ELSIF RedundancyTestFailed THEN
    OperatorActionCandidate := '[AU] Défaut redondance contacteurs - réarmer (Reset)';
ELSIF EmergencyArmingFailed THEN
    OperatorActionCandidate := '[AU] Échec réarmement contacteur - réarmer';
ELSIF NOT PowerContactorEngaged THEN
    OperatorActionCandidate := '[PUPITRE] Réarmer AU et puissance';
ELSIF SafeStopActive THEN
    OperatorActionCandidate := '[PUPITRE] Acquitter SafeStop';
ELSIF DirectionBlocked THEN
    IF CurrentDirection < 0 THEN
        OperatorActionCandidate := '[TREUIL] Descente interdite';
    ELSIF TopLimitReached THEN
        // 🛡️ Montée bloquée par butée logicielle haute (agrégat M1/M2) — cause exposée par le safety.
        OperatorActionCandidate := '[TREUIL] Montée interdite - limite haute';
    ELSIF WinchM1Safety.ErrorMecaD OR WinchM2Safety.ErrorMecaD THEN
        // 🛡️ Montée bloquée par capteur haut (non-arrêt au capteur haut, MecaD) — cause exposée par le safety.
        OperatorActionCandidate := '[TREUIL] Montée interdite - capteur haut';
    ELSIF WinchM1Safety.AscentPermit AND NOT WinchM2Safety.AscentPermit THEN
        // 🛡️ Montée bloquée par treuil M2 (M1 autorise, M2 non) — cause exposée par le safety.
        OperatorActionCandidate := '[TREUIL] Montée interdite - treuil M2';
    ELSE
        OperatorActionCandidate := '[TREUIL] Montée interdite';
    END_IF;
ELSIF CurrentMode = E_Mode.SEMI_AUTO THEN
    // Guidance par étape du cycle (AF-07 §5.1) — ne masque jamais un défaut
    // (priorités AU/puissance/SafeStop/DirectionBlocked ci-dessus dominent).
    CASE CycleStep OF
        E_AutoCycleStep.AX0_REPOS:
            OperatorActionCandidate := '[IHM/JOYSTICK] Démarrer le cycle (bouton Start ou homme-mort)';
        E_AutoCycleStep.AX1_INIT:
            OperatorActionCandidate := '[IHM] Vérifier conditions initiales (référencement, treuils FDC haut)';
        E_AutoCycleStep.AX2_TRANSLATE_P1:
            OperatorActionCandidate := '[JOYSTICK] Pousser vers la droite : translation vers P1';
        E_AutoCycleStep.AX3_OPEN_BUCKET:
            OperatorActionCandidate := '[IHM] Ouverture benne en cours';
        E_AutoCycleStep.AX4_DESCEND_DIVING:
            OperatorActionCandidate := '[JOYSTICK] Descendre palier 4 jusqu a l altimetrie de lancement';
        E_AutoCycleStep.AX5_KOBOLD_INIT:
            OperatorActionCandidate := '[JOYSTICK] Maintenir descente : init Kobold en cours';
        E_AutoCycleStep.AX6_SEARCH_IMMERSION:
            OperatorActionCandidate := '[JOYSTICK] Maintenir descente : entree dans l eau attendue';
        E_AutoCycleStep.AX7_SEARCH_BOTTOM:
            OperatorActionCandidate := '[JOYSTICK] Maintenir descente : detection du fond';
        E_AutoCycleStep.AX8_BOTTOM_CONFIRMED:
            OperatorActionCandidate := '[IHM] Fond touche';
        E_AutoCycleStep.AX_DIVING_RETRY:
            OperatorActionCandidate := '[JOYSTICK] Reprise plongee : remonter au FDC haut';
        E_AutoCycleStep.AX9_RAISE_OFF_BOTTOM:
            OperatorActionCandidate := '[JOYSTICK] Retente des cables (palier 1)';
        E_AutoCycleStep.AX10_CLOSE_BUCKET:
            OperatorActionCandidate := '[IHM] Fermeture benne en cours';
        E_AutoCycleStep.AX11_CTRL_ASCENT:
            OperatorActionCandidate := '[JOYSTICK] Remontee de controle';
        E_AutoCycleStep.AX12_LOADED_ASCENT:
            OperatorActionCandidate := '[IHM] Remontee en charge';
        E_AutoCycleStep.AX13_DRAIN_PAUSE:
            OperatorActionCandidate := '[IHM] Attendre egouttage (ou bypass IHM)';
        E_AutoCycleStep.AX14_TRANSLATE_DUMP:
            OperatorActionCandidate := '[JOYSTICK] Deplacer vers tremie';
        E_AutoCycleStep.AX15A_DUMP_ARRIVE, E_AutoCycleStep.AX15B_DUMP_OPEN:
            OperatorActionCandidate := '[IHM] Vidage benne';
        E_AutoCycleStep.AX15C_DUMP_REPOSITION:
            OperatorActionCandidate := '[IHM] Vidage benne';
        E_AutoCycleStep.AX18_DONE_SYNC:
            OperatorActionCandidate := '[JOYSTICK] Cycle termine : aller en P1 pour recommencer';
        E_AutoCycleStep.AX_STAB:
            // Libellé de l'étape d'origine du défaut (CycleStepAtError).
            CASE CycleStepAtError OF
                E_AutoCycleStep.AX0_REPOS: StepAtErrorStr := 'X0 (préparation)';
                E_AutoCycleStep.AX1_INIT: StepAtErrorStr := 'X1 (référencement)';
                E_AutoCycleStep.AX2_TRANSLATE_P1: StepAtErrorStr := 'X2 (sélection position)';
                E_AutoCycleStep.AX3_OPEN_BUCKET: StepAtErrorStr := 'X3 (ouverture benne)';
                E_AutoCycleStep.AX4_DESCEND_DIVING: StepAtErrorStr := 'AX4 (plongee palier 4)';
                E_AutoCycleStep.AX5_KOBOLD_INIT: StepAtErrorStr := 'AX5 (init Kobold)';
                E_AutoCycleStep.AX6_SEARCH_IMMERSION: StepAtErrorStr := 'AX6 (recherche immersion)';
                E_AutoCycleStep.AX7_SEARCH_BOTTOM: StepAtErrorStr := 'AX7 (recherche fond)';
                E_AutoCycleStep.AX8_BOTTOM_CONFIRMED: StepAtErrorStr := 'AX8 (fond confirme)';
                E_AutoCycleStep.AX_DIVING_RETRY: StepAtErrorStr := 'AX_DIVING_RETRY (reprise plongee)';
                E_AutoCycleStep.AX9_RAISE_OFF_BOTTOM: StepAtErrorStr := 'AX9 (retente cables)';
                E_AutoCycleStep.AX10_CLOSE_BUCKET: StepAtErrorStr := 'AX10 (fermeture benne)';
                E_AutoCycleStep.AX11_CTRL_ASCENT: StepAtErrorStr := 'AX11 (remontee controle)';
                E_AutoCycleStep.AX12_LOADED_ASCENT: StepAtErrorStr := 'AX12 (remontee chargee)';
                E_AutoCycleStep.AX13_DRAIN_PAUSE: StepAtErrorStr := 'AX13 (egouttage)';
                E_AutoCycleStep.AX14_TRANSLATE_DUMP: StepAtErrorStr := 'AX14 (translation tremie)';
                E_AutoCycleStep.AX15A_DUMP_ARRIVE: StepAtErrorStr := 'AX15a (arrivee tremie)';
                E_AutoCycleStep.AX15B_DUMP_OPEN: StepAtErrorStr := 'AX15b (vidage benne)';
                E_AutoCycleStep.AX15C_DUMP_REPOSITION: StepAtErrorStr := 'AX15c (repositionnement)';
                E_AutoCycleStep.AX18_DONE_SYNC: StepAtErrorStr := 'AX18 (cycle termine)';
                E_AutoCycleStep.AX_STAB: StepAtErrorStr := 'AX_STAB (stabilisation)';
                ELSE
                    StepAtErrorStr := '?';
            END_CASE;
            // Message compact : ID défaut (ErrorId) + étape d'origine + acquitter.
            // Le détail de la cause est consultable dans le dépannage (GVL_Troubleshooting).
            OperatorActionCandidate := CONCAT('[PUPITRE] Défaut #', CONCAT(WORD_TO_STRING(CycleErrorId), CONCAT(' (étape ', CONCAT(StepAtErrorStr, ') - acquitter'))));
        ELSE
            OperatorActionCandidate := '[IHM] Cycle en cours...';
    END_CASE;
ELSIF DiveActive AND CurrentDirection < 0 THEN
    OperatorActionCandidate := '[TREUIL] Attendre fin du Dive';
ELSIF NOT BucketIsOpen AND CurrentDirection < 0 THEN
    OperatorActionCandidate := '[BENNE] Ouvrir la benne';
ELSIF TopLimitReached AND CurrentDirection > 0 THEN
    OperatorActionCandidate := '[TREUIL] Limite haute';
ELSIF NOT BucketIsClosed AND CurrentDirection > 0 THEN
    // Sécurité : benne mal fermée (branche/caillou) → montee bridee palier 1 pour eviter un choc
    // si la benne se refermait d'un coup en montant vite.
    OperatorActionCandidate := '[BENNE] Benne non fermee - montee bridee palier 1 (securite)';
ELSIF NOT DeadmanArmed THEN
    OperatorActionCandidate := '[JOYSTICK] Appuyer homme-mort au neutre';
ELSIF CurrentMode = E_Mode.DISABLE THEN
    OperatorActionCandidate := '[IHM] Sélectionner un mode';
ELSIF JoystickAtNeutral THEN
    OperatorActionCandidate := '[JOYSTICK] Armé - actionner axe';
ELSE
    OperatorActionCandidate := '[JOYSTICK] Déplacement en cours';
END_IF;

// Interlock = mouvement demandé mais permit absent : c'est une cause
// sécurité (blocage de mouvement) → affichage IMMÉDIAT, comme un défaut.
PowerOrChainFault := (NOT EmergencyChainClosed OR NOT PowerContactorEngaged OR PowerCutOffActiveAny);
HardwareModuleOrBusFault := (NOT LocalIoValid OR NOT Vh0800Valid OR NOT Vh0808Valid OR NOT Vh0008ErValid OR NOT Vh0008Er1Valid OR NOT CanBusValid OR NOT Joy1Valid OR NOT EcatBusValid OR NOT EncM1Valid OR NOT EncM2Valid OR NOT VarM3Valid);
CriticalActionActive := (PowerOrChainFault OR HardwareModuleOrBusFault OR SafeStopActive OR DirectionBlocked);

AntiFlickOperator(NewText := OperatorActionCandidate, ForceInstant := CriticalActionActive, HoldTime := CST_BannerHoldTime);
Banner.OperatorActionText := AntiFlickOperator.Text;
{endregion}

{region "§5 Bandeau alarme"}
// ═══════════════════════════════════════════════════════════════
// 5. BANDEAU D'ALARME — carrousel des défauts actifs (index n/N)
// Format (AF-07 §6) : [ORGANE] raison_brève. Un défaut à la fois,
// rotation 1→2→…→N→1, maintien AlarmHoldTime par message.
// 🧊 Distinct des 4 champs ci-dessus (AF-07 §5.2) : ce carrousel est
//    le SEUL endroit du bandeau qui publie Error/ErrorId (alarmes).
// ═══════════════════════════════════════════════════════════════
AlarmCount := 0;

// 5.0 Collecte — Défauts matériels parents (priorité absolue carrousel)
IF NOT LocalIoValid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[IO] Defaut module Local IO (DI8/DO8)'; AlarmCount := AlarmCount + 1;
END_IF;
IF NOT Vh0800Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[IO] Defaut module VH0800END (DI8)'; AlarmCount := AlarmCount + 1;
END_IF;
IF NOT Vh0808Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[IO] Defaut module VH0808ETP (DI8/DO8)'; AlarmCount := AlarmCount + 1;
END_IF;
IF NOT Vh0008ErValid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[IO] Defaut module VH0008ER (DO8 Relais)'; AlarmCount := AlarmCount + 1;
END_IF;
IF NOT Vh0008Er1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[IO] Defaut module VH0008ER_1 (DO8 Relais)'; AlarmCount := AlarmCount + 1;
END_IF;
IF NOT CanBusValid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[CAN] Defaut bus CANopen'; AlarmCount := AlarmCount + 1;
END_IF;
IF CanBusValid AND NOT Joy1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[CAN] Joystick JOY1 non detecte'; AlarmCount := AlarmCount + 1;
END_IF;
IF NOT EcatBusValid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[ECAT] Defaut bus EtherCAT'; AlarmCount := AlarmCount + 1;
END_IF;
IF EcatBusValid AND NOT EncM1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M1] Codeur absolu COD1 non detecte (ECAT)'; AlarmCount := AlarmCount + 1;
END_IF;
IF EcatBusValid AND NOT EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M2] Codeur absolu COD2 non detecte (ECAT)'; AlarmCount := AlarmCount + 1;
END_IF;
IF EcatBusValid AND NOT VarM3Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M3] Variateur AC600 non detecte (ECAT)'; AlarmCount := AlarmCount + 1;
END_IF;

// 5a. Collecte — treuil M1 (ST_SafetyWinch, bits ErrorId décodés)
// 🧊 Tri bloquant/warning (AF-07 §6, décision 2026-09-01) : seuls les défauts
//    BLOQUANTS (SafeStop/PowerCutOff/interlock) sont publiés. Les warnings non
//    bloquants (mou de câble, surchauffe moteur/frein, limites basse/haute) sont
//    EXCLUS du carrousel — ils restent visibles via OperatorActionText/SpecialCondition.
IF WinchM1Safety.ErrorOperatorComm AND Joy1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M1] ErrorID:01 - perte com operateur'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM1Safety.ErrorEncoder AND EncM1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M1] ErrorID:02 - perte codeur'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM1Safety.ErrorPhaseRotation AND Vh0800Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M1] ErrorID:05 - rotation phases'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM1Safety.ErrorMecaA AND EncM1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M1] ErrorID:08 - MecaA - deplacement sans commande (vitesse/derive)'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM1Safety.ErrorMecaB AND EncM1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M1] ErrorID:09 - MecaB - arret non confirme apres stop'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM1Safety.ErrorMecaC AND EncM1Valid AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M1] ErrorID:10 - MecaC - glissement pendant benne figee'; AlarmCount := AlarmCount + 1;
