    AlarmArray[AlarmCount] := '[M3] ErrorID:07 - butee extreme'; AlarmCount := AlarmCount + 1;
END_IF;
IF TranslationSafety.ErrorSensorIncoherent AND Vh0808Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M3] ErrorID:08 - capteurs incoherents'; AlarmCount := AlarmCount + 1;
END_IF;

// 5d. Collecte — benne (FB_Bucket.ErrorId, bits décodés)
//    Mapping = index cause FB_Bucket (FB_FaultCore : bit i = cause i) :
//    bit0 config géométrie · bit1 écart max · bit2 timeout · bit3 glissement M1 · bit4 codeurs non référencés
IF ((BucketErrorId AND 16#0001) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[BENNE] ErrorID:01 - configuration geometrie invalide'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((BucketErrorId AND 16#0002) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[BENNE] ErrorID:02 - depassement ecart max autorise'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((BucketErrorId AND 16#0004) <> 16#0000) AND EncM1Valid AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[BENNE] ErrorID:03 - timeout commande deplacement'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((BucketErrorId AND 16#0008) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[BENNE] ErrorID:04 - glissement treuil M1'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((BucketErrorId AND 16#0010) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[BENNE] ErrorID:05 - codeurs treuils non references'; AlarmCount := AlarmCount + 1;
END_IF;

// 5e. Collecte — synchro M1/M2 (FB_WinchSync.ErrorId)
IF ((SyncErrorId AND 16#0001) <> 16#0000) AND EncM1Valid AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[SYNC] ErrorID:01 - ecart M1/M2'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((SyncErrorId AND 16#0002) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[SYNC] ErrorID:02 - incoherence commande'; AlarmCount := AlarmCount + 1;
END_IF;
// Discordance contacteurs M1/M2 decodee (FB_SyncContactor PRG_06 §2quinquies) : quel contacteur + niveau.
IF (SyncContactorDiag.MismatchLevel >= 1) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    IF    SyncContactorDiag.RelayFwdMismatch THEN BannerSyncContactorWhich := 'relais montee';
    ELSIF SyncContactorDiag.RelayRevMismatch THEN BannerSyncContactorWhich := 'relais descente';
    ELSIF SyncContactorDiag.Step1Mismatch   THEN BannerSyncContactorWhich := 'palier 1';
    ELSIF SyncContactorDiag.Step2Mismatch   THEN BannerSyncContactorWhich := 'palier 2';
    ELSIF SyncContactorDiag.Step3Mismatch   THEN BannerSyncContactorWhich := 'palier 3';
    ELSIF SyncContactorDiag.Step4Mismatch   THEN BannerSyncContactorWhich := 'palier 4';
    ELSE  BannerSyncContactorWhich := '';
    END_IF;
    IF SyncContactorDiag.MismatchLevel >= 2 THEN
        AlarmArray[AlarmCount] := CONCAT('[SYNC] discordance M1/M2 persistante -> coupure : ', BannerSyncContactorWhich);
    ELSE
        AlarmArray[AlarmCount] := CONCAT('[SYNC] discordance contacteurs M1/M2 -> arret : ', BannerSyncContactorWhich);
    END_IF;
    AlarmCount := AlarmCount + 1;
END_IF;

// 5f. Collecte — plongée / extraction (FB_DiveSearch / FB_ExtractionAssist)
IF ((DiveErrorId AND 16#0001) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[DIVE] ErrorID:01 - timeout immersion'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((DiveErrorId AND 16#0002) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[DIVE] ErrorID:02 - timeout fond'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((DiveErrorId AND 16#0004) <> 16#0000) AND EncM1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[DIVE] ErrorID:03 - limite basse atteinte'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((DiveErrorId AND 16#0008) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[DIVE] ErrorID:04 - contact fond perdu'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((DiveErrorId AND 16#0010) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[DIVE] ErrorID:05 - perte tension cable'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((DiveErrorId AND 16#0020) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[DIVE] ErrorID:06 - anomalie vitesse'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((DiveErrorId AND 16#0040) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[DIVE] ErrorID:07 - config invalide'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((ExtractionErrorId AND 16#0001) <> 16#0000) AND LocalIoValid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[EXTRACTION] ErrorID:01 - fond'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((ExtractionErrorId AND 16#0002) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[EXTRACTION] ErrorID:02 - fermeture'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((ExtractionErrorId AND 16#0004) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[EXTRACTION] ErrorID:03 - controle'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((ExtractionErrorId AND 16#0008) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[EXTRACTION] ErrorID:04 - config'; AlarmCount := AlarmCount + 1;
END_IF;

// 5g. Collecte — AU / armement (FB_Safety_EmergencyManagement.Diag.ErrorId)
IF ((EmergencyErrorId AND 16#0001) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[AU] ErrorID:01 - redondance contacteurs'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((EmergencyErrorId AND 16#0002) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[AU] ErrorID:02 - echec confirmation armement'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((EmergencyErrorId AND 16#0008) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[AU] ErrorID:04 - echec autotest demarrage'; AlarmCount := AlarmCount + 1;
END_IF;

// 5h. Collecte — cycle semi-auto (FB_CycleSemiAuto.ErrorId)
IF ((CycleErrorId AND 16#0001) <> 16#0000) AND EncM1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[CYCLE] ErrorID:01 - limite legale atteinte'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((CycleErrorId AND 16#0002) <> 16#0000) AND EncM1Valid AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[CYCLE] ErrorID:02 - defaut synchro treuils'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((CycleErrorId AND 16#0008) <> 16#0000) AND EncM1Valid AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[CYCLE] ErrorID:04 - ecart codeurs remontee'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((CycleErrorId AND 16#0010) <> 16#0000) AND EncM1Valid AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[CYCLE] ErrorID:05 - ecart vitesse confirme'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((CycleErrorId AND 16#0020) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[CYCLE] ErrorID:06 - perte communication IHM'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((CycleErrorId AND 16#0040) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[CYCLE] ErrorID:07 - timeout etape'; AlarmCount := AlarmCount + 1;
END_IF;

// 5i. Collecte [HISTO] — défauts latched passés (LatchedId AND NOT ErrorId)
// 🕘 Marqueur [HISTO] (AF-07 §6, décision 2026-09-01) : un défaut laté dont la cause a
//    disparu (bit LatchedId=1 ET bit ErrorId=0) reste affiché préfixé [HISTO] tant qu'il
//    n'est pas acquitté (Reset). M1/M2/M3 uniquement (vue latched exposée dans les DUT
//    safety). Les warnings (mou de câble, surchauffe) sont inclus ici : ce sont des défauts
//    passés à acquitter, distincts du carrousel actif (bloquants seuls).
HistoM1 := WinchM1Safety.LatchedId AND (NOT WinchM1Safety.ErrorId);
HistoM2 := WinchM2Safety.LatchedId AND (NOT WinchM2Safety.ErrorId);
HistoM3 := TranslationSafety.LatchedId AND (NOT TranslationSafety.ErrorId);

// ── M1 [HISTO] ──
IF (HistoM1 AND 16#0001) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:01 - perte com operateur'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#0002) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:02 - perte codeur'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#0004) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:03 - surchauffe moteur'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#0008) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:04 - mou de cable'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#0010) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:05 - rotation phases'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#0080) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:08 - MecaA - deplacement sans commande (vitesse/derive)'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#0100) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:09 - MecaB - arret non confirme apres stop'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#0200) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:10 - MecaC - glissement pendant benne figee'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#0400) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:11 - surchauffe frein'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#0800) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:12 - MecaD - non-arret au capteur haut'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#1000) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:13 - MecaE - ecart synchro M1/M2 critique'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#4000) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:15 - sens oppose'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#8000) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:16 - absence mouvement'; AlarmCount := AlarmCount + 1;
END_IF;

// ── M2 [HISTO] ──
IF (HistoM2 AND 16#0001) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:01 - perte com operateur'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#0002) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:02 - perte codeur'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#0004) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:03 - surchauffe moteur'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#0008) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:04 - mou de cable'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#0010) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:05 - rotation phases'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#0080) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:08 - MecaA - deplacement sans commande (vitesse/derive)'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#0100) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:09 - MecaB - arret non confirme apres stop'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#0200) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:10 - MecaC - glissement pendant benne figee'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#0400) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:11 - surchauffe frein'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#0800) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:12 - MecaD - non-arret au capteur haut'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#1000) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:13 - MecaE - ecart synchro M1/M2 critique'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#4000) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:15 - sens oppose'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#8000) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:16 - absence mouvement'; AlarmCount := AlarmCount + 1;
END_IF;

// ── M3 [HISTO] ──
IF (HistoM3 AND 16#0001) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M3] ErrorID:01 - perte com operateur'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM3 AND 16#0002) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M3] ErrorID:02 - perte EtherCAT'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM3 AND 16#0004) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M3] ErrorID:03 - rotation phases'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM3 AND 16#0008) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M3] ErrorID:04 - surchauffe frein'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM3 AND 16#0010) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M3] ErrorID:05 - MecaB - arret non confirme apres stop'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM3 AND 16#0020) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M3] ErrorID:06 - MecaA - deplacement sans commande'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM3 AND 16#0040) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M3] ErrorID:07 - butee extreme'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM3 AND 16#0080) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M3] ErrorID:08 - capteurs incoherents'; AlarmCount := AlarmCount + 1;
END_IF;

// 5j. Rotation carrousel — un message à la fois, maintien AlarmHoldTime
// Publication du tableau complet instantane dans le DUT IHM
FOR i := AlarmCount TO (CST_NbMaxAlarmes - 1) DO
    AlarmArray[i] := '';
END_FOR;
Banner.AlarmBanner.AlarmArray := AlarmArray;

IF AlarmCount = 0 THEN
    AlarmIndex := 0;
    Banner.AlarmBanner.HasAlarm := FALSE;
    Banner.AlarmBanner.Text  := '';
    Banner.AlarmBanner.Index := 0;
    Banner.AlarmBanner.Count := 0;
    TonAlarmBanner(IN := FALSE);
ELSE
    // Index reborné si le nombre de messages a diminué depuis le dernier scan.
    IF AlarmIndex >= AlarmCount THEN
        AlarmIndex := 0;
    END_IF;
    Banner.AlarmBanner.HasAlarm := TRUE;
    TonAlarmBanner(IN := TRUE, PT := AlarmHoldTime);
    IF TonAlarmBanner.Q THEN
        AlarmIndex := (AlarmIndex + 1) MOD AlarmCount;
        TonAlarmBanner(IN := FALSE);
    END_IF;
    // Index n/N prefixe directement dans le texte (ex. '1/2 [M1] perte codeur'),
    // en plus des champs Index/Count numeriques pour un usage IHM programmatique.
    Banner.AlarmBanner.Text := CONCAT(INT_TO_STRING(AlarmIndex + 1),
                                CONCAT('/',
                                CONCAT(INT_TO_STRING(AlarmCount),
                                CONCAT(' ', AlarmArray[AlarmIndex]))));
    Banner.AlarmBanner.Index := AlarmIndex + 1;
    Banner.AlarmBanner.Count := AlarmCount;
END_IF;
{endregion}

{region "§1 CAUSES + SOCLE (appele AVANT le gate)"}
// 🎯 CAUSES exprimées en CLAIR (liste ST_FaultCause) — plus de bitfield WORD.
//    - CalibFail : cause A ACQUITTER (Latching=TRUE) -> arme Fault.Latched.
//    - RawOutOfRange / BusLost : cause LIVE seulement (Latching=FALSE) -> Fault.Error, retombe seule.
//    Interlock sur la cause brute ; le socle gère latch/reset.
RawOutOfRange := (RawX < (0 - Cfg.RawOutOfRangeMargin))
              OR (RawX > (10000 + Cfg.RawOutOfRangeMargin))
              OR (RawY < (0 - Cfg.RawOutOfRangeMargin))
              OR (RawY > (10000 + Cfg.RawOutOfRangeMargin));
BusLost := (NOT BusCanOpenOP.Operational OR NOT JoystickOP.Operational);

// Calibration : un front (Calibrate) hors zone -> cause a acquitter. La cause reste active tant que
// les axes sont HORS zone valide [2000..8000] : Reset ne l'efface que si la cause a disparu
// (interlock socle sur la cause brute). Effacee par un Reset avec axes en zone.
IF Calibrate AND NOT LastCalibrate THEN
    IF RawX >= 2000 AND RawX <= 8000 AND RawY >= 2000 AND RawY <= 8000 THEN
        NeutralXMem := RawX;       // memorisation nouvelle position neutre X
        NeutralYMem := RawY;       // memorisation nouvelle position neutre Y
        CalibFail := FALSE;        // calibration valide : plus de cause
    ELSE
        CalibFail := TRUE;         // échec : cause a acquitter (persistante tant que hors zone)
    END_IF;
END_IF;
LastCalibrate := Calibrate;
// Ré-acquisition de la cause (front Reset + cause disparue) : n'efface la cause QUE si les
// axes sont revenus en zone valide. Reste latee tant que hors zone (interlock sur cause brute).
IF Reset AND (RawX >= 2000 AND RawX <= 8000 AND RawY >= 2000 AND RawY <= 8000) THEN
    CalibFail := FALSE;
END_IF;

// Remplissage de la LISTE de causes pour le socle (index 0..2)
// Cause en clair (Active/Latching/Texte) ; 3 causes fixes.
instCauses[0].Active := CalibFail;     instCauses[0].Latching := TRUE;
instCauses[0].Texte := 'Echec calibration joystick (RawX/Y hors zone)';
instCauses[1].Active := RawOutOfRange; instCauses[1].Latching := FALSE;
instCauses[1].Texte := 'Capteur joystick hors plage ADC';
instCauses[2].Active := BusLost;       instCauses[2].Latching := FALSE;
instCauses[2].Texte := 'Perte liaison bus CAN joystick';

// Appel du socle TOUJOURS (meme si le gate RETURN ensuite) : la cause bus doit etre vue.
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;     // source de verite = socle

// Disponibilite = Enable + bus OK + pas de defaut LATE. Une cause live (bus, capteur) ne latche pas
// -> elle n'entre pas dans Fault.Latched ; le bus est deja couvert par ...OP.Operational ci-dessous.
Ready := Enable AND BusCanOpenOP.Operational AND JoystickOP.Operational AND NOT Fault.Latched;
{endregion}

{region "§2 Gate securite (neutralisation pipeline, n efface pas le statut)"}
// 1. GATE — neutralise le pipeline si indisponible. Le statut a deja ete rempli (zone 0).
IF NOT Enable OR BusLost THEN
    AxisCmdX.Enable := FALSE; AxisCmdX.StartStop := FALSE; AxisCmdX.SpeedTgt := 0.0; AxisCmdX.StepTgt := 0;
    AxisCmdX.DirectionPositive := FALSE; AxisCmdX.DirectionNegative := FALSE; AxisCmdX.AtNeutral := TRUE;
    AxisCmdY.Enable := FALSE; AxisCmdY.StartStop := FALSE; AxisCmdY.SpeedTgt := 0.0; AxisCmdY.StepTgt := 0;
    AxisCmdY.DirectionPositive := FALSE; AxisCmdY.DirectionNegative := FALSE; AxisCmdY.AtNeutral := TRUE;
    AxisCmdX.Direction := 0; AxisCmdX.Deflection := 0;
    AxisCmdY.Direction := 0; AxisCmdY.Deflection := 0;
    AtNeutralXY := TRUE;
    DeadmanArmed := FALSE;
    DeadmanArmPending := FALSE;
    InversionLockActive := FALSE;
    PrevDirX := 0;
    PrevDirY := 0;
    ArmingPermitDenied := FALSE;
    NeutralXYEdge(CLK := FALSE);
    NeutralHoldTimer(IN := FALSE, PT := Cfg.NeutralHoldTime);
    DeadmanArmTimer(IN := FALSE, PT := Cfg.DeadmanArmHoldTime);
    DeadmanArmGraceTimer(IN := FALSE, PT := Cfg.DeadmanArmGraceTime);
    NeutralXAct := NeutralXMem;
    NeutralYAct := NeutralYMem;
    RETURN;
END_IF;
{endregion}

{region "§3 Acquisition + mise a l echelle"}
// Mise a l'echelle (deadband) - le neutre s'evalue sur les 2 axes
ScaleX(RawIn := RawX, Neutral := NeutralXMem, DeadbandRaw := Cfg.DeadbandRaw);
ScaleY(RawIn := RawY, Neutral := NeutralYMem, DeadbandRaw := Cfg.DeadbandRaw);
AtNeutralXY := (ScaleX.OutPct = 0.0) AND (ScaleY.OutPct = 0.0);   // les 2 axes en zone morte - permis mouvement
{endregion}

{region "§4 Armement homme mort"}
// 🔀 Inversion inter-scan : le sens n'est RETENU que si la déflexion dépasse
// CST_InversionFlipThreshold_Pct (>> bruit Hall / bord de deadband). Un aller-retour
// +1<->-1 sans échantillon 0 pose le verrou. Levé exclusivement au front AtNeutralXY.
// RawOutOfRange : lecture capteur non fiable -> aucun sens retenu (le geste est déjà forcé à 0
// par le SEL du pipeline). Une reprise capteur-défaut -> valide ne compte donc pas comme flip.
DirX := 0;
DirY := 0;
IF NOT RawOutOfRange THEN
    IF ScaleX.OutPct > CST_InversionFlipThreshold_Pct THEN
        DirX := 1;
    ELSIF ScaleX.OutPct < -CST_InversionFlipThreshold_Pct THEN
        DirX := -1;
    END_IF;
    IF ScaleY.OutPct > CST_InversionFlipThreshold_Pct THEN
        DirY := 1;
    ELSIF ScaleY.OutPct < -CST_InversionFlipThreshold_Pct THEN
        DirY := -1;
    END_IF;
END_IF;
FlipX := ((PrevDirX = 1) AND (DirX = -1)) OR ((PrevDirX = -1) AND (DirX = 1));
FlipY := ((PrevDirY = 1) AND (DirY = -1)) OR ((PrevDirY = -1) AND (DirY = 1));

NeutralXYEdge(CLK := AtNeutralXY);
IF NeutralXYEdge.Q THEN
    InversionLockActive := FALSE;
END_IF;

IF FlipX OR FlipY THEN
    InversionLockActive := TRUE;
    DeadmanArmed := FALSE;
    DeadmanArmPending := FALSE;
END_IF;

// Bouton homme-mort : armement par MAINTIEN (Cfg.DeadmanArmHoldTime), independant de la position.
// ⚠️ Un appui PENDANT le verrou d'inversion n'arme PAS de demande : le nouveau front conscient
//    doit survenir APRÈS le retour au neutre (sinon on "pré-charge" le réarmement stick inversé).
DeadmanEdge(CLK := RawButton);
IF DeadmanEdge.Q AND NOT InversionLockActive THEN DeadmanArmPending := TRUE; END_IF;
IF NOT RawButton THEN DeadmanArmPending := FALSE; END_IF;

// Securite : armage UNIQUEMENT si DeadmanArmPending ET ArmingPermit.
DeadmanArmTimer(IN := DeadmanArmPending AND NOT DeadmanArmed AND ArmingPermit AND NOT InversionLockActive, PT := Cfg.DeadmanArmHoldTime);
IF DeadmanArmTimer.Q THEN
    DeadmanArmed := TRUE;
    DeadmanArmPending := FALSE;
END_IF;

// Désarmement externe immédiat : le retrait d'ArmingPermit (changement de mode, fin de cycle
// benne) désarme TOUT DE SUITE le geste — pas d'armement résiduel "surprise" à la ré-acquisition.
IF NOT ArmingPermit THEN
    DeadmanArmed := FALSE;
    DeadmanArmPending := FALSE;
END_IF;

// Avertissement "armage non autorise" (niveau, pendant l'appui non autorise)
ArmingPermitDenied := RawButton AND NOT ArmingPermit;

// Desarmage par maintien au neutre (apres grace)
DeadmanArmGraceTimer(IN := DeadmanArmed, PT := Cfg.DeadmanArmGraceTime);
NeutralHoldTimer(IN := DeadmanArmed AND AtNeutralXY AND DeadmanArmGraceTimer.Q, PT := Cfg.NeutralHoldTime);
IF NeutralHoldTimer.Q THEN DeadmanArmed := FALSE; END_IF;
{endregion}

{region "§5 Pipeline axe X"}
CmdXVal := SEL(DeadmanArmed AND NOT RawOutOfRange, 0.0, ScaleX.OutPct);

AxisCmdX.Enable := NOT RawOutOfRange AND ArmingPermit;
AxisCmdX.SpeedTgt := ABS(CmdXVal);   // NON signee (le sens = bits DirectionPositive/Negative + AxisCmdX.Direction)
AxisCmdX.StartStop := (ABS(CmdXVal) > CST_DirectionQualificationThreshold_Pct);

AxisCmdX.DirectionPositive := (CmdXVal > CST_DirectionQualificationThreshold_Pct);
AxisCmdX.DirectionNegative := (CmdXVal < -CST_DirectionQualificationThreshold_Pct);
AxisCmdX.AtNeutral := NOT AxisCmdX.DirectionPositive AND NOT AxisCmdX.DirectionNegative;
IF AxisCmdX.AtNeutral THEN AxisCmdX.SpeedTgt := 0.0; END_IF;

// Projections monitoring dans le struct (les bits restent la source logique)
IF AxisCmdX.DirectionPositive THEN AxisCmdX.Direction := 1;
ELSIF AxisCmdX.DirectionNegative THEN AxisCmdX.Direction := -1;
ELSE AxisCmdX.Direction := 0; END_IF;
AxisCmdX.Deflection := REAL_TO_INT(CmdXVal);   // deflexion signee -100..+100 % (anim IHM)
{endregion}

{region "§6 Pipeline axe Y et sorties"}
CmdYVal := SEL(DeadmanArmed AND NOT RawOutOfRange, 0.0, ScaleY.OutPct);

AxisCmdY.Enable := NOT RawOutOfRange AND ArmingPermit;
AxisCmdY.SpeedTgt := ABS(CmdYVal);   // NON signee (le sens = bits DirectionPositive/Negative + AxisCmdY.Direction)
AxisCmdY.StartStop := (ABS(CmdYVal) > CST_DirectionQualificationThreshold_Pct);

AxisCmdY.DirectionPositive := (CmdYVal > CST_DirectionQualificationThreshold_Pct);
AxisCmdY.DirectionNegative := (CmdYVal < -CST_DirectionQualificationThreshold_Pct);
AxisCmdY.AtNeutral := NOT AxisCmdY.DirectionPositive AND NOT AxisCmdY.DirectionNegative;
IF AxisCmdY.AtNeutral THEN AxisCmdY.SpeedTgt := 0.0; END_IF;

// 🪜 Decodage consigne % -> palier (logique FB_Winch §5, deplacee au joystick).
//    AxisCmdY.SpeedTgt (%) reste pour l'IHM ; AxisCmdY.StepTgt (1..5, 0=arret) pour la logique/limitations.
SpeedStepHyst1(IN := REAL_TO_INT(AxisCmdY.SpeedTgt), HIGH := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[1] + Cfg.SpeedStepHystMargin), LOW := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[1] - Cfg.SpeedStepHystMargin));
SpeedStepHyst2(IN := REAL_TO_INT(AxisCmdY.SpeedTgt), HIGH := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[2] + Cfg.SpeedStepHystMargin), LOW := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[2] - Cfg.SpeedStepHystMargin));
SpeedStepHyst3(IN := REAL_TO_INT(AxisCmdY.SpeedTgt), HIGH := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[3] + Cfg.SpeedStepHystMargin), LOW := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[3] - Cfg.SpeedStepHystMargin));
SpeedStepHyst4(IN := REAL_TO_INT(AxisCmdY.SpeedTgt), HIGH := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[4] + Cfg.SpeedStepHystMargin), LOW := REAL_TO_INT(Cfg.SpeedStepTable.StepThreshold_Pct[4] - Cfg.SpeedStepHystMargin));

// ⚠️ HYSTERESIS (Util CODESYS) est un hystérésis BAS : OUT=TRUE quand IN<LOW, OUT=FALSE
//    quand IN>HIGH. Pour un décodage ASCENDANT (petite déflexion → palier bas, grande →
//    palier haut) on teste donc `NOT OUT` : palier supérieur seulement une fois IN au-dessus
//    du seuil (bande d'hystérésis LOW..HIGH autour de StepThreshold_Pct[n]).
IF AxisCmdY.SpeedTgt <= CST_DirectionQualificationThreshold_Pct THEN
    AxisCmdY.StepTgt := 0;
ELSE
    AxisCmdY.StepTgt := 1;
    IF NOT SpeedStepHyst1.OUT THEN AxisCmdY.StepTgt := 2; END_IF;
    IF NOT SpeedStepHyst2.OUT THEN AxisCmdY.StepTgt := 3; END_IF;
    IF NOT SpeedStepHyst3.OUT THEN AxisCmdY.StepTgt := 4; END_IF;
    IF NOT SpeedStepHyst4.OUT THEN AxisCmdY.StepTgt := 5; END_IF;
END_IF;

// Projections monitoring dans le struct (les bits restent la source logique)
IF AxisCmdY.DirectionPositive THEN AxisCmdY.Direction := 1;
ELSIF AxisCmdY.DirectionNegative THEN AxisCmdY.Direction := -1;
ELSE AxisCmdY.Direction := 0; END_IF;
AxisCmdY.Deflection := REAL_TO_INT(CmdYVal);   // deflexion signee -100..+100 % (anim IHM)

// Memorisation apres traitement : l'inversion suivante compare deux scans qualifies successifs.
PrevDirX := DirX;
PrevDirY := DirY;

// Miroirs point neutre courant
NeutralXAct := NeutralXMem;
NeutralYAct := NeutralYMem;
{endregion}

IF Hmi <> Prev THEN
    RetainVal := Hmi;
ELSE
    Hmi := RetainVal;
END_IF;
Prev := Hmi;

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. RESTAURATION BOOT DES DRAPEAUX PERSISTANTS
// Non-RETAIN -> réinitialisé à chaque warm/cold reset ; relu depuis GVL_PERSISTENT (miroir
// réécrit chaque scan par PRG_03). Aucune perte du re-homing obligatoire sur coupure.
IF NOT FirstScanDone THEN
    FirstScanDone         := TRUE;
    MaintHomingRequiredM1 := BootHomingRequiredM1;
    MaintHomingRequiredM2 := BootHomingRequiredM2;
    PrevArbitratedMode    := E_Mode.DISABLE;
END_IF;

// 🔑 1ter. RE-HOMING OBLIGATOIRE — ARMEMENT IMMÉDIAT (AF-05 §4bis)
// Armé AVANT l'arbitrage de mode (§3) et non à la sortie du mode maintenance :
//   1. pas de fenêtre d'un scan où le re-homing serait perdu malgré un override effectif ;
//   2. pas de perte de l'obligation sur coupure / download pendant la maintenance
//      (la valeur est écrite dans le miroir PERSISTENT dès le scan courant, pas à la sortie).
// Le re-homing ne bloque PAS la sélection SEMI_AUTO : il est publié à l'IHM
// (Auth.HomingRequiredM1/M2) et le cycle ne progresse pas tant qu'il n'est pas levé.
IF M1PositionLimitOverridden THEN
    MaintHomingRequiredM1 := TRUE;
END_IF;
IF M2PositionLimitOverridden THEN
    MaintHomingRequiredM2 := TRUE;
END_IF;

// Levée : UNIQUEMENT sur cycle de homing complet réussi (Done + Homed + non suspect).
IF MaintHomingRequiredM1 AND M1HomingDone AND M1Homed AND NOT M1HomingSuspect THEN
    MaintHomingRequiredM1 := FALSE;
END_IF;
IF MaintHomingRequiredM2 AND M2HomingDone AND M2Homed AND NOT M2HomingSuspect THEN
    MaintHomingRequiredM2 := FALSE;
END_IF;

// Diagnostic « cycle non prêt » — le mode SEMI_AUTO reste sélectionnable mais le
// cycle ne tournera pas tant que ces conditions ne sont pas saines. Info NON-bloquante :
// la sélection n'est pas refusée, le mouvement est coupé en aval (FB_CycleSemiAuto/FB_Safety_Winch).
// Une cause = un fait (AF03 §4) : défaut codeur, re-homing et référencement sont distincts.
SemiAutoCycleNotReadyFault         := (SelMode = E_Mode.SEMI_AUTO) AND EncoderFaultPresent;
SemiAutoCycleNotReadyHoming        := (SelMode = E_Mode.SEMI_AUTO) AND (MaintHomingRequiredM1 OR MaintHomingRequiredM2);
SemiAutoCycleNotReadyMachineHoming := (SelMode = E_Mode.SEMI_AUTO) AND NOT MachineHomed;

instCauses[0].Active   := SemiAutoCycleNotReadyFault;
instCauses[0].Latching := FALSE;
instCauses[0].Texte    := 'Mode Semi-Auto selectionne mais cycle non pret : defaut codeur present';

instCauses[2].Active   := SemiAutoCycleNotReadyHoming;
instCauses[2].Latching := FALSE;
instCauses[2].Texte    := 'Semi-Auto selectionne : re-homing obligatoire';

instCauses[3].Active   := SemiAutoCycleNotReadyMachineHoming;
instCauses[3].Latching := FALSE;
instCauses[3].Texte    := 'Semi-Auto selectionne : referencement incomplet';

// Cause 1 — changement de mode refusé : treuils non à l'arrêt mécanique confirmé.
// Non latchée (live) : l'information disparaît dès que la condition redevient vraie, sans
// acquittement — c'est une consigne d'action IHM (« arrêter les treuils »), pas un défaut machine.
// 📌 Lag 1 scan assumé : la cause est évaluée avant l'arbitrage §3 du cycle courant.
instCauses[1].Active   := Auth.ModeChangePendingBlocked;
instCauses[1].Latching := FALSE;
instCauses[1].Texte    := 'Changement de mode refuse : arreter les treuils avant de changer de mode';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE — neutralisation si désactivé (l'arbitrage de mode reste actif même AU non armé :
//    homing, réarmement défaut. Aucune autorisation de mouvement n'est accordée sans la chaîne
//    AU physique : chaque FB de mouvement garde son propre gate PowerContactorEngaged.)
IF NOT Enable THEN
    Auth.Mode := E_Mode.DISABLE;
    Auth.SyncEnable := TRUE;
    Auth.InhibitM1 := FALSE;
    Auth.InhibitM2 := FALSE;
    Auth.HomingApproachEnable := FALSE;
    Auth.JoystickWinchSelectArbitrated := 0;  // Couplé nominal par défaut
    Auth.MaintenanceM3TargetEnable := FALSE;
    // Faits persistants : PUBLIÉS même neutralisé (l'IHM doit continuer à voir
    // qu'un re-homing est requis tant que la machine n'est pas réarmée). Aucune autorisation
    // n'est accordée ici : Auth.Mode := DISABLE verrouille tout le reste.
    Auth.ModeChangePendingBlocked := FALSE;
    Auth.ModeChangeBlockReason := '';
    Auth.HomingRequiredM1 := MaintHomingRequiredM1;
    Auth.HomingRequiredM2 := MaintHomingRequiredM2;
    PrevArbitratedMode := Auth.Mode;
    Ready := FALSE;
    PrevInhibitM1 := FALSE;
    PrevInhibitM2 := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Arbitrage du mode"}
// ⚙️ 3. ARBITRAGE DU MODE

// 3.1 ARRÊT MÉCANIQUE CONFIRMÉ DES DEUX TREUILS (condition de bascule, AF-05 §4bis)
// Même composite que l'armement Méca B : contacteurs retombés + frein serré, redondé par
// la mesure absolue de vitesse. Vaut pour les DEUX treuils (M1 ET M2).
ModeChangeAllowed := M1ContactorsReleased AND NOT M1BrakeIsOpen
                     AND (ABS(M1SpeedAbsMps) < MovementSpeedThresholdMps)
                     AND M2ContactorsReleased AND NOT M2BrakeIsOpen
                     AND (ABS(M2SpeedAbsMps) < MovementSpeedThresholdMps);

// Détail des 6 sous-conditions (diagnostic IHM) — TRUE = condition satisfaite.
// Permet à l'opérateur de voir EXACTEMENT ce qui bloque la bascule de mode.
Auth.M1ContactorsReleased := M1ContactorsReleased;
Auth.M1BrakeApplied       := NOT M1BrakeIsOpen;
Auth.M1SpeedLow           := ABS(M1SpeedAbsMps) < MovementSpeedThresholdMps;
Auth.M2ContactorsReleased := M2ContactorsReleased;
Auth.M2BrakeApplied       := NOT M2BrakeIsOpen;
Auth.M2SpeedLow           := ABS(M2SpeedAbsMps) < MovementSpeedThresholdMps;

// 3.2 ARBITRAGE — le mode suit la sélection IHM (découplé de l'AU/défaut)
// La sélection de mode n'est JAMAIS bloquée par l'AU, l'arrêt d'urgence ou un défaut :
// le mode est un état de sélection, le mouvement est coupé en aval (FB_CycleSemiAuto, FB_Safety_Winch,
// FB_Winch) par PowerContactorEngaged et les interlocks. Seule la bascule N1/N2/SEMI_AUTO
// reste soumise à l'arrêt mécanique confirmé des treuils (ModeChangeAllowed).
// 3.2bis (AF-05 §4bis - referencement benne guide) : SEMI_AUTO est un mode "homed-only".
// Une selection SEMI_AUTO sans datum machine valide (MachineHomed) est REFUSEE et le mode
// est force vers MAINT_N1 (expulsion). Vaut aussi si MachineHomed retombe alors qu'on EST
// en SEMI_AUTO (perte de datum -> bascule MAINT_N1). Le SafeStop des treuils sur perte de
// datum en mouvement est assure en aval (PRG_04 via MachineHoming.HomingLoss). L'expulsion
// n'est jamais bloquee par l'arret mecanique (comme la sortie DISABLE, contrat D2).
IF (SelMode = E_Mode.SEMI_AUTO) AND NOT MachineHomed THEN
    Auth.Mode := E_Mode.MAINT_N1;
    Auth.ModeChangePendingBlocked := TRUE;
    // Motif distinct : perte de datum EN cours de SEMI_AUTO (arret controle assure en
    // aval par MachineHoming.HomingLoss si les treuils bougeaient) vs simple selection
    // refusee. Aucune coupure de puissance, aucun redemarrage automatique.
    IF PrevArbitratedMode = E_Mode.SEMI_AUTO THEN
        Auth.ModeChangeBlockReason := 'Datum machine perdu : arret controle';
    ELSE
        Auth.ModeChangeBlockReason := 'SEMI_AUTO refuse : datum machine absent';
    END_IF;
ELSIF (SelMode <> PrevArbitratedMode)
      AND (SelMode <> E_Mode.DISABLE) AND (PrevArbitratedMode <> E_Mode.DISABLE)
      AND NOT ModeChangeAllowed THEN
    // Bascule N1/N2/SEMI_AUTO refusée : le mode courant est MAINTENU.
    // ⚠️ Exception de sécurité (contrat D2) : une transition vers ou depuis DISABLE n'est
    // JAMAIS bloquée — sortir d'un mode maintenance ne doit jamais dépendre d'un treuil à l'arrêt.
    Auth.Mode := PrevArbitratedMode;
    Auth.ModeChangePendingBlocked := TRUE;
    // Motif du blocage (texte IHM court) — première condition échouée, ordre M1 puis M2.
    IF NOT M1ContactorsReleased THEN
        ModeChangeBlockReason := 'Chgt mode refuse : contacteur M1';
    ELSIF M1BrakeIsOpen THEN
        ModeChangeBlockReason := 'Chgt mode refuse : frein M1';
    ELSIF ABS(M1SpeedAbsMps) >= MovementSpeedThresholdMps THEN
        ModeChangeBlockReason := 'Chgt mode refuse : M1 en mvt';
    ELSIF NOT M2ContactorsReleased THEN
        ModeChangeBlockReason := 'Chgt mode refuse : contacteur M2';
    ELSIF M2BrakeIsOpen THEN
        ModeChangeBlockReason := 'Chgt mode refuse : frein M2';
    ELSIF ABS(M2SpeedAbsMps) >= MovementSpeedThresholdMps THEN
        ModeChangeBlockReason := 'Chgt mode refuse : M2 en mvt';
    ELSE
        ModeChangeBlockReason := '';
    END_IF;
    Auth.ModeChangeBlockReason := ModeChangeBlockReason;
ELSE
    Auth.Mode := SelMode;
    Auth.ModeChangePendingBlocked := FALSE;
    Auth.ModeChangeBlockReason := '';
END_IF;

PrevArbitratedMode := Auth.Mode;
{endregion}

{region "§3bis Publication du re-homing obligatoire"}
// 🧭 3bis. PUBLICATION DU RE-HOMING OBLIGATOIRE
// Armement et levée réalisés en §1ter, AVANT l'arbitrage de mode — voir le commentaire §1ter
// (pas de fenêtre d'un scan, pas de perte sur coupure en cours de maintenance).
Auth.HomingRequiredM1 := MaintHomingRequiredM1;
Auth.HomingRequiredM2 := MaintHomingRequiredM2;
{endregion}

{region "§4 Calcul autorisations machine"}
// 4. SYNC ENABLE — actionnable en MAINT_N1 ou MAINT_N2
// FALSE (désactivé) seulement si en MAINT_N1/N2 ET case décochée ; TRUE partout ailleurs.
Auth.SyncEnable := NOT ((Auth.Mode = E_Mode.MAINT_N1 OR Auth.Mode = E_Mode.MAINT_N2) AND NOT SelSyncEnable);

// 4bis. TOGGLE INHIBITIONS + EXCLUSION MUTUELLE + RESET SYNC ENABLE
// Chaque bouton est un TOGGLE (écran tactile simple, pas d'appui simultané possible) :
//   - front montant d'un bouton dont le treuil n'est PAS inhibé  -> pose l'inhibition
//     et lève l'autre (exclusion mutuelle), coupe la synchro.
//   - front montant d'un bouton dont le treuil EST déjà inhibé   -> lève l'inhibition
//     (retour à l'état normal), sans toucher à l'autre ni à la synchro.
IF InhibitM1Request AND NOT PrevInhibitM1 THEN
    IF Auth.InhibitM1 THEN
        // M1 déjà inhibé -> lever (toggle off)
        Auth.InhibitM1 := FALSE;
    ELSE
        // inhiber M1, lever M2 (exclusion mutuelle)
        Auth.InhibitM1 := TRUE;
        Auth.InhibitM2 := FALSE;
        SelSyncEnable := FALSE;
    END_IF;
ELSIF InhibitM2Request AND NOT PrevInhibitM2 THEN
    IF Auth.InhibitM2 THEN
        // M2 déjà inhibé -> lever (toggle off)
        Auth.InhibitM2 := FALSE;
    ELSE
        // inhiber M2, lever M1 (exclusion mutuelle)
        Auth.InhibitM2 := TRUE;
        Auth.InhibitM1 := FALSE;
        SelSyncEnable := FALSE;
    END_IF;
END_IF;

PrevInhibitM1 := InhibitM1Request;
PrevInhibitM2 := InhibitM2Request;

Auth.InhibitM1 := (Auth.Mode = E_Mode.MAINT_N2) AND Auth.InhibitM1;
Auth.InhibitM2 := (Auth.Mode = E_Mode.MAINT_N2) AND Auth.InhibitM2;

// 4ter. AUTORISATION ARRÊT HAUT (HomingApproach)
Auth.HomingApproachEnable := (Auth.Mode = E_Mode.MAINT_N2) AND SelHomingApproachEnable;

// 4quater. SÉLECTEUR JOYSTICK TREUIL
IF (Auth.Mode = E_Mode.MAINT_N2) OR (Auth.Mode = E_Mode.MAINT_N1) THEN
    Auth.JoystickWinchSelectArbitrated := JoystickWinchSelectRequest;
ELSE
    Auth.JoystickWinchSelectArbitrated := 0;  // Couplé nominal forcé
END_IF;

// 4quinquies. CIBLE TRANSLATION MAINTENANCE
Auth.MaintenanceM3TargetEnable := ((Auth.Mode = E_Mode.MAINT_N2) OR (Auth.Mode = E_Mode.MAINT_N1)) AND SelMaintenanceZoneAccess;

// Re-vérification sécurité si sortie MAINT
IF (Auth.Mode <> E_Mode.MAINT_N2) AND (Auth.Mode <> E_Mode.MAINT_N1) THEN
    Auth.InhibitM1 := FALSE;
    Auth.InhibitM2 := FALSE;
    Auth.HomingApproachEnable := FALSE;
    Auth.MaintenanceM3TargetEnable := FALSE;
    Auth.JoystickWinchSelectArbitrated := 0;
END_IF;
{endregion}

// Détection du comportement (Accélération vs Décélération)
// Classification par CÔTÉ DE ZÉRO + sens de déplacement, plus par signe brut de Target seul
// (robuste à une traversée de zéro rapide).
// 🛡️ Garde-fou : la rampe ne sort jamais de la plage normalisée ±100 %.
TargetLimited := LIMIT(-100.0, Target, 100.0);
Current := LIMIT(-100.0, Current, 100.0);

IF (Current >= 0.0 AND TargetLimited >= Current) OR (Current <= 0.0 AND TargetLimited <= Current) THEN
    StepX := AccelRate * CycleTimeS; // S'éloigne du zéro (reste du même côté, va plus loin)
ELSE
    StepX := DecelRate * CycleTimeS; // Retourne vers zéro, ou le traverse vers l'autre signe
END_IF;

// Application de la rampe
IF Current < TargetLimited THEN
    Current := Current + StepX;
    IF Current > TargetLimited THEN Current := TargetLimited; END_IF;
ELSIF Current > TargetLimited THEN
    Current := Current - StepX;
    IF Current < TargetLimited THEN Current := TargetLimited; END_IF;
END_IF;

// 🛡️ Limitation finale : même une valeur d'état déjà corrompue reste bornée.
Current := LIMIT(-100.0, Current, 100.0);

// === IMPLEMENTATION ===

{region "§1 Fronts de commande"}
// 🔄 Fronts
EnableRising(CLK := Enable);
ResetEdge(CLK := Reset);
ArmReqEdge(CLK := ArmRequest);
{endregion}

{region "§2 Gate Enable (neutralisation fail-safe)"}
// 🛑 GATE — neutralisation si désactivé : réinitialise l'état interne de la séquence.
// Les sorties physiques sont forcées à FALSE par la projection fail-safe (§10) ; le socle
// défaut reste appelé (§9) pour maintenir le latch non acquitté.
IF NOT Enable THEN
    ArmingSeqStep := CST_STEP_IDLE;
    ForceTestA := FALSE;
    ForceTestB := FALSE;
    StartupFail := FALSE;
    StartupCheckDone := FALSE;
    StartupCheckOK := FALSE;
    RedundancyTestFailed := FALSE;
    EmergencyArmingFailed := FALSE;
    EmergencyArmingLockoutActive := FALSE;
    Armable := FALSE;
    ArmingBusy := FALSE;
    LastAbortStep := CST_STEP_IDLE;
    LastAbortCause := INT_TO_WORD(CST_ABORT_NONE);
    // Neutralisation = coupure surveillance, pas un defaut : Cause et Ack repartent propres
    RedundancyTestFailedCause := FALSE;
    RedundancyTestFailedAck := TRUE;
    EmergencyArmingFailedCause := FALSE;
    EmergencyArmingFailedAck := TRUE;
    TonTestA(IN := FALSE);
    TonRestoreA(IN := FALSE);
    TonTestB(IN := FALSE);
    TonRestoreB(IN := FALSE);
    TonArmingPulse(IN := FALSE);
    TonArmingConfirm(IN := FALSE);
    TonArmingLockout(IN := FALSE);
    TonRedundancyDisplay(IN := FALSE);
    TonArmingFailedDisplay(IN := FALSE);
END_IF;
{endregion}

{region "§3 Autotest demarrage"}
// 🏁 AUTOTEST DÉMARRAGE (§5.4 AF01) — vérifications synchrones 1 cycle au 1er Enable=TRUE
IF Enable THEN
    IF EnableRising.Q THEN
        StartupCheckDone := FALSE;
    END_IF;

    IF NOT StartupCheckDone THEN
        // Exécute les 4 contrôles en 1 cycle
        StartupCheckOK := EmergencyChainClosed          // 1. Boucle AU fermée
                          AND NOT PowerContactorEngaged // 2. Contacteur au repos
                          AND (ArmingSeqStep = CST_STEP_IDLE); // 4. Pas de séquence résiduelle
        StartupCheckDone := TRUE;
        StartupFail := NOT StartupCheckOK;
        // StartupFail est laté via le socle FB_FaultCore (§9) : il reste jusqu'au front Reset.
    END_IF;
END_IF;
{endregion}

{region "§4 Acquittement defauts"}
// 🔍 ACQUITTEMENT DES DÉFAUTS (pattern Cause/Ack — §3.4bis AF01, §9 STD)
// ⚠️ Reset acquitte l'affichage (Ack:=TRUE) ET vide la cause d'auto-test redondance figée.
// Conforme AF-01 §7.4 (« échec auto-test voies → diagnostiquer, puis ACQUITTER, puis réarmer » :
// acquitter est une action distincte du réarmement) et §9 STD (le Reset n'est jamais conditionné).
// Le réarmement réel de la chaîne AU se fait par bouton matériel externe, hors PLC ; la redondance
// électrique reste un étage hardware indépendant (Partie 01). Si l'auto-test PLC rejoue plus tard
// et qu'une voie est réellement collée, il re-détecte et re-latch la cause.
IF Enable THEN
    IF ResetEdge.Q THEN
        RedundancyTestFailedCause := FALSE;
        RedundancyTestFailedAck := TRUE;
        EmergencyArmingFailedCause := FALSE;
        EmergencyArmingFailedAck := TRUE;
        EmergencyArmingLockoutActive := FALSE;
        StartupFail := FALSE;
        PreArmDelayActive := FALSE;
    END_IF;
END_IF;
{endregion}

{region "§5 Sequence rearmement AU"}
// Coupure métier effective : c'est la SEULE forme sous laquelle PowerCutOffRequest agit
// dans ce FB (abort séquence, gate Armable, chute Maintain, blocage ArmPulse).
//  - BypassPowerCutOff : bypass MES dédié « le PLC ne fait jamais chuter l'AU ».
//  - BypassArmingPreconditions : bypass MES large (arme malgré tout) — inclut la coupure.
//  - BypassRedundancyTest : n'a AUCUN effet ici (il ne touche que l'auto-test A/B).
//  - BtnEmergencyCutOff (coup-de-poing / IHM) reste traité à part et reste TOUJOURS dur.
CutOffActive := PowerCutOffRequest AND NOT BypassPowerCutOff AND NOT BypassArmingPreconditions;

IF Enable THEN
    // 🛑 Coupure immédiate de toute séquence en cours
    IF ArmingSeqStep <> CST_STEP_IDLE THEN
        IF BtnEmergencyCutOff THEN
            // Avortement volontaire : pas d'alarme d'échec
            LastAbortStep := ArmingSeqStep;
            LastAbortCause := INT_TO_WORD(CST_ABORT_CUT_IHM);
            ArmingSeqStep := CST_STEP_IDLE;
        ELSIF CutOffActive THEN
            // Avortement sécurité d'urgence : coupure métier (PAS un défaut d'armement).
            // Lockout 5s + interlock (Armable/Maintain* bloqués par CutOffActive).
            // Ne pose PAS EmergencyArmingFailedCause : pas de fausse alarme "échec armement".
            EmergencyArmingLockoutActive := TRUE;
            LastAbortStep := ArmingSeqStep;
            LastAbortCause := INT_TO_WORD(CST_ABORT_POWER_CUTOFF);
            ArmingSeqStep := CST_STEP_IDLE;
        ELSIF (ArmingSeqStep = CST_STEP_PULSE OR ArmingSeqStep = CST_STEP_CONFIRM)
              AND NOT EmergencyChainClosed
              AND NOT BypassArmingPreconditions THEN
            // Chute boucle matérielle : alarme d'échec + verrouillage 5s.
            // ⛔ Levé UNIQUEMENT sous BypassArmingPreconditions. BypassRedundancyTest ne
            //    touche PAS cet abort : EmergencyChainClosed=FALSE peut aussi être un vrai
            //    coup-de-poing physique (même DI) — on ne pulse jamais le contacteur dans
            //    ce cas. Pour armer chaîne réellement ouverte : + BypassArmingPreconditions.
            EmergencyArmingFailedCause := TRUE;
            EmergencyArmingLockoutActive := TRUE;
            LastAbortStep := ArmingSeqStep;
            LastAbortCause := INT_TO_WORD(CST_ABORT_CHAIN_DROP);
            ArmingSeqStep := CST_STEP_IDLE;
        END_IF;
    END_IF;

    // 🚦 PRÉCONDITIONS D'ARMEMENT — source unique (Armable = State.Armable).
    // ⚠️ Armable_NoBlock SANS `NOT RedundancyTestFailedCause` : la cause de redondance est
    //    latée mais la séquence d'armement la re-teste (§5 étape 1/3) : l'armement reste donc
    //    réellement possible (et sûr) tant que les autres préconditions sont réunies. Afficher
    //    le bouton « Armable » sur cette cause seule bloquait le réarmement après acquittement
    //    (Reset ne purge pas la Cause, cf. §4) alors que l'armement était permis.
    // Armable ne dépend PAS de EmergencyChainClosed : c'est la séquence d'armement qui
    //   referme la chaîne (PowerKeepAlive en série dans la boucle). Un armement gaté sur
    //   « chaîne fermée » serait impossible chaîne ouverte alors que c'est exactement l'état
    //   à récupérer. NOT BtnEmergencyCutOff / NOT CutOffActive couvrent les cas où la
    //   chaîne est ouverte pour une vraie raison (coup-de-poing, coupure métier).
    Armable_ChainOk := NOT BtnEmergencyCutOff AND NOT CutOffActive;
    Armable_Idle := (ArmingSeqStep = CST_STEP_IDLE);
    Armable_NoBlock := NOT EmergencyArmingLockoutActive AND NOT PowerContactorEngaged;
    // 🛠️ BypassArmingPreconditions (MES trace) : lève ChainOk + NoBlock ; la séquence doit
    //    toujours partir du repos (Armable_Idle conservé). ⛔ NON SECURISE.
    // NOT ArmPulseInhibitActive inclus ici : Status.State.Armable reflète alors la vérité
    //   « on peut appuyer maintenant » — FALSE pendant les 5 s de garde dure post-séquence
    //   (même après un armement réussi), TRUE de nouveau à l'échéance. Source unique pour l'IHM.
    Armable := (BypassArmingPreconditions OR (Armable_ChainOk AND Armable_NoBlock))
               AND Armable_Idle AND NOT ArmPulseInhibitActive;
    // CASE à étiquettes littérales : 0..6 = CST_STEP_* (GVL_Safety_Emergency).
    // La CI STruCpp exige ces littéraux pour les étiquettes CASE.
    CASE ArmingSeqStep OF
        0: // CST_STEP_IDLE
            ForceTestA := FALSE;
            ForceTestB := FALSE;
            TonTestA(IN := FALSE, PT := CST_TestDuration);
            TonRestoreA(IN := FALSE, PT := CST_RestoreSettle);
            TonTestB(IN := FALSE, PT := CST_TestDuration);
            TonRestoreB(IN := FALSE, PT := CST_KeepAliveHold);
            TonArmingPulse(IN := FALSE, PT := CST_ArmingPulseDuration);
            TonArmingConfirm(IN := FALSE, PT := CST_ArmingConfirmTimeout);

            // ⛔ Ne JAMAIS démarrer la séquence si une coupure métier est active : sinon
            //    ArmingSeqStep passe non-IDLE 1 scan -> Maintain_ChainOk TRUE -> PowerKeepAlive
            //    (contacteur CHAIN OK) colle puis lâche à l'abandon -> mitraillage. On ne
            //    démarre que si la cause est levée. Non contournable par les bypass MES.
            // ⏱️ Délai pré-armement (CST_PreArmDelay) : l'appui est mémorisé mais on TEMPORISE
            //    avant de passer non-IDLE, pour que PowerKeepAlive (contacteur CHAIN OK) ne
            //    claque pas dans le même cycle que le reste -> contacteurs espacés, audibles un
            //    par un. Pendant ce délai on reste en IDLE : aucun maintien asserté.
            IF ArmReqEdge.Q AND Armable AND NOT ArmPulseInhibitActive AND NOT BtnEmergencyCutOff
               AND NOT CutOffActive THEN
                PreArmDelayActive := TRUE;
            END_IF;
            IF BtnEmergencyCutOff OR CutOffActive THEN
                PreArmDelayActive := FALSE; // coupure pendant le délai -> on annule
            END_IF;
            TonPreArm(IN := PreArmDelayActive, PT := CST_PreArmDelay);
            IF PreArmDelayActive AND TonPreArm.Q THEN
                PreArmDelayActive := FALSE;
                RedundancyTestFailedCause := FALSE;
                EmergencyArmingFailedCause := FALSE;
                // 🛠️ BypassRedundancyTest (MES trace) : saute la coupure test A/B. On passe par
                //    RESTORE_B (maintien PowerKeepAlive A+B établi CST_KeepAliveHold) AVANT la
                //    demande contacteur de puissance -> CHAIN OK puis, 1 s plus tard, le gros
                //    contacteur. Pas de claquement simultané.
                IF BypassRedundancyTest THEN
                    ArmingSeqStep := CST_STEP_RESTORE_B;
                ELSE
                    ArmingSeqStep := CST_STEP_TEST_A;
                END_IF;
            END_IF;

        1: // CST_STEP_TEST_A
            ForceTestA := TRUE;
            ForceTestB := FALSE;
            TonTestA(IN := TRUE, PT := CST_TestDuration);

            IF TonTestA.Q THEN
                ForceTestA := FALSE;
                IF EmergencyChainClosed AND NOT BypassArmingPreconditions THEN
                    RedundancyTestFailedCause := TRUE;
                    LastAbortStep := CST_STEP_TEST_A;
                    LastAbortCause := INT_TO_WORD(CST_ABORT_REDUNDANCY_A);
                    ArmingSeqStep := CST_STEP_IDLE;
                ELSE
                    ArmingSeqStep := CST_STEP_RESTORE_A;
                END_IF;
            END_IF;

        2: // CST_STEP_RESTORE_A
            ForceTestA := FALSE;
            ForceTestB := FALSE;
            TonRestoreA(IN := TRUE, PT := CST_RestoreSettle);

            IF TonRestoreA.Q THEN
                IF EmergencyChainClosed OR BypassArmingPreconditions THEN
                    ArmingSeqStep := CST_STEP_TEST_B;
                ELSE
                    LastAbortStep := CST_STEP_RESTORE_A;
                    LastAbortCause := INT_TO_WORD(CST_ABORT_TIMEOUT_RESTORE_A);
                    ArmingSeqStep := CST_STEP_IDLE;
                END_IF;
            END_IF;

        3: // CST_STEP_TEST_B
            ForceTestA := FALSE;
            ForceTestB := TRUE;
            TonTestB(IN := TRUE, PT := CST_TestDuration);

            IF TonTestB.Q THEN
                ForceTestB := FALSE;
                IF EmergencyChainClosed AND NOT BypassArmingPreconditions THEN
                    RedundancyTestFailedCause := TRUE;
                    LastAbortStep := CST_STEP_TEST_B;
                    LastAbortCause := INT_TO_WORD(CST_ABORT_REDUNDANCY_B);
                    ArmingSeqStep := CST_STEP_IDLE;
                ELSE
                    ArmingSeqStep := CST_STEP_RESTORE_B;
                END_IF;
            END_IF;

        4: // CST_STEP_RESTORE_B
            // 🟰 Point d'entrée du chemin BypassRedundancyTest : les deux canaux PowerKeepAlive
            //    sont (ré)établis et TENUS CST_KeepAliveHold avant la demande contacteur de
            //    puissance -> CHAIN OK s'entend d'abord, le gros contacteur 1 s après.
            //    La boucle DOIT s'être refermée pour passer au pulse (sauf BypassArmingPreconditions).
            ForceTestA := FALSE;
            ForceTestB := FALSE;
            TonRestoreB(IN := TRUE, PT := CST_KeepAliveHold);

            IF TonRestoreB.Q THEN
                IF EmergencyChainClosed OR BypassArmingPreconditions THEN
                    ArmingSeqStep := CST_STEP_PULSE;
                ELSE
                    LastAbortStep := CST_STEP_RESTORE_B;
                    LastAbortCause := INT_TO_WORD(CST_ABORT_TIMEOUT_RESTORE_B);
                    ArmingSeqStep := CST_STEP_IDLE;
                END_IF;
            END_IF;

        5: // CST_STEP_PULSE
            ForceTestA := FALSE;
            ForceTestB := FALSE;
            TonArmingPulse(IN := TRUE, PT := CST_ArmingPulseDuration);

            IF TonArmingPulse.Q THEN
                ArmingSeqStep := CST_STEP_CONFIRM;
            END_IF;

        6: // CST_STEP_CONFIRM
            ForceTestA := FALSE;
            ForceTestB := FALSE;
            TonArmingConfirm(IN := TRUE, PT := CST_ArmingConfirmTimeout);

            // 🛠️ CONFIRM exige le VRAI retour contacteur. Seul BypassArmingPreconditions le
            //    fausse (banc sans contacteur). BypassRedundancyTest n'a PAS d'effet ici :
            //    le contacteur de puissance n'est pas la redondance A/B. ⛔ NON SECURISE.
            IF PowerContactorEngaged OR BypassArmingPreconditions THEN
                EmergencyArmingLockoutActive := FALSE;
                WasArmed := TRUE; // séquence aboutie -> maintien PowerKeepAlive (même sans retour contacteur, cas bypass MES)
                ArmingSeqStep := CST_STEP_IDLE;
            ELSIF TonArmingConfirm.Q THEN
                EmergencyArmingFailedCause := TRUE;
                EmergencyArmingLockoutActive := TRUE;
                LastAbortStep := CST_STEP_CONFIRM;
                LastAbortCause := INT_TO_WORD(CST_ABORT_TIMEOUT_CONTACTOR);
                ArmingSeqStep := CST_STEP_IDLE;
            END_IF;

        ELSE
            ForceTestA := FALSE;
            ForceTestB := FALSE;
            EmergencyArmingFailedCause := TRUE;
            EmergencyArmingLockoutActive := TRUE;
            LastAbortStep := ArmingSeqStep;
            LastAbortCause := INT_TO_WORD(CST_ABORT_INVALID_STEP);
            ArmingSeqStep := CST_STEP_IDLE;
    END_CASE;

    // ⏱️ Séquence de verrouillage temporel (5s)
    TonArmingLockout(IN := EmergencyArmingLockoutActive, PT := CST_ArmingLockout);
    IF TonArmingLockout.Q THEN
        EmergencyArmingLockoutActive := FALSE;
    END_IF;
END_IF;
{endregion}

{region "§6 Gestion cause et acquittement"}
// PATTERN CAUSE/ACK — détection ré-apparition + acquittement (§3.4bis AF01, §9 STD)
// L'interlock sécurité (ci-dessous, arbitrage Cmd/Armable) utilise TOUJOURS la Cause brute,
// jamais l'Ack : l'acquittement opérateur n'ouvre jamais un interlock de sécurité.
IF Enable THEN
    RedundancyCauseEdge(CLK := RedundancyTestFailedCause);
    IF RedundancyCauseEdge.Q THEN
        RedundancyTestFailedAck := FALSE; // nouvelle occurrence -> ré-alarme, ré-acquittement requis
    END_IF;

    ArmingFailedCauseEdge(CLK := EmergencyArmingFailedCause);
    IF ArmingFailedCauseEdge.Q THEN
        EmergencyArmingFailedAck := FALSE;
    END_IF;
END_IF;
{endregion}

{region "§7 Etats publics (interlock sur Cause brute)"}
// 🚦 ÉTATS PUBLICS — interlock sur Cause brute (jamais sur l'Ack)
IF Enable THEN
    ArmingBusy := (ArmingSeqStep <> CST_STEP_IDLE) OR EmergencyArmingLockoutActive;
END_IF;
{endregion}

{region "§8 Affichage defauts IHM"}
// 📤 AFFICHAGE IHM — debounce anti-clignotement (Cause lissée) OR NOT Ack (§9 STD)
// ⚠️ Uniquement pour l'affichage : l'action de sécurité ci-dessus (§5/§6) reste instantanée
// sur la Cause brute, jamais retardée par ce debounce.
IF Enable THEN
    TonRedundancyDisplay(IN := RedundancyTestFailedCause, PT := CST_FaultDisplayDebounce);
    RedundancyTestFailed := TonRedundancyDisplay.Q OR NOT RedundancyTestFailedAck;

    TonArmingFailedDisplay(IN := EmergencyArmingFailedCause, PT := CST_FaultDisplayDebounce);
    EmergencyArmingFailed := TonArmingFailedDisplay.Q OR NOT EmergencyArmingFailedAck;
END_IF;
{endregion}

{region "§9 Synthese defaut via socle FB_FaultCore"}
// 📤 SYNTHÈSE DES ERREURS — socle standard FB_FaultCore (vue live + vue latchée).
//    Chaque cause est exprimée EN CLAIR (ST_FaultCause) ; le socle en déduit ST_Fault.
//    StartupFail est une cause indépendante (index 3, Latching=TRUE) : latée jusqu'au front Reset.
//    Mapping bits (préservé pour FB_Hmi_BannerFormatter / PRG_07) :
//      bit0 = RedundancyTestFailed, bit1 = EmergencyArmingFailed, bit3 = StartupFail.
instCauses[0].Active := RedundancyTestFailed; instCauses[0].Latching := TRUE;
instCauses[0].Texte := 'Defaut redondance contacteurs AU';
instCauses[1].Active := EmergencyArmingFailed; instCauses[1].Latching := TRUE;
instCauses[1].Texte := 'Echec rearmement contacteur AU (timeout)';
instCauses[2].Active := FALSE; instCauses[2].Latching := FALSE;
instCauses[2].Texte := '';
instCauses[3].Active := StartupFail; instCauses[3].Latching := TRUE;
instCauses[3].Texte := 'Echec autotest demarrage AU';

// Appel du socle TOUJOURS (même Enable=FALSE) : le Reset reste effectif et le latch non
// acquitté reste publié (fail-safe, pas d'effacement silencieux sur bascule Enable OFF→ON).
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Status.Fault := instFault.Fault; // source de verite = socle
{endregion}

{region "§10 Projection sorties physiques et bus"}
// ⚡ Sorties physiques — Enable gate fail-safe + interlock Cause brute.
// 🛡️ Maintien conditionné sur (chaîne fermée OU séquence en cours) : hors séquence, une
// boucle AU ouverte (coup-de-poing) coupe le maintien (fail-safe). Pendant la séquence, la
// chaîne est volontairement ouverte par ForceTestA/B -> le maintien reste autorisé (restauration).
// Latch « AU armée » : PowerKeepAlive maintenu à travers un appui AU pur (chaîne
//   physiquement ouverte par le coup-de-poing) tant qu'aucune raison MÉTIER ne demande la
//   coupure. Relâchement AU → chaîne se referme instantanément (contacts PLC restés fermés),
//   pas de réarmement. Retombe sur : coupure métier, coupure IHM, Enable OFF, défaut
//   redondance. Non RETAIN : démarrage à froid = non armé.
IF EnableRising.Q THEN
    WasArmed := FALSE;
END_IF;
IF PowerContactorEngaged THEN
    WasArmed := TRUE;
END_IF;
// ⛔ CutOffActive = coupure métier effective (cf. §5). Sous BypassPowerCutOff ou
//    BypassArmingPreconditions, PowerCutOffRequest ne lâche PAS le maintien.
//    BtnEmergencyCutOff (coup-de-poing / IHM), Enable OFF et défaut redondance
//    restent des retombées dures. BypassRedundancyTest n'a aucun effet ici.
IF (CutOffActive OR BtnEmergencyCutOff OR NOT Enable OR RedundancyTestFailedCause) THEN
    WasArmed := FALSE;
    PreArmDelayActive := FALSE; // coupure/Enable OFF pendant le délai pré-armement -> annule
END_IF;

Maintain_ChainOk := (EmergencyChainClosed OR (ArmingSeqStep <> CST_STEP_IDLE) OR WasArmed);
Maintain_NoCutOff := NOT CutOffActive AND NOT BtnEmergencyCutOff;
MaintainA_NoFault := NOT ForceTestA AND NOT RedundancyTestFailedCause;
MaintainB_NoFault := NOT ForceTestB AND NOT RedundancyTestFailedCause;
MaintainA_NoBlock := Maintain_NoCutOff AND MaintainA_NoFault;
MaintainB_NoBlock := Maintain_NoCutOff AND MaintainB_NoFault;
Cmd.MaintainA_Cmd := Enable AND Maintain_ChainOk AND MaintainA_NoBlock;
Cmd.MaintainB_Cmd := Enable AND Maintain_ChainOk AND MaintainB_NoBlock;
// 🛡️ Garde DURE anti-chatter : dès qu'une séquence d'armement DÉMARRE (IDLE -> non-IDLE),
//    aucune nouvelle tentative avant CST_ArmingLockout. Bloque aussi bien le test redondance
//    (ForceTestA/B ouvre PowerKeepAlive A puis B) que l'impulsion contacteur. Inconditionnel :
//    succès, échec, bypass ingénierie MES. Un cyclage rapide du contacteur casse le matériel.
SeqRunStartEdge(CLK := (ArmingSeqStep <> CST_STEP_IDLE));
IF SeqRunStartEdge.Q THEN
    ArmPulseInhibitActive := TRUE;
END_IF;
IF NOT Enable OR EnableRising.Q THEN
    ArmPulseInhibitActive := FALSE;
END_IF;
TonArmPulseInhibit(IN := ArmPulseInhibitActive, PT := CST_ArmingLockout);
IF TonArmPulseInhibit.Q THEN
    ArmPulseInhibitActive := FALSE;
END_IF;

// ⚠️ PAS de `NOT ArmPulseInhibitActive` ici : cette garde est armée dès le départ de
//    séquence (SeqRunStartEdge sur <> IDLE) et tiendrait 5 s -> elle étoufferait l'étape
//    PULSE elle-même (contradiction : PULSE n'existe qu'après un départ qui a armé la garde).
//    L'anti-réessai 5 s est appliqué en amont (garde départ IDLE) et en aval
//    (FB_ContactorProtector Cfg_MinInterval sur la sortie physique, PRG_06).
Cmd.ArmPulse_Cmd  := Enable AND (ArmingSeqStep = CST_STEP_PULSE)
                     AND NOT BtnEmergencyCutOff
                     AND NOT CutOffActive;
// 🧪 TestCutActive : signale à la simulation qu'un canal est coupé pour le test de
// redondance A/B (ForceTestA/B). La simulation ouvre alors la boucle AU (SimChainOk=FALSE)
// pour que le test valide la chute de chaîne — sans dépendre de PowerCutOff_A/B (cercle cassé).
Cmd.TestCutActive := Enable AND (ForceTestA OR ForceTestB);

// 🚦 Bus d'état public
Status.State.ChainOk     := Enable AND EmergencyChainClosed;
Status.State.ContactorOk := Enable AND PowerContactorEngaged;
Status.State.Step        := ArmingSeqStep;
Status.State.Armable     := Armable;
Status.State.ArmingBusy  := ArmingBusy;

// 🛡️ Bus diagnostic public (vue live du socle)
Status.Diag.Error                := Status.Fault.Error;
Status.Diag.ErrorId              := Status.Fault.ErrorId;
Status.Diag.RedundancyTestFailed := RedundancyTestFailed;
Status.Diag.ArmFailed            := EmergencyArmingFailed;
Status.Diag.WasArmed             := WasArmed;
Status.Diag.LockoutActive        := EmergencyArmingLockoutActive;
Status.Diag.LastAbortStep        := LastAbortStep;
Status.Diag.LastAbortCause       := LastAbortCause;
{endregion}

{region "§11 Etats publics IEC + message operateur"}
// 📤 ÉTATS PUBLICS IEC
Status.Ready := Enable AND NOT StartupFail;
Status.Done  := PowerContactorEngaged;

// 💬 MESSAGE OPÉRATEUR — un message explicite par état et par problème de la chaîne AU.
// Priorité : problème de sécurité > état de séquence. Fusionné côté IHM dans les messages
// opérateurs (FB_Hmi_BannerFormatter lit Diag.ErrorId / scalaires).
IF NOT Enable THEN
    Status.OperatorMessage := 'AU neutralisee (Enable=FALSE)';
ELSIF (BypassArmingPreconditions OR BypassRedundancyTest OR BypassPowerCutOff) THEN
    Status.OperatorMessage := 'AU: BYPASS INGENIERIE MES ACTIF - NON SECURISE - retirer avant exploitation';
ELSIF StartupFail THEN
    Status.OperatorMessage := 'AU: autotest demarrage echoue - verifier boucle/contacteur puis Reset';
ELSIF RedundancyTestFailed THEN
    Status.OperatorMessage := 'AU: defaut redondance contacteurs - verifier puis Reset';
ELSIF EmergencyArmingFailed THEN
    // Échec d'armement — non bloquant (alarme seule). Message court décodé sur LastAbortCause.
    IF LastAbortCause = INT_TO_WORD(CST_ABORT_TIMEOUT_CONTACTOR) THEN
        Status.OperatorMessage := 'AU echec: contacteur non confirme';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_REDUNDANCY_A) THEN
        Status.OperatorMessage := 'AU echec: voie A collee';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_REDUNDANCY_B) THEN
        Status.OperatorMessage := 'AU echec: voie B collee';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_TIMEOUT_RESTORE_A) THEN
        Status.OperatorMessage := 'AU echec: chaine non refermee (voie A)';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_TIMEOUT_RESTORE_B) THEN
        Status.OperatorMessage := 'AU echec: chaine non refermee (voie B)';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_CHAIN_DROP) THEN
        Status.OperatorMessage := 'AU echec: chaine ouverte pendant pulse';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_POWER_CUTOFF) THEN
        Status.OperatorMessage := 'AU echec: coupure metier en sequence';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_CUT_IHM) THEN
        Status.OperatorMessage := 'AU echec: coupure IHM en sequence';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_INVALID_STEP) THEN
        Status.OperatorMessage := 'AU echec: etape invalide - Reset';
    ELSE
        Status.OperatorMessage := 'AU echec armement - relancer';
    END_IF;
ELSIF PowerCutOffRequest THEN
    Status.OperatorMessage := 'AU: coupure securite metier active - lever la cause puis rearmer';
ELSIF BtnEmergencyCutOff THEN
    Status.OperatorMessage := 'AU: coupure urgence IHM active - relacher puis rearmer';
ELSIF NOT EmergencyChainClosed THEN
    Status.OperatorMessage := 'AU: boucle urgence ouverte - verifier coup-de-poing';
ELSIF EmergencyArmingLockoutActive THEN
    Status.OperatorMessage := 'AU: verrouillage 5s actif - attendre puis rearmer';
ELSE
    // 📌 Étiquettes en LITTÉRAUX numériques (pattern PresetSeqStep / FB_Encoder_Abs) :
    //    le jumeau CI STruCpp ne génère pas d'étiquettes CASE constexpr depuis des constantes
    //    GVL (IECVar non-constexpr) ; CODESYS accepte les deux formes. La correspondance
    //    symbolique vit ici : 0..6 = CST_STEP_* (GVL_Safety_Emergency).
    CASE ArmingSeqStep OF
        0: // IDLE (= CST_STEP_IDLE)
            IF ArmPulseInhibitActive THEN
                Status.OperatorMessage := 'AU: temporisation 5s en cours - patienter';
            ELSIF PreArmDelayActive THEN
                Status.OperatorMessage := 'AU: appui pris en compte - etablissement chaine';
            ELSE
                Status.OperatorMessage := 'AU: repos - pret a rearmer';
            END_IF;
        1: // TEST_A (= CST_STEP_TEST_A)
            Status.OperatorMessage := 'AU: autotest canal A en cours';
        2: // RESTORE_A (= CST_STEP_RESTORE_A)
            Status.OperatorMessage := 'AU: restauration canal A';
        3: // TEST_B (= CST_STEP_TEST_B)
            Status.OperatorMessage := 'AU: autotest canal B en cours';
        4: // RESTORE_B (= CST_STEP_RESTORE_B)
            Status.OperatorMessage := 'AU: restauration canal B';
        5: // PULSE (= CST_STEP_PULSE)
            Status.OperatorMessage := 'AU: impulsion rearmement contacteur';
        6: // CONFIRM (= CST_STEP_CONFIRM)
            Status.OperatorMessage := 'AU: attente confirmation contacteur';
    END_CASE;
END_IF;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. RESET FRONT
ResetEdge(CLK := Reset);

IF ResetEdge.Q OR BypassGlobal THEN
    PhaseRotationFault    := FALSE;
    BrakeThermalFault     := FALSE;
    MecaBFault            := FALSE;
    MecaAFault            := FALSE;
    SensorIncoherentFault := FALSE;
END_IF;

IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    PhaseRotationFault    := FALSE;
    BrakeThermalFault     := FALSE;
    MecaBFault            := FALSE;
    MecaAFault            := FALSE;
    SensorIncoherentFault := FALSE;
END_IF;

IF NOT BypassGlobal THEN
    TonStartupWarmup(IN := Enable, PT := T#3s);

    // Cause 0 : Perte com opérateur (live)
    IF TonStartupWarmup.Q AND NOT (BypassProcess OR BypassOperatorComm) THEN
        instCauses[0].Active := (NOT JoystickOnline OR NOT JoystickOperational OR NOT HeartbeatIhmOk);
    ELSE
        instCauses[0].Active := FALSE;
    END_IF;
    instCauses[0].Latching := FALSE;
    instCauses[0].Texte    := 'Perte communication operateur translation';

    // Cause 1 : Perte EtherCAT drive (live)
    IF TonStartupWarmup.Q AND NOT (BypassProcess OR BypassDriveComm) THEN
        instCauses[1].Active := (NOT DriveOnline OR NOT DriveOperational);
    ELSE
        instCauses[1].Active := FALSE;
    END_IF;
    instCauses[1].Latching := FALSE;
    instCauses[1].Texte    := 'Perte communication EtherCAT variateur M3';

    // Cause 2 : Rotation de phase (latched)
    IF NOT (BypassProcess OR BypassPhaseRotation) AND NOT PhaseRotationOk THEN
        PhaseRotationFault := TRUE;
    END_IF;
    instCauses[2].Active   := PhaseRotationFault;
    instCauses[2].Latching := TRUE;
    instCauses[2].Texte    := 'Defaut rotation de phases';

    // Cause 3 : Thermique frein (latched)
    IF NOT (BypassSafety OR BypassBrakeThermal) AND BrakeThermalFeedback THEN
        BrakeThermalFault := TRUE;
    END_IF;
    instCauses[3].Active   := BrakeThermalFault;
    instCauses[3].Latching := TRUE;
    instCauses[3].Texte    := 'Surchauffe thermique frein translation';

    // Cause 4 : Méca B (latched)
    // ⚠️ Éval gardée par la comm drive (DriveOnline AND DriveOperational) : sans comm, le
    //    statusword / la fréquence remontés ne sont pas fiables. Une perte bus doit tomber en
    //    Cause 1 (DriveComm, bit1 -> SafeStop acquittable), PAS en Méca B (bit4 -> PowerCutOff
    //    non-resettable). DriveStatusWord.0 (= "ready to switch on")
    //    figé sur bus mort -> coupure chaîne intempestive.
    // Déclencheur = preuve de rotation RÉELLE (fréquence de sortie mesurée) OU retour frein
    // encore ouvert. DriveStatusWord.0 ("ready to switch on") retiré : à 1 dès variateur
    // alimenté, il ne prouve PAS un mouvement.
    IF NOT (BypassSafety OR BypassMecaB) AND DriveOnline AND DriveOperational THEN
        IF (NOT HeartbeatIhmOk) OR (NOT RunRequest AND NOT BrakeCmd) THEN
            UncommandedActiveB := (ABS(DriveActualFreqHz) > CST_StopFreqThresholdHz) OR BrakeFeedback;
        ELSE
            UncommandedActiveB := FALSE;
        END_IF;
        TonMecaB(IN := UncommandedActiveB, PT := PostRampTimeout);
        IF TonMecaB.Q THEN MecaBFault := TRUE; END_IF;
    ELSE
        TonMecaB(IN := FALSE);
    END_IF;
    instCauses[4].Active   := MecaBFault;
    instCauses[4].Latching := TRUE;
    instCauses[4].Texte    := 'Absence confirmation arret translation (Meca B)';

    // Cause 5 : Méca A (latched)
    IF NOT (BypassSafety OR BypassMecaA) THEN
        IF NOT RunRequest AND NOT BrakeCmd THEN
            UncommandedActiveA := ABS(DriveActualFreqHz) > 0.5;
        ELSE
            UncommandedActiveA := FALSE;
        END_IF;
        TonMecaA(IN := UncommandedActiveA, PT := T#1S);
        IF TonMecaA.Q THEN MecaAFault := TRUE; END_IF;
    ELSE
        TonMecaA(IN := FALSE);
    END_IF;
    instCauses[5].Active   := MecaAFault;
    instCauses[5].Latching := TRUE;
    instCauses[5].Texte    := 'Mouvement non commande translation (Meca A)';

    // Cause 6 : Limite extrême escalade (live)
    IF NOT (BypassSafety OR BypassLimitSwitch) THEN
        OverrunCondition := (LimitSwitchTremie AND ReqTremie AND (ABS(DriveActualFreqHz) > 0.5 OR DriveStatusWord.0))
                         OR (LimitSwitchMaintenance AND ReqMaintenance AND (ABS(DriveActualFreqHz) > 0.5 OR DriveStatusWord.0));
        TonLimitSwitchOverrun(IN := OverrunCondition, PT := T#1S500MS);
        instCauses[6].Active := TonLimitSwitchOverrun.Q;
    ELSE
        TonLimitSwitchOverrun(IN := FALSE);
        instCauses[6].Active := FALSE;
    END_IF;
    instCauses[6].Latching := FALSE;
    instCauses[6].Texte    := 'Depassement limite extreme translation';

    // Cause 7 : Mot capteurs incohérent (latched)
    IF NOT (BypassSafety OR BypassSensorIncoherent) AND SensorWordIncoherent THEN
        SensorIncoherentFault := TRUE;
    END_IF;
    instCauses[7].Active   := SensorIncoherentFault;
    instCauses[7].Latching := TRUE;
    instCauses[7].Texte    := 'Incoherence combinaison capteurs translation';

ELSE
    TonMecaB(IN := FALSE);
    TonMecaA(IN := FALSE);
    TonLimitSwitchOverrun(IN := FALSE);

    // 🧪 BypassGlobal : l'évaluation des causes ci-dessus est sautée. Purge de la vue LIVE
    // pour que instCauses[i].Active ne reste pas FIGÉ (sinon PowerCutOff / SafeStop gelés,
    // réarmement impossible malgré le bypass). Latches déjà effacés au § FRONTS & REARMENT.
    FOR CauseIdx := 0 TO 15 DO
        instCauses[CauseIdx].Active := FALSE;
    END_FOR;
END_IF;

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable THEN
    SafeStop := FALSE;
    PowerCutOff := FALSE;
    ErrorOperatorComm := FALSE;
    ErrorDriveComm := FALSE;
    ErrorPhaseRotation := FALSE;
    ErrorBrakeThermal := FALSE;
    ErrorMecaB := FALSE;
    ErrorMecaA := FALSE;
    ErrorLimitSwitch := FALSE;
    ErrorSensorIncoherent := FALSE;
    TremieLimitClear := FALSE;
    MaintenanceLimitClear := FALSE;
    TonMecaB(IN := FALSE);
    TonMecaA(IN := FALSE);
    TonLimitSwitchOverrun(IN := FALSE);
    TonStartupWarmup(IN := FALSE);
    Ready := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Sorties sécurités et drapeaux IHM"}
// 📤 3. SORTIES SÉCURITÉ & DRAPEAUX
SafeStop := Fault.Error OR NOT PowerContactorEngaged;

// PowerCutOff actif si bits 3..7 actifs (causes physiques)
PowerCutOff := (Fault.ErrorId AND 16#00F8) <> 16#0000;

ErrorOperatorComm     := instCauses[0].Active;
ErrorDriveComm        := instCauses[1].Active;
ErrorPhaseRotation    := instCauses[2].Active;
ErrorBrakeThermal     := instCauses[3].Active;
ErrorMecaB            := instCauses[4].Active;
ErrorMecaA            := instCauses[5].Active;
ErrorLimitSwitch      := instCauses[6].Active;
ErrorSensorIncoherent := instCauses[7].Active;

// 🛡️ Permis directionnels M3 — NIVEAU SAFETY (polarité fail-safe : TRUE = autorisé)
// ⚠️ Ces sorties sont des permits directionnels SAFETY (pur directionnel), PAS le permit
// EFFECTIF « pouvoir bouger ». Le permit effectif (prêt à fonctionner) est calculé en
// PRG_05_Translation §1ter : Safety directionnel AND NOT M3_SafeStop_Aggregate AND NOT
// PowerCutOff. C'est LUI qui reflète la sémantique « pouvoir bouger » : quand l'axe est en
// défaut (SafeStop/PowerCutOff), TOUS les sens sont bloqués ; au retour en condition, un sens
// La décision des huit permis est produite en PRG_05. Ce FB ne produit que les faits
// de sécurité nécessaires à cette décision : les deux fins de course sont-elles libres ?
// Le droit d'accès à la zone Maintenance (MaintenanceM3TargetEnable) est volontairement
// séparé : il ne doit pas empêcher le déplacement légal jusqu'à P1.
TremieLimitClear := NOT LimitSwitchTremie;
MaintenanceLimitClear := NOT LimitSwitchMaintenance;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. FRONTS & REARMENT
ResetEdge(CLK := Reset);

IF ResetEdge.Q OR BypassGlobal THEN
    EncoderFaultLatched           := FALSE;
    MotorThermalFaultLatched      := FALSE;
    PhaseRotationFaultLatched     := FALSE;
    MecaAFaultLatched             := FALSE;
    MecaBFaultLatched             := FALSE;
    MecaCFaultLatched             := FALSE;
    BrakeThermalFaultLatched      := FALSE;
    MecaDFaultLatched             := FALSE;
    MecaEFaultLatched             := FALSE;
    MecaEEscaladeFaultLatched     := FALSE;
    OppositeDirectionFaultLatched := FALSE;
    NoMovementFaultLatched        := FALSE;
    OverspeedFaultLatched         := FALSE;
END_IF;

IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    CablePosMPrev                 := CablePosM;
    ExpectedOtherWinchPosMPrev   := ExpectedOtherWinchPosM;
    EncoderFaultLatched           := FALSE;
    MotorThermalFaultLatched      := FALSE;
    PhaseRotationFaultLatched     := FALSE;
    MecaAFaultLatched             := FALSE;
    MecaBFaultLatched             := FALSE;
    MecaCFaultLatched             := FALSE;
    BrakeThermalFaultLatched      := FALSE;
    MecaDFaultLatched             := FALSE;
    MecaEFaultLatched             := FALSE;
    MecaEEscaladeFaultLatched     := FALSE;
    OppositeDirectionFaultLatched := FALSE;
    NoMovementFaultLatched        := FALSE;
    OverspeedFaultLatched         := FALSE;
END_IF;

IF NOT BypassGlobal THEN
    TonStartupWarmup(IN := Enable, PT := T#3s);

    // 🛡️ Fenetre de reference : le preset SDO du codeur (homing, y compris reference benne fermee)
    // fait sauter CablePosM d'un bloc. Sans garde, DriftGuardA voit une derive non commandee (Meca A)
    // et l'ecart M1/M2 depasse la tolerance (Meca E). Le Busy homing seul est trop court (~500ms) :
    // il retombe avant l'application reelle du preset et la reconvergence M1/M2. On maintient donc
    // l'inhibition pendant homing + cycle benne + saut de position detecte + 2s de stabilisation,
    // et on RAZ les latches parasites poses dans le meme scan. Le saut sur ExpectedOtherWinchPosM
    // couvre le cas ou c'est l'AUTRE treuil qui est reference (ce treuil n'est pas en homing).
    // Les autres protections (limites, contacteurs, chaine) restent actives (AF_Partie-09 §13 :
    // le treuil ne passe pas en mode securite degrade, le homing exige l'arret confirme des treuils).
    PosStepDetected := (ABS(CablePosM - CablePosMPrev) > CST_RefPosStepM)
                    OR (ABS(ExpectedOtherWinchPosM - ExpectedOtherWinchPosMPrev) > CST_RefPosStepM);
    CablePosMPrev := CablePosM;
    ExpectedOtherWinchPosMPrev := ExpectedOtherWinchPosM;
    // NOT CrossCheckEnable : homing machine, manipulation benne, pilotage unitaire ->
    // l'ecart croise M1/M2 est volontairement grand ; la fenetre de reference reste
    // ouverte (RAZ continue des latch Meca A/E) tant que le controle croise est coupe.
    TonRefSettle(IN := NOT (InReferencingMode OR BenneBusy OR PosStepDetected OR NOT CrossCheckEnable), PT := T#2s);
    RefWindowActive := InReferencingMode OR BenneBusy OR PosStepDetected OR NOT TonRefSettle.Q
                       OR NOT CrossCheckEnable;
    IF RefWindowActive THEN
        MecaAFaultLatched         := FALSE;
        MecaEFaultLatched         := FALSE;
        MecaEEscaladeFaultLatched := FALSE;
    END_IF;

    // Cause 0 : Perte com opérateur (live)
    IF TonStartupWarmup.Q AND NOT (BypassProcess OR BypassOperatorComm) THEN
        instCauses[0].Active := (NOT JoystickOnline OR NOT JoystickOperational OR NOT HeartbeatIhmOk);
    ELSE
        instCauses[0].Active := FALSE;
    END_IF;
    instCauses[0].Latching := FALSE;
    instCauses[0].Texte    := 'Perte communication operateur treuil';

    // Cause 1 : Perte codeur (latched)
    IF NOT (BypassProcess OR EncoderFaultBypass) AND NOT EncoderAvailable THEN
        EncoderFaultLatched := TRUE;
    END_IF;
    instCauses[1].Active   := EncoderFaultLatched;
    instCauses[1].Latching := TRUE;
    instCauses[1].Texte    := 'Perte ou defaut codeur treuil';

    // Cause 2 : Surchauffe thermique moteur (latched)
    IF NOT (BypassSafety OR BypassMotorThermal) AND ThermalFeedback THEN
        MotorThermalFaultLatched := TRUE;
    END_IF;
    instCauses[2].Active   := MotorThermalFaultLatched;
    instCauses[2].Latching := TRUE;
    instCauses[2].Texte    := 'Surchauffe thermique moteur treuil';

    // Cause 3 : Mou de câble (live / auto-effaçable)
    IF NOT BypassProcess AND SlackCableDetected THEN
        instCauses[3].Active := TRUE;
    ELSE
        instCauses[3].Active := FALSE;
    END_IF;
    instCauses[3].Latching := FALSE;
    instCauses[3].Texte    := 'Detection mou de cable treuil';

    // Cause 4 : Rotation phases (latched)
    IF NOT (BypassProcess OR BypassPhaseRotation) AND NOT PhaseRotationOk THEN
        PhaseRotationFaultLatched := TRUE;
    END_IF;
    instCauses[4].Active   := PhaseRotationFaultLatched;
    instCauses[4].Latching := TRUE;
    instCauses[4].Texte    := 'Defaut rotation de phases treuil';

    // Cause 5 : Fin de course haut capteur (live)
    IF NOT (BypassProcess OR BypassTopLimitSwitch) AND (NOT TopPositionSensor AND NOT InReferencingMode) THEN
        instCauses[5].Active := TRUE;
    ELSE
        instCauses[5].Active := FALSE;
    END_IF;
    instCauses[5].Latching := FALSE;
    instCauses[5].Texte    := 'Fin de course haut capteur atteint';

    // Cause 6 : Limite max câble descente (live)
    IF NOT (BypassProcess OR BypassCableLimitSwitch) AND (CablePosM <= CfgCableLimitDescentM) AND NOT InReferencingMode THEN
        instCauses[6].Active := TRUE;
    ELSE
        instCauses[6].Active := FALSE;
    END_IF;
    instCauses[6].Latching := FALSE;
    instCauses[6].Texte    := 'Limite basse cable atteinte';

    // Cause 7 : Méca A dérive à l'arrêt (latched)
    DriftGuardA(
        Arm        := NOT (BypassSafety OR BypassMecaA) AND FwdRevSpeedFeedbackOff AND NOT BrakeFeedback AND NOT BenneHoldStillActive AND NOT RefWindowActive,
        PositionM  := CablePosM,
        ToleranceM := UncommandedDriftToleranceM
    );
    MecaADriftM := DriftGuardA.DriftM;
    IF DriftGuardA.Violation THEN MecaAFaultLatched := TRUE; END_IF;
    instCauses[7].Active   := MecaAFaultLatched;
    instCauses[7].Latching := TRUE;
    instCauses[7].Texte    := 'Derive non commandee treuil (Meca A)';

    // Cause 8 : Méca B absence confirmation arrêt (latched)
    IF NOT (BypassSafety OR BypassMecaB) THEN
        UncommandedActiveB := JoystickYNeutral AND NOT BenneHoldStillActive AND NOT (FwdRevSpeedFeedbackOff AND NOT BrakeFeedback);
        TonMecaB(IN := UncommandedActiveB, PT := PostRampTimeout);
        IF TonMecaB.Q THEN MecaBFaultLatched := TRUE; END_IF;
    ELSE
        TonMecaB(IN := FALSE);
    END_IF;
    MecaBElapsedTime := TonMecaB.ET;
    instCauses[8].Active   := MecaBFaultLatched;
    instCauses[8].Latching := TRUE;
    instCauses[8].Texte    := 'Absence confirmation arret contacteurs/frein (Meca B)';

    // Cause 9 : Méca C glissement benne (latched)
    DriftGuardC(
        Arm        := NOT (BypassSafety OR BypassMecaC) AND BenneHoldStillActive,
        PositionM  := CablePosM,
        ToleranceM := BenneSlipToleranceM
    );
    MecaCDriftM := DriftGuardC.DriftM;
    IF DriftGuardC.Violation THEN MecaCFaultLatched := TRUE; END_IF;
    instCauses[9].Active   := MecaCFaultLatched;
    instCauses[9].Latching := TRUE;
    instCauses[9].Texte    := 'Glissement treuil pendant cycle benne (Meca C)';

    // Cause 10 : Surchauffe thermique frein (latched)
    IF NOT (BypassSafety OR BypassBrakeThermal) AND BrakeThermalFeedback THEN
        BrakeThermalFaultLatched := TRUE;
    END_IF;
    instCauses[10].Active   := BrakeThermalFaultLatched;
    instCauses[10].Latching := TRUE;
    instCauses[10].Texte    := 'Surchauffe thermique frein treuil';

    // Cause 11 : Méca D escalade capteur haut (latched)
    IF NOT (BypassSafety OR BypassMecaD) THEN
        UncommandedActiveD := NOT TopPositionSensor AND NOT InReferencingMode AND NOT (FwdRevSpeedFeedbackOff AND NOT BrakeFeedback);
        TonMecaD(IN := UncommandedActiveD, PT := PostRampTimeout);
        IF TonMecaD.Q THEN MecaDFaultLatched := TRUE; END_IF;
    ELSE
        TonMecaD(IN := FALSE);
    END_IF;
    instCauses[11].Active   := MecaDFaultLatched;
    instCauses[11].Latching := TRUE;
    instCauses[11].Texte    := 'Escalade fin de course haut (Meca D)';

    // Cause 12 & 13 : Méca E écart critique synchro & escalade (latched).
    // CrossCheckEnable (et non SyncEnable) : le controle d'ecart croise M1/M2 n'a de sens
    // que treuils solidaires ; en jog benne unitaire (M2-M1 varie de ~15 m volontairement)
    // il est inhibe. TonMecaE (:362) ne s'escalade que si MecaEFaultLatched est pose ici,
    // donc gater ce seul point suffit. Le mou-de-cable (:508/:520) reste sur SyncEnable.
    IF Enable AND NOT (BypassProcess OR BypassMecaE) AND CrossCheckEnable AND NOT RefWindowActive AND NOT OtherWinchInhibited
       AND (ABS(CablePosM - ExpectedOtherWinchPosM) > CriticalSyncToleranceM) THEN
        MecaEFaultLatched := TRUE;
    END_IF;
    instCauses[12].Active   := MecaEFaultLatched;
    instCauses[12].Latching := TRUE;
    instCauses[12].Texte    := 'Ecart critique synchronisation treuil (Meca E)';

    TonMecaE(
        IN := NOT (BypassSafety OR BypassMecaE) AND NOT RefWindowActive AND MecaEFaultLatched AND NOT (FwdRevSpeedFeedbackOff AND NOT BrakeFeedback),
        PT := PostRampTimeout
    );
    IF TonMecaE.Q THEN MecaEEscaladeFaultLatched := TRUE; END_IF;
    // Escalade discordance contacteurs M1/M2 (deja debouncee + tempo escalade
    //   dans FB_SyncContactor, PRG_06) -> meme latch que MecaE escalade (bit13 -> PowerCutOff).
    //   Meme neutralisation que MecaE : BypassSafety / BypassMecaE. Efface par le meme Reset.
    IF ExternalSyncEscalation AND NOT (BypassSafety OR BypassMecaE) THEN
        MecaEEscaladeFaultLatched := TRUE;
    END_IF;
    instCauses[13].Active   := MecaEEscaladeFaultLatched;
    instCauses[13].Latching := TRUE;
    instCauses[13].Texte    := 'Escalade ecart synchronisation (Meca E)';

    // Cause 14 : Sens opposé (latched)
    OppositeDirectionActive := NOT BypassProcess AND MeasuredSpeedValid AND (MovementCommanded AND NOT InReferencingMode
        AND ((ReqAscent AND (MeasuredSpeedSignedMps < -MovementSpeedThresholdMps))
          OR (ReqDescend AND (MeasuredSpeedSignedMps > MovementSpeedThresholdMps))));
    TonOppositeDirection(IN := OppositeDirectionActive, PT := OppositeDirectionTimeout);
    IF TonOppositeDirection.Q THEN OppositeDirectionFaultLatched := TRUE; END_IF;
    instCauses[14].Active   := OppositeDirectionFaultLatched;
    instCauses[14].Latching := TRUE;
    instCauses[14].Texte    := 'Sens reel oppose a la commande treuil';

    // Cause 15 : Absence mouvement (latched)
    TonNoMovement(
        IN := NOT BypassProcess AND MeasuredSpeedValid AND (MovementCommanded AND NOT InReferencingMode
              AND (ABS(MeasuredSpeedSignedMps) < MovementSpeedThresholdMps)),
        PT := NoMovementTimeout
    );
    IF TonNoMovement.Q THEN NoMovementFaultLatched := TRUE; END_IF;
    instCauses[15].Active   := NoMovementFaultLatched;
    instCauses[15].Latching := TRUE;
    instCauses[15].Texte    := 'Absence mouvement malgre commande treuil';

    // Survitesse (latch dédié hors bitfield —, alternative validée).
    // Seuil = max bande apprise  (SpeedBandMaxMps). Latché jusqu'au Reset.
    // ⚠️ N'alimente PAS PowerCutOff : couper la puissance en survitesse peut
    // provoquer une chute libre de la charge — décision à trancher (ISO 13849).
    IF NOT BypassProcess AND NOT RefWindowActive AND MeasuredSpeedValid AND (ABS(MeasuredSpeedMps) > SpeedBandMaxMps) THEN
        OverspeedFaultLatched := TRUE;
    END_IF;

ELSE
    TonMecaB(IN := FALSE);
    TonMecaD(IN := FALSE);
    TonMecaE(IN := FALSE);
    TonOppositeDirection(IN := FALSE);
    TonNoMovement(IN := FALSE);
    TonRefSettle(IN := FALSE);
    RefWindowActive := FALSE;
    PosStepDetected := FALSE;
    CablePosMPrev := CablePosM;
    ExpectedOtherWinchPosMPrev := ExpectedOtherWinchPosM;

    // 🧪 BypassGlobal : l'évaluation des causes ci-dessus est sautée. Sans cette purge,
    // instCauses[i].Active resterait FIGÉ à sa dernière valeur (bug : PowerCutOff / SafeStop
    // gelés à TRUE, réarmement impossible malgré le bypass). Les latches sont déjà effacés
    // au § FRONTS & REARMENT (IF ResetEdge.Q OR BypassGlobal). Ici on force la vue LIVE à
    // « pas de cause » pour que CauseXxxActive / CausesPowerCutOffActive / CausesSafeStopActive
    // retombent et que la sortie PowerCutOff/SafeStop puisse se lever.
    FOR CauseIdx := 0 TO 15 DO
        instCauses[CauseIdx].Active := FALSE;
    END_FOR;
END_IF;

// ContactorStuck : proprietaire UNIQUE de la detection contacteur colle.
// Escalade : Meca B (bit8) -> SafeStop + PowerCutOff apres PostRampTimeout si le
// collage persiste. Le champ ContactorsCheck.StuckClosed de FB_Winch est force a
// FALSE (Phase 0) ; la re-alimentation IHM/Troubleshooting se fera depuis cette sortie.
ContactorStuck := MecaBFaultLatched;
OverspeedFault := OverspeedFaultLatched;

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

// Miroirs des causes : exactement les bits de la vue LIVE ErrorId (le socle pose
// ErrorId bit i = Causes[i].Active quand Enable). §2 fait RETURN si Enable=FALSE,
// ces miroirs ne servent qu'en aval, sous Enable.
CauseOperatorCommActive   := instCauses[0].Active;
CauseEncoderActive        := instCauses[1].Active;
CauseMotorThermalActive   := instCauses[2].Active;
CauseSlackCableActive     := instCauses[3].Active;
CausePhaseRotationActive  := instCauses[4].Active;
CauseTopLimitSwitchActive := instCauses[5].Active;
CauseCableLimitActive     := instCauses[6].Active;
CauseMecaAActive          := instCauses[7].Active;
CauseMecaBActive          := instCauses[8].Active;
CauseMecaCActive          := instCauses[9].Active;
CauseBrakeThermalActive   := instCauses[10].Active;
CauseMecaDActive          := instCauses[11].Active;
CauseMecaEActive          := instCauses[12].Active;
CauseMecaEEscaladeActive  := instCauses[13].Active;
CauseOppositeDirActive    := instCauses[14].Active;
CauseNoMovementActive     := instCauses[15].Active;

// Agregats safety (causes homogenes, AF03 §4 — jamais de masque hexa) :
// CausesSafeStop : toutes les causes sauf les 3 purement directionnelles
// (SlackCable bit3, TopLimitSwitch bit5, CableLimitDescent bit6), traitees
// par les permis de sens. CausesPowerCutOff : defauts a coupure immediate,
// SANS MecaE-ecart (bit12, laisse au SafeStop tant que non confirme).
CausesSafeStopActive := CauseOperatorCommActive OR CauseEncoderActive
    OR CauseMotorThermalActive OR CausePhaseRotationActive
    OR CauseMecaAActive OR CauseMecaBActive OR CauseMecaCActive
    OR CauseBrakeThermalActive OR CauseMecaDActive
    OR CauseMecaEActive OR CauseMecaEEscaladeActive
    OR CauseOppositeDirActive OR CauseNoMovementActive;

CausesPowerCutOffActive := CauseMotorThermalActive OR CauseMecaAActive
    OR CauseMecaBActive OR CauseMecaCActive OR CauseBrakeThermalActive
    OR CauseMecaDActive OR CauseMecaEEscaladeActive;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable THEN
    SafeStop := FALSE;
    DescendPermit := FALSE;
    AscentPermit := FALSE;
    PowerCutOff := FALSE;
    TonMecaB(IN := FALSE);
    TonMecaD(IN := FALSE);
    TonMecaE(IN := FALSE);
    TonOppositeDirection(IN := FALSE);
    TonNoMovement(IN := FALSE);
    TonStartupWarmup(IN := FALSE);
    MecaBElapsedTime := T#0s;
    Ready := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Arbitrage sorties securite"}
// 📤 3. ARBITRAGE SÉCURITÉ
// Interlocks sur les miroirs de causes (bits ErrorId) — jamais de masque hexa.
IF NOT PowerContactorEngaged THEN
    SafeStop := TRUE;
ELSE
    // Causes non directionnelles + survitesse. Hors synchro (SyncEnable=FALSE),
    // le mou de cable (bit3) n'entraine pas SafeStop : il bloque la descente
    // seule via DescendPermit (retendre en montant reste possible).
    SafeStop := CausesSafeStopActive
                OR (SyncEnable AND CauseSlackCableActive)
                OR OverspeedFaultLatched;
END_IF;

DescendPermit := NOT (
    ((CauseCableLimitActive OR NOT PowerContactorEngaged) AND NOT (BypassGlobal OR BypassCableLimitSwitch))
    OR ((CablePosM <= CfgCableLimitDescentM) AND NOT InReferencingMode AND NOT BypassCableLimitSwitch)
    // La limite légale est une interdiction d'exploitation distincte du groupe
    // SafeStop/Permit. Le bypass banc BypassProcess ne doit jamais la lever :
    // seul le bypass dédié BypassLimitLegal, déjà filtré par la matrice MAINT_N2
    // dans PRG_04, peut l'autoriser explicitement.
    OR (LimitLegalReached AND NOT BypassLimitLegal)
    OR ((CauseSlackCableActive AND NOT SyncEnable) AND NOT (BypassProcess OR BypassGlobal))
);

AscentPermit := NOT (
    ((CauseTopLimitSwitchActive
    OR (NOT TopPositionSensor AND NOT InReferencingMode))
    AND NOT BypassTopLimitSwitch)
    // TopLimitM porte la relaxation 7,5->8,5 m en override N1 / bypass N2 : la butee
    // logicielle reste active a la valeur relevee. Bypasser le logiciel releve la butee,
    // il ne la supprime pas ; le FDC haut materiel reste une barriere independante.
    OR (Homed AND NOT HomingSuspect AND NOT InReferencingMode AND (CablePosM >= TopLimitM))
);

PowerCutOff := CausesPowerCutOffActive;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Repli image reelle banc desactive"}
IF NOT Enable THEN
    // 🔌 Banc désactivé : repli sur l'image réelle, aucune simulation en cours
    Ready       := FALSE;
    Busy        := FALSE;
    Done        := FALSE;
    Winch       := HwReal.Winch;
    Translation := HwReal.Translation;
    Operator    := HwReal.Operator;
    Machine     := HwReal.Machine;
    RETURN;
END_IF;

// ▶️ Banc actif : le cycle de simulation démarre pour ce scan
Ready := TRUE;
Busy  := TRUE;
Done  := FALSE;


{endregion}

{region "§2 Simulation treuils M1/M2"}
// ── 1. MODÈLE TREUILS (M1 + M2) ─────────────────────────────────────────────
// Presets codeurs : déclenchés si PresetTriggerCmd = 2
M1_PresetCmd := (M1_PresetTriggerCmd = 2);
M2_PresetCmd := (M2_PresetTriggerCmd = 2);

// Conversions d'injection d'écart synchro (0.5m -> points codeur avec 8192 pts/tour, 2m/tour)
// 1m = 4096 points codeur.
M1_OffsetPts := REAL_TO_DINT(SimSyncDeviationOffset_M * 4096.0);
M2_OffsetPts := REAL_TO_DINT(SimSyncDeviationOffset_M * 4096.0);

// Instance modèle codeur M1
instSimEncoderM1(
    Enable           := TRUE,
    RelayFwd         := M1_RelayFwd,
    RelayRev         := M1_RelayRev,
    StepNumber       := M1_StepNumber,
    PresetCmd        := M1_PresetCmd,
    PresetValue      := M1_PresetValueOut,
    SpeedScaleFactor := SimEncoderSpeedFactor,
    CoastDistanceM   := SimWinchCoast_M,
    TestOffsetCmd    := SimSyncDeviationInjectM1,
    TestOffsetPts    := M1_OffsetPts,
    RawPos           := RawPosM1
);

// Instance modèle codeur M2
instSimEncoderM2(
    Enable           := TRUE,
    RelayFwd         := M2_RelayFwd,
    RelayRev         := M2_RelayRev,
    StepNumber       := M2_StepNumber,
    PresetCmd        := M2_PresetCmd,
    PresetValue      := M2_PresetValueOut,
    SpeedScaleFactor := SimEncoderSpeedFactor,
    CoastDistanceM   := SimWinchCoast_M,
    TestOffsetCmd    := SimSyncDeviationInjectM2,
    TestOffsetPts    := M2_OffsetPts,
    RawPos           := RawPosM2
);

// Recopie structures Winch simulées :
// 🛑 POLARITÉ DE FREIN SIMULÉ : 1 = contacteur commandé = frein OUVERT.
// Câblage réel : DI = 1 ⟺ frein OUVERT. Le modèle produit donc M1_BrakeIsOpen_DI := M1_BrakeCmd !
Winch.M1_BrakeIsOpen_DI        := M1_BrakeCmd;
// Retour UNIQUE « tous contacteurs retombés » = sens ET vitesse.
// Omettre les paliers ferait croire à l'arrêt pendant les transitoires → Méca A armée à tort.
Winch.M1_ContactorsReleased_DI := NOT (M1_RelayFwd OR M1_RelayRev
                                    OR M1_SpeedContactor_1 OR M1_SpeedContactor_2
                                    OR M1_SpeedContactor_3 OR M1_SpeedContactor_4);
Winch.M1_ThermalOk_DI          := TRUE; // Sauf panne simulée

Winch.M2_BrakeIsOpen_DI        := M2_BrakeCmd;
Winch.M2_ContactorsReleased_DI := NOT (M2_RelayFwd OR M2_RelayRev
                                    OR M2_SpeedContactor_1 OR M2_SpeedContactor_2
                                    OR M2_SpeedContactor_3 OR M2_SpeedContactor_4);
Winch.M2_ThermalOk_DI          := TRUE;

// Cohérent avec M2_TensionedCable_DI (sain par défaut) : capteur TOP libre en simu,
// sauf stimulus manuel SimTopPositionActive (injection de fait capteur au banc).
Winch.M1M2_TopPositionFree_DI  := NOT SimTopPositionActive;
Winch.M2_TensionedCable_DI     := TRUE; // Câble tendu en simu

Winch.COD1_PosValue            := instSimEncoderM1.RawPosOut;
Winch.COD1_Alarms              := 0;
Winch.COD1_Warnings            := 0;
Winch.COD1_DeviceState         := DEVICE_STATE.RUNNING; // État device RUNNING (bus OK)

Winch.COD2_PosValue            := instSimEncoderM2.RawPosOut;
Winch.COD2_Alarms              := 0;
Winch.COD2_Warnings            := 0;
Winch.COD2_DeviceState         := DEVICE_STATE.RUNNING; // État device RUNNING


{endregion}

{region "§3 Simulation translation M3"}
// ── 2. MODÈLE TRANSLATION M3 (AC600) ─────────────────────────────────────────
M3_RelayFwd := M3_ReqTremie AND NOT M3_ReqMaintenance;
M3_RelayRev := M3_ReqMaintenance AND NOT M3_ReqTremie;

instSimTranslation(
    Enable          := TRUE,
    ReqTremie       := M3_RelayFwd,
    ReqMaintenance  := M3_RelayRev,
    SpeedTgt_Pct    := M3_SpeedCmd_Pct,
    FullTravelTimeS := CST_M3FullTravelTimeS
);

// Remplissage capteurs de position M3 : l'override manuel conserve exactement le
// même ordre que FB_Translation_PositionDecoder (bit4=Trémie ... bit0=Maintenance).
IF SimM3SensorsWordOverrideActive THEN
    Translation.M3_PosTremie_DI      := SimM3SensorsWord.4;
    Translation.M3_PosPV_DI          := SimM3SensorsWord.3;
    Translation.M3_PosPVP2_DI        := SimM3SensorsWord.2;
    Translation.M3_PosP1_DI          := SimM3SensorsWord.1;
    Translation.M3_PosMaintenance_DI := SimM3SensorsWord.0;
ELSE
    Translation.M3_PosTremie_DI      := instSimTranslation.PosTremie;
    Translation.M3_PosPV_DI          := instSimTranslation.PosPV;
    Translation.M3_PosPVP2_DI        := instSimTranslation.PosP2;
    Translation.M3_PosP1_DI          := instSimTranslation.PosP1;
    Translation.M3_PosMaintenance_DI := instSimTranslation.PosMaintenance;
END_IF;

// Polarité frein M3 (1 = OUVERT)
Translation.M3_BrakeIsOpen_DI    := M3_BrakeCmd;

// Thermique moteur/variateur AC600 — pas de panne simulée, toujours OK (comme Winch.M1/M2_ThermalOk_DI)
Translation.M3_ThermalOK_DI      := TRUE;

// Simulation StatusWord AC600 : Bit 0 (Power Ready) = 1, Bit 7 (Comm Ready) = 1 -> 16#0087 en mouvement
// Bit0 retombe à l'arrêt, cohérent avec un variateur qui confirme l'arrêt sans rester "actif" —
// FB_Safety_Translation lit ce bit comme indicateur "mouvement non commandé" (Méca B, TonMecaB 3s) :
// un Bit0 forcé à 1 en continu à l'arrêt déclencherait un PowerCutOff simulé permanent après 3s.
// DrivePowerReady (diagnostic IHM seul, non consommé par un interlock) est le seul autre lecteur,
// aucune régression de mouvement possible.
IF M3_RelayFwd OR M3_RelayRev THEN
    M3_StatusWordSim := 16#0087; // + Operating/Running
    M3_ActualFreqHz  := REAL_TO_UINT(M3_SpeedCmd_Pct * 50.0); // 50.0 Hz à 100% (x100 -> 5000)
ELSE
    M3_StatusWordSim := 16#0080; // Comm Ready seul -- Bit0 retombé, arrêt confirmé
    M3_ActualFreqHz  := 0;
END_IF;

Translation.M3_StatusWord        := M3_StatusWordSim;
Translation.M3_ActualFrequencyHz := M3_ActualFreqHz;
Translation.AC600_DeviceState    := DEVICE_STATE.RUNNING; // État device RUNNING


{endregion}

{region "§4 Simulation operateur joystick"}
// ── 3. MODÈLE OPÉRATEUR / JOYSTICK ───────────────────────────────────────────
instSimJoystick(
    Enable              := TRUE,
    NeutralRaw          := 5000,
    MaxRaw              := 10000,
    BtnLeft_Rev_TREMIE  := SimJoystickLeft_Rev_TREMIE_Active,
    BtnRight_Fwd_MAINT  := SimJoystickRight_Fwd_MAINT_Active,
    BtnFwd_Up_Close     := SimJoystickFwd_Up_Close_Active,
    BtnRev_Down_Open    := SimJoystickRev_Down_Open_Active,
    OvershootActive     := SimJoystickOvershoot_Active,
    BagotementActive    := SimJoystickBagotement_Active,
    CycleTimeS          := 0.010
);

// Les boutons directionnels simplifient les essais : une commande unique impose
// une butée d'axe ; aucune commande ou une combinaison reste au neutre / stimulus avancé.
// Le modèle dynamique (montée/retombée/bagotement) pilote RawX/RawY dès qu'un bouton est actif.
SimJoystickDirectionCount := BOOL_TO_INT(SimJoystickLeft_Rev_TREMIE_Active)
                           + BOOL_TO_INT(SimJoystickRight_Fwd_MAINT_Active)
                           + BOOL_TO_INT(SimJoystickFwd_Up_Close_Active)
                           + BOOL_TO_INT(SimJoystickRev_Down_Open_Active);
IF (SimJoystickDirectionCount >= 1) OR instSimJoystick.ReturningActive THEN
    // Bouton(s) actif(s) OU retour dynamique en cours (retombée/bagotement) → sortie du modèle.
    // (≥2 boutons : le modèle gère lui-même le neutre — pas de diagonale implicite.)
    Operator.JoyXRaw_ANA1 := instSimJoystick.RawX;
    Operator.JoyYRaw_ANA2 := instSimJoystick.RawY;
ELSE
    // Modèle au repos → stimulus analogique avancé (mode « sans bouton »).
    Operator.JoyXRaw_ANA1 := SimJoystickRawX;
    Operator.JoyYRaw_ANA2 := SimJoystickRawY;
END_IF;

// Homme-mort : stimulus brut amont. En simulation avec boutons directionnels actifs,
// l'appui homme-mort est automatiquement inclus pour faciliter les essais sur banc.
Operator.JoyBtnRaw := SimJoystickRawButton OR (SimJoystickDirectionCount > 0);

Operator.CanBusState      := 2; // CANbusState 2 = ACTIVE
Operator.JOY1_DeviceState := DEVICE_STATE.RUNNING; // État device RUNNING


{endregion}

{region "§5 Simulation securite et image machine"}
// ── 4. MODÈLE SÉCURITÉ & COMMUNS MACHINE ─────────────────────────────────────
instSimSafety(
    Enable            := TRUE,
    SimChainOkBit     := SimChainOkBit,
    PowerCutOff_A     := PowerKeepAlive_A,
    PowerCutOff_B     := PowerKeepAlive_B,
    PowerCutOffRequest:= PowerCutOffRequest,
    EmergencyArming   := EmergencyArming_RQ,
    BtnEmergencyStop  := BtnEmergencyStop,
    TestCutActive     := TestCutActive
);

Machine.PowerContactorEngaged_DI   := instSimSafety.SimContactorOk;
Machine.EmergencyChainClosed_DI    := instSimSafety.SimChainOk;
Machine.PhaseRotationOk_DI             := TRUE;
Machine.M1_M2_M3_BrakeThermalOk_DI     := TRUE;
Machine.M1_M2_KoboldBottomTouch_DI     := SimKoboldContactValue;
Machine.HydraulicThermalOk_DI          := TRUE;
Machine.TremieFull_OR_GateRaised_DI    := FALSE; // Pas encore câblé, simulé inactif par défaut

// ✅ Cycle de simulation terminé : les 4 images sont publiées pour ce scan
Busy := FALSE;
Done := TRUE;

{endregion}

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Encoder) ===

{region "§1 Gate"}
IF NOT Enable THEN
    RawPosOut := RawPos;
    RETURN;
END_IF;
{endregion}

{region "§2 Injection test"}
// Injection test banc : VRAI saut de position (comme un glissement réel),
// pour tester Concept 1 / Méca E ET le rattrapage joystick (voir GVL_Simulation bandeau).
TestOffsetEdge(CLK := TestOffsetCmd);
IF TestOffsetEdge.Q THEN
    RawPos := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) + TestOffsetPts);
END_IF;
{endregion}

{region "§3 Comptage"}
// 🎚️ Vitesse simulée = interpolation linéaire du palier (palier 1 → MinSpeedMps, palier 5 → MaxSpeedMps),
// pas par pas de (Max−Min)/4. Palier 0 (arrêt) ramène au palier 1 mais aucun mouvement n'est
// appliqué tant que RelayFwd/RelayRev = FALSE (section plus bas).
EffStep  := MAX(StepNumber, 1);
SpeedMps := MinSpeedMps + (INT_TO_REAL(EffStep) - 1.0) * ((MaxSpeedMps - MinSpeedMps) / 4.0);
// Points par cycle = vitesse (m/s) × points par mètre × période tâche (s) × facteur confort.
Increment := REAL_TO_UDINT(SpeedMps * (UDINT_TO_REAL(PointsPerRev) / CableM_PerRev) * CycleTimeS * SpeedScaleFactor);
// Increment "lent" (palier 1) : vitesse du roulis inertiel apres coupure des relais.
IncrStep1 := REAL_TO_UDINT(MinSpeedMps * (UDINT_TO_REAL(PointsPerRev) / CableM_PerRev) * CycleTimeS * SpeedScaleFactor);

// Front du preset : lance la latence de referencement (le codeur réel n'est pas
// instantane — il met PresetLatencyCycles cycles a se re-referencer apres le front).
PresetEdge(CLK := PresetCmd);
IF PresetEdge.Q THEN
    PresetPending := TRUE;
    PresetCount := PresetLatencyCycles;
END_IF;

// Pendant l'attente, la position brute est conservee (le codeur n'a pas encore re-reference).
// Le mouvement est gelé pendant la latence, comme un codeur réel en cours de referencement.
IF PresetPending THEN
    IF PresetCount > 0 THEN
        PresetCount := PresetCount - 1;
    ELSE
        // Latence écoulée : applique la valeur cible du preset.
        RawPos := PresetValue;
        PresetPending := FALSE;
    END_IF;
ELSIF RelayFwd THEN
    RawPos := RawPos + Increment;
    MovingDir := 1;
    CoastPtsLeft := CoastDistanceM * (UDINT_TO_REAL(PointsPerRev) / CableM_PerRev);
ELSIF RelayRev THEN
    IF RawPos >= Increment THEN
        RawPos := RawPos - Increment;
    ELSE
        RawPos := 0;
    END_IF;
    MovingDir := -1;
    CoastPtsLeft := CoastDistanceM * (UDINT_TO_REAL(PointsPerRev) / CableM_PerRev);
ELSE
    // Relais coupes : roulis inertiel (anticipation d'arret mecanique). Le treuil
    // continue a vitesse palier 1 dans le dernier sens jusqu'a epuisement de CoastPtsLeft.
    IF (CoastPtsLeft >= 1.0) AND (MovingDir <> 0) THEN
        IF MovingDir = 1 THEN
            RawPos := RawPos + IncrStep1;
        ELSIF RawPos >= IncrStep1 THEN
            RawPos := RawPos - IncrStep1;
        ELSE
            RawPos := 0;
        END_IF;
        CoastPtsLeft := CoastPtsLeft - UDINT_TO_REAL(IncrStep1);
    ELSE
        MovingDir := 0;
        CoastPtsLeft := 0.0;
    END_IF;
END_IF;
{endregion}

{region "§4 Sortie"}
RawPosOut := RawPos;
{endregion}

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Joystick) ===

{region "§1 Gate"}
// 🔑 Initialise au neutre au premier cycle uniquement ; ensuite RawX/RawY sont pilotés
// dynamiquement par les boutons. Quand la simulation est coupée, on revient au neutre.
IF NOT Enable THEN
    FirstCycle := TRUE;
    State      := CST_ST_IDLE;
    RawX       := NeutralRaw;
    RawY       := NeutralRaw;
    RawButton  := FALSE;
    ReturningActive := FALSE; // 📊 Neutralisation : simulation inactive hors Enable
    RETURN;
END_IF;
{endregion}

{region "§2 Initialisation neutre"}
IF FirstCycle THEN
    RawX       := NeutralRaw;
    RawY       := NeutralRaw;
    RawButton  := FALSE;
    State      := CST_ST_IDLE;
    FirstCycle := FALSE;
END_IF;
{endregion}

{region "§3 Pseudo-aléatoire (bruit de montée)"}
// 🎲 Compteur qui repasse à zéro, multiplié pour rester dans la plage (méthode validée).
// Le bruit s'ajoute à la rampe de montée uniquement (pas à la retombée, linéaire propre).
RandCnt := (RandCnt + 1) MOD 1000;
Noise   := (RandCnt MOD 50) - 25;   // ±25 points (≈ ±0.5% de la course)
{endregion}

{region "§4 Cibles & transitions"}
// 🎯 Un SEUL bouton impose une butée d'axe ; 0 ou ≥2 boutons = neutre (pas de diagonale implicite).
// Si OvershootActive : la cible de montée DÉPASSE la butée (MaxRaw+AMT ou 0−AMT) pour
// déclencher le défaut capteur hors plage (RawOutOfRange) — test du dépassement de valeur.
BtnCount := BOOL_TO_INT(BtnLeft_Rev_TREMIE) + BOOL_TO_INT(BtnRight_Fwd_MAINT)
          + BOOL_TO_INT(BtnFwd_Up_Close) + BOOL_TO_INT(BtnRev_Down_Open);
IF BtnCount = 1 THEN
    IF BtnLeft_Rev_TREMIE THEN
        IF OvershootActive THEN TargetX := 0 - CST_OVERSHOOT_AMT; ELSE TargetX := 0; END_IF;
        TargetY := NeutralRaw; ActiveAxis := 1;
    ELSIF BtnRight_Fwd_MAINT THEN
        IF OvershootActive THEN TargetX := MaxRaw + CST_OVERSHOOT_AMT; ELSE TargetX := MaxRaw; END_IF;
        TargetY := NeutralRaw; ActiveAxis := 1;
    ELSIF BtnFwd_Up_Close THEN
        TargetX := NeutralRaw;
        IF OvershootActive THEN TargetY := MaxRaw + CST_OVERSHOOT_AMT; ELSE TargetY := MaxRaw; END_IF;
        ActiveAxis := 2;
    ELSE
        TargetX := NeutralRaw;
        IF OvershootActive THEN TargetY := 0 - CST_OVERSHOOT_AMT; ELSE TargetY := 0; END_IF;
        ActiveAxis := 2;
    END_IF;
    State := CST_ST_RISE;
ELSE
    // 0 ou ≥2 boutons : retour au neutre.
    TargetX := NeutralRaw;
    TargetY := NeutralRaw;
    IF State = CST_ST_RISE THEN
        // Front de relâchement : retour au neutre. D'abord retombée linéaire (FALL),
        // puis petit bagotement de quelques % autour du neutre si OvershootActive (voir §6).
        State := CST_ST_FALL;
    END_IF;
END_IF;
{endregion}

{region "§5 Ascending (rampe + bruit)"}
IF State = CST_ST_RISE THEN
    // Pas de montée : pleine course (MaxRaw−NeutralRaw) en RiseTimeS.
    RiseStep := INT_TO_REAL(MaxRaw - NeutralRaw) / (RiseTimeS / CycleTimeS);
    // Axe X
    IF RawX < TargetX THEN
        RawX := MIN(RawX + REAL_TO_INT(RiseStep) + Noise, TargetX);
    ELSIF RawX > TargetX THEN
        RawX := MAX(RawX - REAL_TO_INT(RiseStep) - Noise, TargetX);
    END_IF;
    // Axe Y
    IF RawY < TargetY THEN
        RawY := MIN(RawY + REAL_TO_INT(RiseStep) + Noise, TargetY);
    ELSIF RawY > TargetY THEN
        RawY := MAX(RawY - REAL_TO_INT(RiseStep) - Noise, TargetY);
    END_IF;
END_IF;
{endregion}

{region "§6 Retombée linéaire (sans bagotement)"}
IF State = CST_ST_FALL THEN
    // Pas de retombée : pleine course en FallTimeMs (TIME_TO_REAL → ms, /1000 → s).
    FallStep := INT_TO_REAL(MaxRaw - NeutralRaw) / (TIME_TO_REAL(FallTimeMs) / 1000.0 / CycleTimeS);
    IF RawX < NeutralRaw THEN
        RawX := MIN(RawX + REAL_TO_INT(FallStep), NeutralRaw);
    ELSIF RawX > NeutralRaw THEN
        RawX := MAX(RawX - REAL_TO_INT(FallStep), NeutralRaw);
    END_IF;
    IF RawY < NeutralRaw THEN
        RawY := MIN(RawY + REAL_TO_INT(FallStep), NeutralRaw);
    ELSIF RawY > NeutralRaw THEN
        RawY := MAX(RawY - REAL_TO_INT(FallStep), NeutralRaw);
    END_IF;
    IF RawX = NeutralRaw AND RawY = NeutralRaw THEN
        // Arrivée au neutre : si bagotement demandé, lance un petit balancement de quelques %.
        IF BagotementActive THEN
            State := CST_ST_OVERSHOOT;
            IF ActiveAxis = 1 THEN
                OscDev := INT_TO_REAL(CST_BAGOT_AMT);
            ELSE
                OscDev := INT_TO_REAL(CST_BAGOT_AMT);
            END_IF;
            OscVel := 0.0;
        ELSE
            State := CST_ST_IDLE;
        END_IF;
    END_IF;
END_IF;
{endregion}

{region "§7 Bagotement (dépassement + oscillations amorties)"}
IF State = CST_ST_OVERSHOOT THEN
    // 🎢 Oscillateur harmonique amorti discret (semi-implicite) autour du neutre :
    // le joystick dépasse le centre (~12% de l'écart initial) puis oscille 1-2 fois
    // avant de se stabiliser — comportement d'un opérateur qui relâche et balance.
    OscAcc := -CST_OSC_K * OscDev - CST_OSC_C * OscVel;
    OscVel := OscVel + OscAcc;
    OscDev := OscDev + OscVel;
    IF ActiveAxis = 1 THEN
        RawX := NeutralRaw + REAL_TO_INT(OscDev);
    ELSE
        RawY := NeutralRaw + REAL_TO_INT(OscDev);
    END_IF;
    // Stabilisé : revient exactement au centre.
    IF ABS(OscDev) < 1.0 AND ABS(OscVel) < 1.0 THEN
        State := CST_ST_IDLE;
        IF ActiveAxis = 1 THEN
            RawX := NeutralRaw;
        ELSE
            RawY := NeutralRaw;
        END_IF;
    END_IF;
END_IF;
{endregion}

{region "§8 Homme-mort brut + drapeau retour"}
RawButton := BtnLeft_Rev_TREMIE OR BtnRight_Fwd_MAINT OR BtnFwd_Up_Close OR BtnRev_Down_Open;
// Drapeau "retour dynamique en cours" : TRUE si l'état est FALL ou OVERSHOOT (retombée/bagotement).
// Permet à FB_SimBench d'émettre la sortie du modèle même après relâchement du bouton.
ReturningActive := (State = CST_ST_FALL) OR (State = CST_ST_OVERSHOOT);
{endregion}

// === IMPLEMENTATION ===
{region "§1 Gate"}
IF NOT Enable THEN
    SimChainOk     := FALSE;
    SimContactorOk := FALSE;
    ContactorLatch := FALSE;
    ChainOpen      := TRUE; // Chaîne ouverte par défaut à la ré-entrée (on n'a pas armé)
    ChainOpenReq   := FALSE;
    ContactorEngageReq := FALSE;
    TonChainOpen(IN := FALSE);
    TonChainClose(IN := FALSE);
    TonContactorEngage(IN := FALSE);
    TonContactorDrop(IN := FALSE);
    RETURN;
END_IF;
{endregion}

{region "§2 Chaîne AU (contrôle granulaire + dynamique)"}
// 1. La chaîne AU est saine si l'opérateur la simule fermée (SimChainOkBit = TRUE) ET si aucun
//    événement ne l'ouvre : coup-de-poing (BtnEmergencyStop), test de redondance (TestCutActive),
//    coupure métier (PowerCutOffRequest).
// 🔧 DEADLOCK SIMULATION (corrigé) : la chaîne n'est PAS fermée par défaut ni dépendante de
//    PowerCutOff_A/B (qui sont dans le cercle). Elle est fermée UNIQUEMENT par le bit opérateur
//    `SimChainOkBit`. Le réarmement après échec de test de redondance (RedundancyTestFailedCause laté
//    → PowerCutOff_A=FALSE) reste possible car la chaîne est maintenue fermée par le bit, pas par
//    le PLC. Hors simulation (Enable=FALSE), la chaîne reste pilotée par le matériel via le repli
//    HwReal (PRG_02 §1/§2) — aucune régression sécurité réelle.
// 🆕 DYNAMIQUE : l'ouverture/fermeture suit une temporisation (CST_ChainOpenDelay / CST_ChainCloseDelay)
//    qui simule le temps de retombée des relais AU, tout en restant < 200ms (CST_TestDuration) pour
//    ne pas fausser le test de redondance. Pendant le test, la chaîne clignote (s'ouvre en TEST_A/B,
//    se referme en RESTORE_A/B) puis revient à 1.
ChainOpenReq := (NOT SimChainOkBit) OR BtnEmergencyStop OR TestCutActive OR PowerCutOffRequest;

// Temporisation d'ouverture : la chaîne s'ouvre après CST_ChainOpenDelay de demande soutenue
TonChainOpen(IN := ChainOpenReq, PT := CST_ChainOpenDelay);
// Temporisation de fermeture : la chaîne se ferme après CST_ChainCloseDelay d'absence de demande
TonChainClose(IN := NOT ChainOpenReq, PT := CST_ChainCloseDelay);

// Latch de la chaîne avec temporisations (défaut = ouverte à la ré-entrée)
IF ChainOpenReq THEN
    IF TonChainOpen.Q THEN
        ChainOpen := TRUE;
    END_IF;
ELSE
    IF TonChainClose.Q THEN
        ChainOpen := FALSE;
    END_IF;
END_IF;

SimChainOk := NOT ChainOpen;
{endregion}

{region "§3 Auto-maintien contacteur (dynamique réaliste)"}
// 2. Logique d'auto-maintien (latch) du contacteur avec priorité à la coupure.
// 🆕 DYNAMIQUE : le contacteur ne s'engage QUE pendant l'impulsion d'armement (EmergencyArming)
//    tant que la chaîne est saine, après CST_ContactorEngageDelay (temps de collage bobine), puis
//    s'auto-maintient. Il retombe après CST_ContactorDropDelay (temps de décollage bobine) dès que
//    la chaîne s'ouvre — comme une bobine réelle qui décolle sans alimentation. Ces temporisations
//    restent < CST_ArmingPulseDuration (1s) et CST_ArmingConfirmTimeout (2s) pour que la
//    confirmation contacteur reste validée. À la ré-entrée en simulation, le contacteur est NON
//    engagé (on n'a pas armé).
ContactorEngageReq := EmergencyArming AND SimChainOk;

// Temporisation d'engagement : le contacteur se colle après CST_ContactorEngageDelay de pulse soutenu
TonContactorEngage(IN := ContactorEngageReq, PT := CST_ContactorEngageDelay);
// Temporisation de retombée : le contacteur décolle après CST_ContactorDropDelay de chaîne ouverte
TonContactorDrop(IN := NOT SimChainOk, PT := CST_ContactorDropDelay);

// Latch du contacteur avec priorité à la coupure (retombée > engagement)
IF NOT SimChainOk THEN
    IF TonContactorDrop.Q THEN
        ContactorLatch := FALSE;
    END_IF;
ELSIF ContactorEngageReq THEN
    IF TonContactorEngage.Q THEN
        ContactorLatch := TRUE;
    END_IF;
END_IF;

// Recopie vers la sortie
SimContactorOk := ContactorLatch;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Gate"}
IF NOT Enable THEN
    // Prochain démarrage déterministe sur la Trémie (0 m), pour un état de départ propre.
    PositionProgress := CST_PositionAtTremie;
    Initialized := FALSE;
    PosTremie := FALSE;
    PosPV := FALSE;
    PosP2 := FALSE;
    PosP1 := FALSE;
    PosMaintenance := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§2 Initialisation"}
IF NOT Initialized THEN
    PositionProgress := CST_PositionAtTremie;
    Initialized := TRUE;
END_IF;
{endregion}

{region "§3 Progression"}
instCycleTime(DefaultValueS := 0.010);
SpeedPctBounded := LIMIT(0.0, ABS(SpeedTgt_Pct), 100.0);

// Une vitesse à 100 % parcourt les 30 m (Trémie→Maintenance) pendant FullTravelTimeS.
// Les demandes de sens sont des bits explicites ; une demande contradictoire est neutre.
IF FullTravelTimeS >= CST_MinFullTravelTimeS THEN
    PositionIncrement := (SpeedPctBounded / 100.0)
                         * (CST_TotalDistanceM / FullTravelTimeS)
                         * instCycleTime.CycleTimeS;
ELSE
    PositionIncrement := 0.0;
END_IF;

IF ReqTremie AND NOT ReqMaintenance THEN
    PositionProgress := MAX(CST_PositionAtTremie, PositionProgress - PositionIncrement);
ELSIF ReqMaintenance AND NOT ReqTremie THEN
    PositionProgress := MIN(CST_PositionAtMaintenance, PositionProgress + PositionIncrement);
END_IF;
{endregion}

{region "§4 Publication capteurs"}
// Réinitialisation explicite : aucune valeur transitoire héritée d'une zone précédente.
PosTremie := FALSE;
PosPV := FALSE;
PosP2 := FALSE;
PosP1 := FALSE;
PosMaintenance := FALSE;

// Chaque intervalle correspond à un seul mot thermomètre valide.
IF PositionProgress <= CST_PositionAtTremie THEN
    PosTremie := TRUE;
    PosPV := TRUE;
    PosP2 := TRUE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF PositionProgress <= CST_PositionAtPV THEN
    PosPV := TRUE;
    PosP2 := TRUE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF PositionProgress <= CST_PositionAtP2 THEN
    PosP2 := TRUE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF PositionProgress <= CST_PositionAtP1 THEN
    PosP1 := TRUE;
    PosMaintenance := TRUE;
ELSIF PositionProgress < CST_PositionAtMaintenance THEN
    PosMaintenance := TRUE;
END_IF;
{endregion}

{region "§0 Bornes et validation table"}
// Le plafond est borné avant le plancher : si le plancher demandé dépasse le
// plafond de sécurité, celui-ci garde la priorité.
_MaxStepClamped := LIMIT(1, MaxStepNumber, 5);
_MinStepClamped := LIMIT(1, MinStepNumber, _MaxStepClamped);

// Les seuils restent validés pour conserver le diagnostic table historique.
// Ils ne participent plus au calcul du palier dans ce FB.
_ConfigValid := TRUE;
_ConfigErrorIdInt := 16#0000;
IF NOT (Table.StepThreshold_Pct[1] < Table.StepThreshold_Pct[2] AND
        Table.StepThreshold_Pct[2] < Table.StepThreshold_Pct[3] AND
        Table.StepThreshold_Pct[3] < Table.StepThreshold_Pct[4] AND
        Table.StepThreshold_Pct[4] < Table.StepThreshold_Pct[5]) THEN
    _ConfigValid := FALSE;
    _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
END_IF;
IF (Table.StepThreshold_Pct[1] < 0.0) OR (Table.StepThreshold_Pct[5] > 100.0) THEN
    _ConfigValid := FALSE;
    _ConfigErrorIdInt := _ConfigErrorIdInt OR 16#0001;
END_IF;
ConfigErrorId := _ConfigErrorIdInt;
ConfigError := (ConfigErrorId <> 16#0000);
{endregion}

{region "§1 Gate"}
// Relâche ou table invalide : aucun plancher ne peut maintenir un contacteur.
IF (NOT Enable) OR (NOT _ConfigValid) OR (SpeedStepReq <= 0) THEN
    StepNumber := 0;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§2 Clamp et table contacteurs"}
// Le plancher agit sur la cible. StepNumber ne reçoit jamais directement
// MinStepNumber ; LIMIT final garantit la plage 1..5 après le plafond.
StepNumber := LIMIT(_MinStepClamped, SpeedStepReq, _MaxStepClamped);

CASE StepNumber OF
    1:  Contactor1 := Table.P1R1; Contactor2 := Table.P1R2; Contactor3 := Table.P1R3; Contactor4 := Table.P1R4;
    2:  Contactor1 := Table.P2R1; Contactor2 := Table.P2R2; Contactor3 := Table.P2R3; Contactor4 := Table.P2R4;
    3:  Contactor1 := Table.P3R1; Contactor2 := Table.P3R2; Contactor3 := Table.P3R3; Contactor4 := Table.P3R4;
    4:  Contactor1 := Table.P4R1; Contactor2 := Table.P4R2; Contactor3 := Table.P4R3; Contactor4 := Table.P4R4;
    5:  Contactor1 := Table.P5R1; Contactor2 := Table.P5R2; Contactor3 := Table.P5R3; Contactor4 := Table.P5R4;
ELSE
    // Défense en profondeur face à une divergence type/outil.
    StepNumber := 0;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
END_CASE;
{endregion}

{region "§1 Gate neutralisation"}
// 🛑 1. GATE
IF NOT Enable OR BypassGlobal THEN
    ContactorMismatch := FALSE;
    ContactorMismatchEscalated := FALSE;
    MismatchActive := FALSE;
    BothCommanded := FALSE;
    MismatchTimer(IN := FALSE);
    EscalationTimer(IN := FALSE);
    Diag.RelayFwdMismatch := FALSE;
    Diag.RelayRevMismatch := FALSE;
    Diag.Step1Mismatch := FALSE;
    Diag.Step2Mismatch := FALSE;
    Diag.Step3Mismatch := FALSE;
    Diag.Step4Mismatch := FALSE;
    Diag.MismatchLevel := 0;
    RETURN;
END_IF;
{endregion}

{region "§2 Detection discordance + diagnostic decode"}
// 🔍 2. COHÉRENCE DES COMMANDES SÉCURITÉ — verifie que les commandes envoyees
// aux deux treuils sont identiques (sens et contacteurs).
// Concordance ACTIVE des que les 2 treuils sont commandes (relais ou contacteur)
// OU en mode synchronisme (SyncEnable).
BothCommanded := (RelayFwdM1 OR RelayRevM1 OR Contactor1_M1 OR Contactor2_M1
                  OR Contactor3_M1 OR Contactor4_M1)
             AND (RelayFwdM2 OR RelayRevM2 OR Contactor1_M2 OR Contactor2_M2
                  OR Contactor3_M2 OR Contactor4_M2);

// Diagnostic decode : quel(s) contacteur(s) diverge(nt) (bits nommes, plusieurs possibles).
Diag.RelayFwdMismatch := (BothCommanded OR SyncEnable) AND (RelayFwdM1 <> RelayFwdM2);
Diag.RelayRevMismatch := (BothCommanded OR SyncEnable) AND (RelayRevM1 <> RelayRevM2);
Diag.Step1Mismatch    := (BothCommanded OR SyncEnable) AND (Contactor1_M1 <> Contactor1_M2);
Diag.Step2Mismatch    := (BothCommanded OR SyncEnable) AND (Contactor2_M1 <> Contactor2_M2);
Diag.Step3Mismatch    := (BothCommanded OR SyncEnable) AND (Contactor3_M1 <> Contactor3_M2);
Diag.Step4Mismatch    := (BothCommanded OR SyncEnable) AND (Contactor4_M1 <> Contactor4_M2);

MismatchActive := Diag.RelayFwdMismatch OR Diag.RelayRevMismatch
    OR Diag.Step1Mismatch OR Diag.Step2Mismatch
    OR Diag.Step3Mismatch OR Diag.Step4Mismatch;

// Niveau 1 : discordance confirmee apres MismatchDebounce.
MismatchTimer(IN := MismatchActive, PT := MismatchDebounce);
ContactorMismatch := MismatchTimer.Q;

// Niveau 2 : la discordance confirmee tient au-dela de CST_SyncEscalationTime.
EscalationTimer(IN := ContactorMismatch, PT := CST_SyncEscalationTime);
ContactorMismatchEscalated := EscalationTimer.Q;

// Niveau publie.
IF ContactorMismatchEscalated THEN
    Diag.MismatchLevel := 2;
ELSIF ContactorMismatch THEN
    Diag.MismatchLevel := 1;
ELSE
    Diag.MismatchLevel := 0;
END_IF;
{endregion}

{region "§1 Gate neutralisation"}
// 🛑 1. GATE
IF NOT Enable THEN
    DeltaPosM := 0.0; SignedDeltaPosM := 0.0;
    SyncDeviationWarn := FALSE; SyncDeviationFault := FALSE;
    WarnLatched := FALSE;
    RETURN;
END_IF;
ResetEdge(CLK := Reset);
{endregion}

{region "§2 Calcul ecart"}
// 📏 2. ÉCART M1/M2 — calculé en continu si les 2 treuils sont fiables (HomedAndReliable)
IF HomedAndReliableM1 AND HomedAndReliableM2 THEN
    SignedDeltaPosM := CablePosM1 - CablePosM2 + ActiveOffsetM;
    DeltaPosM := ABS(SignedDeltaPosM);
ELSE
    SignedDeltaPosM := 0.0;
    DeltaPosM := 0.0;
END_IF;
{endregion}

{region "§3 Surveillance ecart 2 seuils"}
// 🔍 3. SURVEILLANCE ECART — 2 seuils (Warn/Fault).
// Warn (seuil 1) = INSTANTANE + LATCH : degrade le palier 1 des que l'ecart depasse,
// sans retard temporel ni oscillation (fidele a l'ancien SyncDegradedStep1).
// Fault (seuil 2) = filtre temporel pour le transitoire mecanique d'arret.
IF NOT BypassGlobal THEN
    WarnActive  := SyncEnable AND HomedAndReliableM1 AND HomedAndReliableM2 AND (DeltaPosM > CfgSyncToleranceM);
    FaultActive := SyncEnable AND HomedAndReliableM1 AND HomedAndReliableM2 AND (DeltaPosM > CfgSyncCriticalToleranceM);

    // Latch Warn : reste actif tant que la cause persiste OU que Reset n'a pas ete demande
    IF WarnActive THEN
        WarnLatched := TRUE;
    ELSIF ResetEdge.Q AND NOT WarnActive THEN
        WarnLatched := FALSE;
    END_IF;
    SyncDeviationWarn := WarnActive OR WarnLatched;

    DeviationFaultTimer(IN := FaultActive, PT := T#800ms);
    SyncDeviationFault := DeviationFaultTimer.Q;
ELSE
    SyncDeviationWarn := FALSE;
    SyncDeviationFault := FALSE;
    WarnLatched := FALSE;
END_IF;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Causes & Socle Défaut (évalué en continu)"}
// 🔑 1. RESET FRONT
ResetEdge(CLK := Reset);

IF ResetEdge.Q THEN
    DriveFaultLatching := FALSE;
END_IF;

IF DriveStatusWord.4 THEN
    DriveFaultLatching := TRUE;
END_IF;

instCauses[0].Active   := Brake.Fault.Error;
instCauses[0].Latching := FALSE;
instCauses[0].Texte    := 'Defaut sequence ou retour frein translation';

instCauses[3].Active   := DriveFaultLatching;
instCauses[3].Latching := TRUE;
instCauses[3].Texte    := 'Defaut variateur translation AC600';

IF NOT BypassLimitSwitch AND ((CommandedTremie AND LimitSwitchTremie) OR (CommandedMaintenance AND LimitSwitchMaintenance)) THEN
    instCauses[6].Active := TRUE;
ELSE
    instCauses[6].Active := FALSE;
END_IF;
instCauses[6].Latching := FALSE;
instCauses[6].Texte    := 'Limite extreme translation atteinte';

// Appel du socle de défaut
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;
{endregion}

{region "§2 Gate neutralisation"}
// 🛑 2. GATE
IF NOT Enable THEN
    SpeedRamp(Target := 0.0, AccelRate := 0.0, DecelRate := 100000.0, CycleTimeS := 1.0);
    Brake(Enable := FALSE);
    RequestedDriveControlWord := 0;
    RequestedDriveFreqHz := 0.0;
    BrakeReleaseRequest := FALSE;
    BrakeCommandOpenConfirmed := FALSE;
    BrakeContactorCheck.Command := FALSE;
    BrakeContactorCheck.Feedback := BrakeFeedback;
    CommandedTremie := FALSE;
    CommandedMaintenance := FALSE;
    DirectionChangePending := FALSE;
    ArrivalLock := FALSE;
    ArrivalWasTremie := FALSE;
    ArrivalWasMaintenance := FALSE;
    TargetReached := FALSE;
    DirectionChangeDelay(IN := FALSE);
    CaptorDebounceTon(IN := FALSE);
    TonBrakeRealFreqTimeout(IN := FALSE);
    Ready := FALSE;
    RETURN;
END_IF;

Ready := Enable AND NOT Fault.Latched;
{endregion}

{region "§3 Premier scan et temps de cycle"}
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
    CommandedTremie := FALSE;
    CommandedMaintenance := FALSE;
END_IF;

CycleTimeCalc();
{endregion}

{region "§4 Arrivée sur cible et interlock direction"}
CaptorDebounceTon(IN := PositionSensorTarget, PT := Cfg.CaptorDebounce);
TargetReached := CaptorDebounceTon.Q;
ArrivalEdge(CLK := TargetReached);

IF ArrivalEdge.Q THEN
    ArrivalLock := TRUE;
    ArrivalWasTremie := CommandedTremie;
    ArrivalWasMaintenance := CommandedMaintenance;
END_IF;

IF ArrivalLock AND ((ReqTremie AND NOT ArrivalWasTremie) OR (ReqMaintenance AND NOT ArrivalWasMaintenance)) THEN
    ArrivalLock := FALSE;
END_IF;

DirectionChangeDelay(
    IN := (ReqTremie OR ReqMaintenance)
          AND ((ReqTremie AND NOT CommandedTremie) OR (ReqMaintenance AND NOT CommandedMaintenance))
          AND (ABS(SpeedRamp.Current) <= 0.1)
          AND (ABS(DriveActualFreqHz) <= 0.5),
    PT := Cfg.DirectionInterlockDelay
);

IF NOT (CommandedTremie OR CommandedMaintenance) AND (ReqTremie OR ReqMaintenance) THEN
    CommandedTremie := ReqTremie;
    CommandedMaintenance := ReqMaintenance;
    DirectionChangePending := FALSE;
ELSIF DirectionChangeDelay.Q THEN
    CommandedTremie := ReqTremie;
    CommandedMaintenance := ReqMaintenance;
    DirectionChangePending := FALSE;
ELSIF (ReqTremie OR ReqMaintenance)
      AND ((ReqTremie AND NOT CommandedTremie) OR (ReqMaintenance AND NOT CommandedMaintenance)) THEN
    DirectionChangePending := TRUE;
ELSE
    DirectionChangePending := FALSE;
END_IF;

IF NOT (ReqTremie OR ReqMaintenance) THEN
    CommandedTremie := FALSE;
    CommandedMaintenance := FALSE;
    DirectionChangePending := FALSE;
END_IF;
{endregion}

{region "§4bis Permis directionnels et EffectiveSafeStop"}
// 🛡️ 4bis. GATE DE SENS (permis directionnels SAFETY) — modèle treuils FB_Winch
// RampStopActive = SafeStop OR demande vers un sens non permis. Bloque la RAMPE
// (arrêt réel) vers un sens non autorisé sans fabriquer de sens numérique.
// Consommé dans la gate de rampe (§5) et le choix de décélération.
// Le permis Maintenance représente la possibilité de rejoindre P1/maintenance physique ;
// l'interdiction d'accès à la zone Maintenance est gérée séparément par la cible P1 et sa
// coupure dure, sans couper le déplacement légal jusqu'à P1.
EffectiveSafeStop := SafeStop
                      OR (ReqTremie AND NOT EffectivePermitM3_Tremie)
                      OR (ReqMaintenance AND NOT EffectivePermitM3_Maintenance)
                      OR (ReqTremie AND ReqMaintenance);
{endregion}

{region "§5 Consigne et rampe de vitesse"}
IF DirectionChangePending OR NOT (ReqTremie OR ReqMaintenance) OR ArrivalLock OR EffectiveSafeStop OR NOT RunRequest THEN
    RampTargetPct := 0.0;
ELSE
    RampTargetPct := LIMIT(0.0, SpeedTgt_Pct, 100.0);
END_IF;

SpeedRamp(
    Target := RampTargetPct,
    AccelRate := Cfg.CfgRampAccelRate,
    DecelRate := SEL(EffectiveSafeStop, Cfg.CfgRampDecelNormalRate, Cfg.CfgRampDecelFastRate),
    CycleTimeS := CycleTimeCalc.CycleTimeS
);
{endregion}

{region "§6 Commande variateur et frein"}
TonBrakeRealFreqTimeout(
    IN := (RampTargetPct <= 0.1) AND (ABS(SpeedRamp.Current) <= 0.1),
    PT := T#2S
);

MovementRequested := (ABS(SpeedRamp.Current) > 0.1)
                  OR ((ABS(DriveActualFreqHz) > 0.5) AND NOT TonBrakeRealFreqTimeout.Q);

Brake(
    Enable := Enable,
    Reset := Reset,
    MovementRequested := MovementRequested,
    ContactorFeedback := BrakeFeedback,
    BypassContactorCheck := BypassContactorCheck,
    DelayContactClose := Cfg.BrakeDelayContactClose,
    DelayMagnetise := Cfg.BrakeDelayMagnetise,
    DelayMotorDecel := Cfg.BrakeDelayMotorDecel,
    FeedbackTimeout := Cfg.BrakeFeedbackTimeout
);

BrakeReleaseRequest := Brake.BrakeCmd;
BrakeCommandOpenConfirmed := Brake.BrakeCommandOpenConfirmed;
BrakeContactorCheck := Brake.ContactorCheck;

PhysicalTremie := CommandedTremie;
PhysicalMaintenance := CommandedMaintenance;
IF InvertDriveDirection THEN
    PhysicalTremie := CommandedMaintenance;
    PhysicalMaintenance := CommandedTremie;
END_IF;

IF PhysicalTremie AND Brake.BrakeCmd THEN
    RequestedDriveControlWord := 1; // FWD
ELSIF PhysicalMaintenance AND Brake.BrakeCmd THEN
    RequestedDriveControlWord := 2; // REV
ELSE
    RequestedDriveControlWord := 0;
END_IF;

RequestedDriveFreqHz := (SpeedRamp.Current / 100.0) * Cfg.DriveFreqScaleMaxHz;

// Ralentissements d'approche
IF CommandedTremie AND SlowdownSensorTremie THEN
    RequestedDriveFreqHz := MIN(RequestedDriveFreqHz, Cfg.ApproachSpeedTremieHz);
ELSIF CommandedMaintenance AND SlowdownSensorMaintenance THEN
    RequestedDriveFreqHz := MIN(RequestedDriveFreqHz, Cfg.ApproachSpeedMaintenanceHz);
ELSIF CommandedMaintenance AND SlowdownSensorP1 THEN
    RequestedDriveFreqHz := MIN(RequestedDriveFreqHz, Cfg.ApproachSpeedP1Hz);
END_IF;

IF Fault.Error THEN
    RequestedDriveControlWord := 0;
    RequestedDriveFreqHz := 0.0;
    BrakeReleaseRequest := FALSE;
END_IF;
{endregion}

// === IMPLEMENTATION ===

Ready := Enable;

// Les deux bits de sens sont reconstruits à chaque cycle : aucune demande ne doit
// rester mémorisée lors d'un changement de source (IHM/joystick/cycle).
RunRequest      := FALSE;
ReqTremie       := FALSE;
ReqMaintenance  := FALSE;
CommandConflict := FALSE;

IF NOT Enable THEN
    RunRequest        := FALSE;
    ReqTremie         := FALSE;
    ReqMaintenance    := FALSE;
    CommandConflict   := FALSE;
    SpeedPct          := 0.0;
    PositioningActive := FALSE;
    SelTarget         := 0;
ELSE
    // ── Pont SEMI_AUTO : consomme la demande du séquenceur de cycle ──
    IF Auth.Mode = E_Mode.SEMI_AUTO THEN
        PositioningActive := TRUE;
        SelTarget := ReqTranslation.PositionTgt;
        RunRequest := ReqTranslation.ReqStart AND Context.HeightInterlockOk;
        IF RunRequest THEN
            SpeedPct := 100.0;
            IF SelTarget = 1 THEN
                ReqTremie := TRUE;
            ELSE
                ReqMaintenance := TRUE;
            END_IF;
        ELSE
            SpeedPct := 0.0;
        END_IF;
    ELSIF (Auth.Mode = E_Mode.MAINT_N1) OR (Auth.Mode = E_Mode.MAINT_N2) THEN
        // ── Mode maintenance : jog joystick ou boutons IHM ──
        PositioningActive := IHM.SelPositioning;
        SelTarget := 0;

        IF NOT TglJoystickMaster AND IHM.BtnTremie THEN
            ReqTremie := TRUE;
        ELSIF NOT TglJoystickMaster AND IHM.BtnMaintenance THEN
            ReqMaintenance := TRUE;
        ELSIF TglJoystickMaster THEN
            ReqTremie := Joystick.AxisX.DirectionPositive;
            ReqMaintenance := Joystick.AxisX.DirectionNegative;
        END_IF;

        // Homme-mort exigé même pour boutons IHM en MAINT_N1/N2.
        // ⚠️ Tautologie conservée bit-identique : (BypassGlobal OR NOT Tgl OR Tgl) = toujours TRUE.
        RunRequest := (ReqTremie OR ReqMaintenance)
                     AND (IHM.BypassGlobal OR NOT TglJoystickMaster OR TglJoystickMaster)
                     AND Joystick.DeadmanArmed
                     AND Context.HeightInterlockOk;

        // Échelle fréquence : SetFreq_Hz (ou 100% si non renseignée), manche mis à l'échelle si joystick maître
        FreqPct := SEL(IHM.SetFreq_Hz > 0.0,
                       100.0,
                       (IHM.SetFreq_Hz / SEL(Cfg.MaxFreq_Hz > 0.0, 50.0, Cfg.MaxFreq_Hz)) * 100.0);
        SpeedPct := SEL(TglJoystickMaster,
                        FreqPct,
                        (ABS(Joystick.AxisX.SpeedTgt) / 100.0) * FreqPct);
    ELSE
        // ── Autres modes : neutralisé ──
        PositioningActive := FALSE;
        SelTarget := 0;
        RunRequest := FALSE;
        SpeedPct  := 0.0;
    END_IF;
END_IF;

// Une demande contradictoire est toujours neutralisée. RunRequest reste vrai afin de
// conserver la sémantique de décélération de FB_Translation ; aucune direction n'est choisie.
CommandConflict := ReqTremie AND ReqMaintenance;
IF CommandConflict THEN
    ReqTremie := FALSE;
    ReqMaintenance := FALSE;
END_IF;

// Clamp consigne (bit-identique PRG_05 §1)
SpeedPct := LIMIT(0.0, ABS(SpeedPct), 100.0);

// SelTarget = Maintenance (4) interdit si Maintenance non autorisée
IF (SelTarget = 4) AND NOT Auth.MaintenanceM3TargetEnable THEN
    SelTarget := 0;
END_IF;

// ── 1. FRONT RESET AVANT GATE ───────────────────────────────────────────
ResetEdge(CLK := Reset);

IF NOT Enable OR NOT PowerContactorEngaged THEN
    BrakeTimeout(IN := FALSE, PT := T#500ms);
    DriveControlWord := 0;
    DriveFreqCmd_Hz := 0.0;
    DriveFreqCmdWord := 0;
    BrakeCmd := FALSE;
    BrakeTimeoutElapsed := T#0ms;
    Ready := FALSE;
    Reason := E_TranslationFinalInterlockReason.NONE;
    RETURN;
END_IF;

MovementRequested := (RequestedDriveControlWord = 1) OR (RequestedDriveControlWord = 2);
PermitFinalBlocked := ((RequestedDriveControlWord = 1) AND NOT EffectivePermitM3_Tremie)
                   OR ((RequestedDriveControlWord = 2) AND NOT EffectivePermitM3_Maintenance);

// ── 2. Watchdog : exclusivement après ordre effectif de desserrage ──────
BrakeTimeout(
    IN := BrakeReleaseRequest AND NOT BrakeCommandOpenConfirmed AND NOT RestartInhibit,
    PT := T#500ms
);
BrakeTimeoutElapsed := BrakeTimeout.ET;

IF BrakeTimeout.Q THEN
    BrakeTimeoutCause := TRUE;
ELSIF BrakeCommandOpenConfirmed THEN
    BrakeTimeoutCause := FALSE;
END_IF;

BrakeTimeoutCauseEdge(CLK := BrakeTimeoutCause);
IF BrakeTimeoutCauseEdge.Q THEN
    BrakeTimeoutAck := FALSE;
    RestartInhibit := TRUE;
    ResetRequired := TRUE;
    NeutralRequestSeen := FALSE;
    Reason := E_TranslationFinalInterlockReason.BRAKE_COMMAND_NOT_CONFIRMED;
END_IF;

IF ResetEdge.Q THEN
    BrakeTimeoutAck := TRUE;
    ResetRequired := FALSE;
END_IF;

instCauses[0].Active   := BrakeTimeoutCause OR NOT BrakeTimeoutAck;
instCauses[0].Latching := TRUE;
instCauses[0].Texte    := 'Timeout confirmation ouverture frein translation';

instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

// ── 3. Réarmement anti-redémarrage automatique ──────────────────────────
IF RestartInhibit AND NOT Fault.Error AND NOT ResetRequired AND NOT ResetEdge.Q THEN
    IF RequestedDriveControlWord = 0 THEN
        NeutralRequestSeen := TRUE;
    ELSIF NeutralRequestSeen AND MovementRequested THEN
        RestartInhibit := FALSE;
        NeutralRequestSeen := FALSE;
    END_IF;
END_IF;

// ── 4. Décision finale : zéro couple utile sans confirmation frein ──────
DriveControlWord := 0;
DriveFreqCmd_Hz := 0.0;
DriveFreqCmdWord := 0;

BrakeCmd := BrakeReleaseRequest AND NOT Fault.Error AND NOT RestartInhibit;
Ready := NOT Fault.Error AND NOT RestartInhibit;

IF Fault.Error THEN
    BrakeCmd := FALSE;
ELSIF RequestedDriveControlWord = 7 THEN
    DriveControlWord := 7;
ELSIF RestartInhibit THEN
    Reason := E_TranslationFinalInterlockReason.RESTART_INHIBITED;
ELSIF MovementRequested AND NOT PermitFinalBlocked THEN
    IF BrakeReleaseRequest AND BrakeCommandOpenConfirmed THEN
        DriveControlWord := RequestedDriveControlWord;
        DriveFreqCmd_Hz := MAX(0.0, RequestedDriveFreqHz);
    END_IF;
END_IF;

// ── 5. Mise à l'échelle finale REAL Hz -> WORD registre PDO 0x3100 ──────
DriveFreqCmdWord := REAL_TO_WORD(LIMIT(0.0, DriveFreqCmd_Hz, DriveFreqWordMaxHz) * DriveFreqWordScale);

// === IMPLEMENTATION ===

{region "§1 Assemblage mot et cohérence"}
// 🧾 Assemblage du mot (bit4=Trémie ... bit0=Maintenance, ordre doc AF_Partie-02 §3bis)
SensorsWord := 0;
IF SensorTremie      THEN SensorsWord := SensorsWord OR 16#10; END_IF;
IF SensorPV          THEN SensorsWord := SensorsWord OR 16#08; END_IF;
IF SensorP2          THEN SensorsWord := SensorsWord OR 16#04; END_IF;
IF SensorP1          THEN SensorsWord := SensorsWord OR 16#02; END_IF;
IF SensorMaintenance THEN SensorsWord := SensorsWord OR 16#01; END_IF;

// 🎯 Les 6 combinaisons valides (progression monotone décroissante Trémie→Maintenance)
CASE SensorsWord OF
    2#11111, 2#01111, 2#00111, 2#00011, 2#00001, 2#00000:
        Incoherent := FALSE;
    ELSE
        Incoherent := TRUE;
END_CASE;

// 🚧 Limites extrêmes — uniquement sur mot valide (évite un Fdc fantôme déclenché par une incohérence)
LimitSwitchTremie := (NOT Incoherent) AND (SensorsWord = 2#11111);
LimitSwitchMaintenance := (NOT Incoherent) AND (SensorsWord = 2#00000);
{endregion}

{region "§2 Reprise capteurs"}
// Reprise des capteurs de position pour les consommateurs aval (passthrough, identique à l'entrée filtrée)
// ⚠️ CUMULATIF — voir avertissement en déclaration, réservé au ralentissement d'approche.
TranslationPosTremie      := SensorTremie;
TranslationPosPV          := SensorPV;
TranslationPosP2          := SensorP2;
TranslationPosP1          := SensorP1;
TranslationPosMaintenance := SensorMaintenance;
{endregion}

{region "§3 Fronts individuels"}
// Front individuel par capteur — voir avertissement en déclaration. Transitoire (1 cycle),
// mémorisé par l'appelant.
EdgeUpTremie(CLK := SensorTremie);           EdgeDnTremie(CLK := SensorTremie);
EdgeUpPV(CLK := SensorPV);                   EdgeDnPV(CLK := SensorPV);
EdgeUpP2(CLK := SensorP2);                   EdgeDnP2(CLK := SensorP2);
EdgeUpP1(CLK := SensorP1);                   EdgeDnP1(CLK := SensorP1);
EdgeUpMaintenance(CLK := SensorMaintenance); EdgeDnMaintenance(CLK := SensorMaintenance);

// Front du capteur PROPRE à chaque position — voir modèle en déclaration.
// Extrémités : un seul sens valide chacune. Points intermédiaires : les deux fronts de LEUR PROPRE
// capteur (montant = atteint en venant de Maintenance, descendant = dépassé en venant de Trémie).
TranslationAtTremie      := EdgeUpTremie.Q;
TranslationAtPV          := EdgeUpPV.Q OR EdgeDnPV.Q;
TranslationAtP2          := EdgeUpP2.Q OR EdgeDnP2.Q;
TranslationAtP1          := EdgeUpP1.Q OR EdgeDnP1.Q;
TranslationAtMaintenance := EdgeDnMaintenance.Q;
{endregion}

// === IMPLEMENTATION ===

{region "§1 Gate et initialisation"}
IF NOT Enable THEN
    Recalibrated := FALSE;
    RecalibratedSensorId := -1;
    // 🔒 Sorties odométriques VOLONTAIREMENT conservées hors Enable (AC3 / persistance continue RETAIN) :
    // - PositionEstimatedM & Initialized : estimation odométrique et référence absolue maintenues pour ne pas perdre la position M3 hors Enable
    RETURN;
END_IF;

IF ColdStart THEN
    PositionEstimatedM := PersistedPositionM;
    Initialized := PersistedInitialized;
    ColdStart := FALSE;
END_IF;

CycleTimeCalc(DefaultValueS := 0.010);
Recalibrated := FALSE;
{endregion}

{region "§2 Fronts capteurs"}
// 1. Détection des fronts montants sur franchissement des capteurs fixes
TrigTremie(CLK := SensorTremie);
TrigPV(CLK := SensorPV);
TrigP2(CLK := SensorP2);
TrigP1(CLK := SensorP1);
TrigMaintenance(CLK := SensorMaintenance);
{endregion}

{region "§3 Recalage et intégration"}
// 2. Recalage absolu sur franchissement capteur — UNIQUEMENT après le premier scan utile.
//    Au 1er scan, un capteur "déjà présent" à l'initialisation (sim démarre à la trémie :
//    5 capteurs actifs) n'est pas un franchissement réel ; sinon le recalage IF/ELSIF
//    partirait de Maintenance (premier dans l'ordre) et écraserait la position à 30 m.
IF NOT FirstScanDone THEN
    FirstScanDone := TRUE;
ELSE
    IF TrigMaintenance.Q THEN
        PositionEstimatedM := PosMaintenanceM;
        Recalibrated := TRUE;
        RecalibratedSensorId := 0;
    ELSIF TrigP1.Q THEN
        PositionEstimatedM := PosP1M;
        Recalibrated := TRUE;
        RecalibratedSensorId := 1;
    ELSIF TrigP2.Q THEN
        PositionEstimatedM := PosP2M;
        Recalibrated := TRUE;
        RecalibratedSensorId := 2;
    ELSIF TrigPV.Q THEN
        PositionEstimatedM := PosPVM;
        Recalibrated := TRUE;
        RecalibratedSensorId := 3;
    ELSIF TrigTremie.Q THEN
        PositionEstimatedM := PosTremieM;
        Recalibrated := TRUE;
        RecalibratedSensorId := 4;
    END_IF;
END_IF;

// 3. Initialisation au tout premier démarrage sur le premier capteur actif vu (si non initialisé)
IF NOT Initialized THEN
    IF SensorTremie THEN PositionEstimatedM := PosTremieM; Initialized := TRUE;
    ELSIF SensorPV THEN PositionEstimatedM := PosPVM; Initialized := TRUE;
    ELSIF SensorP2 THEN PositionEstimatedM := PosP2M; Initialized := TRUE;
    ELSIF SensorP1 THEN PositionEstimatedM := PosP1M; Initialized := TRUE;
    ELSIF SensorMaintenance THEN PositionEstimatedM := PosMaintenanceM; Initialized := TRUE;
    END_IF;
END_IF;

// 4. Intégration temporelle continue (Odométrie cycle par cycle)
// Les bits explicites portent le sens sémantique. Une demande contradictoire est
// neutralisée : aucun déplacement estimé ne doit être inventé.
IF DriveActualFreqHz > 0.1 THEN
    IF ReqTremie AND NOT ReqMaintenance THEN
        PositionEstimatedM := PositionEstimatedM - (DriveActualFreqHz * GainMetersPerHzSec * CycleTimeCalc.CycleTimeS);
    ELSIF ReqMaintenance AND NOT ReqTremie THEN
        PositionEstimatedM := PositionEstimatedM + (DriveActualFreqHz * GainMetersPerHzSec * CycleTimeCalc.CycleTimeS);
    END_IF;
END_IF;
{endregion}

{region "§4 Bornage"}
// Bornage de sécurité pour éviter la dérive infinie hors rail
// Convention 0 m=Trémie, 30 m=Maintenance : bornage [Trémie-0.5, Maintenance+0.5].
PositionEstimatedM := LIMIT(PosTremieM - 0.5, PositionEstimatedM, PosMaintenanceM + 0.5);
{endregion}

// 🛑 GATE — neutralisation ; aucune écriture GVL_Troubleshooting si Enable=FALSE
IF NOT Enable THEN
    Ready := FALSE;
    RETURN;
END_IF;
Ready := TRUE;

{region "§0 Contexte machine global"}
// === 🌐 0. ContexteMachineGlobal : ST_ChainContextGlobal (fiche §5.1) ===
GVL_Troubleshooting.A_ContexteMachineGlobal.Idx101_ModeActive        := Auth.Mode;
GVL_Troubleshooting.A_ContexteMachineGlobal.Idx102_SimulationEnabled := SimulationModeActive;
GVL_Troubleshooting.A_ContexteMachineGlobal.Idx103_JoystickCommOk    := Network.Joystick.Operational;
GVL_Troubleshooting.A_ContexteMachineGlobal.Idx201_JoystickSelected  := GVL_IHM.Modes.Cmd.TglJoystickMaster;
GVL_Troubleshooting.A_ContexteMachineGlobal.Idx202_BypassNetworkGlobal := Network.Bypass.Global;
GVL_Troubleshooting.A_ContexteMachineGlobal.Idx203_BypassSensorsGlobal := FALSE; // TBD non câblé - voir fiche §6 (agrégat multi-domaine à définir)
GVL_Troubleshooting.A_ContexteMachineGlobal.Idx301_EmergencyChainClosed := HwIn.Machine.EmergencyChainClosed_DI;
GVL_Troubleshooting.A_ContexteMachineGlobal.Idx302_PowerContactorEngaged := HwIn.Machine.PowerContactorEngaged_DI;
// Agrégat simple OR de faits déjà publiés (fiche §5.1) — pas un nouveau calcul métier
GVL_Troubleshooting.A_ContexteMachineGlobal.Idx303_SafeStopActiveAny := WinchM1.Safety.SafeStop OR WinchM2.Safety.SafeStop OR Translation.Safety.SafeStop;
GVL_Troubleshooting.A_ContexteMachineGlobal.Idx304_PowerCutOffActiveAny := WinchM1.Safety.PowerCutOff OR WinchM2.Safety.PowerCutOff OR Translation.Safety.PowerCutOff;
GVL_Troubleshooting.A_ContexteMachineGlobal.Idx401_HmiHeartbeatOk    := Commun.HeartbeatIhmOk;
GVL_Troubleshooting.A_ContexteMachineGlobal.Idx402_CycleAutoBusy     := CycleAutoBusy;

{endregion}

{region "§1 Levage synchronise M1/M2"}
// === 🛗 1. LevageSynchroniseM1M2 : ST_ChainWinchSync (fiche §5.2) ===
GVL_Troubleshooting.H_LevageSynchroniseM1M2.Idx101_M1_CablePos_M  := WinchM1.State.Position_M;
GVL_Troubleshooting.H_LevageSynchroniseM1M2.Idx102_M2_CablePos_M  := WinchM2.State.Position_M;
GVL_Troubleshooting.H_LevageSynchroniseM1M2.Idx103_SyncDelta_M    := Sync.State.DeltaPos_M;
GVL_Troubleshooting.H_LevageSynchroniseM1M2.Idx202_SyncEnabled_IHM := Sync.Cmd.SelSyncEnable;
GVL_Troubleshooting.H_LevageSynchroniseM1M2.Idx301_EmergencyChainClosed := HwIn.Machine.EmergencyChainClosed_DI;
GVL_Troubleshooting.H_LevageSynchroniseM1M2.Idx302_SyncFaultActive := Sync.State.Error;
GVL_Troubleshooting.H_LevageSynchroniseM1M2.Idx303_M1_AscentPermit := WinchM1.Safety.AscentPermit;
GVL_Troubleshooting.H_LevageSynchroniseM1M2.Idx304_M2_AscentPermit := WinchM2.Safety.AscentPermit;
GVL_Troubleshooting.H_LevageSynchroniseM1M2.Idx501_M1_CmdRelayFwd_DQ := WinchM1.State.RelayFwd;
GVL_Troubleshooting.H_LevageSynchroniseM1M2.Idx502_M2_CmdRelayFwd_DQ := WinchM2.State.RelayFwd;
// Idx201_JoyYRaw_Pct / Idx203_ArbitratedSpeed_Pct / Idx303-304_AscentPermit / Idx401_SyncMotionAllowed /
// Idx402-403_SetpointSpeed : non câblés — fiche §5.2 "(reste) champs à revoir un par un", laissés à
// leur valeur d'initialisation, pas de calcul inventé (fiche §7).

{endregion}

{region "§2 Levage unitaire M1/M2"}
// === 🛗 2. LevageUnitaireM1 / LevageUnitaireM2 : ST_ChainWinch (fiche §5.3) ===
// --- M1 ---
GVL_Troubleshooting.I_LevageUnitaireM1.Inputs_100.Idx101_EncoderRawPos := UDINT_TO_DINT(HwIn.Winch.COD1_PosValue);
GVL_Troubleshooting.I_LevageUnitaireM1.Inputs_100.Idx102_CablePos_M := WinchM1.State.Position_M;
GVL_Troubleshooting.I_LevageUnitaireM1.Inputs_100.Idx103_ContactorsReleased_DI := HwIn.Winch.M1_ContactorsReleased_DI;
GVL_Troubleshooting.I_LevageUnitaireM1.Inputs_100.Idx104_BrakeApplied := NOT HwIn.Winch.M1_BrakeIsOpen_DI;
GVL_Troubleshooting.I_LevageUnitaireM1.Inputs_100.Idx105_ThermalOk_DI := HwIn.Winch.M1_ThermalOk_DI;

GVL_Troubleshooting.I_LevageUnitaireM1.Demandes_200.Idx201_JoyRawPhysical_ANA := HwIn.Operator.JoyYRaw_ANA2;
GVL_Troubleshooting.I_LevageUnitaireM1.Demandes_200.Idx202_JoyScaledPhysical_Pct := JoystickHMI.State.AxisCmdY.Deflection;
GVL_Troubleshooting.I_LevageUnitaireM1.Demandes_200.Idx203_HmiManualCmd_BtnAscent := WinchM1.Cmd.BtnAscent;
GVL_Troubleshooting.I_LevageUnitaireM1.Demandes_200.Idx204_HmiManualCmd_BtnDescent := WinchM1.Cmd.BtnDescent;
GVL_Troubleshooting.I_LevageUnitaireM1.Demandes_200.Idx205_CycleAutoCmd_Pct := CycleM1SpeedTgt_Pct;
GVL_Troubleshooting.I_LevageUnitaireM1.Demandes_200.Idx206_ModeActive := Auth.Mode;
GVL_Troubleshooting.I_LevageUnitaireM1.Demandes_200.Idx207_BypassOperatorComm := WinchM1.Bypass.OperatorComm;
GVL_Troubleshooting.I_LevageUnitaireM1.Demandes_200.Idx208_ArbitratedSpeed_Pct := M1LogicRequestSpeedCmd_Pct;
GVL_Troubleshooting.I_LevageUnitaireM1.Demandes_200.Idx209_ArbitratedDirection := M1LogicRequestDirection;
GVL_Troubleshooting.I_LevageUnitaireM1.Demandes_200.Idx210_CoupledUserRequestDirection := WinchBothMotionDirection;
GVL_Troubleshooting.I_LevageUnitaireM1.Demandes_200.Idx211_CoupledUserRequestActive := WinchBothMotionActive;

GVL_Troubleshooting.I_LevageUnitaireM1.Safety_300.Idx301_EmergencyChainClosed := HwIn.Machine.EmergencyChainClosed_DI;
GVL_Troubleshooting.I_LevageUnitaireM1.Safety_300.Idx302_SafeStopActive := WinchM1.Safety.SafeStop;
GVL_Troubleshooting.I_LevageUnitaireM1.Safety_300.Idx303_PowerCutOffActive := WinchM1.Safety.PowerCutOff;
GVL_Troubleshooting.I_LevageUnitaireM1.Safety_300.Idx304_TopSensorPhysical_DI := HwIn.Winch.M1M2_TopPositionFree_DI;
GVL_Troubleshooting.I_LevageUnitaireM1.Safety_300.Idx305_TopSensorBypassActive := Commun.SimTopSensorBypassActive;
GVL_Troubleshooting.I_LevageUnitaireM1.Safety_300.Idx306_AscentPermitEffective := WinchM1.Safety.AscentPermit;
GVL_Troubleshooting.I_LevageUnitaireM1.Safety_300.Idx307_SlackCablePhysical_DI := FALSE; // TBD non câblé - voir fiche §6 (capteur mou de câble présent uniquement côté M2 dans ST_HwWinch)
GVL_Troubleshooting.I_LevageUnitaireM1.Safety_300.Idx308_SlackCableBypassActive := Commun.SimSlackCableBypassActive;
GVL_Troubleshooting.I_LevageUnitaireM1.Safety_300.Idx309_DescendPermitEffective := WinchM1.Safety.DescendPermit;
GVL_Troubleshooting.I_LevageUnitaireM1.Safety_300.Idx310_ErrorOperatorComm := WinchM1.Safety.ErrorOperatorComm;
GVL_Troubleshooting.I_LevageUnitaireM1.Safety_300.Idx311_ErrorEncoder      := WinchM1.Safety.ErrorEncoder;
GVL_Troubleshooting.I_LevageUnitaireM1.Safety_300.Idx312_ErrorPhaseRotation:= WinchM1.Safety.ErrorPhaseRotation;
GVL_Troubleshooting.I_LevageUnitaireM1.Safety_300.Idx313_ErrorMecaA        := WinchM1.Safety.ErrorMecaA;
GVL_Troubleshooting.I_LevageUnitaireM1.Safety_300.Idx314_ErrorMecaB        := WinchM1.Safety.ErrorMecaB;
GVL_Troubleshooting.I_LevageUnitaireM1.Safety_300.Idx315_ErrorMecaC        := WinchM1.Safety.ErrorMecaC;
GVL_Troubleshooting.I_LevageUnitaireM1.Safety_300.Idx316_ErrorMecaD        := WinchM1.Safety.ErrorMecaD;
GVL_Troubleshooting.I_LevageUnitaireM1.Safety_300.Idx317_ErrorMecaE        := WinchM1.Safety.ErrorMecaE;
GVL_Troubleshooting.I_LevageUnitaireM1.Safety_300.Idx318_ErrorBrakeThermal := WinchM1.Safety.ErrorBrakeThermal;
GVL_Troubleshooting.I_LevageUnitaireM1.Safety_300.Idx319_ErrorOppositeDir  := WinchM1.Safety.ErrorOppositeDir;
