WinchM2FinalInterlockRequest.DescendPermit := M2DescendPermitApplied;

{endregion}

{region "📊 §8 Publication états IHM"}
// === 📤 §8 PUBLICATION ÉTATS IHM (faits publics, lecture seule) ===
// Projection déléguée à FB_WinchStateProjection () : recopie bit-identique
// des sources → WinchM1State/WinchM2State/WinchM1Safety/WinchM2Safety/CableLimitAscent.
// Aucune logique de commande modifiée (non-régression). SyncState/BucketState/
// Benne_IsRoughlyClosed/GLV_IHM restent ici (hors scope du FB).
instWinchStateProjection(
    EncoderM1 := PRG_02_Acquisition.Data.EncoderM1,
    EncoderM2 := PRG_02_Acquisition.Data.EncoderM2,
    WinchM1Ref := instWinchM1,
    WinchM2Ref := instWinchM2,
    SafetyM1 := instSafetyWinchM1,
    SafetyM2 := instSafetyWinchM2,
    InterlockM1 := PRG_06_Outputs.instWinchOutputInterlockM1,
    InterlockM2 := PRG_06_Outputs.instWinchOutputInterlockM2,
    Auth := PRG_03_Modes_Cycle.Data.Auth,
    HwInWinch := PRG_02_Acquisition.HwIn.Winch,
    HwRealWinch := PRG_02_Acquisition.HwReal.Winch,
    M1_PrevSpeed_Mps := M1_PrevSpeed_Mps,
    M2_PrevSpeed_Mps := M2_PrevSpeed_Mps,
    M1LogicRequestSpeedCmd_Pct := M1LogicRequestSpeedCmd_Pct,
    M2LogicRequestSpeedCmd_Pct := M2LogicRequestSpeedCmd_Pct,
    BottomLimitM1_Active := BottomLimitM1_Active,
    BottomLimitM2_Active := BottomLimitM2_Active,
    SafeStopM1_Active := SafeStopM1_Active,
    SafeStopM2_Active := SafeStopM2_Active,
    EffectivePermitM1_Ascent := EffectivePermitM1_Ascent,
    EffectivePermitM1_Descend := EffectivePermitM1_Descend,
    EffectivePermitM2_Ascent := EffectivePermitM2_Ascent,
    EffectivePermitM2_Descend := EffectivePermitM2_Descend,
    M2_LimitShift := M2_LimitShift,
    CfgCableLimitAscent_M := _CommunCfgPersist.CfgCableLimitAscent_M,
    CfgCableLimitDescentM1_M := _WinchM1CfgPersist.CfgCableLimitDescent_M,
    CfgCableLimitDescentM2_M := _WinchM2CfgPersist.CfgCableLimitDescent_M,
    EncoderM1_Operational := PRG_02_Acquisition.Data.Network.EncoderM1.Operational,
    EncoderM2_Operational := PRG_02_Acquisition.Data.Network.EncoderM2.Operational,
    M1PowerCutOffSafetyInfo := PRG_06_Outputs.M1PowerCutOffSafetyInfo,
    M1SafeStopSafetyInfo := PRG_06_Outputs.M1SafeStopSafetyInfo,
    M1BlockedBySafetyInfo := PRG_06_Outputs.M1BlockedBySafetyInfo,
    M2PowerCutOffSafetyInfo := PRG_06_Outputs.M2PowerCutOffSafetyInfo,
    M2SafeStopSafetyInfo := PRG_06_Outputs.M2SafeStopSafetyInfo,
    M2BlockedBySafetyInfo := PRG_06_Outputs.M2BlockedBySafetyInfo
);
WinchM1State := instWinchStateProjection.WinchM1State;
WinchM2State := instWinchStateProjection.WinchM2State;
WinchM1Safety := instWinchStateProjection.WinchM1Safety;
WinchM2Safety := instWinchStateProjection.WinchM2Safety;
CableLimitAscentM1Reached := instWinchStateProjection.CableLimitAscentM1Reached;
CableLimitAscentM2Reached := instWinchStateProjection.CableLimitAscentM2Reached;

SyncState.DeltaPos_M := instWinchSync.SignedDeltaPosM;
SyncState.SyncActive := instWinchSync.SyncActive;
SyncState.SyncWarn := instWinchSync.SyncWarn;
SyncState.SyncDeviationWarn := instWinchSync.SyncDeviationWarn;
SyncState.Ready := instWinchSync.Ready;
SyncState.Error := instWinchSync.Fault.Error;
SyncState.ErrorId := instWinchSync.Fault.ErrorId;
IF instWinchSync.Fault.Error THEN
    SyncState.FBState := E_State.ERROR;
ELSIF instWinchSync.SyncActive THEN
    SyncState.FBState := E_State.BUSY;
ELSE
    SyncState.FBState := E_State.READY;
END_IF;

BucketState.MechState := _BucketState;
BucketState.MechState.ActiveOffsetValid := instBucket.ActiveOffsetValid;
IF instBucket.Fault.Error THEN
    BucketState.FBState := E_State.ERROR;
ELSIF instBucket.Lifecycle.Busy THEN
    BucketState.FBState := E_State.BUSY;
ELSE
    BucketState.FBState := E_State.READY;
END_IF;
BucketState.ActiveOffset_M := instBucket.ActiveOffsetM;
BucketState.M2RunRequest := instBucket.M2_RunRequest;
BucketState.M2ReqAscent := instBucket.M2_ReqAscent;
BucketState.M2ReqDescend := instBucket.M2_ReqDescend;
BucketState.M2BucketJogLimit := instBucket.M2_BucketJogLimit;
BucketState.ManualBucketLimitsActive := ManualBucketLimitsActive;
BucketState.OffsetStateMismatchWarn := instBucket.OffsetStateMismatchWarn;
BucketState.M2PositionCorrected := PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM - instBucket.ActiveOffsetM;
BucketState.Ready := instBucket.Ready;
BucketState.Busy := instBucket.Lifecycle.Busy;
BucketState.Done := instBucket.Lifecycle.Done;
BucketState.Error := instBucket.Fault.Error;
BucketState.ErrorId := instBucket.Fault.ErrorId;
BucketState.RemainingTravel_M := instBucket.RemainingTravelM;
BucketState.DeltaPosition_M := instBucket.DeltaPosition_M;
BucketState.BucketOpening_Pct := instBucket.BucketOpening_Pct;
BucketState.CloseActive := instBucket.CloseReq;
BucketState.OpenActive := instBucket.OpenReq;
// Reflète le séquencement auto : occupé sur une ouverture/fermeture qu'IL a armée, ou en phase
// vitesse contrôlée post-fermeture.
BucketState.AutoBucketSeqActive := (instBucket.Lifecycle.Busy AND (WinchBothDiveBucketOpenArmed OR WinchBothAscentBucketCloseArmed)) OR ExtractionControlActive;
BucketState.CoupledDiveOpenArmed := WinchBothDiveBucketOpenArmed;
BucketState.CoupledAscentCloseArmed := WinchBothAscentBucketCloseArmed;
BucketState.MachineHomed := PRG_02_Acquisition.Data.MachineHoming.Homed;
BucketState.MachineHomingStep := PRG_02_Acquisition.Data.MachineHoming.Step;
BucketState.MachineHomingInstruction := PRG_02_Acquisition.Data.MachineHoming.Instruction;
BucketState.MachineHomingFailed := PRG_02_Acquisition.Data.MachineHoming.Failed;
BucketState.MachineHomingActive := PRG_02_Acquisition.Data.MachineHoming.Active;
BucketState.MachineHomingLossSafeStop := PRG_02_Acquisition.Data.MachineHoming.HomingLoss;
BucketState.ExtractionControlActive := ExtractionControlActive;
BucketState.CoupledMotionBlockedByBucket := WinchBothMotionBlockedByBucket;
GVL_IHM.Commun.KoboldImmersionConfirmed := KoboldImmersionConfirmed;
GVL_IHM.Commun.KoboldBottomTouchLatched := KoboldBottomTouchLatched;

// Tolérance matière benne : « à peu près fermée » = fermée OU
// intermédiaire proche de l'offset fermé (tolérance 2 m). Évite le blocage au fond sur
// matière dense (galets) qui ne ferme jamais à 100% de la consigne fine.
Benne_IsRoughlyClosed := _BucketState.IsClosed
    OR (_BucketState.IsIntermediate
        AND (instBucket.DeltaPosition_M >= (_BucketCfgPersist.Config.OffsetCloseM - 2.0)));

{region "🕵️ §8bis Trace blocage"}
// === 🕵️ §8bis TRACE DE BLOCAGE TERRAIN (cause priorisée + horodatage) ===
// Diagnostic lecture seule, publié via Data.TraceM1/M2 et consommé par FB_TroubleshootingView.
// L'ordre IF/ELSIF EST l'ordre de priorité (cf. E_WinchTraceBlockReason) : la cause la plus
// grave gagne. BlockReasonTimestamp est latched au premier scan du changement (1 scan, mémoire).
// Aucune action de conduite ne dépend de ces champs.

// --- M1 ---
TraceM1.DescendPermitEffective := EffectivePermitM1_Descend;
TraceM1.AscentPermitEffective  := EffectivePermitM1_Ascent;
TraceM1.AscentPermitApplied     := EffectivePermitM1_Ascent;
TraceM1.DescendPermitApplied    := EffectivePermitM1_Descend;
TraceM1.FinalPermitBlocked      := (ReqM1Winch.RunRequest AND ReqM1Winch.ReqAscent AND NOT EffectivePermitM1_Ascent)
                               OR (ReqM1Winch.RunRequest AND ReqM1Winch.ReqDescend AND NOT EffectivePermitM1_Descend);
TraceM1.SafeStopActive         := SafeStopM1_Active;
TraceM1.SafeStopSourceSafety   := instSafetyWinchM1.SafeStop;
TraceM1.SafeStopSourceInput    := PRG_02_Acquisition.Data.InputModules.Fault
                                  OR PRG_02_Acquisition.Data.MachineHoming.HomingLoss
                                  OR instBucket.M1SlipDetected;
TraceM1.SafeStopSourceSync     := ((instWinchSync.Fault.ErrorId AND 16#0002) <> 16#0000)
                                  OR (instWinchSync.SyncActive AND SafeStopM2_Raw);
TraceM1.PowerCutOffActive      := instSafetyWinchM1.PowerCutOff;
TraceM1.Inhibited              := (PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.DISABLE)
                                  OR PRG_03_Modes_Cycle.Data.Auth.InhibitM1;
TraceM1.FinalInterlockError    := WinchM1State.FinalInterlockError;
TraceM1.FinalInterlockReason   := WinchM1State.FinalInterlockReason;
TraceM1.StepNumber             := WinchM1State.StepNumber;

IF instSafetyWinchM1.PowerCutOff THEN
    TraceM1.BlockReason := E_WinchTraceBlockReason.POWER_CUTOFF;
ELSIF TraceM1.Inhibited THEN
    TraceM1.BlockReason := E_WinchTraceBlockReason.AXIS_DISABLED;
ELSIF SafeStopM1_Active THEN
    TraceM1.BlockReason := E_WinchTraceBlockReason.SAFESTOP;
ELSIF instSafetyWinchM1.Fault.Error THEN
    TraceM1.BlockReason := E_WinchTraceBlockReason.SAFETY_FAULT;
ELSIF NOT (SafetyPermitM1_Ascent OR SafetyPermitM1_Descend) THEN
    TraceM1.BlockReason := E_WinchTraceBlockReason.SAFETY_PERMIT_MISSING;
ELSIF NOT (ProcessPermitM1_Ascent OR ProcessPermitM1_Descend) THEN
    TraceM1.BlockReason := E_WinchTraceBlockReason.PROCESS_PERMIT_MISSING;
ELSIF NOT (EffectivePermitM1_Ascent OR EffectivePermitM1_Descend) THEN
    TraceM1.BlockReason := E_WinchTraceBlockReason.COUPLING_BLOCKED;
ELSIF instWinchM1.Fault.Error THEN
    TraceM1.BlockReason := E_WinchTraceBlockReason.WINCH_FAULT;
ELSIF WinchM1State.FinalInterlockError THEN
    TraceM1.BlockReason := E_WinchTraceBlockReason.FINAL_INTERLOCK_BLOCKED;
ELSE
    TraceM1.BlockReason := E_WinchTraceBlockReason.NONE;
END_IF;
IF TraceM1.BlockReason <> TraceM1_PrevReason THEN
    TraceM1.BlockReasonTimestamp := TIME_TO_UDINT(TIME());
END_IF;
TraceM1_PrevReason := TraceM1.BlockReason;

// --- M2 ---
TraceM2.DescendPermitEffective := EffectivePermitM2_Descend;
TraceM2.AscentPermitEffective  := EffectivePermitM2_Ascent;
TraceM2.AscentPermitApplied     := M2AscentPermitApplied;
TraceM2.DescendPermitApplied    := M2DescendPermitApplied;
TraceM2.FinalPermitBlocked      := (ReqM2Winch.RunRequest AND ReqM2Winch.ReqAscent AND NOT EffectivePermitM2_Ascent)
                               OR (ReqM2Winch.RunRequest AND ReqM2Winch.ReqDescend AND NOT EffectivePermitM2_Descend);
TraceM2.SafeStopActive         := SafeStopM2_Active;
TraceM2.SafeStopSourceSafety   := instSafetyWinchM2.SafeStop;
TraceM2.SafeStopSourceInput    := PRG_02_Acquisition.Data.InputModules.Fault
                                  OR PRG_02_Acquisition.Data.MachineHoming.HomingLoss;
TraceM2.SafeStopSourceSync     := ((instWinchSync.Fault.ErrorId AND 16#0002) <> 16#0000)
                                  OR (instWinchSync.SyncActive AND SafeStopM1_Raw);
TraceM2.PowerCutOffActive      := instSafetyWinchM2.PowerCutOff;
TraceM2.Inhibited              := (PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.DISABLE)
                                  OR PRG_03_Modes_Cycle.Data.Auth.InhibitM2;
TraceM2.FinalInterlockError    := WinchM2State.FinalInterlockError;
TraceM2.FinalInterlockReason   := WinchM2State.FinalInterlockReason;
TraceM2.StepNumber             := WinchM2State.StepNumber;

IF instSafetyWinchM2.PowerCutOff THEN
    TraceM2.BlockReason := E_WinchTraceBlockReason.POWER_CUTOFF;
ELSIF TraceM2.Inhibited THEN
    TraceM2.BlockReason := E_WinchTraceBlockReason.AXIS_DISABLED;
ELSIF SafeStopM2_Active THEN
    TraceM2.BlockReason := E_WinchTraceBlockReason.SAFESTOP;
ELSIF instSafetyWinchM2.Fault.Error THEN
    TraceM2.BlockReason := E_WinchTraceBlockReason.SAFETY_FAULT;
ELSIF NOT (SafetyPermitM2_Ascent OR SafetyPermitM2_Descend) THEN
    TraceM2.BlockReason := E_WinchTraceBlockReason.SAFETY_PERMIT_MISSING;
ELSIF NOT (ProcessPermitM2_Ascent OR ProcessPermitM2_Descend) THEN
    TraceM2.BlockReason := E_WinchTraceBlockReason.PROCESS_PERMIT_MISSING;
ELSIF NOT (EffectivePermitM2_Ascent OR EffectivePermitM2_Descend) THEN
    TraceM2.BlockReason := E_WinchTraceBlockReason.COUPLING_BLOCKED;
ELSIF instWinchM2.Fault.Error THEN
    TraceM2.BlockReason := E_WinchTraceBlockReason.WINCH_FAULT;
ELSIF WinchM2State.FinalInterlockError THEN
    TraceM2.BlockReason := E_WinchTraceBlockReason.FINAL_INTERLOCK_BLOCKED;
ELSE
    TraceM2.BlockReason := E_WinchTraceBlockReason.NONE;
END_IF;
IF TraceM2.BlockReason <> TraceM2_PrevReason THEN
    TraceM2.BlockReasonTimestamp := TIME_TO_UDINT(TIME());
END_IF;
TraceM2_PrevReason := TraceM2.BlockReason;

{endregion}

// 🧩 Cause de blocage priorisée sur l'état public IHM (miroir de la trace terrain §8bis)
WinchM1State.AxisBlockReason := TraceM1.BlockReason;
WinchM2State.AxisBlockReason := TraceM2.BlockReason;

// === 🔌 PUBLICATION BUS INTER-PRG (Data : ST_WinchInterPrg) ===
// Copie des structs internes vers le bus de sortie (producteur unique).
Data.WinchM1FinalInterlockRequest := WinchM1FinalInterlockRequest;
Data.WinchM2FinalInterlockRequest := WinchM2FinalInterlockRequest;
Data.M1LogicRequestSpeedCmd_Pct   := M1LogicRequestSpeedCmd_Pct;
Data.M2LogicRequestSpeedCmd_Pct   := M2LogicRequestSpeedCmd_Pct;
Data.KoboldContactorCmdArbitrated := KoboldContactorCmdArbitrated;
Data.WinchM1State                 := WinchM1State;
Data.WinchM2State                 := WinchM2State;
Data.WinchM1Safety                := WinchM1Safety;
Data.WinchM2Safety                := WinchM2Safety;
Data.SyncState                    := SyncState;
Data.WinchSyncError               := instWinchSync.Fault.Error;
Data.WinchSyncSignedDeltaPosM     := instWinchSync.SignedDeltaPosM;
Data.BucketState                  := BucketState;
Data.Benne_IsRoughlyClosed        := Benne_IsRoughlyClosed;
Data.BucketBusy                   := instBucket.Lifecycle.Busy;
Data.BucketDone                   := instBucket.Lifecycle.Done;
Data.BucketError                  := instBucket.Fault.Error;
Data.EffectivePermitBucket_Open   := EffectivePermitBucket_Open;
Data.EffectivePermitBucket_Close  := EffectivePermitBucket_Close;
Data.ArmingPermit                 := ArmingPermit;
Data.ProcessPermitM1_Ascent       := ProcessPermitM1_Ascent;
Data.ProcessPermitM1_Descend      := ProcessPermitM1_Descend;
Data.ProcessPermitM2_Ascent       := ProcessPermitM2_Ascent;
Data.ProcessPermitM2_Descend      := ProcessPermitM2_Descend;
Data.DescendPermitDiveBucketOpen  := DescendPermitDiveBucketOpen;
Data.ExtractionAssistActive       := ExtractionAssistActive;
Data.ExtractionAscentPermit       := PRG_03_Modes_Cycle.Data.ReqProgram.ReqBucket.AscentPermit;
// Usage effectif d'un override/bypass de position (consommé PRG_03 → FB_Modes)
Data.PositionLimitOverriddenM1    := PositionLimitOverriddenM1;
Data.PositionLimitOverriddenM2    := PositionLimitOverriddenM2;
// 🕵️ Trace de blocage terrain (consommée FB_TroubleshootingView)
Data.TraceM1                      := TraceM1;
Data.TraceM2                      := TraceM2;
// 🔗 ATOMICITÉ BOTH : diagnostic IHM lecture seule
Data.BothActive                   := WinchBothMotionActive;
Data.BothBlocked                  := BothBlocked;
Data.BothBlockReason              := BothBlockReason;

{endregion}

{region "§0 Decodage position M3"}
// === 🧩 §0 DÉCODAGE POSITION M3 (migré de PRG_02, AF-02 TBD §8 #5) ===
// PRG_02_Acquisition s'exécute avant ce POU (rang 01 < 05) : HwIn.Translation est
// disponible au même scan. Le décodage des capteurs M3 est propriété de PRG_05.
instPosDecoderM3(
    SensorTremie      := PRG_02_Acquisition.HwIn.Translation.M3_PosTremie_DI,
    SensorPV          := PRG_02_Acquisition.HwIn.Translation.M3_PosPV_DI,
    SensorP2          := PRG_02_Acquisition.HwIn.Translation.M3_PosPVP2_DI,
    SensorP1          := PRG_02_Acquisition.HwIn.Translation.M3_PosP1_DI,
    SensorMaintenance := PRG_02_Acquisition.HwIn.Translation.M3_PosMaintenance_DI
);

// 📤 Publication des faits M3 dans le bus PRG_05 (consommés par PRG_07)
Data.M3_SensorWordIncoherent := instPosDecoderM3.Incoherent;
{endregion}

{region "§0 Interlock hauteur M1/M2"}
// === 🚧 §0 INTERLOCK HAUTEUR M1/M2 (risque collision translation) ===
// PRG_02_Acquisition s'exécute avant ce POU dans la MainTask (rang 01 < 05) : lecture
// du même scan, aucun retard. Bypass = maintenance consciente, doctrine ST_BypassTranslation.
// ⚠️ Une position encodeur incohérente (hors plage OU homing suspect,
// FB_Encoder_Safety) ne doit PAS pouvoir se lire comme "≥ seuil" par accident — fail-safe :
// hauteur non confirmée = interlock actif (comme une hauteur insuffisante), sauf bypass.
// 🔒 Bypass.Global NE lève PLUS cet interlock (contrairement aux autres
// causes de l'axe M3) — risque de collision jugé trop grave pour être levé par un bypass
// générique. Seul Bypass.MinHeight (dédié, conscient) lève l'anti-collision hauteur.
M3_HeightInterlockOk := GVL_IHM.TranslationM3.Bypass.MinHeight
                        OR (PRG_02_Acquisition.Data.EncoderM1.HomedAndReliable
                            AND PRG_02_Acquisition.Data.EncoderM2.HomedAndReliable
                            AND (PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM >= GVL_PERSISTENT._TranslationMinHeightM1M2_M)
                            AND (PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM >= GVL_PERSISTENT._TranslationMinHeightM1M2_M));
TranslationState.HeightInterlockBlocking := NOT M3_HeightInterlockOk;

{endregion}

{region "§0bis Coupure dure limite translation"}
// === 🚧 §0bis COUPURE DURE (LimitSwitchMaintenance) — bascule sur P1 si Maintenance interdite ===
// LimitSwitchTremie/Maintenance protègent nativement Trémie/Maintenance
// (§5bis FB_Translation : coupure immédiate, sans rampe, dès que CommandedDirection insiste
// dans l'extrémité). P1/P2 n'ont aucune protection dure équivalente — seul le verrou souple
// (arrival-lock) les couvre. Quand Maintenance est interdite, la coupure dure doit protéger
// P1 comme si c'était l'extrémité réelle : mot 00001 (P1=0 ET Maintenance=1), UN CRAN AVANT
// la vraie extrémité Maintenance (00000) — backup si le verrou souple a déjà échoué à arrêter
// avant P1, garde la machine hors de la zone interdite plutôt que d'attendre le vrai fond.
M3_LimitSwitchMaintenanceEffective := SEL(PRG_03_Modes_Cycle.Data.Auth.MaintenanceM3TargetEnable,
                                   NOT instPosDecoderM3.TranslationPosP1 AND instPosDecoderM3.TranslationPosMaintenance,
                                   instPosDecoderM3.LimitSwitchMaintenance);

// 🔒 §0ter STABILISATION BISTABLE FINS DE COURSE EXTRÊMES (Trémie & Maintenance/P1)
// Maintient la détection stable à 1 même si le capteur physique vibre ou saute brièvement.
// Se libère uniquement sur un mouvement effectif dans le SENS INVERSE (dégagement).
IF instPosDecoderM3.LimitSwitchTremie THEN
    M3_LimitSwitchTremieStable := TRUE;
ELSIF M3_ReqMaintenance_Active THEN
    M3_LimitSwitchTremieStable := FALSE;
END_IF;

IF M3_LimitSwitchMaintenanceEffective THEN
    M3_LimitSwitchMaintenanceStable := TRUE;
ELSIF M3_ReqTremie_Active OR (PRG_03_Modes_Cycle.Data.Auth.MaintenanceM3TargetEnable AND NOT instPosDecoderM3.LimitSwitchMaintenance) THEN
    M3_LimitSwitchMaintenanceStable := FALSE;
END_IF;

// 🔒 §0quater MÉMORISATION DU DERNIER POINT ATTEINT (front → jeton unique)
// PositionDecoder n'émet qu'un front transitoire (1 cycle) par capteur, montant OU descendant
// SELON LE SENS (voir FB_Translation_PositionDecoder.st) — mémorisé ici pour
// tenir le niveau nécessaire au débounce (100ms) + verrou anti-rebond (§4ter DirectionAtArrival)
// de FB_Translation, et pour l'affichage IHM. MUTUELLEMENT EXCLUSIFS : un nouveau front RAZ tous
// les autres (jeton "dernier point franchi" unique). Libéré
// (RAZ complet) UNIQUEMENT sur mouvement CONFIRMÉ (fréquence réelle mesurée, pas juste la consigne
// de sens) soutenu ≥1.5s — pas un rebond capteur ni un changement de sens instantané.
M3_ConfirmedMoving := (UINT_TO_REAL(PRG_02_Acquisition.Data.M3.ActualFrequencyHz) / 100.0) > 0.5;
TonM3ConfirmedMoving(IN := M3_ConfirmedMoving, PT := T#1s500ms);

IF instPosDecoderM3.TranslationAtTremie THEN
    M3_AtTremieStable := TRUE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
ELSIF instPosDecoderM3.TranslationAtPV THEN
    M3_AtPVStable := TRUE; M3_AtTremieStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
ELSIF instPosDecoderM3.TranslationAtP2 THEN
    M3_AtP2Stable := TRUE; M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
ELSIF instPosDecoderM3.TranslationAtP1 THEN
    M3_AtP1Stable := TRUE; M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtMaintenanceStable := FALSE;
ELSIF instPosDecoderM3.TranslationAtMaintenance THEN
    M3_AtMaintenanceStable := TRUE; M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE;
ELSIF TonM3ConfirmedMoving.Q THEN
    // Mouvement réel confirmé ≥1.5s sans nouveau front : on a vraiment quitté le dernier point.
    M3_AtTremieStable := FALSE; M3_AtPVStable := FALSE; M3_AtP2Stable := FALSE; M3_AtP1Stable := FALSE; M3_AtMaintenanceStable := FALSE;
END_IF;

{endregion}

{region "§1 Arbitrage cible et direction"}
// === 🔀 §1 ARBITRAGE DU SÉLECTEUR DE CIBLE ET DE LA DIRECTION ===

// ── Arbitrage M3 (FB_TranslationCmdArbitrationM3) ──
// Remplissage des structs d'arbitrage (champ par champ, CODESYS 3.5 refuse l'init anonyme en appel)
// 🎛️ Stimuli boutons IHM M3 : en simulation ET JoyMaster inactif, les stimuli pilotent les
// boutons IHM (SEL) ; sinon la valeur IHM réelle est conservée (jamais écrasée, producteur unique).
SimBtnIHM_Active := GVL_Simulation.SimulationModeActive AND NOT GVL_IHM.Modes.Cmd.TglJoystickMaster;
ArbM3_IHM.BtnTremie         := SEL(SimBtnIHM_Active, GVL_IHM.TranslationM3.Cmd.BtnTremie, GVL_Simulation.SimBtnTremie);
ArbM3_IHM.BtnMaintenance    := SEL(SimBtnIHM_Active, GVL_IHM.TranslationM3.Cmd.BtnMaintenance, GVL_Simulation.SimBtnMaintenance);
ArbM3_IHM.SelPositioning    := GVL_IHM.TranslationM3.Cmd.SelPositioning;
ArbM3_IHM.SetFreq_Hz        := GVL_IHM.TranslationM3.Cmd.SetFreq_Hz;
ArbM3_IHM.BypassGlobal      := GVL_IHM.TranslationM3.Bypass.Global;

ArbM3_Context.HeightInterlockOk := M3_HeightInterlockOk;
ArbM3_Cfg.MaxFreq_Hz            := GVL_PERSISTENT._TranslationMaxFreq_Hz;

instArbM3(
    Enable         := TRUE,
    Joystick       := PRG_02_Acquisition.Data.Joystick,
    Auth           := PRG_03_Modes_Cycle.Data.Auth,
    ReqTranslation := PRG_03_Modes_Cycle.Data.ReqProgram.ReqTranslation,
    IHM            := ArbM3_IHM,
    TglJoystickMaster := GVL_IHM.Modes.Cmd.TglJoystickMaster,
    Context        := ArbM3_Context,
    Cfg            := ArbM3_Cfg
);
M3_PositioningActive := instArbM3.PositioningActive;
SelTarget := instArbM3.SelTarget;
M3_RunRequest_Active := instArbM3.RunRequest;
M3_ReqTremie_Active := instArbM3.ReqTremie;
M3_ReqMaintenance_Active := instArbM3.ReqMaintenance;
M3_CommandConflict := instArbM3.CommandConflict;
M3_SpeedCmd_Active := instArbM3.SpeedPct;

// InvertDirection est appliqué dans FB_Translation (InvertDriveDirection), uniquement au mot
// de commande variateur en sortie — les bits ReqTremie/ReqMaintenance restent le sens sémantique réel.

// 🩺 InputModuleFault (AF06 §3bis) : un module DI TOR hors service rend indisponibles
// les retours frein/thermique/positions du VH_0808ETP/VH_0800END portant M3 — rampe rapide.
M3_SafeStop_Active := PRG_02_Acquisition.Data.InputModules.Fault;

// En mode manuel (SelTarget=0), n'importe quel des 3 points d'arrêt (Trémie/P1/Maintenance)
// arme le verrou anti-rebond §4ter de FB_Translation (DirectionAtArrival). Mot EXACT
// (TranslationAtXxx), pas le cumulatif (TranslationPosXxx) — front franc à l'arrivée quel que
// soit le sens de venue (voir FB_Translation_PositionDecoder.st).
CASE SelTarget OF
    1: M3_PositionSensorTarget := M3_AtTremieStable;
    2: M3_PositionSensorTarget := M3_AtP2Stable;
    3: M3_PositionSensorTarget := M3_AtP1Stable;
    4: M3_PositionSensorTarget := M3_AtMaintenanceStable;
ELSE
    IF M3_ReqTremie_Active THEN
        // En Marche Avant (+1 vers Trémie) : seule Trémie est le point d'arrêt automatique
        M3_PositionSensorTarget := M3_AtTremieStable;
    ELSIF M3_ReqMaintenance_Active THEN
        // En Marche Arrière (-1 vers Maintenance) :
        // - Si Maintenance autorisée -> arrêt sur Maintenance
        // - Si Maintenance interdite -> arrêt sur P1
        IF PRG_03_Modes_Cycle.Data.Auth.MaintenanceM3TargetEnable THEN
            M3_PositionSensorTarget := M3_AtMaintenanceStable;
        ELSE
            M3_PositionSensorTarget := M3_AtP1Stable;
        END_IF;
    ELSE
        M3_PositionSensorTarget := FALSE;
    END_IF;
END_CASE;


{endregion}

{region "§1bis Securite M3"}
// === 🛡️ §1bis SÉCURITÉ M3 (FB_Safety_Translation, câblée en parallèle visible) ===
// ⚠️ Ordre d'appel volontaire : la safety lit ici le BrakeReleaseRequest et le
// BrakeCmd du SCAN PRÉCÉDENT d'instTranslationM3 (elle est appelée avant), soit un retard
// d'un scan. Bénin : BrakeReleaseRequest ne change pas plus vite qu'un scan MainTask 10 ms
// sur une commande frein.
instSafetyTranslationM3(
    Enable                  := (PRG_03_Modes_Cycle.Data.Auth.Mode <> E_Mode.DISABLE),
    Reset                   := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged   := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode                    := PRG_03_Modes_Cycle.Data.Auth.Mode,
    JoystickOnline          := PRG_02_Acquisition.Data.Network.Joystick.Online,
    JoystickOperational     := PRG_02_Acquisition.Data.Network.Joystick.Operational,
    HeartbeatIhmOk          := GVL_IHM.Commun.HeartbeatIhmOk,
    PhaseRotationOk         := PRG_02_Acquisition.HwIn.Machine.PhaseRotationOk_DI,
    BrakeThermalFeedback    := NOT PRG_02_Acquisition.HwIn.Machine.M1_M2_M3_BrakeThermalOk_DI,
    DriveOnline             := PRG_02_Acquisition.Data.Network.DriveM3.Online,
    DriveOperational        := PRG_02_Acquisition.Data.Network.DriveM3.Operational,
    DriveStatusWord         := PRG_02_Acquisition.Data.M3.StatusWord,
    DriveActualFreqHz       := UINT_TO_REAL(PRG_02_Acquisition.Data.M3.ActualFrequencyHz) / 100.0,
    BrakeFeedback           := SEL(GVL_IHM.TranslationM3.Bypass.ContactorFeedback OR GVL_IHM.TranslationM3.Bypass.Global, PRG_02_Acquisition.HwIn.Translation.M3_BrakeIsOpen_DI, instTranslationM3.BrakeReleaseRequest),
    BrakeCmd                := instTranslationM3.BrakeReleaseRequest,
    RunRequest              := M3_RunRequest_Active,
    ReqTremie               := M3_ReqTremie_Active,
    ReqMaintenance          := M3_ReqMaintenance_Active,
    LimitSwitchTremie       := M3_LimitSwitchTremieStable,
    LimitSwitchMaintenance  := M3_LimitSwitchMaintenanceStable,
    SensorWordIncoherent    := instPosDecoderM3.Incoherent,
    BypassGlobal            := GVL_IHM.TranslationM3.Bypass.Global,
    BypassOperatorComm      := GVL_IHM.TranslationM3.Bypass.OperatorComm,
    BypassDriveComm         := GVL_IHM.TranslationM3.Bypass.DriveComm,
    BypassPhaseRotation     := GVL_IHM.TranslationM3.Bypass.PhaseRotation,
    BypassBrakeThermal      := GVL_IHM.TranslationM3.Bypass.BrakeThermal,
    BypassMecaB             := GVL_IHM.TranslationM3.Bypass.MecaB,
    BypassMecaA             := GVL_IHM.TranslationM3.Bypass.MecaA,
    BypassLimitSwitch       := GVL_IHM.TranslationM3.Bypass.LimitSwitch,
    BypassSensorIncoherent  := GVL_IHM.TranslationM3.Bypass.SensorIncoherent,
    BypassSafety            := GVL_IHM.TranslationM3.Bypass.Safety,
    BypassProcess           := GVL_IHM.TranslationM3.Bypass.Process
);

// SafeStop réellement appliqué au mouvement = agrégat InputModuleFault OR safety M3
// (8 mécanismes) — aucune des deux causes ne doit être perdue.
// + Verrou translation pendant le cycle de homing machine (HX2..HX6) : le chariot M3
//   ne doit pas bouger tant que M1/M2 se référencent (produit par FB_CycleMachineHoming,
//   publié PRG_02.Data.MachineHoming.M3Locked). Pas de bypass : conscient = quitter le cycle.
M3_SafeStop_Aggregate := M3_SafeStop_Active
                         OR instSafetyTranslationM3.SafeStop
                         OR PRG_02_Acquisition.Data.MachineHoming.M3Locked;

{endregion}

{region "§1ter Permis effectifs M3 (D1)"}
// === 🟢 §1ter PERMIS EFFECTIFS M3 (D1 — Phase 3) ===
// Niveau exposé à l'IHM = EFFECTIF, aligné sur les treuils M1/M2 (PRG_04 §5).
// ⚠️ Le permit est une INFORMATION DE POSSIBILITÉ de mouvement dans une direction,
// donnée AVANT l'ordre. Il reflète que l'axe est PRÊT À FONCTIONNER (pas de défaut,
// puissance, thermique) ET que la direction est physiquement possible (fins de course,
// autorisation cible). Il ne reflète PAS la commande (homme-mort) : l'homme-mort est une
// condition de COMMANDE (arbitrage FB_TranslationCmdArbitrationM3 / FB_CycleSemiAuto), pas de
// possibilité — il n'entre donc PAS dans le permit exposé.
// Pour M3, le Safety (FB_Safety_Translation) fournit les faits de sécurité :
//   - TremieLimitClear = NOT LimitSwitchTremie (direction possible vers Trémie)
//   - MaintenanceLimitClear = NOT LimitSwitchMaintenance (direction possible jusqu'à P1)
//   - SafeStop / PowerCutOff = défauts (thermique, Méca A/B, incohérence, comm, phases...)
// Le permis effectif = fait de limite libre AND NOT SafeStop AND NOT PowerCutOff
// (prêt à fonctionner), aligné sur le modèle treuils où le Safety produit déjà des
// permis gatés par les défauts. Pas de Process supplémentaire (pas de benne/Kobold).
// ⚠️ Le verrou « descente treuil interdite tant que M3 pas à P1 » (DumpAtTremieDescentLocked)
// est côté TREUIL (PRG_04 §5, lignes 802-805), pas dans le permit M3 : le permit M3 reste une
// information de possibilité de mouvement de la translation, indépendante de l'état de la trémie.
// ⚠️ Le permit M3 est un permit EFFECTIF « pouvoir bouger » (prêt à fonctionner), PAS un pur
// directionnel. Quand l'axe est en défaut (SafeStop/PowerCutOff), TOUS les sens sont bloqués ;
// au retour en condition, un sens peut être permis et pas l'autre. L'interdiction d'accès à la
// zone Maintenance ne retire PAS le permis de rejoindre P1 : elle agit sur la cible et la
// coupure dure M3_LimitSwitchMaintenanceEffective.
EffectivePermitM3_Tremie    := instSafetyTranslationM3.TremieLimitClear
                               AND NOT M3_SafeStop_Aggregate
                               AND NOT instSafetyTranslationM3.PowerCutOff;
EffectivePermitM3_Maintenance := instSafetyTranslationM3.MaintenanceLimitClear
                                  AND NOT M3_SafeStop_Aggregate
                                  AND NOT instSafetyTranslationM3.PowerCutOff;

{endregion}

{region "§2 Pilotage translation M3"}
// === ⚙️ §2 EXÉCUTION PILOTAGE TRANSLATION M3 ===

// 🔧 Assemblage de la config FB_Translation (C3) — SOURCE UNIQUE : GVL_PERSISTENT.
// Fini le double sourcing (rampes flat + vitesses d'approche via GVL_IHM.TranslationM3.Cfg).
// Les 3 vitesses d'approche sont lues dans _TranslationCfgPersist (miroir persistant de
// ST_TranslationCfg, synchronisé par FB_CfgPersistBridge_TranslationCfg dans PRG_07) — la
// valeur reflète toute modification IHM persistée. Les délais (DirectionInterlockDelay,
// CaptorDebounce, BrakeDelay*, BrakeFeedbackTimeout) restent aux valeurs défaut du struct
// (non réglés IHM) — même comportement qu'avant (non câblés, défauts FB).
TranslationCfg.CfgRampAccelRate           := _TranslationRampAccelRate_Pct;
TranslationCfg.CfgRampDecelNormalRate     := _TranslationRampDecelNormal_Pct;
TranslationCfg.CfgRampDecelFastRate       := _TranslationRampDecelFast_Pct;
TranslationCfg.DriveFreqScaleMaxHz        := _TranslationMaxFreq_Hz;
TranslationCfg.ApproachSpeedTremieHz      := _TranslationCfgPersist.CfgApproachSpeedTremie_Hz;
TranslationCfg.ApproachSpeedMaintenanceHz := _TranslationCfgPersist.CfgApproachSpeedMaintenance_Hz;
TranslationCfg.ApproachSpeedP1Hz          := _TranslationCfgPersist.CfgApproachSpeedP1_Hz;

instTranslationM3(
    Enable                  := (PRG_03_Modes_Cycle.Data.Auth.Mode <> E_Mode.DISABLE),
    Reset                   := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged   := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    Mode                    := PRG_03_Modes_Cycle.Data.Auth.Mode,
    RunRequest              := M3_RunRequest_Active,
    SafeStop                := M3_SafeStop_Aggregate,
    ReqTremie               := M3_ReqTremie_Active,
    ReqMaintenance          := M3_ReqMaintenance_Active,
    InvertDriveDirection    := GVL_IHM.TranslationM3.Cmd.InvertDirection,
    SpeedTgt_Pct            := M3_SpeedCmd_Active,
    PositionSensorTarget    := M3_PositionSensorTarget,
    SlowdownSensorTremie       := instPosDecoderM3.TranslationPosPV,
    // Les 5 capteurs forment un code thermomètre cumulatif depuis la Trémie (voir
    // FB_Translation_PositionDecoder.st). Chaque zone est délimitée par "capteur PRÉCÉDENT retombé
    // à 0" ET "capteur de la zone encore à 1" — zone P2→P1 = NOT PosP2 AND PosP1 (mot 00011) ;
    // zone P1→Maintenance = NOT PosP1 AND PosMaintenance (mot 00001). Zones mutuellement exclusives,
    // chacune sa propre vitesse d'approche (CfgApproachSpeedP1_Hz / CfgApproachSpeedMaintenance_Hz).
    SlowdownSensorMaintenance  := (NOT instPosDecoderM3.TranslationPosP1) AND instPosDecoderM3.TranslationPosMaintenance,
    // Ralentissement P2→P1 UNIQUEMENT si P1 est un vrai point
    // d'arrêt (zone Maintenance NON autorisée). Zone Maintenance autorisée -> 100% vitesse jusqu'à
    // P1, ralentissement seulement après (zone P1→Maintenance, SlowdownSensorMaintenance ci-dessus).
    SlowdownSensorP1           := (NOT instPosDecoderM3.TranslationPosP2) AND instPosDecoderM3.TranslationPosP1
                                   AND NOT PRG_03_Modes_Cycle.Data.Auth.MaintenanceM3TargetEnable,
    LimitSwitchTremie       := M3_LimitSwitchTremieStable,
    LimitSwitchMaintenance  := M3_LimitSwitchMaintenanceStable,
    // 🛡️ Permis directionnels SAFETY (source unique instSafetyTranslationM3) — gate de sens FB_Translation
    EffectivePermitM3_Tremie := EffectivePermitM3_Tremie,
    EffectivePermitM3_Maintenance := EffectivePermitM3_Maintenance,
    DriveStatusWord         := PRG_02_Acquisition.Data.M3.StatusWord,
    DriveActualFreqHz       := UINT_TO_REAL(PRG_02_Acquisition.Data.M3.ActualFrequencyHz) / 100.0,
    Cfg                     := TranslationCfg,
    BrakeFeedback           := SEL(GVL_IHM.TranslationM3.Bypass.ContactorFeedback OR GVL_IHM.TranslationM3.Bypass.Global, PRG_02_Acquisition.HwIn.Translation.M3_BrakeIsOpen_DI, instTranslationM3.BrakeReleaseRequest),
    BypassContactorCheck    := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.ContactorFeedback,
    BypassLimitSwitch       := GVL_IHM.TranslationM3.Bypass.Global OR GVL_IHM.TranslationM3.Bypass.LimitSwitch
);

// 📐 Estimateur de position continue M3 (odométrie + recalage 5 capteurs)
instPosEstimatorM3(
    Enable               := (PRG_03_Modes_Cycle.Data.Auth.Mode <> E_Mode.DISABLE),
    Reset                := PRG_07_Supervision.FaultMachineReset_IHM,
    DriveActualFreqHz    := TO_REAL(PRG_02_Acquisition.Data.M3.ActualFrequencyHz) / 100.0,
    ReqTremie            := M3_ReqTremie_Active,
    ReqMaintenance       := M3_ReqMaintenance_Active,
    SensorMaintenance    := instPosDecoderM3.TranslationPosMaintenance,
    SensorP1             := instPosDecoderM3.TranslationPosP1,
    SensorP2             := instPosDecoderM3.TranslationPosP2,
    SensorPV             := instPosDecoderM3.TranslationPosPV,
    SensorTremie         := instPosDecoderM3.TranslationPosTremie,
    PosMaintenanceM      := GVL_PERSISTENT._TranslationPosMaintenance_M,
    PosP1M               := GVL_PERSISTENT._TranslationPosP1_M,
    PosP2M               := GVL_PERSISTENT._TranslationPosP2_M,
    PosPVM               := GVL_PERSISTENT._TranslationPosPV_M,
    PosTremieM           := GVL_PERSISTENT._TranslationPosTremie_M,
    GainMetersPerHzSec   := GVL_PERSISTENT._TranslationGainMetersPerHzSec,
    PersistedPositionM   := GVL_PERSISTENT._TranslationPosEstimated_M,
    PersistedInitialized := GVL_PERSISTENT._TranslationPosEstimatedInitialized
);
// Recopie continue (reprise après reboot, doctrine _TranslationSetFreq_Hz) — pas de bridge dédié.
GVL_PERSISTENT._TranslationPosEstimated_M := instPosEstimatorM3.PositionEstimatedM;
GVL_PERSISTENT._TranslationPosEstimatedInitialized := instPosEstimatorM3.Initialized;


{endregion}

{region "§3 Publication demande translation"}
// === 📤 §3 PUBLICATION DEMANDE BRUTE TRANSLATION ===

TranslationFinalInterlockRequest.Enable := (PRG_03_Modes_Cycle.Data.Auth.Mode <> E_Mode.DISABLE);
TranslationFinalInterlockRequest.Reset := PRG_07_Supervision.FaultMachineReset_IHM;
TranslationFinalInterlockRequest.PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI;
TranslationFinalInterlockRequest.SafeStop := M3_SafeStop_Aggregate;
TranslationFinalInterlockRequest.PowerCutOff := instSafetyTranslationM3.PowerCutOff;
TranslationFinalInterlockRequest.EffectivePermitM3_Tremie := EffectivePermitM3_Tremie;
TranslationFinalInterlockRequest.EffectivePermitM3_Maintenance := EffectivePermitM3_Maintenance;
TranslationFinalInterlockRequest.BrakeReleaseRequest := instTranslationM3.BrakeReleaseRequest;
TranslationFinalInterlockRequest.BrakeCommandOpenConfirmed := instTranslationM3.BrakeCommandOpenConfirmed;
TranslationFinalInterlockRequest.RequestedDriveControlWord := instTranslationM3.RequestedDriveControlWord;
TranslationFinalInterlockRequest.RequestedDriveFreqHz := instTranslationM3.RequestedDriveFreqHz;

{endregion}

{region "§4 Publication etat IHM"}
// === 📤 PUBLICATION ÉTAT TRANSLATION IHM (lecture seule) ===
IF instTranslationM3.Fault.Error THEN
    TranslationState.FBState := E_State.ERROR;
ELSIF ABS(instTranslationM3.RequestedDriveFreqHz) > 0.1 THEN
    TranslationState.FBState := E_State.BUSY;
ELSE
    TranslationState.FBState := E_State.READY;
END_IF;
TranslationState.Ready := instTranslationM3.Ready;
TranslationState.Busy := (ABS(instTranslationM3.RequestedDriveFreqHz) > 0.1);
TranslationState.Done := instTranslationM3.TargetReached;
TranslationState.Error := instTranslationM3.Fault.Error;
TranslationState.ErrorId := instTranslationM3.Fault.ErrorId;
TranslationState.BrakeCmd := instTranslationM3.BrakeReleaseRequest;
TranslationState.BrakeCommandOpenConfirmed := instTranslationM3.BrakeCommandOpenConfirmed;
// 🔌 Retour physique direct frein M3 (même source que le SEL §1bis/§2) — consommé FB_TroubleshootingView Idx108
TranslationState.BrakeFeedback := PRG_02_Acquisition.HwIn.Translation.M3_BrakeIsOpen_DI;
TranslationState.PositionReached := instTranslationM3.TargetReached;
TranslationState.DriveControlWord := instTranslationM3.RequestedDriveControlWord;
TranslationState.DriveFreqCmd_Hz := instTranslationM3.RequestedDriveFreqHz;
// 🎯 Cohérence sim : les bits actifs/SpeedCmd_Pct n'affichent la
// consigne QUE si la commande variateur est réellement émise (RequestedDriveControlWord <> 0).
// Sinon, un interlock bloquant (hauteur, SafeStop…) laisserait l'IHM suggérer un mouvement
// qui n'a pas lieu ("je bouge mais ça bouge pas"). Affiche 0 quand c'est bloqué.
TranslationState.ActiveTremie := instTranslationM3.RequestedDriveControlWord = 1;
TranslationState.ActiveMaintenance := instTranslationM3.RequestedDriveControlWord = 2;
TranslationState.SpeedCmd_Pct := SEL(instTranslationM3.RequestedDriveControlWord <> 0, M3_SpeedCmd_Active, 0.0);
TranslationState.PositionTremie := instPosDecoderM3.TranslationPosTremie;
TranslationState.PositionPV := instPosDecoderM3.TranslationPosPV;
TranslationState.PositionP2 := instPosDecoderM3.TranslationPosP2;
TranslationState.PositionP1 := instPosDecoderM3.TranslationPosP1;
TranslationState.PositionMaintenance := instPosDecoderM3.TranslationPosMaintenance;
// Affichage IHM = M3_AtXxxStable (§0quater) — armé sur front
// (direction-dépendant), libéré sur mouvement réel confirmé ≥1.5s (pas juste un rebond capteur
// ni un changement de sens instantané). Même signal que celui consommé par M3_PositionSensorTarget.
TranslationState.AtTremie := M3_AtTremieStable;
TranslationState.AtPV := M3_AtPVStable;
TranslationState.AtP2 := M3_AtP2Stable;
TranslationState.AtP1 := M3_AtP1Stable;
TranslationState.AtMaintenance := M3_AtMaintenanceStable;
TranslationState.EstimatedPosM3_M := instPosEstimatorM3.PositionEstimatedM;
TranslationState.SensorsWord := instPosDecoderM3.SensorsWord;
TranslationState.SensorWordIncoherent := instPosDecoderM3.Incoherent;
TranslationState.LimitSwitchTremie := M3_LimitSwitchTremieStable;
TranslationState.LimitSwitchMaintenance := M3_LimitSwitchMaintenanceStable;
TranslationState.DriveActualFreq_Hz := TO_REAL(PRG_02_Acquisition.Data.M3.ActualFrequencyHz) / 100.0;
TranslationState.DriveThermalOk := PRG_02_Acquisition.HwIn.Translation.M3_ThermalOK_DI;
// 🛡️ Pas de sortie State sur FB_TranslationOutputInterlock : le "vrai état" de la
// barrière finale M3 est dérivé de son défaut (READY normal / ERROR sur défaut barrière).
IF PRG_06_Outputs.instTranslationOutputInterlockM3.Fault.Error THEN
    TranslationState.FinalInterlockState := E_State.ERROR;
ELSE
    TranslationState.FinalInterlockState := E_State.READY;
END_IF;
TranslationState.FinalInterlockReason := PRG_06_Outputs.instTranslationOutputInterlockM3.Reason;
TranslationState.FinalInterlockError := PRG_06_Outputs.instTranslationOutputInterlockM3.Fault.Error;
TranslationState.FinalInterlockErrorId := PRG_06_Outputs.instTranslationOutputInterlockM3.Fault.ErrorId;
TranslationState.FinalBrakeTimeoutElapsed := PRG_06_Outputs.instTranslationOutputInterlockM3.BrakeTimeoutElapsed;
TranslationState.DriveCommReady := (PRG_02_Acquisition.Data.M3.StatusWord AND 16#0080) <> 0;
TranslationState.DrivePowerReady := (PRG_02_Acquisition.Data.M3.StatusWord AND 16#0001) <> 0;
TranslationState.MaintenanceTargetEnable := PRG_03_Modes_Cycle.Data.Auth.MaintenanceM3TargetEnable;
TranslationState.SimulationModeActive := GVL_Simulation.SimulationModeActive;

// 🛡️ Producteur unique (CODE_QUALITY_STANDARDS §5) : la safety M3 (instSafetyTranslationM3)
// est la source de tous les diagnostics de sécurité (ErrorLimitSwitch/ErrorSensorIncoherent).
// Les erreurs propres au mouvement (frein, variateur AC600) restent sur TranslationState.ErrorId
// ci-dessus, bitfield différent, jamais mélangé.
TranslationSafety.SafeStop := M3_SafeStop_Aggregate;
TranslationSafety.PowerCutOff := instSafetyTranslationM3.PowerCutOff;
TranslationSafety.Error := instSafetyTranslationM3.Fault.Error;
TranslationSafety.ErrorId := instSafetyTranslationM3.Fault.ErrorId;
TranslationSafety.LatchedId := instSafetyTranslationM3.Fault.LatchedId;
TranslationSafety.ErrorOperatorComm := instSafetyTranslationM3.ErrorOperatorComm;
TranslationSafety.ErrorDriveComm := instSafetyTranslationM3.ErrorDriveComm;
TranslationSafety.ErrorPhaseRotation := instSafetyTranslationM3.ErrorPhaseRotation;
TranslationSafety.ErrorBrakeThermal := instSafetyTranslationM3.ErrorBrakeThermal;
TranslationSafety.ErrorMecaB := instSafetyTranslationM3.ErrorMecaB;
TranslationSafety.ErrorMecaA := instSafetyTranslationM3.ErrorMecaA;
TranslationSafety.ErrorLimitSwitch := instSafetyTranslationM3.ErrorLimitSwitch;
TranslationSafety.ErrorSensorIncoherent := instSafetyTranslationM3.ErrorSensorIncoherent;
// 🟢 Permis directionnels M3 EFFECTIFS (D1 — Safety AND Process, §1ter) — projetés vers l'IHM
// (source safety : FB_Safety_Translation ; fusion Process en local, modèle treuils PRG_04 §5)
TranslationSafety.EffectivePermitM3_Tremie := EffectivePermitM3_Tremie;
TranslationSafety.EffectivePermitM3_Maintenance := EffectivePermitM3_Maintenance;
TranslationSafety.PowerCutOffSafety := PRG_06_Outputs.M3PowerCutOffSafetyInfo;
TranslationSafety.SafeStopSafety := PRG_06_Outputs.M3SafeStopSafetyInfo;
TranslationSafety.BlockedBySafety := PRG_06_Outputs.M3BlockedBySafetyInfo;

{region "§4bis Trace de blocage terrain M3 (ST_TraceTranslation)"}
// === ↔️ §4bis TRACE DE BLOCAGE TERRAIN M3 (cause priorisée + horodatage) ===
// Diagnostic lecture seule, publié via Data.TranslationTrace et consommé par FB_TroubleshootingView.
// L'ordre IF/ELSIF EST l'ordre de priorité (cf. E_TranslationTraceBlockReason) : la cause la plus
// grave gagne. BlockReasonTimestamp est latched au premier scan du changement (1 scan, mémoire).
// Aucune action de conduite ne dépend de ces champs.
TranslationTrace.SafeStopActive           := M3_SafeStop_Aggregate;
TranslationTrace.SafeStopSourceInput      := M3_SafeStop_Active;
TranslationTrace.SafeStopSourceSafety     := instSafetyTranslationM3.SafeStop;
TranslationTrace.PowerCutOffActive        := instSafetyTranslationM3.PowerCutOff;
TranslationTrace.HeightInterlockBlocking  := NOT M3_HeightInterlockOk;
TranslationTrace.DriveOperational         := PRG_02_Acquisition.Data.Network.DriveM3.Operational;
TranslationTrace.FinalInterlockError      := TranslationState.FinalInterlockError;
// 🟢 Permis directionnels par sens EFFECTIFS (D1 — Safety AND Process, §1ter) — reflet exact des permis appliqués
TranslationTrace.EffectivePermitM3_Tremie      := EffectivePermitM3_Tremie;
TranslationTrace.EffectivePermitM3_Maintenance := EffectivePermitM3_Maintenance;

// Permis de mouvement effectif = toutes les barrières levées (agrégat diagnostic)
TranslationTrace.MotionPermitEffective := NOT M3_SafeStop_Aggregate
    AND NOT instSafetyTranslationM3.PowerCutOff
    AND M3_HeightInterlockOk
    AND PRG_02_Acquisition.Data.Network.DriveM3.Operational
    AND NOT TranslationState.FinalInterlockError
    AND NOT instTranslationM3.Fault.Error;

IF instSafetyTranslationM3.PowerCutOff THEN
    TranslationTrace.BlockReason := E_TranslationTraceBlockReason.POWER_CUTOFF;
ELSIF M3_SafeStop_Aggregate THEN
    TranslationTrace.BlockReason := E_TranslationTraceBlockReason.SAFESTOP;
ELSIF instSafetyTranslationM3.Fault.Error THEN
    TranslationTrace.BlockReason := E_TranslationTraceBlockReason.SAFETY_FAULT;
ELSIF NOT M3_HeightInterlockOk THEN
    TranslationTrace.BlockReason := E_TranslationTraceBlockReason.HEIGHT_INTERLOCK;
ELSIF NOT PRG_02_Acquisition.Data.Network.DriveM3.Operational THEN
    TranslationTrace.BlockReason := E_TranslationTraceBlockReason.DRIVE_UNAVAILABLE;
ELSIF TranslationState.FinalInterlockError THEN
    TranslationTrace.BlockReason := E_TranslationTraceBlockReason.FINAL_INTERLOCK;
ELSIF instTranslationM3.Fault.Error THEN
    TranslationTrace.BlockReason := E_TranslationTraceBlockReason.FAULT;
ELSE
    TranslationTrace.BlockReason := E_TranslationTraceBlockReason.NONE;
END_IF;
IF TranslationTrace.BlockReason <> TraceTranslation_PrevReason THEN
    TranslationTrace.BlockReasonTimestamp := TIME_TO_UDINT(TIME());
END_IF;
TraceTranslation_PrevReason := TranslationTrace.BlockReason;
{endregion}

// 🧩 Cause de blocage priorisée sur l'état public IHM (miroir de la trace terrain §4bis)
TranslationState.AxisBlockReason := TranslationTrace.BlockReason;

// === 🔌 PUBLICATION BUS INTER-PRG (Data : ST_TranslationInterPrg) ===
// Copie des structs internes vers le bus de sortie (producteur unique).
Data.TranslationFinalInterlockRequest := TranslationFinalInterlockRequest;
Data.TranslationState                 := TranslationState;
Data.TranslationSafety                := TranslationSafety;
Data.TranslationBusy                  := (ABS(instTranslationM3.RequestedDriveFreqHz) > 0.1);
Data.TranslationDone                  := instTranslationM3.TargetReached;
Data.M3_AtTremieStable                := M3_AtTremieStable;
Data.M3_AtP1Stable                    := M3_AtP1Stable;
Data.M3_AtMaintenanceStable           := M3_AtMaintenanceStable;
// 🕵️ Trace de blocage terrain (consommée FB_TroubleshootingView)
Data.TranslationTrace                 := TranslationTrace;

{endregion}

// ═══════════════════════════════════════════════════════════════
// 🛗 §1 TREUIL M1 (Retenue) — conditions + interlock + sorties
// ═══════════════════════════════════════════════════════════════
// 👁️ D'un coup d'œil : ce qui active/désactive la sortie M1.
//   - M1InterlockEnable      : gate finale (Enable ET pas de PowerCutOff)
//   - M1PowerCutOffSafetyInfo: défauts qui COUPENT la puissance
//   - M1SafeStopSafetyInfo   : défauts qui font SafeStop (rampe rapide)
//   - AscentPermit/DescendPermit : permis directionnels reconsommes par la barriere finale
//   - M1BlockedBySafetyInfo  : synthese (PowerCutOff OU SafeStop)
// Sources : PRG_04 (WinchM1FinalInterlockRequest / WinchM1Safety).

M1InterlockEnable := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.Enable
                      AND NOT PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.PowerCutOff;

M1PowerCutOffSafetyInfo := PRG_04_Treuils_Benne.Data.WinchM1Safety.PowerCutOff
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaA
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaB
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaC
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaD
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaE
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ThermalFault;

M1SafeStopSafetyInfo := PRG_04_Treuils_Benne.Data.WinchM1Safety.SafeStop
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.Error
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorOperatorComm
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorEncoder
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorPhaseRotation
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorOppositeDir
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorNoMovement;

M1BlockedBySafetyInfo := M1PowerCutOffSafetyInfo OR M1SafeStopSafetyInfo;

instWinchOutputInterlockM1(
    Enable                     := M1InterlockEnable,
    Reset                      := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged      := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.PowerContactorEngaged,
    SafeStop                   := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.SafeStop,
    AscentPermit               := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.AscentPermit,
    DescendPermit              := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.DescendPermit,
    BrakeFeedback              := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.BrakeFeedback,
    FwdRevSpeedFeedbackOff     := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.FwdRevSpeedFeedbackOff,
    RequestedRelayFwd          := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedRelayFwd,
    RequestedRelayRev          := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedRelayRev,
    RequestedContactor1        := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedContactor1,
    RequestedContactor2        := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedContactor2,
    RequestedContactor3        := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedContactor3,
    RequestedContactor4        := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedContactor4,
    RequestedStep               := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedStep
);

M1RelayFwd        := instWinchOutputInterlockM1.RelayFwd;
M1RelayRev        := instWinchOutputInterlockM1.RelayRev;
M1SpeedContactor1 := instWinchOutputInterlockM1.Contactor1;
M1SpeedContactor2 := instWinchOutputInterlockM1.Contactor2;
M1SpeedContactor3 := instWinchOutputInterlockM1.Contactor3;
M1SpeedContactor4 := instWinchOutputInterlockM1.Contactor4;
// Pre-calcul frein M1 (regate en §2ter apres controle concordance M1/M2).
M1BrakeCmd        := M1RelayFwd OR M1RelayRev;
// Sorties physiques M1 + bus inter-PRG : ecrites en §2ter, apres le controle
// de concordance des vecteurs M1/M2 (une seule ecriture des DQ treuils).

// ═══════════════════════════════════════════════════════════════
// 🛗 §2 TREUIL M2 (Benne) — conditions + interlock + sorties
// ═══════════════════════════════════════════════════════════════
// 👁️ Même lecture que M1 : gate finale, défauts PowerCutOff / SafeStop, synthèse.
// Sources : PRG_04 (WinchM2FinalInterlockRequest / WinchM2Safety / BucketState).

M2InterlockEnable := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.Enable
                      AND NOT PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.PowerCutOff;

M2PowerCutOffSafetyInfo := PRG_04_Treuils_Benne.Data.WinchM2Safety.PowerCutOff
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaA
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaB
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaC
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaD
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaE
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ThermalFault;

M2SafeStopSafetyInfo := PRG_04_Treuils_Benne.Data.WinchM2Safety.SafeStop
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.Error
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorOperatorComm
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorEncoder
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorPhaseRotation
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorOppositeDir
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorNoMovement
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.SlackCable
                     OR PRG_04_Treuils_Benne.Data.BucketState.Error
                     OR PRG_04_Treuils_Benne.Data.BucketState.CoupledMotionBlockedByBucket;

M2BlockedBySafetyInfo := M2PowerCutOffSafetyInfo OR M2SafeStopSafetyInfo;

instWinchOutputInterlockM2(
    Enable                     := M2InterlockEnable,
    Reset                      := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged      := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.PowerContactorEngaged,
    SafeStop                   := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.SafeStop,
    AscentPermit               := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.AscentPermit,
    DescendPermit              := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.DescendPermit,
    BrakeFeedback              := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.BrakeFeedback,
    FwdRevSpeedFeedbackOff     := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.FwdRevSpeedFeedbackOff,
    RequestedRelayFwd          := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedRelayFwd,
    RequestedRelayRev          := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedRelayRev,
    RequestedContactor1        := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedContactor1,
    RequestedContactor2        := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedContactor2,
    RequestedContactor3        := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedContactor3,
    RequestedContactor4        := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedContactor4,
    RequestedStep               := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedStep
);

M2RelayFwd        := instWinchOutputInterlockM2.RelayFwd;
M2RelayRev        := instWinchOutputInterlockM2.RelayRev;
M2SpeedContactor1 := instWinchOutputInterlockM2.Contactor1;
M2SpeedContactor2 := instWinchOutputInterlockM2.Contactor2;
M2SpeedContactor3 := instWinchOutputInterlockM2.Contactor3;
M2SpeedContactor4 := instWinchOutputInterlockM2.Contactor4;
// Pre-calcul frein M2 (regate en §2ter apres controle concordance M1/M2).
M2BrakeCmd        := M2RelayFwd OR M2RelayRev;

// ═══════════════════════════════════════════════════════════════
// 🔒 §2ter CONCORDANCE SORTIES TREUILS M1/M2
// ═══════════════════════════════════════════════════════════════
// Les 2 barrieres finales (instWinchOutputInterlockM1/M2) resolvent chacune leur
// commande via des tempos INDEPENDANTES : rien ne garantit des vecteurs identiques
// le meme scan. En couple, un contacteur asymetrique = les 2 treuils tirent le
// cable de facon desynchronisee.
// 🛡️ L'ex-zeroage binaire INSTANTANE est remplace par instSyncContactorFinal :
//    reponse graduee, debounce 500 ms (tolere les transitoires de changement de
//    palier), et remontee decodee. La coupure effective (SafeStop niveau 1,
//    PowerCutOff niveau 2 via MecaE bit13) est appliquee par la chaine safety
//    (PRG_04) au scan suivant. Bypass = GVL_IHM.M1M2Sync.Bypass.Global.
// Concordance contacteurs M1/M2 : jamais armee pendant un homing machine (M2-M1 varie
// volontairement de ~15 m -> faux ContactorMismatch -> escalade MecaE bit13 / PowerCutOff).
WinchOutputCoupled := (PRG_04_Treuils_Benne.Data.SyncState.SyncActive
                       OR PRG_03_Modes_Cycle.Data.WinchBothIntent.Active)
                      AND NOT PRG_02_Acquisition.Data.MachineHoming.Active;

// Frein = OR des relais de sens GATES (jamais desserre sans un sens valide).
M1BrakeCmd := M1RelayFwd OR M1RelayRev;
M2BrakeCmd := M2RelayFwd OR M2RelayRev;

{region "🛡️ §2quater Garde anti-chatter dure sorties contacteurs M1/M2"}
// ═══════════════════════════════════════════════════════════════
// 🛡️ §2quater GARDE ANTI-CHATTER DURE — au plus près des sorties contacteurs
// ═══════════════════════════════════════════════════════════════
// Dernier rempart avant l'écriture hardware : contacteurs de SENS et de PALIER passent
// par un FB_ContactorProtector. À la retombée d'une commande, aucune ré-activation avant
// CST_ContactorMinInterval (400 ms). Les interlocks amont séquencent déjà à >= 500 ms
// -> transparent en exploitation ; n'agit qu'en cas de re-commande anormalement rapide
// (bug logique, bypass, glitch concordance §2ter).
// Enable=TRUE fixe : sécurité positive assurée par le FB (Cmd=FALSE si non autorisé).
//
// ⚠️ PAS sur le FREIN : il doit pouvoir re-desserrer IMMÉDIATEMENT quand un mouvement est
//    (re)commandé. Un plancher retarderait le desserrage -> couple moteur contre frein serré
//    = contrainte méca + usure (frein serré alors que le treuil est commandé). Le frein suit déjà les relais de sens
//    filtrés (M1BrakeCmd := M1RelayFwd OR M1RelayRev), eux planchés à 1 s par le DeadTime
//    interlock -> il ne peut pas mitrailler plus vite que les relais.
instM1FwdProtector(Enable := TRUE, Request := M1RelayFwd, Cfg_MinInterval := CST_ContactorMinInterval);
instM1RevProtector(Enable := TRUE, Request := M1RelayRev, Cfg_MinInterval := CST_ContactorMinInterval);
instM1Sc1Protector(Enable := TRUE, Request := M1SpeedContactor1, Cfg_MinInterval := CST_ContactorMinInterval);
instM1Sc2Protector(Enable := TRUE, Request := M1SpeedContactor2, Cfg_MinInterval := CST_ContactorMinInterval);
instM1Sc3Protector(Enable := TRUE, Request := M1SpeedContactor3, Cfg_MinInterval := CST_ContactorMinInterval);
instM1Sc4Protector(Enable := TRUE, Request := M1SpeedContactor4, Cfg_MinInterval := CST_ContactorMinInterval);
M1RelayFwd        := instM1FwdProtector.Cmd;
M1RelayRev        := instM1RevProtector.Cmd;
M1SpeedContactor1 := instM1Sc1Protector.Cmd;
M1SpeedContactor2 := instM1Sc2Protector.Cmd;
M1SpeedContactor3 := instM1Sc3Protector.Cmd;
M1SpeedContactor4 := instM1Sc4Protector.Cmd;

instM2FwdProtector(Enable := TRUE, Request := M2RelayFwd, Cfg_MinInterval := CST_ContactorMinInterval);
instM2RevProtector(Enable := TRUE, Request := M2RelayRev, Cfg_MinInterval := CST_ContactorMinInterval);
instM2Sc1Protector(Enable := TRUE, Request := M2SpeedContactor1, Cfg_MinInterval := CST_ContactorMinInterval);
instM2Sc2Protector(Enable := TRUE, Request := M2SpeedContactor2, Cfg_MinInterval := CST_ContactorMinInterval);
instM2Sc3Protector(Enable := TRUE, Request := M2SpeedContactor3, Cfg_MinInterval := CST_ContactorMinInterval);
instM2Sc4Protector(Enable := TRUE, Request := M2SpeedContactor4, Cfg_MinInterval := CST_ContactorMinInterval);
M2RelayFwd        := instM2FwdProtector.Cmd;
M2RelayRev        := instM2RevProtector.Cmd;
M2SpeedContactor1 := instM2Sc1Protector.Cmd;
M2SpeedContactor2 := instM2Sc2Protector.Cmd;
M2SpeedContactor3 := instM2Sc3Protector.Cmd;
M2SpeedContactor4 := instM2Sc4Protector.Cmd;

// Frein recalculé APRÈS filtrage des relais de sens (pas de protecteur propre, cf. supra).
M1BrakeCmd := M1RelayFwd OR M1RelayRev;
M2BrakeCmd := M2RelayFwd OR M2RelayRev;
{endregion}

{region "🔀 §2quinquies Concordance contacteurs M1/M2"}
// Compare les vecteurs PHYSIQUES finaux M1/M2 (post §2quater). Reponse graduee via
// FB_SyncContactor : niveau 1 (debounce 500 ms) -> Data.ContactorMismatch -> SafeStop
// des 2 treuils (PRG_04, scan N+1) ; niveau 2 (persistance CST_SyncEscalationTime) ->
// Data.ContactorMismatchEscalated -> latch MecaE escalade -> PowerCutOff.
// Bypass : groupe synchro treuils OU l'un des 2 bypass groupe treuil (l'operateur
// qui bypasse un treuil en MES neutralise aussi la concordance).
instSyncContactorFinal(
    Enable        := TRUE,
    Reset         := PRG_07_Supervision.FaultMachineReset_IHM,
    SyncEnable    := WinchOutputCoupled,
    RelayFwdM1    := M1RelayFwd,        RelayFwdM2    := M2RelayFwd,
    RelayRevM1    := M1RelayRev,        RelayRevM2    := M2RelayRev,
    Contactor1_M1 := M1SpeedContactor1, Contactor1_M2 := M2SpeedContactor1,
    Contactor2_M1 := M1SpeedContactor2, Contactor2_M2 := M2SpeedContactor2,
    Contactor3_M1 := M1SpeedContactor3, Contactor3_M2 := M2SpeedContactor3,
    Contactor4_M1 := M1SpeedContactor4, Contactor4_M2 := M2SpeedContactor4,
    BypassGlobal  := GVL_IHM.M1M2Sync.Bypass.Global
                     OR GVL_IHM.M1TreuilRetenue.Bypass.Global
                     OR GVL_IHM.M2TreuilBenne.Bypass.Global
);
Data.ContactorMismatch          := instSyncContactorFinal.ContactorMismatch;
Data.ContactorMismatchEscalated := instSyncContactorFinal.ContactorMismatchEscalated;
Data.SyncContactorDiag          := instSyncContactorFinal.Diag;
{endregion}

// ── Sorties physiques M1 (apres controle concordance §2ter) ──
M1_RelayAscent_DQ            := M1RelayFwd;
M1_RelayDescent_DQ           := M1RelayRev;
M1_SpeedContactor_1_DQ       := M1SpeedContactor1;
M1_SpeedContactor_2_DQ       := M1SpeedContactor2;
M1_SpeedContactor_3_DQ       := M1SpeedContactor3;
M1_SpeedContactor_4_DQ       := M1SpeedContactor4;
M1_BrakeRelease_RQ           := M1BrakeCmd;

// ── Sorties physiques M2 (apres controle concordance §2ter) ──
M2_RelayAscent_Close_DQ      := M2RelayFwd;
M2_RelayDescent_Open_DQ      := M2RelayRev;
M2_SpeedContactor_1_DQ       := M2SpeedContactor1;
M2_SpeedContactor_2_DQ       := M2SpeedContactor2;
M2_SpeedContactor_3_DQ       := M2SpeedContactor3;
M2_SpeedContactor_4_DQ       := M2SpeedContactor4;
M2_BrakeRelease_RQ           := M2BrakeCmd;

// ── Bus inter-PRG M1 (image reelle des sorties, apres §2ter) ──
Data.M1RelayFwd            := M1RelayFwd;
Data.M1RelayRev            := M1RelayRev;
Data.M1SpeedContactor1     := M1SpeedContactor1;
Data.M1SpeedContactor2     := M1SpeedContactor2;
Data.M1SpeedContactor3     := M1SpeedContactor3;
Data.M1SpeedContactor4     := M1SpeedContactor4;
Data.M1BrakeCmd            := M1BrakeCmd;

// ── Bus inter-PRG M2 (image reelle des sorties, apres §2ter) ──
Data.M2RelayFwd            := M2RelayFwd;
Data.M2RelayRev            := M2RelayRev;
Data.M2SpeedContactor1     := M2SpeedContactor1;
Data.M2SpeedContactor2     := M2SpeedContactor2;
Data.M2SpeedContactor3     := M2SpeedContactor3;
Data.M2SpeedContactor4     := M2SpeedContactor4;
Data.M2BrakeCmd            := M2BrakeCmd;

// ═══════════════════════════════════════════════════════════════
// ↔️ §3 TRANSLATION M3 (variateur AC600) — conditions + interlock + sorties
// ═══════════════════════════════════════════════════════════════
// 👁️ Même lecture : gate finale, défauts PowerCutOff / SafeStop, synthèse.
// Sources : PRG_05 (TranslationFinalInterlockRequest / TranslationSafety).

M3InterlockEnable := PRG_05_Translation.Data.TranslationFinalInterlockRequest.Enable
                      AND NOT PRG_05_Translation.Data.TranslationFinalInterlockRequest.PowerCutOff;

M3PowerCutOffSafetyInfo := PRG_05_Translation.Data.TranslationSafety.PowerCutOff
                        OR PRG_05_Translation.Data.TranslationSafety.ErrorMecaA
                        OR PRG_05_Translation.Data.TranslationSafety.ErrorMecaB
                        OR PRG_05_Translation.Data.TranslationSafety.ErrorBrakeThermal;

M3SafeStopSafetyInfo := PRG_05_Translation.Data.TranslationSafety.SafeStop
                     OR PRG_05_Translation.Data.TranslationSafety.Error
                     OR PRG_05_Translation.Data.TranslationSafety.ErrorOperatorComm
                     OR PRG_05_Translation.Data.TranslationSafety.ErrorDriveComm
                     OR PRG_05_Translation.Data.TranslationSafety.ErrorPhaseRotation
                     OR PRG_05_Translation.Data.TranslationSafety.ErrorLimitSwitch
                     OR PRG_05_Translation.Data.TranslationSafety.ErrorSensorIncoherent;

M3BlockedBySafetyInfo := M3PowerCutOffSafetyInfo OR M3SafeStopSafetyInfo;

instTranslationOutputInterlockM3(
    Enable                     := M3InterlockEnable,
    Reset                      := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged      := PRG_05_Translation.Data.TranslationFinalInterlockRequest.PowerContactorEngaged,
    SafeStop                   := PRG_05_Translation.Data.TranslationFinalInterlockRequest.SafeStop,
    EffectivePermitM3_Tremie   := PRG_05_Translation.Data.TranslationFinalInterlockRequest.EffectivePermitM3_Tremie,
    EffectivePermitM3_Maintenance := PRG_05_Translation.Data.TranslationFinalInterlockRequest.EffectivePermitM3_Maintenance,
    BrakeReleaseRequest        := PRG_05_Translation.Data.TranslationFinalInterlockRequest.BrakeReleaseRequest,
    BrakeCommandOpenConfirmed  := PRG_05_Translation.Data.TranslationFinalInterlockRequest.BrakeCommandOpenConfirmed,
    RequestedDriveControlWord  := PRG_05_Translation.Data.TranslationFinalInterlockRequest.RequestedDriveControlWord,
    RequestedDriveFreqHz       := PRG_05_Translation.Data.TranslationFinalInterlockRequest.RequestedDriveFreqHz
);

TranslationBrakeCmd := instTranslationOutputInterlockM3.BrakeCmd;
// Pas de garde anti-chatter sur le frein M3 : re-desserrage immédiat requis (cf. §2quater).

// ── Sorties physiques M3 ──
M3_BrakeRelease_RQ           := TranslationBrakeCmd;
M3_CommandWord               := instTranslationOutputInterlockM3.DriveControlWord;
M3_SetpointFrequencyHz       := instTranslationOutputInterlockM3.DriveFreqCmdWord;

// ── Bus inter-PRG M3 ──
Data.TranslationBrakeCmd   := TranslationBrakeCmd;

// ═══════════════════════════════════════════════════════════════
// 🪝 §4 KOBOLD (capteur fond) — commande + sortie
// ═══════════════════════════════════════════════════════════════
// Source : PRG_04 (KoboldContactorCmdArbitrated).
KoboldContactorCmd := PRG_04_Treuils_Benne.Data.KoboldContactorCmdArbitrated;
M1_M2_KoboldMeasureEnable_DQ := KoboldContactorCmd;

// ═══════════════════════════════════════════════════════════════
// 🛡️ §5 AU / MAINTIEN PUISSANCE — coupure + réarmement + sorties
// ═══════════════════════════════════════════════════════════════
// 👁️ D'un coup d'œil : ce qui coupe la puissance (PowerCutOffReq) et ce qui
//    maintient/réarme (instSafetyEmergencyManagement) → sorties physiques.
// Sources : PRG_04/05 (PowerCutOff), GVL_IHM (ArmRequest / BtnEmergencyCutOff),
//           PRG_02 (EmergencyChainClosed / PowerContactorEngaged).

// PowerCutOffReq = agrégation OU strict des demandes de coupure des trois procédés (M5, A-04).
PowerCutOffReq := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.PowerCutOff
               OR PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.PowerCutOff
               OR PRG_05_Translation.Data.TranslationFinalInterlockRequest.PowerCutOff;

instSafetyEmergencyManagement(
    Enable := TRUE,
    Reset := PRG_07_Supervision.FaultMachineReset_IHM,
    ArmRequest := GVL_IHM.Emergency.Cmd.BtnEmergencyArming,
    EmergencyChainClosed := PRG_02_Acquisition.HwIn.Machine.EmergencyChainClosed_DI,
    PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    PowerCutOffRequest := PowerCutOffReq,
    BtnEmergencyCutOff := GVL_IHM.Emergency.Cmd.BtnEmergencyCutOff,
    // 🛠️ Bypass ingenierie MES (RETAIN, jamais IHM) — trace timing chaine/contacteur
    BypassArmingPreconditions := GVL_BypassRetain.BypassAuArmingPreconditions,
    BypassRedundancyTest := GVL_BypassRetain.BypassAuRedundancyTest,
    BypassPowerCutOff := GVL_BypassRetain.BypassAuPowerCutOff
);

// ── Ordres AU (logique) — sorties structurées Status : ST_Safety_Emergency_Status + Cmd : ST_Safety_Emergency_Cmd ──
// 🛡️ Garde anti-chatter sur les 2 contacteurs CHAIN OK (PowerKeepAlive A/B) : chaque
//    ré-enclenchement est espacé d'au moins Cfg_MinInterval. Intervalle court (100 ms) :
//    inférieur à la durée du test de redondance (CST_TestDuration 200 ms) pour ne pas bloquer
//    RESTORE_A/B, mais suffisant pour tuer un mitraillage. La retombée reste instantanée.
instKeepAliveAProtector(
    Enable          := TRUE,
    Request         := instSafetyEmergencyManagement.Cmd.MaintainA_Cmd,
    Cfg_MinInterval := T#100ms
);
instKeepAliveBProtector(
    Enable          := TRUE,
    Request         := instSafetyEmergencyManagement.Cmd.MaintainB_Cmd,
    Cfg_MinInterval := T#100ms
);
PowerKeepAliveACmd := instKeepAliveAProtector.Cmd;
PowerKeepAliveBCmd := instKeepAliveBProtector.Cmd;
// 🛡️ Garde anti-chatter generique sur l'impulsion contacteur AU : une impulsion passe
//    integralement, puis aucune nouvelle avant 5s (redondant avec la garde interne du FB AU,
//    au plus pres de la sortie physique). Un cyclage rapide du contacteur casse le materiel.
instArmContactorProtector(
    Enable          := TRUE,
    Request         := instSafetyEmergencyManagement.Cmd.ArmPulse_Cmd,
    Cfg_MinInterval := T#5s
);
EmergencyArmingCmd := instArmContactorProtector.Cmd;

// ── Sorties physiques AU ──
PowerKeepAlive_A_RQ          := PowerKeepAliveACmd;
PowerKeepAlive_B_RQ          := PowerKeepAliveBCmd;
EmergencyArming_RQ           := EmergencyArmingCmd;

// ── Bus inter-PRG AU ──
Data.PowerKeepAliveACmd    := PowerKeepAliveACmd;
Data.PowerKeepAliveBCmd    := PowerKeepAliveBCmd;
Data.EmergencyArmingCmd    := EmergencyArmingCmd;
Data.TestCutActive         := instSafetyEmergencyManagement.Cmd.TestCutActive;
Data.PowerCutOffRequest    := PowerCutOffReq;

// ── Diagnostics chaîne AU (DUT structurés State/Diag, source unique) ──
EmergencyState := instSafetyEmergencyManagement.Status.State;
EmergencyDiag := instSafetyEmergencyManagement.Status.Diag;
EmergencyReady := instSafetyEmergencyManagement.Status.Ready;
EmergencyDone := instSafetyEmergencyManagement.Status.Done;
EmergencyFault := instSafetyEmergencyManagement.Status.Fault;
EmergencyOperatorMessage := instSafetyEmergencyManagement.Status.OperatorMessage;
PowerCutOffActive := PowerCutOffReq;

{region "§1 Horloge, heartbeat et reset machine"}
// === 🧩 §1 HORLOGE, HEARTBEAT & RESET MACHINE ===
// Trois fonctions de tête : clignotant global, heartbeat IHM (surveillance lien),
// et acquittement machine (porte d'entrée des reset).

// ---------- §1a. Horloge clignotante ----------
instBlink1Hz(
    ENABLE   := TRUE,
    TIMEHIGH := _BlinkTimeOn,
    TIMELOW  := _BlinkTimeOff
);
GVL_Global.BlinkClock := instBlink1Hz.OUT;

// ---------- §1b. Heartbeat IHM (front simulé) ----------
// 💓 Front heartbeat simulé par le clignotant PLC 1 Hz quand le bypass
// IhmHeartbeat est actif (défaut sécurisé), pour ne jamais latcher un timeout
// artificiel. Repasser le bypass à FALSE côté IHM active la vraie surveillance.
instDiagIhmHeartbeat(
    Enable          := TRUE,
    TglHeartbeatIhm := SEL(GVL_IHM.Network.Bypass.IhmHeartbeat, GVL_IHM.Commun.TglHeartbeatIhm, GVL_Global.BlinkClock)
);

// ---------- §1c. Acquittement global machine (reset) ----------
// 🚨 Acquittement global machine : une impulsion est émise dès que l'opérateur appuie
// sur l'un des boutons de reset IHM (défaut global, treuil M1, treuil M2, ou benne).
// Ce signal est consommé par tous les FB du domaine sécurité/métier pour réarmer
// les défauts (Reset sur front). C'est LA porte d'entrée unique de l'acquittement.
FaultMachineReset_IHM := GVL_IHM.Modes.Cmd.BtnFaultReset
                    OR GVL_IHM.M1TreuilRetenue.Cmd.BtnReset
                    OR GVL_IHM.M2TreuilBenne.Cmd.BtnReset
                    OR GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnReset;


{endregion}

{region "§2 Persistance, bypass et simulation"}
// === 🌉 §2 PERSISTANCE, RESTAURATION & BYPASS ===
// Quatre responsabilités distinctes : persistance des configs, restauration boot des
// bypass, synchronisation bidirectionnelle IHM↔RETAIN, et pilotage des bypass par simulation.

// ---------- §2a. Persistance des configs (bridges) ----------
// Chaque FB_CfgPersistBridge_* synchronise UNE structure de config entre GVL_IHM (Hmi)
// et GVL_PERSISTENT (Persist) sur le flag `Initialized` :
//   - au 1er cycle (Hmi.Initialized=FALSE) : Hmi := Persist (restaure la config sauvegardée)
//     et JustRestored := TRUE sur ce seul cycle ;
//   - ensuite : Persist := Hmi (la config IHM est sauvegardée en continu).
// Le flag commun GVL_IHM.Commun.ConfigRestoredFromPersistent est levé dès qu'au moins
// un bridge a restauré au boot, pour signaler à l'IHM qu'une config persistante a été rappelée.

instCfgPersistBridgeWinchM1(Hmi := GVL_IHM.M1TreuilRetenue.Cfg, Persist := _WinchM1CfgPersist);
IF instCfgPersistBridgeWinchM1.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeWinchM2(Hmi := GVL_IHM.M2TreuilBenne.Cfg, Persist := _WinchM2CfgPersist);
IF instCfgPersistBridgeWinchM2.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

// M1 = MAITRE pour la position capteur haut : M1 et M2 montent lies au meme capteur,
// on force donc M2 = M1 en continu (IHM + persistant). Regler CfgTopSensorPos_M cote M1
// sur l'IHM ; le champ M2 suit automatiquement et le homing M2 (qui lit
// _WinchM2CfgPersist.CfgTopSensorPos_M) prend la meme valeur. Aucun champ persistant neuf.
GVL_IHM.M2TreuilBenne.Cfg.CfgTopSensorPos_M := GVL_IHM.M1TreuilRetenue.Cfg.CfgTopSensorPos_M;
_WinchM2CfgPersist.CfgTopSensorPos_M       := GVL_IHM.M1TreuilRetenue.Cfg.CfgTopSensorPos_M;

instCfgPersistBridgeSync(Hmi := GVL_IHM.M1M2Sync.Cfg, Persist := _SyncCfgPersist);
IF instCfgPersistBridgeSync.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeTranslation(Hmi := GVL_IHM.TranslationM3.Cfg, Persist := _TranslationCfgPersist);
IF instCfgPersistBridgeTranslation.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeJoystick(Hmi := GVL_IHM.JOY1Joystick.Cfg, Persist := _JoystickCfgPersist);
IF instCfgPersistBridgeJoystick.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeEncoder(Hmi := GVL_IHM.Commun.EncoderCfg, Persist := _EncoderCfgPersist);
IF instCfgPersistBridgeEncoder.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeBucket(Hmi := GVL_IHM.M2TreuilBenne.Bucket.Cfg, Persist := _BucketCfgPersist);
IF instCfgPersistBridgeBucket.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeCommun(Hmi := GVL_IHM.Commun.Cfg, Persist := _CommunCfgPersist);
IF instCfgPersistBridgeCommun.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeCycle(Hmi := GVL_IHM.Cycle.Cfg, Persist := _CycleCfgPersist);
IF instCfgPersistBridgeCycle.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeCycleMachineHoming(Hmi := GVL_IHM.CycleMachineHoming.Cfg, Persist := _CycleMachineHomingCfgPersist);
IF instCfgPersistBridgeCycleMachineHoming.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

// Ponts persistance configs cycle (DiveSearch / Extraction / DumpAtTremie)
instCfgPersistBridgeCycleDiveSearchCfg(Hmi := GVL_IHM.CycleDiveSearch.Cfg, Persist := _CycleDiveSearchCfgPersist);
IF instCfgPersistBridgeCycleDiveSearchCfg.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeCycleExtractionCfg(Hmi := GVL_IHM.CycleExtraction.Cfg, Persist := _CycleExtractionCfgPersist);
IF instCfgPersistBridgeCycleExtractionCfg.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeCycleDumpAtTremieCfg(Hmi := GVL_IHM.CycleDumpAtTremie.Cfg, Persist := _CycleDumpAtTremieCfgPersist);
IF instCfgPersistBridgeCycleDumpAtTremieCfg.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

// Pont persistance toggles assistance (répartis dans les 3 Cmd, mémorisés via _CycleAssistTogglesPersist)
AssistTogglesHmi.TglEnableDiveSearch         := GVL_IHM.CycleDiveSearch.Cmd.TglEnableDiveSearch;
AssistTogglesHmi.TglEnableExtractionSequence := GVL_IHM.CycleExtraction.Cmd.TglEnableExtractionSequence;
AssistTogglesHmi.TglEnableDumpAtTremie       := GVL_IHM.CycleDumpAtTremie.Cmd.TglEnableDumpAtTremie;
instCfgPersistBridgeCycleAssistToggles(Hmi := AssistTogglesHmi, Persist := _CycleAssistTogglesPersist);
IF instCfgPersistBridgeCycleAssistToggles.JustRestored THEN
    GVL_IHM.CycleDiveSearch.Cmd.TglEnableDiveSearch         := AssistTogglesHmi.TglEnableDiveSearch;
    GVL_IHM.CycleExtraction.Cmd.TglEnableExtractionSequence := AssistTogglesHmi.TglEnableExtractionSequence;
    GVL_IHM.CycleDumpAtTremie.Cmd.TglEnableDumpAtTremie       := AssistTogglesHmi.TglEnableDumpAtTremie;
    GVL_IHM.Commun.ConfigRestoredFromPersistent            := TRUE;
END_IF;

// Consigne variateur M3 (SetFreq_Hz) : pas de bridge Cfg dédié (c'est une Cmd, pas une
// Cfg) → initialisation manuelle au 1er cycle à partir du persist RETAIN _TranslationSetFreq_Hz.
// Le flag Cmd.Initialized distingue le 1er passage (restaure) des suivants (survit).
IF NOT GVL_IHM.TranslationM3.Cmd.Initialized THEN
    GVL_IHM.TranslationM3.Cmd.SetFreq_Hz := _TranslationSetFreq_Hz;
    GVL_IHM.TranslationM3.Cmd.Initialized := TRUE;
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;
// Recopie continue (après restauration) : toute consigne changée en session survit au
// prochain boot/reset chaud, pas seulement le défaut d'usine.
_TranslationSetFreq_Hz := GVL_IHM.TranslationM3.Cmd.SetFreq_Hz;

// Acquittement du bandeau « config restaurée » par l'opérateur (front) → efface le flag.
instAckConfigRestored(CLK := GVL_IHM.Commun.BtnAckConfigRestored);
IF instAckConfigRestored.Q THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := FALSE;
END_IF;

// ---------- §2b. Restauration boot des bypass (RETAIN → IHM) ----------
// 🎚️ Restauration boot des BYPASS IHM depuis le RETAIN (BypassXxxGlobal) :
// au 1er cycle (Bypass.Initialized=FALSE), si un bypass global RETAIN est actif, on le
// rejoue sur l'IHM, puis on marque Initialized pour ne pas réécraser les actions suivantes
// de l'opérateur. Même pattern pour chaque domaine (Translation / M1 / M2 / Sync / Commun).
IF NOT GVL_IHM.TranslationM3.Bypass.Initialized THEN
    IF BypassTranslationGlobal THEN
        GVL_IHM.TranslationM3.Bypass.Global := TRUE;
    END_IF;
    GVL_IHM.TranslationM3.Bypass.Initialized := TRUE;
END_IF;

IF NOT GVL_IHM.M1TreuilRetenue.Bypass.Initialized THEN
    IF BypassWinchM1Global THEN
        GVL_IHM.M1TreuilRetenue.Bypass.Global := TRUE;
    END_IF;
    GVL_IHM.M1TreuilRetenue.Bypass.Initialized := TRUE;
END_IF;

IF NOT GVL_IHM.M2TreuilBenne.Bypass.Initialized THEN
    IF BypassWinchM2Global THEN
        GVL_IHM.M2TreuilBenne.Bypass.Global := TRUE;
    END_IF;
    GVL_IHM.M2TreuilBenne.Bypass.Initialized := TRUE;
END_IF;

// Restauration boot du bypass synchro (RETAIN), même pattern que les autres domaines.
IF NOT GVL_IHM.M1M2Sync.Bypass.Initialized THEN
    IF BypassSyncGlobal THEN
        GVL_IHM.M1M2Sync.Bypass.Global := TRUE;
    END_IF;
    GVL_IHM.M1M2Sync.Bypass.Initialized := TRUE;
END_IF;

IF NOT GVL_IHM.Commun.Bypass.Initialized THEN
    IF BypassCommunGlobal THEN
        GVL_IHM.Commun.Bypass.Global := TRUE;
    END_IF;
    IF BypassLimitLegal THEN
        GVL_IHM.Commun.Bypass.LimitLegal := TRUE;
    END_IF;
    IF BypassTopLimitSwitch THEN
        GVL_IHM.Commun.Bypass.TopLimitSwitch := TRUE;
    END_IF;
    IF BypassTopLimitSoftware THEN
        GVL_IHM.Commun.Bypass.TopLimitSoftware := TRUE;
    END_IF;
    IF BypassCableLimitSwitch THEN
        GVL_IHM.Commun.Bypass.CableLimitSwitch := TRUE;
    END_IF;
    IF BypassSlackCable THEN
        GVL_IHM.Commun.Bypass.SlackCable := TRUE;
    END_IF;
    GVL_IHM.Commun.Bypass.Initialized := TRUE;
END_IF;

// Restauration boot du bypass reseau global (RETAIN), meme pattern que les autres domaines.
// GVL_IHM.Network.Bypass.Global neutralise les diagnostics bus + 5 modules E/S dans
// PRG_02_Acquisition (VH_0008ER, CANopen, EtherCAT). Sans ce relais, BypassNetworkGlobal
// etait orphelin (jamais rejoue vers l'IHM).
IF NOT GVL_IHM.Network.Bypass.Initialized THEN
    IF BypassNetworkGlobal THEN
        GVL_IHM.Network.Bypass.Global := TRUE;
    END_IF;
    GVL_IHM.Network.Bypass.Initialized := TRUE;
END_IF;

// ---------- §2c. Synchronisation bidirectionnelle IHM ↔ RETAIN ----------
// 🔄 SYNC BIDIRECTIONNEL (dernier-écrit-gagne), factorisé dans FB_MirrorBypassRetain
// (CODE/A_COMMUN) : si l'IHM a changé → RETAIN ; sinon → IHM := RETAIN.
instMirrorBypassTranslation(Hmi := GVL_IHM.TranslationM3.Bypass.Global, RetainVal := BypassTranslationGlobal, Prev := PrevTranslationBypass);
instMirrorBypassM1(Hmi := GVL_IHM.M1TreuilRetenue.Bypass.Global, RetainVal := BypassWinchM1Global, Prev := PrevM1Bypass);
instMirrorBypassM2(Hmi := GVL_IHM.M2TreuilBenne.Bypass.Global, RetainVal := BypassWinchM2Global, Prev := PrevM2Bypass);
instMirrorBypassSync(Hmi := GVL_IHM.M1M2Sync.Bypass.Global, RetainVal := BypassSyncGlobal, Prev := PrevSyncBypass);
instMirrorBypassCommun(Hmi := GVL_IHM.Commun.Bypass.Global, RetainVal := BypassCommunGlobal, Prev := PrevCommunBypass);
instMirrorBypassLimitLegal(Hmi := GVL_IHM.Commun.Bypass.LimitLegal, RetainVal := BypassLimitLegal, Prev := PrevLimitLegal);
instMirrorBypassTopLimitSwitch(Hmi := GVL_IHM.Commun.Bypass.TopLimitSwitch, RetainVal := BypassTopLimitSwitch, Prev := PrevTopLimitSwitch);
instMirrorBypassTopLimitSoftware(Hmi := GVL_IHM.Commun.Bypass.TopLimitSoftware, RetainVal := BypassTopLimitSoftware, Prev := PrevTopLimitSoftware);
instMirrorBypassCableLimitSwitch(Hmi := GVL_IHM.Commun.Bypass.CableLimitSwitch, RetainVal := BypassCableLimitSwitch, Prev := PrevCableLimitSwitch);
instMirrorBypassSlackCable(Hmi := GVL_IHM.Commun.Bypass.SlackCable, RetainVal := BypassSlackCable, Prev := PrevSlackCable);
instMirrorBypassNetwork(Hmi := GVL_IHM.Network.Bypass.Global, RetainVal := BypassNetworkGlobal, Prev := PrevNetworkBypass);

// ---------- §2d. Pilotage des bypass par simulation ----------
// 🧪 PILOTAGE BYPASS IHM PAR SIMULATION (front montant/descendant)
// La simulation emprunte le chemin IHM : le bypass banc ne devient effectif
// que lorsque les trois conditions sont réunies. Sans ce gate, la valeur par
// défaut TRUE de SimulationBypassActive pouvait armer BypassProcess en MAINT_N2
// sur une machine réelle (ou avant l'activation du domaine treuil simulé).
SimulationBypassEffective := GVL_Simulation.SimulationModeActive
                             AND GVL_Simulation.SimWinchActive
                             AND GVL_Simulation.SimulationBypassActive;
SimBypassRise(CLK := SimulationBypassEffective);
SimBypassFall(CLK := SimulationBypassEffective);

IF SimBypassRise.Q THEN
    // 🧪 Bypass sim étendu aux tests Meca (Meca A-E via Safety ; NoMovement/
    // OppositeDir via Process) pour travailler sans faux blocage en banc.
    // Les trois limites banc demandées sont écrites depuis leur producteur unique.
    // Elles restent strictement inertes hors SimulationBypassEffective.
    GVL_IHM.M1TreuilRetenue.Bypass.Safety  := TRUE;
    GVL_IHM.M1TreuilRetenue.Bypass.Process := TRUE;
    GVL_IHM.M2TreuilBenne.Bypass.Safety    := TRUE;
    GVL_IHM.M2TreuilBenne.Bypass.Process   := TRUE;
    GVL_IHM.Commun.Bypass.TopLimitSwitch   := TRUE;
    GVL_IHM.Commun.Bypass.TopLimitSoftware := TRUE;
    GVL_IHM.Commun.Bypass.CableLimitSwitch := TRUE;
END_IF;
IF SimBypassFall.Q THEN
    GVL_IHM.Commun.Bypass.TopLimitSwitch   := FALSE;
    GVL_IHM.Commun.Bypass.TopLimitSoftware := FALSE;
    GVL_IHM.Commun.Bypass.CableLimitSwitch := FALSE;
    GVL_IHM.Commun.Bypass.LimitLegal       := FALSE;
    GVL_IHM.M1TreuilRetenue.Bypass.Safety  := FALSE;
    GVL_IHM.M1TreuilRetenue.Bypass.Process := FALSE;
    GVL_IHM.M2TreuilBenne.Bypass.Safety    := FALSE;
    GVL_IHM.M2TreuilBenne.Bypass.Process   := FALSE;
END_IF;

{endregion}

{region "§3 Projections IHM et mapping"}
// === 📊 §3 PROJECTIONS IHM ET MAPPING ===
// Ensemble des recopies GVL_IHM ← sources inter-PRG. Chaque sous-région est un domaine
// IHM cohérent (faits machine, heartbeat, preflight, bypass, état, réseau, cycle, bandeau).

// ---------- §3a. Faits machine communs (lecture seule) ----------
GVL_IHM.Commun.LimitLegalReached         := _CommunCfgPersist.LimitLegalEnabled
    AND ((PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM <= _CommunCfgPersist.LimitLegalDepthMinAllowed_M)
      OR (PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM <= _CommunCfgPersist.LimitLegalDepthMinAllowed_M));
GVL_IHM.Commun.TopPositionSensorActive   := NOT PRG_02_Acquisition.HwIn.Winch.M1M2_TopPositionFree_DI;
GVL_IHM.Commun.HydraulicThermalFault     := NOT PRG_02_Acquisition.HwIn.Machine.HydraulicThermalOk_DI;
GVL_IHM.Commun.BrakeThermalFault         := NOT PRG_02_Acquisition.HwIn.Machine.M1_M2_M3_BrakeThermalOk_DI;
GVL_IHM.Commun.PhaseRotationFault        := NOT PRG_02_Acquisition.HwIn.Machine.PhaseRotationOk_DI;

// ---------- §3b. Heartbeat IHM↔PLC ----------
GVL_IHM.Commun.HeartbeatIhmOk            := instDiagIhmHeartbeat.HeartbeatIhmOk;
GVL_IHM.Commun.HeartbeatIhmTimeout       := instDiagIhmHeartbeat.HeartbeatIhmTimeout;
GVL_IHM.Commun.HeartbeatIhmElapsed       := instDiagIhmHeartbeat.TimeSinceIhmEdge;
GVL_IHM.Commun.TglHeartbeatPlc           := instDiagIhmHeartbeat.TglHeartbeatPlc;

// ---------- §3c. Preflight machine à l'arrêt ----------
instPreflight(
    Execute                   := GVL_IHM.Commun.Preflight.BtnRun,
    MachineIsStill            := (PRG_04_Treuils_Benne.Data.WinchM1State.StepNumber = 0)
                                 AND (PRG_04_Treuils_Benne.Data.WinchM2State.StepNumber = 0)
                                 AND (PRG_05_Translation.Data.TranslationState.FBState = E_State.READY),
    M1BrakeApplied            := NOT PRG_02_Acquisition.HwIn.Winch.M1_BrakeIsOpen_DI,
    M2BrakeApplied            := NOT PRG_02_Acquisition.HwIn.Winch.M2_BrakeIsOpen_DI,
    M3BrakeApplied            := TRUE, // Pas de retour frein M3 direct
    M1ContactorsReleased      := PRG_02_Acquisition.HwIn.Winch.M1_ContactorsReleased_DI,
    M2ContactorsReleased      := PRG_02_Acquisition.HwIn.Winch.M2_ContactorsReleased_DI,
    M1ThermalOk               := PRG_02_Acquisition.HwIn.Winch.M1_ThermalOk_DI,
    M2ThermalOk               := PRG_02_Acquisition.HwIn.Winch.M2_ThermalOk_DI,
    BrakeThermalOk            := PRG_02_Acquisition.HwIn.Machine.M1_M2_M3_BrakeThermalOk_DI,
    PhaseRotationOk           := PRG_02_Acquisition.HwIn.Machine.PhaseRotationOk_DI,
    SlackCableTensioned       := PRG_02_Acquisition.HwIn.Winch.M2_TensionedCable_DI,
    M3SensorWordIncoherent    := PRG_05_Translation.Data.M3_SensorWordIncoherent,
    EmergencyChainClosed      := PRG_02_Acquisition.HwIn.Machine.EmergencyChainClosed_DI,
    PowerContactorEngaged     := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    EncoderM1Operational      := PRG_02_Acquisition.Data.Network.EncoderM1.Operational,
    EncoderM2Operational      := PRG_02_Acquisition.Data.Network.EncoderM2.Operational,
    HomedM1                   := PRG_04_Treuils_Benne.Data.WinchM1State.Encoder.Homed,
    HomedM2                   := PRG_04_Treuils_Benne.Data.WinchM2State.Encoder.Homed,
    M1PositionInBounds        := NOT PRG_02_Acquisition.Data.EncoderM1.Measurement.EncoderIncoherent,
    M2PositionInBounds        := NOT PRG_02_Acquisition.Data.EncoderM2.Measurement.EncoderIncoherent
);
GVL_IHM.Commun.Preflight.PreflightOk      := instPreflight.PreflightOk;
GVL_IHM.Commun.Preflight.PreflightDone    := instPreflight.PreflightDone;
GVL_IHM.Commun.Preflight.PreflightBusy    := instPreflight.PreflightBusy;
GVL_IHM.Commun.Preflight.PreflightErrorId := instPreflight.PreflightErrorId;

// ---------- §3c-bis. Diagnostic passif symétrie M1/M2 (FB_Winch_Symmetry) ----------
// ⚖️ Observateur STRICT (AF-10 §7.3bis) : aucune écriture de commande, de
// sécurité ou de mouvement. Sources : états publics M1/M2 (PRG_04 Data), encodeurs
// (PRG_02), synchro (PRG_04). Config & données persistantes : GVL_PERSISTENT.
instWinchSymmetry(
    Reset           := GVL_IHM.Commun.WinchSymmetry.BtnReset,
    M1CommandActive := PRG_04_Treuils_Benne.Data.WinchM1State.Busy,
    M2CommandActive := PRG_04_Treuils_Benne.Data.WinchM2State.Busy,
    M1Direction     := SEL(PRG_04_Treuils_Benne.Data.WinchM1State.CommandedAscent, SEL(PRG_04_Treuils_Benne.Data.WinchM1State.CommandedDescend, 0, -1), 1),
    M2Direction     := SEL(PRG_04_Treuils_Benne.Data.WinchM2State.CommandedAscent, SEL(PRG_04_Treuils_Benne.Data.WinchM2State.CommandedDescend, 0, -1), 1),
    M1BrakeCmd      := PRG_04_Treuils_Benne.Data.WinchM1State.BrakeCmd,
    M2BrakeCmd      := PRG_04_Treuils_Benne.Data.WinchM2State.BrakeCmd,
    M1BrakeApplied  := NOT PRG_04_Treuils_Benne.Data.WinchM1State.BrakeCommandOpenConfirmed,
    M2BrakeApplied  := NOT PRG_04_Treuils_Benne.Data.WinchM2State.BrakeCommandOpenConfirmed,
    M1Position_M    := PRG_04_Treuils_Benne.Data.WinchM1State.Position_M,
    M2Position_M    := PRG_04_Treuils_Benne.Data.WinchM2State.Position_M,
    M1Speed_Mps     := PRG_04_Treuils_Benne.Data.WinchM1State.MeasuredSpeed_Mps,
    M2Speed_Mps     := PRG_04_Treuils_Benne.Data.WinchM2State.MeasuredSpeed_Mps,
    SyncDeviation_M := ABS(PRG_04_Treuils_Benne.Data.WinchSyncSignedDeltaPosM),
    Config          := _WinchSymmetryCfgPersist,
    Data            := _WinchSymmetryDataPersist
);
// Publication IHM (ST_WinchSymmetryHMI via GVL_IHM.Commun.WinchSymmetry) — lecture seule.
GVL_IHM.Commun.WinchSymmetry.SymmetryOk        := instWinchSymmetry.SymmetryOk;
GVL_IHM.Commun.WinchSymmetry.SymmetryValid     := instWinchSymmetry.SymmetryValid;
GVL_IHM.Commun.WinchSymmetry.DeltaStartDelay_Ms       := _WinchSymmetryDataPersist.DeltaStartDelay_Ms;
GVL_IHM.Commun.WinchSymmetry.DeltaBrakeReleaseTime_Ms := _WinchSymmetryDataPersist.DeltaBrakeReleaseTime_Ms;
GVL_IHM.Commun.WinchSymmetry.DeltaBrakeApplyTime_Ms   := _WinchSymmetryDataPersist.DeltaBrakeApplyTime_Ms;
GVL_IHM.Commun.WinchSymmetry.DeltaStopDistance_M      := UDINT_TO_REAL(_WinchSymmetryDataPersist.DeltaStopDistance_Mm) / 1000.0;
GVL_IHM.Commun.WinchSymmetry.DeltaStopTime_Ms         := _WinchSymmetryDataPersist.DeltaStopTime_Ms;
GVL_IHM.Commun.WinchSymmetry.MaxSyncDeviation_M       := _WinchSymmetryDataPersist.MaxSyncDeviation_M;

// ---------- §3d. Bypass simulation (retours simulés vers IHM) ----------
GVL_IHM.M1TreuilRetenue.Bypass.ContactorFeedback := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimWinchActive;
GVL_IHM.M2TreuilBenne.Bypass.ContactorFeedback   := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimWinchActive;
GVL_IHM.TranslationM3.Bypass.ContactorFeedback   := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimTranslationActive;
// Ces deux indicateurs ne décrivent PAS le domaine simulation : ils publient
// l'état des bypasss réellement consommés par FB_Safety_Winch.
GVL_IHM.Commun.SimSlackCableBypassActive         := GVL_IHM.Commun.Bypass.SlackCable;
GVL_IHM.Commun.SimTopSensorBypassActive          := GVL_IHM.Commun.Bypass.TopLimitSwitch;
GVL_IHM.Commun.WinchInputSourceChanged           := PRG_02_Acquisition.Data.InputSource.WinchInputSourceChanged;

// ---------- §3e. Structures d'état & safety (recopies directes des bus) ----------
GVL_IHM.M1TreuilRetenue.State := PRG_04_Treuils_Benne.Data.WinchM1State;
GVL_IHM.M2TreuilBenne.State := PRG_04_Treuils_Benne.Data.WinchM2State;
GVL_IHM.M1TreuilRetenue.Safety := PRG_04_Treuils_Benne.Data.WinchM1Safety;
GVL_IHM.M2TreuilBenne.Safety := PRG_04_Treuils_Benne.Data.WinchM2Safety;
GVL_IHM.M1M2Sync.State := PRG_04_Treuils_Benne.Data.SyncState;
GVL_IHM.M2TreuilBenne.Bucket.State := PRG_04_Treuils_Benne.Data.BucketState;
GVL_IHM.TranslationM3.State := PRG_05_Translation.Data.TranslationState;

// ---------- §3e-bis. Gel affichage position pendant transaction preset codeur (anti-clignotement, voir VAR) ----------
M1HomingDisplaySettle(IN := NOT GVL_IHM.M1TreuilRetenue.State.Encoder.HomingBusy, PT := T#2s);
M2HomingDisplaySettle(IN := NOT GVL_IHM.M2TreuilBenne.State.Encoder.HomingBusy, PT := T#2s);
M1PosDisplayFrozen := GVL_IHM.M1TreuilRetenue.State.Encoder.HomingBusy OR NOT M1HomingDisplaySettle.Q;
M2PosDisplayFrozen := GVL_IHM.M2TreuilBenne.State.Encoder.HomingBusy OR NOT M2HomingDisplaySettle.Q;

IF M1PosDisplayFrozen THEN
    GVL_IHM.M1TreuilRetenue.State.Position_M := M1PosHmiHeld_M;
ELSE
    M1PosHmiHeld_M := GVL_IHM.M1TreuilRetenue.State.Position_M;
END_IF;

IF M2PosDisplayFrozen THEN
    GVL_IHM.M2TreuilBenne.State.Position_M                 := M2PosHmiHeld_M;
    GVL_IHM.M2TreuilBenne.Bucket.State.M2PositionCorrected := M2PosCorrectedHmiHeld_M;
ELSE
    M2PosHmiHeld_M          := GVL_IHM.M2TreuilBenne.State.Position_M;
    M2PosCorrectedHmiHeld_M := GVL_IHM.M2TreuilBenne.Bucket.State.M2PositionCorrected;
END_IF;
GVL_IHM.TranslationM3.Safety := PRG_05_Translation.Data.TranslationSafety;

GVL_IHM.Modes.State.CurrentMode := PRG_03_Modes_Cycle.Data.Auth.Mode;
// — Chaîne AU / sécurité : sortie de Modes.State vers GVL_IHM.Emergency —
// Point de vue IHM : Cmd = boutons (produits par l'IHM), State = état AU
// (champs plats) + cmd FB AU (MaintainA/B_Cmd, ArmPulse_Cmd) + Diag interne.
GVL_IHM.Emergency.State.ChainOk     := PRG_06_Outputs.EmergencyState.ChainOk;
GVL_IHM.Emergency.State.ContactorOk := PRG_06_Outputs.EmergencyState.ContactorOk;
GVL_IHM.Emergency.State.Step        := PRG_06_Outputs.EmergencyState.Step;
GVL_IHM.Emergency.State.Armable     := PRG_06_Outputs.EmergencyState.Armable;
GVL_IHM.Emergency.State.ArmingBusy  := PRG_06_Outputs.EmergencyState.ArmingBusy;
GVL_IHM.Emergency.State.MaintainA_Cmd := PRG_06_Outputs.PowerKeepAliveACmd;
GVL_IHM.Emergency.State.MaintainB_Cmd := PRG_06_Outputs.PowerKeepAliveBCmd;
GVL_IHM.Emergency.State.ArmPulse_Cmd  := PRG_06_Outputs.EmergencyArmingCmd;
GVL_IHM.Emergency.State.Diag := PRG_06_Outputs.EmergencyDiag;
// États publics FB AU (Ready/Done/Fault/OperatorMessage) — miroir Status du FB
// (produits par PRG_06). Busy non exposé : redondant avec ArmingBusy (déjà câblé).
GVL_IHM.Emergency.State.Ready := PRG_06_Outputs.EmergencyReady;
GVL_IHM.Emergency.State.Done := PRG_06_Outputs.EmergencyDone;
GVL_IHM.Emergency.State.Fault := PRG_06_Outputs.EmergencyFault;
GVL_IHM.Emergency.State.OperatorMessage := PRG_06_Outputs.EmergencyOperatorMessage;
// OR avec les défauts d'arbitrage de mode (refus Semi-Auto, bascule de mode refusée) —
// publiés par PRG_03 : sans eux ces refus restaient silencieux pour l'opérateur.
GVL_IHM.Modes.State.AnyFaultActive := PRG_06_Outputs.EmergencyDiag.Error
                                      OR PRG_02_Acquisition.Data.InputModules.Fault
                                      OR PRG_03_Modes_Cycle.Data.ModesFault.Error
                                      OR PRG_03_Modes_Cycle.Data.ModesFault.Latched
                                      OR GVL_IHM.M1TreuilRetenue.Safety.Error
                                      OR GVL_IHM.M2TreuilBenne.Safety.Error
                                      OR GVL_IHM.TranslationM3.Safety.Error
                                      OR GVL_IHM.M1M2Sync.State.Error
                                      OR GVL_IHM.M2TreuilBenne.Bucket.State.Error
                                      OR GVL_IHM.Cycle.State.Error
                                      OR GVL_IHM.JOY1Joystick.State.Error;
// Miroir IHM des états de maintenance (AF-05 §4bis, producteur FB_Modes via PRG_03)
GVL_IHM.Modes.State.ModeChangePendingBlocked := PRG_03_Modes_Cycle.Data.Auth.ModeChangePendingBlocked;
GVL_IHM.Modes.State.ModeChangeBlockReason := PRG_03_Modes_Cycle.Data.Auth.ModeChangeBlockReason;
GVL_IHM.Modes.State.M1ContactorsReleased := PRG_03_Modes_Cycle.Data.Auth.M1ContactorsReleased;
GVL_IHM.Modes.State.M1BrakeApplied := PRG_03_Modes_Cycle.Data.Auth.M1BrakeApplied;
GVL_IHM.Modes.State.M1SpeedLow := PRG_03_Modes_Cycle.Data.Auth.M1SpeedLow;
GVL_IHM.Modes.State.M2ContactorsReleased := PRG_03_Modes_Cycle.Data.Auth.M2ContactorsReleased;
GVL_IHM.Modes.State.M2BrakeApplied := PRG_03_Modes_Cycle.Data.Auth.M2BrakeApplied;
GVL_IHM.Modes.State.M2SpeedLow := PRG_03_Modes_Cycle.Data.Auth.M2SpeedLow;
GVL_IHM.Modes.State.HomingRequiredM1 := PRG_03_Modes_Cycle.Data.Auth.HomingRequiredM1;
GVL_IHM.Modes.State.HomingRequiredM2 := PRG_03_Modes_Cycle.Data.Auth.HomingRequiredM2;
// Etat publie du cycle de referencement machine (visu IHM) - recopie whole-struct.
GVL_IHM.CycleMachineHoming.State := PRG_02_Acquisition.Data.MachineHoming;

// ---------- §3f. État joystick & réseau (diagnostic bus) ----------
GVL_IHM.JOY1Joystick.State.RawX := PRG_02_Acquisition.HwIn.Operator.JoyXRaw_ANA1;
GVL_IHM.JOY1Joystick.State.RawY := PRG_02_Acquisition.HwIn.Operator.JoyYRaw_ANA2;
GVL_IHM.JOY1Joystick.State.RawButton := PRG_02_Acquisition.HwIn.Operator.JoyBtnRaw;
GVL_IHM.JOY1Joystick.State.AxisCmdX := PRG_02_Acquisition.Data.Joystick.AxisX;
GVL_IHM.JOY1Joystick.State.AxisCmdY := PRG_02_Acquisition.Data.Joystick.AxisY;
GVL_IHM.JOY1Joystick.State.NeutralXAct := PRG_02_Acquisition.Data.Joystick.NeutralXAct;
GVL_IHM.JOY1Joystick.State.NeutralYAct := PRG_02_Acquisition.Data.Joystick.NeutralYAct;
GVL_IHM.JOY1Joystick.State.DeadmanArmed := PRG_02_Acquisition.Data.Joystick.DeadmanArmed;
GVL_IHM.JOY1Joystick.State.AtNeutral := PRG_02_Acquisition.Data.Joystick.AtNeutralXY;
GVL_IHM.JOY1Joystick.State.Online := PRG_02_Acquisition.Data.Network.Joystick.Online;
GVL_IHM.JOY1Joystick.State.Operational := PRG_02_Acquisition.Data.Network.Joystick.Operational;
// 🕹️ Le défaut fonctionnel du joystick (calibration bit0, capteur hors plage bit1, perte
// bus bit2) vient du FB lui-même, pas du diagnostic bus. Le diagnostic CAN reste exposé
// séparément (GVL_IHM.Network.CanError) — ici on remonte l'erreur du FB joystick.
GVL_IHM.JOY1Joystick.State.Error := PRG_02_Acquisition.Data.Joystick.Fault.Error;
GVL_IHM.JOY1Joystick.State.ErrorId := PRG_02_Acquisition.Data.Joystick.Fault.ErrorId;

GVL_IHM.Network.BusCanOpen  := PRG_02_Acquisition.Data.Network.CanOpenMaster;
GVL_IHM.Network.Joystick    := PRG_02_Acquisition.Data.Network.Joystick;
GVL_IHM.Network.CanError    := GVL_IHM.Network.BusCanOpen.Error OR GVL_IHM.Network.Joystick.Error;
GVL_IHM.Network.CanErrorId  := GVL_IHM.Network.BusCanOpen.ErrorId OR GVL_IHM.Network.Joystick.ErrorId;

GVL_IHM.Network.BusEthercat := PRG_02_Acquisition.Data.Network.EthercatMaster;
GVL_IHM.Network.EncoderM1   := PRG_02_Acquisition.Data.Network.EncoderM1;
GVL_IHM.Network.EncoderM2   := PRG_02_Acquisition.Data.Network.EncoderM2;
GVL_IHM.Network.VariateurM3 := PRG_02_Acquisition.Data.Network.DriveM3;
GVL_IHM.Network.EcatError   := GVL_IHM.Network.BusEthercat.Error OR GVL_IHM.Network.EncoderM1.Error OR GVL_IHM.Network.EncoderM2.Error OR GVL_IHM.Network.VariateurM3.Error;
GVL_IHM.Network.EcatErrorId := GVL_IHM.Network.BusEthercat.ErrorId OR GVL_IHM.Network.EncoderM1.ErrorId OR GVL_IHM.Network.EncoderM2.ErrorId OR GVL_IHM.Network.VariateurM3.ErrorId;

// 🩺 Diagnostic carte des 5 modules d'E/S physiques (AF06 §3bis) — lecture seule, calculé
// dans PRG_02_Acquisition, simple recopie ici pour l'IHM (même patron que Network.*).
GVL_IHM.Network.InputModules.LocalDigitalIoOk := PRG_02_Acquisition.Data.InputModules.LocalDigitalIoOk;
GVL_IHM.Network.InputModules.Vh0800EndOk      := PRG_02_Acquisition.Data.InputModules.Vh0800EndOk;
GVL_IHM.Network.InputModules.Vh0808EtpOk      := PRG_02_Acquisition.Data.InputModules.Vh0808EtpOk;
GVL_IHM.Network.InputModules.Vh0008ErOk       := PRG_02_Acquisition.Data.InputModules.Vh0008ErOk;
GVL_IHM.Network.InputModules.Vh0008Er1Ok      := PRG_02_Acquisition.Data.InputModules.Vh0008Er1Ok;
GVL_IHM.Network.InputModules.Fault            := PRG_02_Acquisition.Data.InputModules.Fault;

// ---------- §3g. État cycle semi-auto & bandeau ----------
GVL_IHM.Cycle.State.Ready                  := PRG_03_Modes_Cycle.Data.SequenceState.Ready;
GVL_IHM.Cycle.State.Busy                   := PRG_03_Modes_Cycle.Data.SequenceState.Lifecycle.Busy;
GVL_IHM.Cycle.State.Done                   := PRG_03_Modes_Cycle.Data.SequenceState.Lifecycle.Done;
GVL_IHM.Cycle.State.Error                  := PRG_03_Modes_Cycle.Data.SequenceState.Fault.Error;
GVL_IHM.Cycle.State.ErrorId                := PRG_03_Modes_Cycle.Data.SequenceState.Fault.ErrorId;
GVL_IHM.Cycle.State.CycleStep              := PRG_03_Modes_Cycle.Data.SequenceState.Step;
GVL_IHM.Cycle.State.CycleStateStr          := PRG_03_Modes_Cycle.Data.SequenceState.StepStr;
GVL_IHM.Cycle.State.CycleStepAtError       := PRG_03_Modes_Cycle.Data.SequenceState.StepAtFault;
GVL_IHM.Cycle.State.SampleCount            := _CycleSampleCount;
GVL_IHM.Cycle.State.CurrentCycleElapsed    := PRG_03_Modes_Cycle.Data.SequenceState.CurrentCycleElapsed;
GVL_IHM.Cycle.State.LastCycleDuration      := PRG_03_Modes_Cycle.Data.SequenceState.LastCycleDuration;
GVL_IHM.Cycle.State.SelTarget              := GVL_IHM.TranslationM3.Cmd.SelTarget;
GVL_IHM.Cycle.State.KoboldContactFond      := PRG_02_Acquisition.HwIn.Machine.M1_M2_KoboldBottomTouch_DI;
GVL_IHM.Cycle.State.KoboldContactorCmd     := PRG_03_Modes_Cycle.Data.ReqProgram.ReqBucket.ReqKoboldMeasureEnable;
GVL_IHM.Cycle.State.LimitLegalReached      := GVL_IHM.Commun.LimitLegalReached;
GVL_IHM.Cycle.State.LimitLegalDepth_M      := _CommunCfgPersist.LimitLegalDepthMinAllowed_M;
GVL_IHM.Cycle.State.WinchSyncError         := PRG_04_Treuils_Benne.Data.WinchSyncError;
GVL_IHM.Cycle.State.WinchSyncDelta_M       := PRG_04_Treuils_Benne.Data.WinchSyncSignedDeltaPosM;
GVL_IHM.Cycle.State.SpeedMismatch_Mps      := PRG_03_Modes_Cycle.Data.SequenceState.SpeedMismatchMps;
GVL_IHM.Cycle.State.SpeedMismatchActive    := PRG_03_Modes_Cycle.Data.SequenceState.SpeedMismatchActive;
GVL_IHM.Cycle.State.SpeedMismatchConfirmed := PRG_03_Modes_Cycle.Data.SequenceState.SpeedMismatchConfirmed;
// Position cycle : meme gel affichage que M1TreuilRetenue/M2TreuilBenne pendant le preset codeur.
GVL_IHM.Cycle.State.M1Position_M           := SEL(M1PosDisplayFrozen, PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM, M1PosHmiHeld_M);
GVL_IHM.Cycle.State.M2Position_M           := SEL(M2PosDisplayFrozen, PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM, M2PosHmiHeld_M);
GVL_IHM.Cycle.State.DeadmanArmed           := PRG_02_Acquisition.Data.Joystick.DeadmanArmed;
// 🕹️ JoystickDeflected = déflexion joystick seule (SANS homme-mort) — même signal que
// JoystickDeflected (FB_CycleSemiAuto, alimenté par PRG_03) = NOT AtNeutralXY. Un seul signal
// « joystick défléchi » est projeté à l'IHM.
GVL_IHM.Cycle.State.JoystickDeflected   := NOT PRG_02_Acquisition.Data.Joystick.AtNeutralXY;

// Projection Assistance Dragage (CycleDiveSearch / CycleExtraction / CycleDumpAtTremie)
GVL_IHM.CycleDiveSearch.State.DiveReady                  := PRG_03_Modes_Cycle.Data.SequenceState.DiveReady;
GVL_IHM.CycleDiveSearch.State.DiveBusy                   := PRG_03_Modes_Cycle.Data.SequenceState.DiveBusy;
GVL_IHM.CycleDiveSearch.State.DiveDone                   := PRG_03_Modes_Cycle.Data.SequenceState.DiveDone;
GVL_IHM.CycleDiveSearch.State.DiveError                  := PRG_03_Modes_Cycle.Data.SequenceState.DiveError;
GVL_IHM.CycleDiveSearch.State.DiveErrorId                := PRG_03_Modes_Cycle.Data.SequenceState.DiveErrorId;
GVL_IHM.CycleDiveSearch.State.DiveState                  := PRG_03_Modes_Cycle.Data.SequenceState.DiveState;
GVL_IHM.CycleDiveSearch.State.DiveStepAtFault            := PRG_03_Modes_Cycle.Data.SequenceState.DiveStepAtFault;
GVL_IHM.CycleDiveSearch.State.BottomTouchConfirmed       := PRG_03_Modes_Cycle.Data.SequenceState.BottomTouchConfirmed;
GVL_IHM.CycleExtraction.State.ExtractionReady             := PRG_03_Modes_Cycle.Data.SequenceState.ExtractionReady;
GVL_IHM.CycleExtraction.State.ExtractionBusy              := PRG_03_Modes_Cycle.Data.SequenceState.ExtractionBusy;
GVL_IHM.CycleExtraction.State.ExtractionDone              := PRG_03_Modes_Cycle.Data.SequenceState.ExtractionDone;
GVL_IHM.CycleExtraction.State.ExtractionError             := PRG_03_Modes_Cycle.Data.SequenceState.ExtractionError;
GVL_IHM.CycleExtraction.State.ExtractionErrorId           := PRG_03_Modes_Cycle.Data.SequenceState.ExtractionErrorId;
GVL_IHM.CycleExtraction.State.ExtractionState             := PRG_03_Modes_Cycle.Data.SequenceState.ExtractionState;
GVL_IHM.CycleExtraction.State.ExtractionStepAtFault       := PRG_03_Modes_Cycle.Data.SequenceState.ExtractionStepAtFault;
GVL_IHM.CycleDiveSearch.State.OperatorActionId           := PRG_03_Modes_Cycle.Data.SequenceState.OperatorActionId;
GVL_IHM.CycleDiveSearch.State.OperatorAction             := PRG_03_Modes_Cycle.Data.SequenceState.OperatorAction;
GVL_IHM.CycleDumpAtTremie.State.DumpAtTremieArmed           := PRG_03_Modes_Cycle.Data.SequenceState.DumpAtTremieArmed;
GVL_IHM.CycleDumpAtTremie.State.DumpAtTremieAssistActive      := PRG_03_Modes_Cycle.Data.SequenceState.DumpAtTremieAssistActive;
GVL_IHM.CycleDumpAtTremie.State.DumpAtTremieAtTremie          := PRG_03_Modes_Cycle.Data.SequenceState.DumpAtTremieAtTremie;
GVL_IHM.CycleDumpAtTremie.State.DumpAtTremieBucketOpenArmed   := PRG_03_Modes_Cycle.Data.SequenceState.DumpAtTremieBucketOpenArmed;
GVL_IHM.CycleDumpAtTremie.State.DumpAtTremieDescentLocked     := PRG_03_Modes_Cycle.Data.SequenceState.DumpAtTremieDescentLocked;
GVL_IHM.CycleDiveSearch.State.BypassDiveActive            := PRG_03_Modes_Cycle.Data.SequenceState.BypassDiveActive;
GVL_IHM.CycleDiveSearch.State.BypassKoboldBottomTouched   := PRG_03_Modes_Cycle.Data.SequenceState.BypassKoboldBottomTouched;

instHmiBannerFormatter(
    Enable                := TRUE,
    SimulationModeActive  := GVL_Simulation.SimulationModeActive,
    CurrentMode           := PRG_03_Modes_Cycle.Data.Auth.Mode,
    BothAxesCoupled       := (GVL_IHM.Modes.Cmd.SelJoystickWinch = 0),
    WinchSelected         := GVL_IHM.Modes.Cmd.SelJoystickWinch,
    CycleStep             := GVL_IHM.Cycle.State.CycleStep,
    CycleStateStr         := GVL_IHM.Cycle.State.CycleStateStr,
    CycleErrorId          := PRG_03_Modes_Cycle.Data.SequenceState.Fault.ErrorId,
    CycleStepAtError      := PRG_03_Modes_Cycle.Data.SequenceState.StepAtFault,
    DiveState             := GVL_IHM.CycleDiveSearch.State.DiveState,
    ExtractionState       := GVL_IHM.CycleExtraction.State.ExtractionState,
    MachineHomingStep        := PRG_02_Acquisition.Data.MachineHoming.Step,
    MachineHomingInstruction := PRG_02_Acquisition.Data.MachineHoming.Instruction,
    BypassGlobalActive    := GVL_IHM.Network.Bypass.Global,
    BypassWinchM1Active   := GVL_IHM.M1TreuilRetenue.Bypass.Global,
    BypassWinchM2Active   := GVL_IHM.M2TreuilBenne.Bypass.Global,
    BypassTranslation     := GVL_IHM.TranslationM3.Bypass.Global,
    BypassSyncActive      := GVL_IHM.M1M2Sync.Bypass.Global,
    SyncDegradedActive    := PRG_04_Treuils_Benne.Data.SyncState.SyncDeviationWarn,
    LegalLimitReached     := GVL_IHM.Commun.LimitLegalReached,
    ModeChangePendingBlocked := PRG_03_Modes_Cycle.Data.Auth.ModeChangePendingBlocked,
    ModeChangeBlockReason    := PRG_03_Modes_Cycle.Data.Auth.ModeChangeBlockReason,
    EmergencyChainClosed  := PRG_02_Acquisition.HwIn.Machine.EmergencyChainClosed_DI,
    PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
